-- Hegemony policies; native mode metadata selects Original Hegemony variants.
local known = AIValue.requireKnown
local original_query_methods={isWeak="originalHegemonyWeak",getOverflow="originalHegemonyOverflow",
    needToLoseHp="originalHegemonyNeedToLoseHp",needToThrowArmor="originalHegemonyNeedToThrowArmor",
    damageIsEffective="originalHegemonyDamageIsEffective",needKongcheng="originalHegemonyNeedKongcheng",
    hasCrossbowEffect="originalHegemonyCrossbowEffect"}

-- Resolve only the Original overrides admitted by the native mode facts.
local function hegemony_source_query(object, method, ...)
    local facts = object and object.world and AIHegemony.facts(object.world)
    local mapped = original_query_methods[method]
    if mapped and facts and facts.enabled and facts.original_overrides_loaded == true
        and type(object[mapped]) == "function" then method = mapped end
    if AIValue.isPlayer(object) then
        if method == "getMark" then method = "getStrategyMark"
        elseif method == "hasFlag" then method = "getStrategyFlag" end
    end
    return AIValue.callKnown(object, method, ...)
end
local function remember_pindian(self,id)
    self.shuangren_card=id
    self:remember("shuangren_card",id)
end
local function heg_facts(self)
    local row=self.world and AIHegemony.facts(self.world)
    if type(row)~="table" or type(row.enabled)~="boolean" then ai_unsupported("Hegemony mode facts missing","hegemony") end
    return row
end
local function heg_enabled(self)return heg_facts(self).enabled end
local function heg_player(self,p)
    local rows=heg_facts(self).players
    local row=type(rows)=="table" and rows[p:objectName()]
    if type(row)~="table" then ai_unsupported("public Hegemony reveal facts missing","hegemony") end
    return row
end
local function shown(self,p,name)
    if not heg_enabled(self) then return p:hasSkill(name) end
    local row=heg_player(self,p)
    if type(row.shown_skills)~="table" then ai_unsupported("shown skill catalog missing",name) end
    return row.shown_skills[name]~=nil
end
local function shown_entry(self,p,name)
    local row=heg_player(self,p);local entry=row.shown_skills and row.shown_skills[name]
    if type(entry)~="table" then ai_unsupported("shown general slot missing",name) end
    if type(entry.general)~="string" or type(entry.head)~="boolean" then
        ai_unsupported("shown skill entry metadata is malformed",name)
    end
    if entry.instances~=nil then
        if not AIValue.isList(entry.instances) then ai_unsupported("shown skill instances are malformed",name)end
        for _,instance in ipairs(entry.instances)do
            if type(instance)~="table" or type(instance.general)~="string" or type(instance.head)~="boolean" then
                ai_unsupported("shown skill instance metadata is malformed",name)
            end
        end
    end
    return entry
end
-- A shown skill can have several public instances (innate, acquired, or
-- attached).  Qingcheng and Chuanxin need the instance bound to this player's
-- own general; `head=false` alone would incorrectly treat an unbound or
-- foreign instance as the deputy general.
local function shown_general_source(self,p,name,want_bind)
    local entry=shown_entry(self,p,name)
    local candidates={entry}
    if entry.instances~=nil then
        for _,instance in ipairs(entry.instances)do candidates[#candidates+1]=instance end
    end
    local owner=p:objectName()
    for _,candidate in ipairs(candidates)do
        local bind,source=candidate.bind_head,candidate.source_owner
        if type(bind)~="number" or bind%1~=0 or bind<0 or bind>2 then
            ai_unsupported("shown skill binding metadata is malformed",name)
        end
        if type(source)~="string" then
            ai_unsupported("shown skill source owner is unavailable",name)
        end
        if source==owner and (want_bind==nil and (bind==1 or bind==2) or bind==want_bind) then
            return candidate
        end
    end
    return nil
end
local function public_kingdom(self,p)local k=known(heg_player(self,p).public_kingdom,"public kingdom");return k~="" and k or "unknown" end
local function heg_kingdom(self,p)
    if not p then return "unknown" end
    if p:objectName()==self.player:objectName() then
        local role=self.world.self and self.world.self.role
        if role=="careerist" then return "careerist" end
        return known(heg_facts(self).own_kingdom,"own kingdom")
    end
    return public_kingdom(self,p)
end
-- Generic stand-ins for removed owner/public facts. Methods, not main-chunk locals:
-- this chunk is at Lua's 200-local limit.
-- Room::getLord(kingdom) consumes the viewer-scoped public-lord map.  A result
-- naming the viewer itself is accepted only when that viewer's head is shown;
-- concealed owner state must remain unavailable.
function SmartAIView:originalHegemonyPublicLord(kingdom)
    local facts=self.world and self.world.hegemony_facts
    if type(facts)~='table' then ai_unsupported('public lord projection is unavailable',kingdom)end
    local public_lords=known(facts.public_lords,'public Hegemony lords')
    local name=known(public_lords[kingdom],'public lord '..tostring(kingdom))
    if type(name)~='string' then ai_unsupported('public lord projection is malformed',kingdom)end
    if name=='' then return nil end
    local lord=known(self.room:findPlayerByObjectName(name,true),'public lord roster')
    if lord:objectName()==self.player:objectName() then
        local row=heg_player(self,self.player)
        if not known(row.shown_head,'owner head-general reveal') then return nil end
    end
    return lord
end
function SmartAIView:originalHegemonyIsLordGeneral(p)
    local general=type(p.getGeneralName)=="function" and p:getGeneralName()
    return type(general)=="string" and general:sub(1,9)=="heg_lord_"
end
-- The owner facts the Original policies read, from generic owner views.
function SmartAIView:originalHegemonyOwnerFact(key)
    local facts=self.world and self.world.hegemony_facts
    if type(facts)=='table' and facts[key]~=nil then
        return known(facts[key],key)
    end
    if key=="owner_current_card_use_reason" then return known(self.request.reason,key)
    elseif key=="owner_can_slash_without_crossbow" then return known(self.player:canSlashWithoutCrossbow(),key)
    elseif key=="owner_wenji_record" then return self.player:getPropertyValue("wenji_record") or "" -- absent: ""
    elseif key=="owner_analeptic_available" then
        -- Analeptic::IsAvailable(owner) is the printed Analeptic's owner rule.
        return known(known(self:getEvaluationCard("analeptic"),"analeptic prototype"):isAnalepticAvailable(self.player),key)
    elseif key=="owner_slash_count" then
        -- Player::getSlashCount sums the raw history of every Slash class; the
        -- no-limit properties zero the projected usedTimes instead.
        if self.player:getPropertyValue("AllSkillNoLimitingTimes") or (self.player:getPropertyValue("SkillNoLimitingTimes") or "")~="" then
            ai_unsupported("raw Slash history is not projected",key)
        end
        local count=0
        for class,name in pairs(known(AICardCatalog.patternClassNames(),"card catalog"))do
            local row=AICardCatalog.get(name)
            if row and AIValue.isList(row.kind_of) and table.contains(row.kind_of,"Slash") then
                count=count+known(self.player:usedTimes(class),key)
            end
        end
        return count
    elseif key=="owner_hegemony_lord" then
        -- The owner result is a native viewer-scoped fact.  Do not inspect the
        -- raw owner general here: concealed head state must not leak through a
        -- local PlayerView fallback.
        ai_unsupported("owner lord projection is unavailable",key)
    end
    -- Room::countHistoryCards (owner_card_used_times/responded_times) is not projected.
    ai_unsupported("owner fact is not projected",key)
end
-- Original getKnownNum: hand plus Wooden Ox cards this observer sees.
local function original_visible_count_row(self,player)
    local world=self.world
    local facts=world and world.hegemony_facts
    if type(facts)~='table' then ai_unsupported('Original visible card count projection is unavailable','visible_counts')end
    local counts=known(known(facts.card_counts,'Original.cardCounts').visible_counts,
        'Original visible card counts')
    local row=known(counts[player:objectName()],
        'Original visible card count '..player:objectName())
    if type(row)~='table' then ai_unsupported('Original visible card count row is malformed',player:objectName())end
    return row
end
function SmartAIView:originalHegemonyVisibleCount(player)
    local row=original_visible_count_row(self,player)
    local hand=known(row.hand_visible_count,'visible hand')
    local ox=known(row.wooden_ox_visible_count,'visible Wooden Ox')
    return hand,ox
end
local function current_for_cardneed(player)
    local room=rawget(player,"_room")
    return room:getCurrent()
end

local function heg_process(self)
	local value = {}
	local kingdoms = {"wei", "shu", "wu", "qun"}
	for _, kingdom in ipairs(kingdoms) do
		value[kingdom] = 0
	end

	local function shown_count(kingdom)
        local count=0;for _,p in ipairs(self.room:getAlivePlayers())do if public_kingdom(self,p)==kingdom then count=count+1 end end;return count
    end
	local anjiang = 0
	local players = self.room:getAlivePlayers()
	for _, ap in ipairs(players) do
		if table.contains(kingdoms, public_kingdom(self,ap)) then
			local v = 3 + self:getDefense(ap) / 2
			value[public_kingdom(self,ap)] = value[public_kingdom(self,ap)] + v
		else
			anjiang = anjiang + 1
		end
	end

	local cmp = function(a, b)
		return value[a] > value[b]
	end
	table.sort(kingdoms, cmp)
	local sum_value1, sum_value2, sum_value3 = 0, 0, 0
	for i = 2, #kingdoms do
		sum_value1 = sum_value1 + value[kingdoms[i]]
		if i < #kingdoms then sum_value2 = sum_value2 + value[kingdoms[i]] end
		if i < #kingdoms - 1 then sum_value3 = sum_value3 + value[kingdoms[i]] end

	end

	local process = "==="
	if value[kingdoms[1]] >= sum_value1 and value[kingdoms[1]] > 0 then
		local playerNum_1 = shown_count(kingdoms[1])
		local playerNum_2 = shown_count(kingdoms[2])
		if #players > 4 and (#players / 2 <= playerNum_1 or playerNum_2 + anjiang <= playerNum_1 or anjiang <= 1) then process = kingdoms[1] .. ">>>"
		elseif anjiang <= #players / 2  - 1 then process = kingdoms[1] .. ">>"
		elseif anjiang <= #players / 2 + 1 then process = kingdoms[1] .. ">" end
	elseif value[kingdoms[1]] >= sum_value2 and value[kingdoms[1]] > 0 then
		if anjiang == 0 then process = kingdoms[1] .. ">>"
		elseif anjiang <= #players / 2 - 1 then process = kingdoms[1] .. ">" end
	elseif value[kingdoms[1]] >= sum_value3 and value[kingdoms[1]] > 0 then
		process = kingdoms[1] .. ">"
	end

	return process
end

local function show_attack(self)
	if self.room:getMode() == "jiange_defense" then return true end
	if known(heg_player(self,self.player).shown_one,"shown_one") then return true end
	if #self.room:getAlivePlayers() < 3 then return true end

	local notshown, shown, f, e, eAtt = 0, 0, 0, 0, 0
	for _,p in ipairs(self.room:getAlivePlayers()) do
		if  not known(heg_player(self,p).shown_one,"shown_one") then
			notshown = notshown + 1
		end
		if known(heg_player(self,p).shown_one,"shown_one") then
			shown = shown + 1
			if heg_kingdom(self,p) == known(heg_facts(self).own_kingdom,"own kingdom") then
				f = f + 1
			else
				e = e + 1
				if hegemony_source_query(self,'isWeak',p) and p:getHp() == 1 and self.player:distanceTo(p) <= self.player:getAttackRange() then eAtt= eAtt + 1 end
			end
		end
	end

	local showRate = math.random() + f/20 + eAtt/10 + shown/20 + self.room:getTurnCount()/10

	local firstShowReward = false
	if known(heg_facts(self).first_show_reward,"first show reward") then
		if shown == 0 then
			firstShowReward = true
		end
	end
	if firstShowReward and showRate > 0.9 then return true end

	if showRate < 0.8 then return false end
	if e < f or eAtt <= 0 then return false end

return true
end

-- Full fixed Original common4614–4649; ordinary lexical show_attack remains unchanged.
function SmartAIView:originalHegemonyWillShowForAttack()
	if self.room:getMode() == "jiange_defense" then return true end
	if known(heg_player(self,self.player).shown_one,"shown_one") then return true end
	if self.room:alivePlayerCount() < 3 then return true end

	local notshown, shown, f, e, eAtt = 0, 0, 0, 0, 0
	for _,p in ipairs(self.room:getAlivePlayers()) do
		if  not known(heg_player(self,p).shown_one,"shown_one") then
			notshown = notshown + 1
		end
		if known(heg_player(self,p).shown_one,"shown_one") then
			shown = shown + 1
			if self:evaluateKingdom(p) == self:originalHegemonyOwnKingdom() then
				f = f + 1
			else
				e = e + 1
				if hegemony_source_query(self,'isWeak',p) and p:getHp() == 1 and self.player:distanceTo(p) <= self.player:getAttackRange() then eAtt= eAtt + 1 end
			end
		end
	end

	local showRate = math.random() + f/20 + eAtt/10 + shown/20 + self.room:getTurnCount()/10

	local firstShowReward = false
	if known(heg_facts(self).first_show_reward,"first show reward") then
		if shown == 0 then
			firstShowReward = true
		end
	end
	if firstShowReward and showRate > 0.9 then return true end

	if showRate < 0.8 then return false end
	if e < f or eAtt <= 0 then return false end

return true
end

local function show_defence(self)
	if self.room:getMode() == "jiange_defense" then return true end
	if known(heg_player(self,self.player).shown_one,"shown_one") then return true end
	if #self.room:getAlivePlayers() < 3 then return true end
	if hegemony_source_query(self,'isWeak') then return true end

	local notshown, shown, f, e, eAtt = 0, 0, 0, 0, 0
	for _,p in ipairs(self.room:getAlivePlayers()) do
		if  not known(heg_player(self,p).shown_one,"shown_one") then
			notshown = notshown + 1
		end
		if known(heg_player(self,p).shown_one,"shown_one") then
			shown = shown + 1
			if heg_kingdom(self,p) == known(heg_facts(self).own_kingdom,"own kingdom") then
				f = f + 1
			else
				e = e + 1
				if hegemony_source_query(self,'isWeak',p) and p:getHp() == 1 and self.player:distanceTo(p) <= self.player:getAttackRange() then eAtt= eAtt + 1 end
			end
		end
	end
	local showRate = math.random() - e/10 - self.player:getHp()/10 + shown/20 + self.room:getTurnCount()/10

	local firstShowReward = false
	if known(heg_facts(self).first_show_reward,"first show reward") then
		if shown == 0 then
			firstShowReward = true
		end
	end
	if firstShowReward and showRate > 0.9 then return true end

	if showRate < 0.8 then return false end
	if f < 2 or not hegemony_source_query(self,'isWeak') then return false end

	return true
end


local function hegemonyWillShow(self,defence)
    if not heg_enabled(self) then return true end
    if defence then return show_defence(self) end
    return show_attack(self)
end

ai_card_use.ShowDistanceCard = function(self, card, use, request)
    if not heg_enabled(self) then return end
    -- The native ticket already selects a revealable exact source. Distance
    -- skills can aid either side of a distance check; share reveal timing only,
    -- without assuming every skill is Mashu or simulating concealed effects.
    if show_attack(self) or show_defence(self) then use.card = card end
end

sgs.ai_skill_cardask["@xiaoguo"] = function(self,data)
	local currentplayer = self.room:getCurrent()

	local has_analeptic,has_slash,has_jink
	for _,acard in ipairs(self.player:getHandcards())do
		if acard:isKindOf("Analeptic") then has_analeptic = acard
		elseif acard:isKindOf("Slash") then has_slash = acard
		elseif acard:isKindOf("Jink") then has_jink = acard
		end
	end

	local card

	if has_slash then card = has_slash
	elseif has_jink then card = has_jink
	elseif has_analeptic then
		if (getCardsNum("EquipCard",currentplayer,self.player)==0 and not hegemony_source_query(self,'isWeak')) or self:getCardsNum("Analeptic")>1 then
			card = has_analeptic
		end
	end

	if not card then return "." end
	if self:isFriend(currentplayer) then
		if hegemony_source_query(self,'needToThrowArmor',currentplayer) then
			if card:isKindOf("Slash") or (card:isKindOf("Jink") and self:getCardsNum("Jink")>1) then
				return "$"..card:getKnownEffectiveId()
			else return "."
			end
		end
	elseif self:isEnemy(currentplayer) then
		if not hegemony_source_query(self,'damageIsEffective',currentplayer) then return "." end
		if hegemony_source_query(self,'needToLoseHp',currentplayer,self.player) then return "." end
		if hegemony_source_query(self,'needToThrowArmor') then return "." end
		if currentplayer:getHp()>2 and (currentplayer:getHandcardNum()>2 or currentplayer:getCards("e"):length()>1)then return "." end
		if currentplayer:getHp()>1 and (currentplayer:getHandcardNum()>3 or currentplayer:getCards("e"):length()>2)then return "." end
		if self:hasSkills(sgs.lose_equip_skill,currentplayer) and currentplayer:getCards("e"):length()>0 then return "." end
		return "$"..card:getKnownEffectiveId()
	end
	return "."
end

sgs.ai_choicemade_filter.cardResponded = sgs.ai_choicemade_filter.cardResponded or {}
sgs.ai_choicemade_filter.cardResponded["@xiaoguo"] = function(self,player,promptlist)
	if promptlist[#promptlist]~="" then
		local current = self.room:getCurrent()
		if not current then return end
		local intention = 10
		if self:hasSkills(sgs.lose_equip_skill,current) and current:getCards("e"):length()>0 then intention = 0 end
		if hegemony_source_query(self,'needToThrowArmor',current) then return end
		self:updateIntention(player,current,intention)
	end
end

sgs.ai_skill_cardask["@xiaoguo-discard"] = function(self,data)
	local yuejin = self.room:findPlayerBySkillName("xiaoguo")
	if hegemony_source_query(self,'needToThrowArmor') then
		return "$"..self.player:getArmor():getEffectiveId()
	end
	if not hegemony_source_query(self,'damageIsEffective',self.player,sgs.DamageStruct_Normal,yuejin) then
		return "."
	end
	if hegemony_source_query(self,'needToLoseHp',self.player,yuejin) then
		return "."
	end
	local card_id
	if self:hasSkills(sgs.lose_equip_skill,self.player) then
		if self.player:getWeapon() then card_id = self.player:getWeapon():getId()
		elseif self.player:getOffensiveHorse() then card_id = self.player:getOffensiveHorse():getId()
		elseif self.player:getArmor() then card_id = self.player:getArmor():getId()
		elseif self.player:getDefensiveHorse() then card_id = self.player:getDefensiveHorse():getId()
		end
	end

	if not card_id then
		for _,card in ipairs(self.player:getCards("h"))do
			if card:isKindOf("EquipCard") then
				card_id = card:getKnownEffectiveId()
				break
			end
		end
	end

	if not card_id then
		if self.player:getWeapon() then card_id = self.player:getWeapon():getId()
		elseif self.player:getOffensiveHorse() then card_id = self.player:getOffensiveHorse():getId()
		elseif hegemony_source_query(self,'isWeak',self.player) and self.player:getArmor() then card_id = self.player:getArmor():getId()
		elseif hegemony_source_query(self,'isWeak',self.player) and self.player:getDefensiveHorse() then card_id = self.player:getDefensiveHorse():getId()
		end
	end

	if not card_id then return "." else return "$"..card_id end
end

sgs.ai_cardneed.xiaoguo = function(to,card)
	return getKnownCard(to,current_for_cardneed(to),"BasicCard",true)==0 and card:getTypeId()==sgs.Card_Basic
end

ai_skill_choice.shushen = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end

	return  ai_choice_result((self:getStrategyMemory("shushen_choice")),options)
end

-- Effective ordinary-source override: extra-ai.lua:1143, loaded after this file.
sgs.ai_skill_playerchosen.shushen = function(self,targets)
    if #self.friends_noself==0 then return nil end
    return self:findPlayerToDraw(false,2)
end

sgs.ai_playerchosen_intention.shushen = -80

ai_skill_invoke.shenzhi = function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

	if self:getCardsNum("Peach")>0 then return (false) or false  end
	if self.player:getHandcardNum()>=3 then return (false) or false  end
	if self.player:getHandcardNum()>=self.player:getHp() and self.player:isWounded() then return (true) or false  end
	if self.player:hasSkill("beifa") and self.player:getHandcardNum()==1 and hegemony_source_query(self,'needKongcheng') then return (true) or false  end
	if self.player:hasSkill("sijian") and self.player:getHandcardNum()==1 then return (true) or false  end
	return (false) or false 
end

function sgs.ai_cardneed.shenzhi(to,card)
	return to:getHandcardNum()<to:getHp()
end

-- Canonical HStandard skills can also be acquired by identity-mode extensions.
-- Keep only skill/card policies here; the mode-wide Hegemony AI stays gated.
function SmartAIView:useCardAwaitExhausted(AwaitExhausted, use)
	if not AwaitExhausted:isAvailable(self.player) then return end
	use.card = AwaitExhausted
	return
end
sgs.ai_use_priority.AwaitExhausted = 2.8
sgs.ai_use_value.AwaitExhausted = 4.9
sgs.ai_keep_value.AwaitExhausted = 1
sgs.ai_card_intention.AwaitExhausted = function(self, card, from, tos)
	for _, to in ipairs(tos) do
		self:updateIntention(from, to, -50)
	end
end
sgs.ai_nullification.AwaitExhausted = function(self, card, from, to, positive)
	if positive then
		if self:isEnemy(to) and (not heg_enabled(self) or heg_kingdom(self,to) ~= "unknown") then
			if hegemony_source_query(self,'getOverflow') > 0 or self:getCardsNum("Nullification") > 1 then return true end
			if self:hasSkills(sgs.lose_equip_skill,to) and to:getEquips():length() > 0 then return true end
			if to:getArmor() and hegemony_source_query(self,'needToThrowArmor',to) then return true end
		end
	else
		if self:isFriend(to) and (hegemony_source_query(self,'getOverflow') > 0 or self:getCardsNum("Nullification") > 1) then return true end
	end
	return
end

-- Source ordinary hegemony206 calls sgs.isGoodTarget, while Fenxun353
-- calls the distinct SmartAI method. Preserve prior ordinary adapter behavior;
-- admitted Original must select its actual global provider, not shadow methods.
local function original_duoshi_good_target(self,enemy,targets)
    local f=AIHegemony.facts(self.world)
    if f and f.enabled and known(f.original_overrides_loaded,"original_hegemony_ai_loaded")then
        return self:originalHegemonyIsGoodTarget(enemy,targets)
    end
    return self:isGoodTarget(enemy,targets)
end

ai_fill_skill.heg_duoshi = function(self,options,request)
    local inclusive=(options or {}).inclusive

	local DuoTime = 2
	if self.player:hasSkills("heg_fenming|heg_zhiheng|fenxun|heg_keji") then
		DuoTime = 1
	end
	if self.player:hasSkills("heg_hongyan|heg_yingzi_zhouyu|heg_yingzi_sunce") then
		DuoTime = 3
	end
	if self.player:hasSkills("heg_xiaoji|heg_haoshi") then
		DuoTime = 4
	end
	for _, player in ipairs(self.friends) do
		if (shown(self,player,"heg_xiaoji") or shown(self,player,"heg_haoshi")) then
			DuoTime = 4
			break
		end
	end

	if (self.player:usedTimes("DuoshiAE") >= DuoTime and hegemony_source_query(self,'getOverflow') <= 0) or self.player:usedTimes("DuoshiAE") >= 4 	then return end


	if self.room:getTurnCount() <= 1 and #self.friends_noself == 0 and not hegemony_source_query(self,'isWeak') and hegemony_source_query(self,'getOverflow') <= 0 then return end
	local cards = self.player:getCards("h")
	cards = AIList.new(cards)


	if (hegemony_source_query(self,'hasCrossbowEffect') or self:getCardsNum("Crossbow") > 0) and self:getCardsNum("Slash") > 0 then
		self:sortInPlace(self.enemies, "defense")
		for _, enemy in ipairs(self.enemies) do
			local inAttackRange = self.player:distanceTo(enemy) == 1 or self.player:distanceTo(enemy) == 2
									and self:getCardsNum("OffensiveHorse") > 0 and not self.player:getOffensiveHorse()
			if inAttackRange  and original_duoshi_good_target(self,enemy,self.enemies) then
				local slashes = self:getCards("Slash")
				local slash_count = 0
				for _, slash in ipairs(slashes) do
					if not self:slashProhibit(slash,enemy) and self:slashIsEffective(slash,enemy) then
						slash_count = slash_count + 1
					end
				end
				if slash_count >= enemy:getHp() then return end
			end
		end
	end

	local red_card
	if self.player:getHandcardNum() <= 2 then return end
	cards = self:sortByUseValue(cards, true)

	for _, card in ipairs(cards) do
		if card:isRed() then
			local shouldUse = true
			if card:isKindOf("Slash") then
				local dummy_use = { isDummy = true }
				if self:getCardsNum("Slash") == 1 then
					self:useBasicCard(card, dummy_use)
					if dummy_use.card then shouldUse = false end
				end
			end

			if self:getUseValue(card) > sgs.ai_use_value.AwaitExhausted and card:isKindOf("TrickCard") then
				local dummy_use = { isDummy = true }
				self:useTrickCard(card, dummy_use)
				if dummy_use.card then shouldUse = false end
			end

			local heg_sunshangxiang = false
			if self.player:hasSkills("heg_xiaoji") and self.player:getCards("e"):length() > 0 then
				heg_sunshangxiang = true
			end
			for _, player in ipairs(self.friends) do
				if shown(self,player,"heg_xiaoji") and player:getCards("e"):length() > 0 then
					heg_sunshangxiang = true
					break
				end
			end

			if not hegemonyWillShow(self, true) and not heg_sunshangxiang then
				shouldUse = false
			end

			if shouldUse and not card:isKindOf("Peach") then
				red_card = card
				break
			end

		end
	end

	if red_card then
		local card_id = red_card:getKnownEffectiveId()
        return self:bindTurnConversion("heg_duoshi","AwaitExhausted",{name="await_exhausted",skill="heg_duoshi",suit=red_card:getSuit(),number=red_card:getNumber(),subcards={red_card:getKnownEffectiveId()}},request)

	end
end


-- Shared identity Fenxun uses the V2 proxy; its historical usage key stays FenxunCard.
ai_fill_skill.fenxun = function(self,options,request)
    local inclusive=(options or {}).inclusive

	if #self.enemies==0 then return end
	if self:needBear() then return end
	if not self.player:isNude() then
		local card_id
		local slashcount = self:getCardsNum("Slash")
		local jinkcount = self:getCardsNum("Jink")
		local cards = self.player:getHandcards()
		cards = AIList.new(cards)
		cards = self:sortByKeepValue(cards)

		if hegemony_source_query(self,'needToThrowArmor') then
			return self:bindSkillCard("fenxun",{self.player:getArmor():getId()},request)
		elseif self.player:getHandcardNum()>0 then
			local lightning = self:getCard("Lightning")
			if lightning and not self:willUseLightning(lightning) then
				card_id = lightning:getEffectiveId()
			else
				for _,acard in ipairs(cards)do
					if (acard:isKindOf("AmazingGrace") or acard:isKindOf("EquipCard")) then
						card_id = acard:getKnownEffectiveId()
						break
					end
				end
			end
			if not card_id and jinkcount>1 then
				for _,acard in ipairs(cards)do
					if acard:isKindOf("Jink") then
						card_id = acard:getKnownEffectiveId()
						break
					end
				end
			end
			if not card_id and slashcount>1 then
				for _,acard in ipairs(cards)do
					if acard:isKindOf("Slash") then
						slashcount = slashcount-1
						card_id = acard:getKnownEffectiveId()
						break
					end
				end
			end
		end

		if not card_id and self.player:getWeapon() then
			card_id = self.player:getWeapon():getId()
		end

		if not card_id then
			for _,acard in ipairs(cards)do
				if (acard:isKindOf("AmazingGrace") or acard:isKindOf("EquipCard") or acard:isKindOf("BasicCard"))
					and not isCard("Peach",acard,self.player) and not isCard("Slash",acard,self.player) then
					card_id = acard:getKnownEffectiveId()
					break
				end
			end
		end

		if slashcount>0 and card_id then
			return self:bindSkillCard("fenxun",{card_id},request)
		end
	end
	return nil
end

ai_card_use.fenxun = function(self,card,use)
	self:sortInPlace(self.enemies, "defense")
	local target
	for _,slash in ipairs(self:getCards("Slash"))do
		if not card:getSubcards():contains(slash:getKnownEffectiveId()) then
			local target_num,hastarget = 0,nil
			for _,enemy in ipairs(self.enemies)do
				if not self:slashProhibit(slash,enemy) and self.player:canSlash(enemy,slash,false) and self:isGoodTarget(enemy,self.enemies,slash) then
					if self.player:distanceTo(enemy)>1 and not target then target = enemy
					elseif self.player:distanceTo(enemy)==1 then
						hastarget = true
					end
					if self.player:inMyAttackRange(enemy) then
						target_num = target_num+1
					end
				end
			end
			if hastarget and target_num>=2 then return end
		end
	end
	if target and self:getCardsNum("Slash")>0 then
		use.card = card
		use.to:append(target)
	end
end

