		if (not heg_enabled(self) or self:objectiveLevel(friend) == 2 or self.player:isPublicHegemonyFriend(friend)) and hegemony_source_query(self,'isWeak',friend) then
			return self:bindSkillCard("xiongyi",{},request)
		end
	end
	if heg_enabled(self) and heg_process(self) == "qun>>>" then
		return self:bindSkillCard("xiongyi",{},request)
	end
end

