sgs.ai_skill_askforyiji.lirang = function(self, card_ids)
	self:updatePlayers()
	local cards = {}
	for _, card_id in ipairs(card_ids) do
		table.insert(cards, known(self:getKnownCardById(card_id),"Lirang offered card"))
	end
	local id = card_ids[1]

	local card, friend = self:getCardNeedPlayer(cards, self.friends_noself)
	if card and friend then return friend, card:getKnownId() end
	if #self.friends_noself > 0 then
		self:sortInPlace(self.friends_noself, "handcard")
		for _, afriend in ipairs(self.friends_noself) do
			if not hegemony_source_query(self,'needKongcheng',afriend,true) then
				return afriend, id
			end
		end
		self:sortInPlace(self.friends_noself, "defense")
		return self.friends_noself[1], id
	end
	return nil, -1
end

sgs.ai_skill_playerchosen.shuangren = function(self, targets)
	if self.player:isKongcheng() then return nil end
	if not hegemonyWillShow(self) then return nil end
	if hegemony_source_query(self.player,'getMark',"ViewAsSkill_shuangxiongEffect") > 0 and self.player:hasSkill("shuangxiong") then return nil end

	self:sortInPlace(self.enemies, "handcard")
	local max_card = self:getMaxCard()
	local max_point = max_card:getNumber()

	local slash = known(self:getEvaluationCard("slash"),"printed Slash")
	local dummy_use = { isDummy = true, to = AIList.new({}) }
    slash = self:evaluateSkillCard("shuangren","slash",{})
    self:useBasicCard(slash,dummy_use)

	if dummy_use.card and not dummy_use.to:isEmpty() then
		for _, enemy in ipairs(dummy_use.to) do
			local enemy_max_card = self:getMaxCard(enemy)
			local enemy_max_point = enemy_max_card and enemy_max_card:getNumber() or 100
			if targets:contains(enemy) and max_point > enemy_max_point then
				remember_pindian(self,max_card:getKnownEffectiveId())
				return enemy
			end
		end
		for _, enemy in ipairs(dummy_use.to) do
			if targets:contains(enemy) and max_point >= 10 then
				remember_pindian(self,max_card:getKnownEffectiveId())
				return enemy
			end
		end
	end
	return nil
end

function sgs.ai_skill_pindian.shuangren(minusecard, self, requestor)
	local maxcard = self:getMaxCard()
	return self:isFriend(requestor) and self:getMinCard() or (maxcard:getNumber() < 6 and minusecard or maxcard)
end

