-- original-hegemony/heg-loader-ai.lua overrides only after its guarded load
-- succeeds. Do not mutate the ordinary registries when the mode is disabled.
local function original_enabled(self)
    local facts=heg_facts(self)
    if not facts.enabled then return false end
    return known(facts.original_overrides_loaded,"original_hegemony_ai_loaded")
end
local function original_category(self,name)
    return known(heg_facts(self)[name],"original category "..name)
end
local original_skill_aliases = {
    nosganglie = {"heg_ganglie"}, nostuxi = {"tenyeartuxi"}, nosluoyi = {"heg_luoyi"},
    nosyiji = {"heg_yiji"}, shensu = {"heg_shensu"},
    duanliang = {"heg_duanliang"}, nosjushou = {"heg_jushou"}, qiangxi = {"heg_qiangxi"},
    jieming = {"heg_jieming"}, fangzhu = {"mobilefangzhu"}, luoshen = {"heg_luoshen"},
    guicai = {"heg_guicai"},
    paoxiao = {"heg_paoxiao"}, kongcheng = {"heg_kongcheng"}, longdan = {"heg_longdan"},
    tieqi = {"heg_tieqi"}, jizhi = {"heg_jizhi"}, liegong = {"heg_liegong"},
    wusheng = {"tenyearwusheng"}, kuanggu = {"tenyearkuanggu"}, huoshou = {"heg_huoshou"}, juxiang = {"heg_juxiang"},
    keji = {"heg_keji"},
    kurou = {"heg_kurou"}, yingzi = {"heg_yingzi_sunce", "heg_yingzi_zhouyu"},
    qicai = {"nosqicai"},
    fanjian = {"heg_fanjian"}, guose = {"heg_guose"}, qianxun = {"heg_qianxun"},
    xiaoji = {"heg_xiaoji"}, yinghun = {"heg_yinghun_sunjian", "heg_yinghun_sunce"},
    tianxiang = {"heg_tianxiang"}, buqu = {"heg_buqu"}, guzheng = {"heg_guzheng"},
    duanbing = {"heg_duanbing"}, fenxun = {"heg_fenxun"}, luanji = {"heg_luanji"},
     weimu = {"heg_weimu"},
	leiji = {"nosleiji"}, duanchang = {"heg_duanchang"},
    wushuang = {"heg_wushuang"}, jiang = {"heg_jiang"},
}
local function original_shown_skills(self,p,expression)
    -- Preserve the admitted bundle's rename alternatives and conjunctions.
    for group in expression:gmatch("[^|]+") do
        local all=true
        for skill in group:gmatch("[^+]+") do
            local found=false
            for _,actual in ipairs(original_skill_aliases[skill] or {skill})do if shown(self,p,actual)then found=true;break end end
            if not found then all=false;break end
        end
        if all then return true end
    end
    return false
end
local function original_both_shown(self,p)
    local row=heg_player(self,p)
    return known(row.shown_head,"shown head") and known(row.shown_deputy,"shown deputy")
end
local function original_find_shown(self,name)
    for _,p in ipairs(self.room:getAllPlayers())do if shown(self,p,name)then return p end end
end
local ordinary_xiaoguo=sgs.ai_skill_cardask["@xiaoguo"]
sgs.ai_skill_cardask["@xiaoguo"]=function(self,data)
    if not original_enabled(self) then return ordinary_xiaoguo(self,data) end
    if not hegemonyWillShow(self) then return "." end
    local current=self.room:getCurrent()
    if hegemony_source_query(self.player,'getMark',"Global_TurnCount")<2 and not known(heg_player(self,self.player).shown_one,"shown one")
        and hegemony_source_query(self,'getOverflow',self.player,false)<1 and not known(heg_player(self,current).shown_one,"shown one") then return "." end
    local analeptic,slash,jink
    for _,card in ipairs(self.player:getHandcards())do
        if card:isKindOf("Analeptic")then analeptic=card
        elseif card:isKindOf("Slash")then slash=card
        elseif card:isKindOf("Jink")then jink=card end
    end
    local card=slash or jink
    if not card and analeptic and ((getCardsNum("EquipCard",current,self.player)==0 and not hegemony_source_query(self,'isWeak'))
        or self:getCardsNum("Analeptic")>1)then card=analeptic end
    if not card then return "." end
    if self:isFriend(current)then
        if hegemony_source_query(self,'needToThrowArmor',current)then
            if card:isKindOf("Slash") or card:isKindOf("Jink") and self:getCardsNum("Jink")>1 then return "$"..card:getKnownEffectiveId() end
            return "."
        end
    elseif self:isEnemy(current)then
        if not hegemony_source_query(self,'damageIsEffective',current)then return "." end
        if self:originalHegemonyNeedDamagedEffects(current) or hegemony_source_query(self,'needToLoseHp',current,self.player)then return "." end
        if hegemony_source_query(self,'needToThrowArmor',current)then return "." end
        if current:getHp()>2 and (current:getHandcardNum()>2 or #current:getCards("e")>1)then return "." end
        if current:getHp()>1 and (current:getHandcardNum()>3 or #current:getCards("e")>2)then return "." end
        if original_shown_skills(self,current,original_category(self,"lose_equip_skill")) and current:hasEquip()then return "." end
        if shown(self,current,"heg_mingshi") and (not known(heg_player(self,self.player).shown_one,"shown one")
            or shown(self,self.player,"xiaoguo") and not known(heg_player(self,self.player).shown_all,"shown all"))then return "." end
        return "$"..card:getKnownEffectiveId()
    end
    return "."
end
local ordinary_xiaoguo_intention=sgs.ai_choicemade_filter.cardResponded["@xiaoguo"]
sgs.ai_choicemade_filter.cardResponded["@xiaoguo"]=function(self,player,promptlist)
    if not original_enabled(self)then return ordinary_xiaoguo_intention(self,player,promptlist)end
    if promptlist[#promptlist]~="_nil_"then
        local current=self.room:getCurrent();if not current then return end
        local intention=10
        if original_shown_skills(self,current,original_category(self,"lose_equip_skill")) and current:hasEquip()then intention=0 end
        if hegemony_source_query(self,'needToThrowArmor',current)then return end
        self:updateIntention(player,current,intention)
    end
end
local ordinary_xiaoguo_discard=sgs.ai_skill_cardask["@xiaoguo-discard"]
sgs.ai_skill_cardask["@xiaoguo-discard"]=function(self,data)
    if not original_enabled(self)then return ordinary_xiaoguo_discard(self,data)end
    local yuejin=original_find_shown(self,"xiaoguo");local player=self.player
    if hegemony_source_query(self,'needToThrowArmor')then return "$"..(player:getArmor()):getKnownEffectiveId()end
    if not hegemony_source_query(self,'damageIsEffective',player,sgs.DamageStruct_Normal,yuejin)then return "." end
    if self:originalHegemonyNeedDamagedEffects(player,yuejin)then return "." end
    if hegemony_source_query(self,'needToLoseHp',player,yuejin)then return "." end
    local card_id
    if player:hasSkills(original_category(self,"lose_equip_skill"))then
        if player:getWeapon()then card_id=player:getWeapon():getId()
        elseif player:getOffensiveHorse()then card_id=player:getOffensiveHorse():getId()
        elseif player:getArmor()then card_id=player:getArmor():getId()
        elseif player:getDefensiveHorse()then card_id=player:getDefensiveHorse():getId()end
    end
    if not card_id then for _,card in ipairs(player:getCards("h"))do if card:isKindOf("EquipCard")then card_id=card:getEffectiveId();break end end end
    if not card_id then
        if player:getWeapon()then card_id=player:getWeapon():getId()
        elseif player:getOffensiveHorse()then card_id=player:getOffensiveHorse():getId()
        elseif player:getTreasure() and not(player:getPileCount("wooden_ox")>1 or player:hasTreasure("JadeSeal"))then card_id=player:getTreasure():getId()
        elseif hegemony_source_query(self,'isWeak',player) and player:getArmor()then card_id=player:getArmor():getId()
        elseif hegemony_source_query(self,'isWeak',player) and player:getDefensiveHorse()then card_id=player:getDefensiveHorse():getId()end
    end
    return card_id and "$"..card_id or "."
end
local ordinary_xiaoguo_need=sgs.ai_cardneed.xiaoguo
sgs.ai_cardneed.xiaoguo=function(to,card)
    local room=rawget(to,"_room");local self=room and rawget(room,"_ai")
    if not self then ai_unsupported("cardneed viewer absent","xiaoguo")end
    if not original_enabled(self)then return ordinary_xiaoguo_need(to,card)end
    return getKnownCard(to,current_for_cardneed(to),"BasicCard",true)==0 and card:getTypeId()==sgs.Card_TypeBasic
end
local ordinary_shushen=sgs.ai_skill_playerchosen.shushen
