-- Narrow dependencies of the Xiaoguo override, without replacing ordinary
-- damage/HP policy or exposing another player's hidden Slash.
local function original_ignore_armor(from,to)
    local armor=to:getArmor()
    if not armor then return true end
    if not to:hasArmorEffect(armor:objectName()) or from:hasWeapon("QinggangSword")then return true end
end
function SmartAIView:originalHegemonyHeavySlashDamage(from,slash,to,get_value)
    from=from or self.room:getCurrent()
    if not slash or not slash:isKindOf("Slash")then
        -- Preserve the donor's 'and/or': owner with no Slash also uses a probe.
        slash=from and self.player:objectName()==from:objectName() and self:getCard("Slash") or self:getEvaluationCard("slash")
    end
    to=to or self.player
    if not from or not to then return false end
    if to:hasArmorEffect("SilverLion") and not original_ignore_armor(from,to)then return get_value and 1 or false end
    local damage=1
    local fire=slash and(slash:isKindOf("FireSlash") or slash:objectName()=="slash" and from:hasWeapon("Fan"))
    if slash and hegemony_source_query(slash,'hasFlag',"drank")then damage=damage+1
    elseif hegemony_source_query(from,'getMark',"drank")>0 then damage=damage+hegemony_source_query(from,'getMark',"drank")end
    if hegemony_source_query(from,'hasFlag',"heg_luoyi")then damage=damage+1 end
    if from:hasWeapon("GudingBlade") and slash and to:isKongcheng()then damage=damage+1 end
    if hegemony_source_query(to,'getMark',"@gale")>0 and fire then damage=damage+1 end
    local chiying=original_find_shown(self,"jgchiying")
    if chiying and chiying:isPublicHegemonyFriend(to)then damage=1 end
    if to:hasArmorEffect("Vine") and not original_ignore_armor(from,to) and fire then damage=damage+1 end
    if get_value then return damage end
    return damage>1
end
function SmartAIView:originalHegemonyGoodHp(player)
    if player:getHp()>1 or getCardsNum("Peach",player,self.player)>=1 or getCardsNum("Analeptic",player,self.player)>=1
        or shown(self,player,"heg_buqu") and player:getPileCount("heg_buqu")<=4
        or shown(self,player,"heg_niepan") and hegemony_source_query(player,'getMark',"@nirvana")>0
        or shown(self,player,"heg_jizhao") and hegemony_source_query(player,'getMark',"@heg_jizhao")>0 then return true end
    local n=0
    for _,friend in ipairs(self:getFriends(player))do
        local current=self.room:getCurrent()
        if not(current and shown(self,current,"wansha") and player:objectName()~=friend:objectName())then
            n=n+getCardsNum("Peach",friend,self.player)
        end
    end
    return n>0
end
local original_need_damaged={}
original_need_damaged.heg_sidi=function()end -- heg-overseas-ai.lua:323, empty donor callback.
original_need_damaged.heg_jieming=function(self,attacker,player)
    if not shown(self,player,"heg_jieming")then return false end
    local maximum=0
    for _,friend in ipairs(self:getFriends(player))do maximum=math.max(maximum,math.min(friend:getMaxHp(),5)-friend:getHandcardNum())end
    return maximum>=3
end
original_need_damaged.heg_yiji=function(self,attacker,player)
    if not shown(self,player,"heg_yiji")then return end
    local current=self.room:getCurrent();local need=false
    if hegemony_source_query(self,'hasCrossbowEffect',current) or shown(self,current,"heg_paoxiao") or hegemony_source_query(current,'hasFlag',"shuangxiong")then need=true end
    if original_shown_skills(self,current,"jieyin|jijiu") and hegemony_source_query(self,'getOverflow',current)<=0 then need=true end
    if self:isFriend(current,player) and need then return true end
    if #self.friends>0 then
        self:sortInPlace(self.friends, "hp")
        if self.friends[1]:objectName()==player:objectName() and hegemony_source_query(self,'isWeak',player) and getCardsNum("Peach",player,attacker or self.player)==0 then return false end
        if #self.friends>1 and hegemony_source_query(self,'isWeak',self.friends[2])then return true end
    end
    return player:getHp()>2 and self.room:getTurnCount()>2 and #self.friends>1
end
original_need_damaged.heg_wanggui=function(self,attacker,player)
    if not shown(self,player,"heg_wanggui") or hegemony_source_query(player,'hasFlag',"WangguiUsed")then return false end
    if known(heg_player(self,player).shown_all,"shown all")then
        local kingdom=player:getKnownKingdom();local count=0
        for _,p in ipairs(self.room:getAlivePlayers())do
            local faction=known(heg_player(self,p).public_kingdom,"public kingdom")
            if faction~=""then if faction=="careerist"then if kingdom=="careerist"then count=1 end elseif faction==kingdom then count=count+1 end end
        end
        if count>2 then return true end
    end
    if known(heg_player(self,player).shown_one,"shown one")then
        for _,p in ipairs(self:getEnemies(player))do if p:getHp()==1 and hegemony_source_query(self,'isWeak',p)then return true end end
    end
    return false
end
local function original_jieming_draw(self,player)
    local maximum=0
    for _,friend in ipairs(self:getFriends(player))do maximum=math.max(maximum,math.min(friend:getMaxHp(),5)-friend:getHandcardNum())end
    return maximum
end
local function original_good_target(self,player,targets)
    if targets and type(targets)=="table"then
        if #targets==1 then return true end
        local found=false
        for _,p in ipairs(targets)do if original_good_target(self,p) and not self:cantbeHurt(p)then found=true;break end end
        if not found then return true end
    end
    local masochism=false
    for _,skill in ipairs({"heg_jieming","heg_yiji","mobilefangzhu"})do
        if shown(self,player,skill)then
            if skill=="heg_jieming" and original_jieming_draw(self,player)<2 then masochism=false
            elseif skill=="heg_yiji" and not self:originalHegemonyHasDrawFriend(player)then masochism=false
            else masochism=true;break end
        end
    end
    return not(masochism and self:originalHegemonyGoodHp(player) and not self.player:hasSkills("heg_tieqi|heg_tieqi_xh|heg_yinbing"))
end
local function original_turn_over(self,player,n)
    if not player:faceUp()then return false end
    if n>1 then
        if player:getPhase()~=sgs.Player_NotActive and(original_shown_skills(self,player,original_category(self,"Active_cardneed_skill")) or hegemony_source_query(self,'hasCrossbowEffect',player))
            or player:getPhase()==sgs.Player_NotActive and original_shown_skills(self,player,original_category(self,"notActive_cardneed_skill"))then return false end
    end
    if not self:isFriend(player) and shown(self,player,"heg_jushou") and player:getPhase()<=sgs.Player_Finish then return false end
    return true
end
original_need_damaged.heg_ganglie=function(self,attacker,player)
    if not attacker then return end
    return self:isEnemy(attacker) and attacker:getHp()+attacker:getHandcardNum()<=3
        and not(original_shown_skills(self,attacker,"heg_kongcheng|heg_buqu") and attacker:getHandcardNum()>1)
        and original_good_target(self,attacker,self:getEnemies(attacker))
end
original_need_damaged.heg_fudi=function(self,attacker,player)
    if not attacker or self:isFriend(attacker)then return end
    if self.player:getPhase()~=sgs.Player_NotActive then return false end
    return self:isEnemy(attacker) and attacker:getHp()>=self.player:getHp()-1 and hegemony_source_query(self,'isWeak',attacker)
        and hegemony_source_query(self,'damageIsEffective',attacker,nil,self.player) and not shown(self,attacker,"heg_buqu")
        and original_good_target(self,attacker,self:getEnemies(attacker))
end
original_need_damaged.mobilefangzhu=function(self,attacker,player)
    if not shown(self,player,"mobilefangzhu")then return end
    local enemies=self:getEnemies(player)
    if #enemies<1 then return false end
    self:sortInPlace(enemies, "defense")
    for _,enemy in ipairs(enemies)do if player:getLostHp()<1 and original_turn_over(self,enemy,player:getLostHp()+1)then return true end end
    local friends={}
    for _,p in ipairs(self.room:getAlivePlayers())do if self:isFriend(p,player) and p:objectName()~=player:objectName()then friends[#friends+1]=p end end
    for _,friend in ipairs(friends)do
        if not friend:faceUp() and(player:getHp()>1 or getCardsNum("Peach",player,attacker or self.player)>0 or getCardsNum("Analeptic",player,attacker or self.player)>0)then return true end
    end
    self:sortInPlace(friends, "hp")
    for _,friend in ipairs(friends)do if not original_turn_over(self,friend,player:getLostHp()+1)then return true end end
    return false
end
original_need_damaged.nosfankui=function(self,attacker,player)
    -- Preserve the source's hasSkill (singular), including its literal '+' name.
    -- Native Player::hasSkill does not interpret conjunctions here.
    if not player:hasSkill("guicai+nosfankui")then return false end
    if not attacker then return end
    local function need_retrial(target)
        local alive=self.room:alivePlayerCount()
        return alive+target:getSeat()%alive>(self.room:getCurrent()):getSeat() and target:getSeat()<alive+player:getSeat()%alive
    end
    local retrial,other={},{}
    for _,c in ipairs(player:getKnownCards())do
        local suit=c:getSuit()
        if suit==sgs.Card_Spade and c:getNumber()>=2 and c:getNumber()<=9 then retrial.spade=true end
        if suit==sgs.Card_Heart then retrial.heart=true end
        if suit==sgs.Card_Club then retrial.club=true end
    end
    local cards={};for _,c in ipairs(attacker:getEquips())do cards[#cards+1]=c end
    local hand=attacker:getKnownCards()
    if attacker:getHandcardNum()==1 and #hand==1 and hegemony_source_query(hand[1],'hasFlag',"visible")then cards[#cards+1]=hand[1]end
    for _,c in ipairs(cards)do
        local suit=c:getSuit()
        if suit==sgs.Card_Spade and c:getNumber()>=2 and c:getNumber()<=9 then other.spade=sgs.Card_Spade end
        if suit==sgs.Card_Heart then other.heart=sgs.Card_Heart end
        if suit==sgs.Card_Club then other.club=sgs.Card_Club end
    end
    for _,p in ipairs(self.room:getOtherPlayers(player))do
        if p:containsTrick("lightning") and self:getFinalRetrial(p)==1 and need_retrial(p) and not retrial.spade and other.spade then return other.spade end
        if self:isFriend(p,player) and not shown(self,p,"qiaobian") and p:containsTrick("indulgence") and self:getFinalRetrial(p)==1 and need_retrial(p)
            and p:getHandcardNum()>=p:getHp() and not retrial.heart and other.heart then return other.heart end
    end
    return false
end
local function original_need_damaged_callback(self,skill)
    local presence=known(heg_facts(self).need_damaged_presence,
        "Original damaged callback metadata")
    if type(presence)~="table"or type(presence[skill])~="boolean"then
        ai_unsupported("Original damaged callback presence missing",skill)
    end
    if not presence[skill]then return nil end
    local callback=original_need_damaged[skill]
    if type(callback)~="function"then ai_unsupported("Original damaged callback is not migrated",skill)end
    return callback
end
function SmartAIView:originalHegemonyNeedDamagedCallback(skill)
    return original_need_damaged_callback(self,skill)
end
function SmartAIView:originalHegemonyNeedDamagedEffects(to,from,is_slash)
    from=from or self.room:getCurrent() or self.player;to=to or self.player
    if is_slash and from:hasWeapon("IceSword") and to:getCardCount(true)>1 and not self:isFriend(from,to)then return false end
    if from:objectName()~=to:objectName() and self:originalHegemonyHeavySlashDamage(from,nil,to)then return false end
    if self:originalHegemonyGoodHp(to)then
        for _,skill in ipairs(to:getVisibleSkillList(true))do
            local name=skill:objectName()
            local callback=original_need_damaged_callback(self,name)
            if callback then
                if callback(self,from,to)then return true end
            end
        end
    end
    return false
end

-- Loader alias and H-prefixed metadata for this same card policy. Function
