sgs.ai_use_priority.HAwaitExhausted=function(self)if original_enabled(self)then return 2.8 end end
sgs.ai_use_value.HAwaitExhausted=function(self)if original_enabled(self)then return 4.9 end end
sgs.ai_keep_value.HAwaitExhausted=function(self)if original_enabled(self)then return 3.22 end end
sgs.ai_card_intention.HAwaitExhausted=function(self,card,from,tos)
