function SmartAIView:originalHegemonyWeak(player)
    player=player or self.player
    if shown(self,player,"heg_buqu") and player:getPileCount("heg_buqu")<=4 then return false end
    if shown(self,player,"heg_niepan") and hegemony_source_query(player,'getMark',"@nirvana")>0
        or shown(self,player,"heg_jizhao") and hegemony_source_query(player,'getMark',"@heg_jizhao")>0 then return false end
    if shown(self,player,"heg_kongcheng") and player:isKongcheng() and player:getHp()>=2 then return false end
    return player:getHp()<=2 and player:getHandcardNum()<=2 or player:getHp()<=1
end
function SmartAIView:originalHegemonyOverflow(player,get_max_cards)
    player=player or self.player
    local maximum=player:getMaxCards()
    if shown(self,player,"qiaobian") and not hegemony_source_query(player,'hasFlag',"AI_ConsideringQiaobianSkipDiscard")then
        maximum=math.max(self.player:getHandcardNum()-1,maximum)
        -- The source clears this same flag only after proving it already false.
    end
    if shown(self,player,"heg_keji") and not hegemony_source_query(player,'hasFlag',"KejiSlashInPlayPhase")then maximum=self.player:getHandcardNum()end
    if get_max_cards then return maximum end
    return player:getHandcardNum()-maximum
end
function SmartAIView:originalHegemonyDamageIsEffective(to,nature,from)
    return self:originalHegemonyDamageIsEffectiveStruct({to=to or self.player,
        from=from or self.room:getCurrent(),nature=nature or sgs.DamageStruct_Normal})
end
-- The original damage hook iterates sgs.ai_damage_effect directly.  Keep the
-- registry opaque to the native projection: a present table is a complete
-- local pure-value callback catalog, while an absent/malformed table remains
-- an explicit capability gap.
local function original_damage_effect_callbacks(self)
    local callbacks=sgs.ai_damage_effect
    if type(callbacks)~="table" then
        ai_unsupported("Original damage-effect registry is unavailable","ai_damage_effect")
    end
    for name,callback in pairs(callbacks)do
        if type(name)~="string" or type(callback)~="function"then
            ai_unsupported("Original damage-effect registry is malformed",tostring(name))
        end
    end
    return callbacks
end
function SmartAIView:originalHegemonyDamageIsEffectiveStruct(damageStruct)
    if type(damageStruct)~="table" or not damageStruct.to then return nil end
    local to,from=damageStruct.to,damageStruct.from
    local nature=damageStruct.nature or sgs.DamageStruct_Normal
    local damage=damageStruct.damage or 1
    if shown(self,to,"heg_mingshi") and from and not original_both_shown(self,from)then
        damage=damage-1
        if damage<1 then return false end
    end
    if to:hasArmorEffect("PeaceSpell") and nature~=sgs.DamageStruct_Normal then return false end
    if original_shown_skills(self,to,"jgyuhuo_pangtong|jgyuhuo_zhuque") and nature==sgs.DamageStruct_Fire then return false end
    if hegemony_source_query(to,'getMark',"@fog")>0 and nature~=sgs.DamageStruct_Thunder then return false end
    if to:hasArmorEffect("Breastplate") and damage>=to:getHp()then return false end
    for name,callback in pairs(original_damage_effect_callbacks(self))do
        local result=callback(self,damageStruct)
        if AIUnsupported.is(result)then error(result,0)end
        if result==false then return false end
    end
    return true
end
-- Nullable equipment getters are exact nil only for a disclosed equipment
-- zone. Do not turn a missing facade capability into the donor empty-slot path.
local function original_equipment(player,method)
    if not player or type(player[method])~="function"then
        ai_unsupported("Original equipment getter is unavailable",method)
    end
    local value=player[method](player)
    if AIUnsupported.is(value)then error(value,0)end
    if value==nil then
        local row=type(player)=="table"and rawget(player,"_view")
        if type(row)=="table"and not AIValue.isList(row.equips)then
            ai_unsupported("Original equipment zone is not disclosed",method)
        end
    end
    return value
end
function SmartAIView:originalHegemonyNeedToThrowArmor(player)
    player=player or self.player
    if not original_equipment(player,"getArmor") or not player:hasArmorEffect((original_equipment(player,"getArmor")):objectName())then return false end
    if shown(self,player,"bazhen") and not (original_equipment(player,"getArmor")):isKindOf("EightDiagram")then return true end
    if self:evaluateArmor(original_equipment(player,"getArmor"),player)<=-2 then return true end
    if player:hasArmorEffect("SilverLion") and player:isWounded()then
        if self:isFriend(player)then
            if player:objectName()==self.player:objectName()then return true end
            return hegemony_source_query(self,'isWeak',player) and not original_shown_skills(self,player,original_category(self,"use_lion_skill"))
        end
        return true
    end
    -- Fixed source accesses .damage on the QVariant itself, not :toDamage().
    -- That field is nil; do not repair it by inspecting private damage state.
    return false
end

local function original_used(self,player,key)
    local used=player:hasUsed(key)
    if used~=nil then return used end
    if player:objectName()==self.player:objectName()then ai_unsupported("owner used history missing",key)end
    return self:useKnowledgeEstimate({value=false,status="estimate",basis="no observed public use; inactive action-history prior",
        viewer=self.player:objectName(),observer=self.player:objectName(),target=player:objectName(),history=key},"OriginalHegemony.hasUsed")
end
function SmartAIView:originalHegemonyNeedToLoseHp(to,from,is_slash,passive,recover)
    to=to or self.player
    if is_slash and from and from:hasWeapon("IceSword") and to:getCardCount()>1 and not self:isFriend(from,to)then return false end
    if from and self:hasHeavySlashDamage(from,nil,to)then return false end
    local n=to:getMaxHp()
    if not passive then
        if shown(self,to,"rende") and to:getMaxHp()>2 and not self:willSkipPlayPhase(to) and self:findFriendsByType(sgs.Friend_Draw,to)then n=math.min(n,to:getMaxHp()-1)
        elseif shown(self,to,"heg_hengzheng") and to==self.player and self:originalHegemonyHengzheng()then n=math.min(n,to:getMaxHp()-1)
        elseif original_shown_skills(self,to,"heg_yinghun_sunjian|heg_yinghun_sunce|heg_zaiqi")then n=math.min(n,to:getMaxHp()-1)end
    end
    local xiangxiang=original_find_shown(self,"jieyin")
    if xiangxiang and xiangxiang:isWounded() and self:isFriend(xiangxiang,to) and not to:isWounded() and to:isMale()
        and(xiangxiang:getPhase()==sgs.Player_Play and xiangxiang:getHandcardNum()>=2 and not original_used(self,xiangxiang,"JieyinCard")
            or self:getEnemyNumBySeat(self.room:getCurrent(),xiangxiang,self.player)<=1)then
        local friends=self:getFriendsNoself(to)
        local need=true;self:sortInPlace(friends, "hp")
        for _,friend in ipairs(friends)do if friend:isMale() and friend:isWounded()then need=false end end
        if need then n=math.min(n,to:getMaxHp()-1)end
    end
    if recover then return to:getHp()>=n end
    return to:getHp()>n
end
-- Fixed Original heg-standard-shu30–81, actual SmartAI method override.
-- This is separate from needRende and from the ordinary standard-ai method.
function SmartAIView:originalHegemonyShouldUseRende()
    if (hegemony_source_query(self,'hasCrossbowEffect') or self:getCardsNum("Crossbow")>0 or self.player:hasSkill("heg_paoxiao")) and self:getCardsNum("Slash")>0 then
        self:sortInPlace(self.enemies, "defense")
        for _,enemy in ipairs(self.enemies)do
            local inAttackRange=self.player:distanceTo(enemy)==1 or self.player:distanceTo(enemy)==2
                and self:getCardsNum("OffensiveHorse")>0 and not original_equipment(self.player,"getOffensiveHorse")
            local inPaoxiaoAttackRange=self.player:distanceTo(enemy)<=self.player:getAttackRange() and self.player:hasSkill("heg_paoxiao")
            if (inAttackRange or inPaoxiaoAttackRange) and self:originalHegemonyIsGoodTarget(enemy,self.enemies)then
                local slashes=self:getCards("Slash")
                local slash_count=0
                for _,slash in ipairs(slashes)do
                    if not self:slashProhibit(slash,enemy) and self:slashIsEffective(slash,enemy)then slash_count=slash_count+1 end
                end
                if slash_count>=enemy:getHp()then return false end
            end
        end
    end
    for _,enemy in ipairs(self.enemies)do
        if enemy:canSlash(self.player) and not self:slashProhibit(nil,self.player,enemy)
            and hegemony_source_query(self,'hasCrossbowEffect',enemy) and getCardsNum("Slash",enemy)>1 and hegemony_source_query(self,'getOverflow')<=0 then return false end
    end
    for _,player in ipairs(self.friends_noself)do
        if(shown(self,player,"haoshi")and not player:containsTrick("supply_shortage"))or shown(self,player,"jijiu")then return true end
    end
    local giveNum=hegemony_source_query(self.player,'getMark',"rende")
    local keepNum=self.player:getHandcardNum()-2+giveNum
    if self.player:hasSkill("heg_kongcheng")and keepNum<=2 then return true
    elseif keepNum<0 and hegemony_source_query(self.player,'getMark',"@firstshow")+hegemony_source_query(self.player,'getMark',"@careerist")==0 then return false end
    if hegemony_source_query(self,'getOverflow')>0 then return true end
    if self.player:getHandcardNum()>keepNum then return true end
    if giveNum>0 and giveNum<2 and(2-giveNum)>=(self.player:getHandcardNum()-keepNum)then return true end
    return false
end

function SmartAIView:originalHegemonyCrossbowEffect(player)
    player=player or self.player
    return player:hasWeapon("Crossbow") or shown(self,player,"heg_paoxiao")
end
function SmartAIView:originalHegemonyNeedKongcheng(player,keep)
    player=player or self.player
    if keep then return player:isKongcheng() and shown(self,player,"heg_kongcheng")end
    local least=0;local shoucheng=original_find_shown(self,"heg_shoucheng")
    if shoucheng and self:isFriend(shoucheng,player)then least=1 end
    if not(player:getHandcardNum()>least) and not player:isKongcheng()then return true end
    -- Preserve source precedence: (not hp)==1 is always false, but invocation
    -- is still evaluated first and can affect its helper caches/order.
    if shown(self,player,"heg_hengzheng") and player==self.player and self:originalHegemonyHengzheng() and not player:getHp()==1 then return true end
    return shown(self,player,"heg_kongcheng")
end
function SmartAIView:originalHegemonyHasDrawFriend(player)
    player=player or self.player
    for _,friend in ipairs(self.room:getAlivePlayers())do
        if self:isFriend(friend,player) and friend:objectName()~=player:objectName() and not hegemony_source_query(self,'needKongcheng',friend,true)then return true end
    end
    return false
end
function SmartAIView:originalHegemonyHengzheng()
    local value=0
    for _,p in ipairs(self.room:getOtherPlayers(self.player))do
        if not(p:isNude() and #p:getJudgingArea()==0)then
            if self:isFriend(p)then
                local good=false
                if #p:getJudgingArea()>0 then value=value+1.5;good=true end
                if hegemony_source_query(self,'needToThrowArmor',p)then value=value+1.2;good=true end
                if #p:getEquips()>0 and original_shown_skills(self,p,original_category(self,"lose_equip_skill"))then value=value+1;good=true end
                if shown(self,p,"heg_tuntian")then value=value+0.5;good=true end
                if hegemony_source_query(self,'needKongcheng',p,false,true) and p:getHandcardNum()==1 then value=value+0.8;good=true end
                if not good then value=value-1 end
            elseif self:isEnemy(p)then
                if p:isNude()then value=value-1.5
                else
                    if self:getDangerousCard(p) or self:getValuableCard(p)then
                        value=value+0.8
                        if original_shown_skills(self,p,original_category(self,"lose_equip_skill"))then value=value-1 end
                    elseif #p:getEquips()==0 then
                        if hegemony_source_query(self,'needKongcheng',p,false,true) and p:getHandcardNum()==1 then value=value-0.8 end
                        if getKnownCard(p,self.player,"Peach",true,"h")>0 or getKnownCard(p,self.player,"Analeptic",true,"h")>0 then value=value+2/p:getHandcardNum()end
                    elseif p:isKongcheng()then
                        if #p:getEquips()==1 and hegemony_source_query(self,'needToThrowArmor',p)then value=value-1 end
                        if original_shown_skills(self,p,original_category(self,"lose_equip_skill"))then value=value-1 end
                    end
                    if shown(self,p,"heg_tuntian")then value=value-0.5 end
                    value=value+1
                end
            else value=value+1 end
        end
    end
    return value>2
end

-- Original common 3851–3870. The donor indexes equipment by objectName,
-- not class name; its capitalized armor registrations are therefore not silently
-- substituted for absent lower-case keys. First skill callback returns early.
function SmartAIView:originalHegemonyEvaluateArmor(card,player)
    player=player or self.player
    local ecard=card or original_equipment(player,"getArmor")
    if not ecard then return 0 end
    local value=0
    if shown(self,player,"jijiu") and ecard:isRed()then value=value+0.5 end
    if original_shown_skills(self,player,"qixi|guidao") and ecard:isBlack()then value=value+0.5 end
    local presence=known(AIHegemony.facts(self.world).armor_value_presence,"original armor callback metadata")
    for _,skill in ipairs(player:getVisibleSkillList())do
        local name=skill:objectName()
        if known(presence[name],"original armor callback:"..name)then
            -- The only skill-key callback in the admitted fixed original bundle.
            -- bazhen returns nil for nonnil ecard; preserve the early return.
            if name=="bazhen"then return value end
            ai_unsupported("Original armor skill callback is not migrated",name)
        end
    end
    local name=ecard:objectName()
    if known(presence[name],"original armor callback:"..name)then
        ai_unsupported("Original armor object-name callback is not migrated",name)
    end
    return value+0.5
end

-- Original common3071 counts visible cards only; it has neither the ordinary
-- +1 hidden-hand heuristic nor comma-union parsing. Only Wooden Ox is appended.
function SmartAIView:originalHegemonyKnownCard(player,from,class,viewas,flags,return_table)
    if not player or(flags and type(flags)~="string")then return 0 end
    flags=flags or "h"
    local cards=known(getKnownCards(player,self.player,flags:gsub("&","")),"Original visible cards")
    if flags:find("j",1,true)then for _,card in ipairs(player:getJudgingArea())do cards[#cards+1]=card end end
    if flags:find("h",1,true)then
        local view=rawget(player,"_view")
        local piles=known(view and view.piles,"Original Wooden Ox visibility")
        for _,pile in ipairs(piles)do
            if pile.name=="wooden_ox" then
                local rows=pile.cards or{}
                if player:objectName()==self.player:objectName() and #rows~=player:getPileCount("wooden_ox")then
                    ai_unsupported("owner Wooden Ox identities are not projected","getKnownCard.wooden_ox")
                end
                for _,row in ipairs(rows)do cards[#cards+1]=CardView.new(row)end
            end
        end
    end
    local matches={};local estimate=false
    for _,card in ipairs(cards)do
        local converted,coverage
        if viewas then converted,coverage=self:originalHegemonyIsCard(class,card,player)end
        if coverage and coverage.status=="estimate" then estimate=true end
        if converted or card:isKindOf(class)
            or((class=="club"or class=="spade"or class=="diamond"or class=="heart")and card:getSuitString()==class)
            or(class=="red"and card:isRed())or(class=="black"and card:isBlack())then matches[#matches+1]=card end
    end
    local result={value=#matches,status=estimate and "estimate"or "exact",basis="original_visible_card_count",known_count=#matches,
        viewer=self.player:objectName(),observer=from and from:objectName()or self.player:objectName(),target=player:objectName()}
    if result.status=="estimate" then self:useKnowledgeEstimate(result,"Original.getKnownCard")end
    if return_table then return matches,result end
    return #matches,result
end

function SmartAIView:originalHegemonyCanBeChained(to,from)
    if to:isChained()or not to:hasArmorEffect("IronArmor",from)then return true end
    local facts=heg_facts(self)
    local byTo=facts.can_be_chained_by and facts.can_be_chained_by[to:objectName()]
    if byTo and type(byTo[from:objectName()])=="boolean"then return byTo[from:objectName()]end
    local counts={};local maximum=0
    for _,p in ipairs(self.room:getAlivePlayers())do
        if known(heg_player(self,p).shown_one,"shown one")then
            local kingdom=public_kingdom(self,p)
            local key=kingdom:find("careerist",1,true)and p:objectName()or kingdom
            if key~="unknown" then counts[key]=(counts[key]or 0)+1;maximum=math.max(maximum,counts[key])end
        end
    end
    local kingdom=public_kingdom(self,to)
    local key=kingdom:find("careerist",1,true)and to:objectName()or kingdom
    local possible=maximum==0 or(known(heg_player(self,to).shown_one,"shown one")and(counts[key]or 0)==maximum)
    return self:useKnowledgeEstimate({value=possible,status="estimate",viewer=self.player:objectName(),target=to:objectName(),
        basis="IronArmor public revealed kingdom cardinalities; private source-specific BigKingdom modifiers excluded"},"Original.canBeChainedBy")
end
function SmartAIView:originalHegemonyHasTrickEffective(card,to,from)
    from=from or self.room:getCurrent();to=to or self.player
    if to:isRemoved()then return false end
    if not card:isKindOf("TrickCard")then return nil end
    if shown(self,to,"hongyan")and card:isKindOf("Lightning")then return false end
    if shown(self,to,"heg_qianxun")and card:isKindOf("Snatch")then return false end
    if shown(self,to,"heg_qianxun")and card:isKindOf("Indulgence")then return false end
    if card:isKindOf("Indulgence")then
        if to:hasSkills("jgjiguan_qinglong|jgjiguan_baihu|jgjiguan_zhuque|jgjiguan_xuanwu")then return false end
        if to:hasSkills("jgjiguan_bian|jgjiguan_suanni|jgjiguan_chiwen|jgjiguan_yazi")then return false end
    end
    if shown(self,to,"heg_weimu")and card:isBlack()then
        if not(from:objectName()==to:objectName()and card:isKindOf("Disaster"))then return false end
    end
    if shown(self,to,"heg_kongcheng")and to:isKongcheng()and card:isKindOf("Duel")then return false end
    if card:isKindOf("IronChain")and not self:originalHegemonyCanBeChained(to,from)then return false end
    local nature=sgs.DamageStruct_Normal
    if card:isKindOf("FireAttack")or card:isKindOf("BurningCamps")then nature=sgs.DamageStruct_Fire
    elseif card:isKindOf("Drowning")then nature=sgs.DamageStruct_Thunder end
    if(card:isKindOf("Duel")or card:isKindOf("FireAttack")or card:isKindOf("ArcheryAttack")or card:isKindOf("SavageAssault"))and not self:damageIsEffective(to,nature,from)then return false end
    -- Keep the source query order for known values. A concealed armor result
    -- cannot affect this conjunction for a non-fire trick; prove that from the
    -- public card kind instead of requiring hidden armor/skill information.
    if type(to.hasArmorEffect)~="function"then ai_unsupported("Hegemony query unavailable","hasArmorEffect")end
    local iron_armor=to:hasArmorEffect("IronArmor")
    if iron_armor~=false and(card:isKindOf("FireAttack")or card:isKindOf("BurningCamps"))
        and known(iron_armor,"hasArmorEffect")then return false end
    for _,name in ipairs(known(heg_facts(self).trick_prohibit_functions,"Original trick callback catalog"))do
        -- Fixed manoeuvre382 is an empty body. No other fixed source writer.
        if name~="heg_yusui" then ai_unsupported("Original trick prohibition callback is not migrated",name)end
    end
    return true
end
function SmartAIView:originalHegemonyTrickIsEffective(...)return self:originalHegemonyHasTrickEffective(...)end

-- Mode-only Original common1214/4505/4898 and maneuvering359–496.
function SmartAIView:originalHegemonyFriendsNoself(player)
    player=player or self.player
    local friends={}
    for _,p in ipairs(self.room:getAlivePlayers())do
        if self:isFriend(p,player) and p:objectName()~=player:objectName()then friends[#friends+1]=p end
    end
    return friends
end
function SmartAIView:originalHegemonyReward(player)
    if self.player:getKnownRole()=="careerist" or
        (known(heg_facts(self).owner_head_kingdom,"owner original head kingdom")=="careerist" and self.player:hasSkill("heg_shilu"))then return 3 end
    if known(heg_player(self,player).shown_one,"shown one general") and known(heg_player(self,player).public_careerist,"shown careerist")then return 1 end
    local count=1
    for _,p in ipairs(self.room:getOtherPlayers(player))do
        if p:isPublicHegemonyFriend(player)then count=count+1 end
    end
    return count
end
function SmartAIView:originalHegemonyCantbeHurt(player,from,damageNum)
    from=from or self.player;damageNum=damageNum or 1
    if not player then return nil end
    if shown(self,player,"heg_duanchang") and not player:isLord() and #self:originalHegemonyFriendsNoself(player)>0 and player:getHp()<=1 then
        if not(from:getMaxHp()==3 and from:getArmor() and from:getDefensiveHorse())then
            if from:getMaxHp()<=3 or(from:isLord() and hegemony_source_query(self,'isWeak',from))then return true end
        end
    end
    if shown(self,player,"heg_tianxiang") and getKnownCard(player,self.player,"diamond|club",false)<player:getHandcardNum()then
        local peach_num=from:objectName()==self.player:objectName() and self:getCardsNum("Peach")or getCardsNum("Peach",from,self.player)
        local dyingfriend=0
        for _,friend in ipairs(self:getFriends(from))do
            if friend:getHp()<2 and peach_num==0 then dyingfriend=dyingfriend+1 end
        end
        if dyingfriend>0 and player:getHandcardNum()>0 then return true end
    end
    if shown(self,player,"heg_hengzheng") and player:getHandcardNum()~=0 and player:getHp()-damageNum==1
        and (from:getNextAlive()):objectName()==player:objectName()then
        if player:objectName()==self.player:objectName() and self:originalHegemonyHengzheng()then return true end
    end
    return false
end
function SmartAIView:originalHegemonyChainPartner(player)
    player=player or self.player
    if (shown(self,player,"heg_buqu") and player:getPileCount("scars")<=4)
        or(shown(self,player,"heg_niepan") and hegemony_source_query(player,'getMark',"@nirvana")>0)
        or(shown(self,player,"heg_jizhao") and hegemony_source_query(player,'getMark',"@heg_jizhao")>0)
        or self:needToLoseHp(player) or self:needDamagedEffects(player)then return true end
    return false
end
function SmartAIView:originalHegemonyChainTarget(who,source,nature,damagecount,card)
    if not who then return nil end
    if not who:isChained()then return not self:isFriend(who)end
    return self:originalHegemonyChainTargetStruct({to=who,from=source or self.player,nature=nature or sgs.DamageStruct_Fire,damage=damagecount or 1,card=card})
end
function SmartAIView:originalHegemonyChainTargetStruct(damageStruct)
    local to=damageStruct.to
    if not to then return nil end
    if not to:isChained()then return not self:isFriend(to)end
    local from=damageStruct.from or self.player
    local nature=damageStruct.nature or sgs.DamageStruct_Fire
    local damage=damageStruct.damage or 1
    local card=damageStruct.card
    if card and card:isKindOf("Slash")then
        nature=known((sgs.Slash_Natures or{})[card:getClassName()],"Original Slash nature")
        damage=self:hasHeavySlashDamage(from,card,to,true)
    end
    if nature==sgs.DamageStruct_Fire and hegemony_source_query(to,'getMark',"@gale")>0 then damage=damage+1 end
    if not self:damageIsEffective_(damageStruct)then return nil end
    if card and card:isKindOf("TrickCard") and not self:hasTrickEffective(card,to,self.player)then return nil end
    if nature==sgs.DamageStruct_Fire and from:hasSkill("heg_xinghuo")then damage=damage+1 end
    local zidan=original_find_shown(self,"jgchiying")
    if zidan and zidan:isPublicHegemonyFriend(to)then damage=1 end
    if nature==sgs.DamageStruct_Fire and to:hasArmorEffect("Vine")then damage=damage+1 end
    if to:hasArmorEffect("SilverLion")then damage=1 end
    local punish
    local kills,the_enemy=0,nil
    local good,bad,F_count,E_count=0,0,0,0
    local peach_num=from:objectName()==self.player:objectName() and self:getCardsNum("Peach")or getCardsNum("Peach",from,self.player)
    local function value(target,dmg)
        local newvalue=0
        if self:isGoodChainPartner(target)then newvalue=newvalue+(self:isFriend(target)and 1 or -1)end
        if hegemony_source_query(self,'isWeak',target)then newvalue=newvalue+(self:isFriend(target)and -1 or 1)end
        if dmg and nature==sgs.DamageStruct_Fire then
            if target:hasArmorEffect("Vine")then dmg=dmg+1 end
            if hegemony_source_query(target,'getMark',"@gale")>0 then dmg=dmg+1 end
        end
        if self:cantbeHurt(target,from,damage)then newvalue=newvalue-100 end
        if damage+(dmg or 0)>=target:getHp()then
            if self:isFriend(target)or self:isFriend(from)then newvalue=newvalue-self:getReward(to)end
            if self:isFriend(from)and self:isFriend(target)and not punish and getCardsNum("Peach",from,self.player)+getCardsNum("Peach",target,self.player)==0 then
                punish=true;newvalue=newvalue-from:getCardCount(true)
            end
            if self:isEnemy(target)then kills=kills+1 end
            if target:objectName()==self.player:objectName() and #self.friends_noself==0 and peach_num<damage+(dmg or 0)then newvalue=newvalue-100 end
        elseif self:isEnemy(target) and self:isFriend(from) and from:getHandcardNum()<2 and original_shown_skills(self,target,"heg_ganglie") and from:getHp()==1 and self:damageIsEffective(from,nil,target) and peach_num<1 then newvalue=newvalue-100 end
        if target:hasArmorEffect("SilverLion")then return newvalue+(self:isFriend(target)and 1 or -1)end
        return newvalue-damage*2-(dmg and dmg*2 or 0)
    end
    local v=value(to)
    if self:isFriend(to)then good=v;F_count=F_count+1 elseif self:isEnemy(to)then bad=v;E_count=E_count+1 end
    if nature==sgs.DamageStruct_Normal then return good>bad end
    if card and card:isKindOf("FireAttack") and from:objectName()==to:objectName()then good=good-1 end
    for _,player in ipairs(self.room:getAllPlayers())do
        -- Preserve the donor's alias and cumulative damage mutation even for
        -- nonchained players. This is a local pure DTO, never native damage state.
        local nextDamage=damageStruct;nextDamage.to=player
        if nature==sgs.DamageStruct_Fire and player:hasArmorEffect("Vine")then nextDamage.damage=nextDamage.damage+1 end
        if player:objectName()~=to:objectName() and player:isChained() and self:damageIsEffective_(nextDamage)
            and not(card and card:isKindOf("FireAttack")and not self:hasTrickEffective(card,to,self.player))then
            local score=value(player,0)
            if kills==#self.enemies and self:originalHegemonyGetDefenseSlash(player)<2 then
                local current=self.room:getCurrent()
                if card and current and from:objectName()==current:objectName() and from:getPhase()==sgs.Player_Play then self:setStrategyCardFlag(card,"AIGlobal_KillOff",true)end
                return true
            end
            if self:isFriend(player)then good=good+score;F_count=F_count+1 else bad=bad+score;E_count=E_count+1;the_enemy=player end
        end
    end
    if card and F_count==1 and E_count==1 and the_enemy and the_enemy:isKongcheng()and the_enemy:getHp()==1 then
        for _,c in ipairs(self:getCards("Slash"))do if not c:isKindOf("NatureSlash")and not self:slashProhibit(c,the_enemy,from)then return nil end end
    end
    if F_count>0 and E_count<=0 then return nil end
    return good>bad
end

