-- Append inside isolated/hegemony-ai.lua, sharing its local original_enabled/q.
-- Actual callback: original-hegemony/heg-basara-ai.lua:31-62.
-- Native entry: HegNullification::use -> askForChoice("heg_nullification",
-- "single+all", CardEffectStruct); mode admission is checked by producer.
local ordinary_heg_nullification_choice = ai_skill_choice.heg_nullification
ai_skill_choice.heg_nullification = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end
    local data=request and self:getDecisionData(request) or nil

    if not original_enabled(self) then
        if type(ordinary_heg_nullification_choice)=="function" then
            return  ai_choice_result((ordinary_heg_nullification_choice(self,{reason='heg_nullification',choices=options and options.choices or (choices~=nil and {} or nil),inquiry_scope='ordinary_internal'},request)),options)
        end
        return  ai_choice_result((ordinary_heg_nullification_choice),options)
    end
    local effect=known(data and data:toCardEffect(),"HegNullification effect")
    local card=known(effect.card,"HegNullification effect card")
    if card:isKindOf("AOE") or card:isKindOf("GlobalEffect") then
        -- The donor's isFriendWith is an alias to SmartAI:isFriend.  Preserve
        -- the native public-faction fact separately: a public same-kingdom
        -- target is a confirmed group target, while a strategy-only friend
        -- is deliberately narrowed to this effect.
        local target=known(effect.to,"HegNullification effect target")
        if self.player:isPublicHegemonyFriend(target) then return  ai_choice_result(("all"),options) end
        if self:isFriend(target) then return  ai_choice_result(("single"),options) end
        if self:isEnemy(target) then return  ai_choice_result(("all"),options) end
    end
    if card:isKindOf("HFightTogether") then
        local context=self:getDecisionContext(request)
        local row=known(context.heg_nullification,"HegNullification ordered current-trick targets")
        if type(row)~="table" or row.source~="current_trick_use"
            or row.targets_present~=true or type(row.targets)~="table" then
            ai_unsupported("invalid HegNullification current-trick target receipt","heg_nullification.targets")
        end
        local targets={}
        for _,name in ipairs(row.targets) do
            if type(name)~="string" then ai_unsupported("invalid HegNullification target name","heg_nullification.targets") end
            targets[#targets+1]=known(self.room:findPlayerByObjectName(name,true),"HegNullification target")
        end
        if #targets==0 then
            ai_unsupported("donor source error: HFightTogether dereferences empty target tag","heg_nullification.empty_targets")
        end
        local ed,no=0,0
        for _,p in ipairs(targets) do
            if p:objectName()~=(targets[1]):objectName() and p:isChained() then ed=ed+1 end
            if p:objectName()~=(targets[1]):objectName() and not p:isChained() then no=no+1 end
        end
        if (targets[1]):isChained() then
            if no>ed then return  ai_choice_result(("single"),options) end
        elseif ed>no then return  ai_choice_result(("single"),options) end
    end
    return  ai_choice_result(("all"),options)
end

-- Original Hegemony source subtree, fixed b6025acc. Install these methods only
-- after the admitted Original bundle mode gate; never overwrite ordinary mode.
local hs_known = AIValue.requireKnown
local function hs_q(object,method,...)
    if AIValue.isPlayer(object)then
        if method=='getMark'then method='getStrategyMark'elseif method=='hasFlag'then method='getStrategyFlag'end
    end
    if not object or type(object[method])~='function'then ai_unsupported('Original Slash dependency unavailable',method)end
    return hs_known(object[method](object,...),method)
end
local function hs_facts(self)return hs_known(AIHegemony.facts(self.world),'hegemony facts')end
local function hs_fact(self,key)
    if key:match('^owner_')then return self:originalHegemonyOwnerFact(key)end
    return hs_known(hs_facts(self)[key],key)
end
local function hs_row(self,p)return hs_known(hs_fact(self,'players')[p:objectName()],'public Hegemony player')end
local function hs_shown(self,p,name)return hs_known(hs_row(self,p).shown_skills,'shown skills')[name]~=nil end
local hs_skill_aliases = {
    nosganglie = {"heg_ganglie"}, nostuxi = {"tenyeartuxi"}, nosluoyi = {"heg_luoyi"},
    nosyiji = {"heg_yiji"}, shensu = {"heg_shensu"},
    duanliang = {"heg_duanliang"}, nosjushou = {"heg_jushou"}, qiangxi = {"heg_qiangxi"},
    jieming = {"heg_jieming"}, fangzhu = {"mobilefangzhu"}, luoshen = {"heg_luoshen"},
    guicai = {"heg_guicai"},
    paoxiao = {"heg_paoxiao"}, kongcheng = {"heg_kongcheng"}, longdan = {"heg_longdan"},
    tieqi = {"heg_tieqi"}, jizhi = {"heg_jizhi"}, liegong = {"heg_liegong"},
    wusheng = {"tenyearwusheng"}, kuanggu = {"tenyearkuanggu"}, huoshou = {"heg_huoshou"}, juxiang = {"heg_juxiang"},
    keji = {"heg_keji"},
    kurou = {"heg_kurou"}, yingzi = {"heg_yingzi_sunce", "heg_yingzi_zhouyu"},
    qicai = {"nosqicai"},
    fanjian = {"heg_fanjian"}, guose = {"heg_guose"}, qianxun = {"heg_qianxun"},
    xiaoji = {"heg_xiaoji"}, yinghun = {"heg_yinghun_sunjian", "heg_yinghun_sunce"},
    tianxiang = {"heg_tianxiang"}, buqu = {"heg_buqu"}, guzheng = {"heg_guzheng"},
    duanbing = {"heg_duanbing"}, fenxun = {"heg_fenxun"}, luanji = {"heg_luanji"},
     weimu = {"heg_weimu"},
	leiji = {"nosleiji"}, duanchang = {"heg_duanchang"},
    wushuang = {"heg_wushuang"}, jiang = {"heg_jiang"},
}
local function hs_shown_skills(self,p,names)
    for group in names:gmatch('[^|]+')do
        local all=true;for name in group:gmatch('[^+]+')do
            local found=false;for _,actual in ipairs(hs_skill_aliases[name]or{name})do if hs_shown(self,p,actual)then found=true;break end end
            if not found then all=false;break end
        end
        if all then return true end
    end
    return false
end
local function hs_find_shown(self,name)
    for _,p in ipairs(self.room:getAllPlayers())do if hs_shown(self,p,name)then return p end end
end
local function hs_both_shown(self,p)local r=hs_row(self,p);return hs_known(r.shown_head,'shown head')and hs_known(r.shown_deputy,'shown deputy')end
local function hs_public_friend(self,a,b)return a:isPublicHegemonyFriend(b)end
local function hs_visible(self,id)
    -- Negative virtual IDs have no engine physical card; source getCard returns
    -- no physical card there. Positive IDs must remain in the lawful domain.
    if type(id)=='number'and id<0 then return nil end
    return hs_known(self:getKnownCardById(id),'lawful source card '..tostring(id))
end
local function hs_target_mod(self,card,kind)
    local method=({distance='getTargetModDistance',extra='getTargetModExtra',residue='getTargetModResidue'})[kind]
    return hs_q(card,hs_known(method,'target modifier kind'),self.player)
end
local function hs_no_response(self,card)return self:cardNoResponseNames(card)end
local function hs_skill(self,name)
    if name==''then return nil end
    return hs_known(self.room:getPublicSkill(name),'skill definition outside the visible roster')
end
local function hs_ignore_armor(self,from,to)
    if not from or not to then return end
    local armor=to:getArmor()
    if not armor then return true end
    if not to:hasArmorEffect(armor:objectName())or from:hasWeapon('QinggangSword')then return true end
end
local function hs_private_jink(self,target)
    -- Fixed common4749 cardIsVisible ignores the formal observer and uses
    -- current_self.player. Preserve that lawful source contract exactly.
    return hs_known(getKnownCard(target,target,'Jink',true,'he'),'Original known Jink')
end

local function hs_original_lack(self,target,kind)
    if type(self.getOriginalHegemonyCardLack)=="function" then return self:getOriginalHegemonyCardLack(target,kind)end
    return self:useKnowledgeEstimate({value=0,status="estimate",basis="no_observed_original_hegemony_card_lack_prior",
        viewer=self.player:objectName(),target=target:objectName(),class=kind},"OriginalAnaleptic.card_lack")
end
-- Unwired hook helpers live on a table: main-chunk locals are capped at 200 (LUAI_MAXVARS) and this file already peaks near that limit.
local hooks_pending = {}
hooks_pending.hs_damage_callbacks = function(self)
    return original_damage_effect_callbacks(self)
end

local function hs_head_kingdom(self,player)
    local row=hs_row(self,player)
    if player:objectName()==self.player:objectName()then return hs_known(hs_facts(self).owner_head_kingdom,'owner head kingdom')end
    return hs_known(row.head_kingdom,'viewer-known head kingdom or exact anjiang fallback')
end
local function hs_public_kingdom(self,player)
    local kingdom=hs_known(hs_row(self,player).public_kingdom,'public kingdom')
    return kingdom~=''and kingdom or'unknown'
end
function SmartAIView:originalHegemonyEvaluateKingdom(player,observer)
    if not player then return 'unknown'end
    if player:objectName()==self.player:objectName()and(not observer or observer==self.player)then
        return player:getRole()=='careerist'and'careerist'or hs_fact(self,'own_kingdom')
    end
    return hs_public_kingdom(self,player)
end
local function hs_null_skill(self,skill,player)
    local value=player:hasSkill(skill)
    if value~=nil then return not value end
    return self:useKnowledgeEstimate({value=true,status='estimate',basis='foreign_unseen_skill_absence_prior',viewer=self.player:objectName(),target=player:objectName(),skill=skill},'OriginalDefense.hasNullSkill')
end

local function hs_siege(self,holder,target)
    return hs_known(hs_known(hs_row(self,holder).siege_targets,'public siege targets')[target:objectName()],'public siege relation')
end
local function hs_jink_limited(self,player,jink)
    local result=player:isCardLimited(jink,sgs.Card_MethodUse)
    if result~=nil then return result end
    if player:objectName()==self.player:objectName()then return hs_known(nil,'owner Jink limitation')end
    return self:useKnowledgeEstimate({value=false,status='estimate',basis='foreign_unprojected_jink_limitation_prior',viewer=self.player:objectName(),target=player:objectName()},'OriginalDefense.JinkLimited')
end

local function hs_careerist(self,player)
    if player:objectName()==self.player:objectName()then return player:getRole()=='careerist'end
    local row=hs_row(self,player)
    if hs_known(row.shown_one,'shown one')then return hs_known(row.public_careerist,'public careerist')end
    return self:useKnowledgeEstimate({value=false,status='estimate',basis='unrevealed_careerist_role_prior',viewer=self.player:objectName(),target=player:objectName()},'OriginalDefense.careerist_role')
end

function SmartAIView:originalHegemonySlashProhibit(card, enemy, from)
	card = card or self:getEvaluationCard("slash")
	from = from or self.player
	if enemy:isRemoved() then return true end

	local nature = sgs.Slash_Natures[card:getClassName()]
	for _, askill in sgs.qlist(enemy:getVisibleSkillList(true)) do
		if hs_shown(self,enemy,askill:objectName()) then
			local filter = sgs.ai_slash_prohibit[askill:objectName()]
			if filter and type(filter) == "function" and filter(self, from, enemy, card) then return true end
		end
	end

	if self:isFriend(enemy,from) then
		if (card:isKindOf("FireSlash") or from:hasWeapon("Fan")) and enemy:hasArmorEffect("Vine")
			and not (enemy:isChained() and self:originalHegemonyIsGoodChainTarget(enemy, from, nil, nil, card)) then return true end
		if enemy:isChained() and card:isKindOf("NatureSlash") and self:originalHegemonySlashIsEffective(card,enemy,from)
			and not self:originalHegemonyIsGoodChainTarget(enemy, from, nature, nil, card) then return true end
		if getCardsNum("Jink",enemy, from) == 0 and enemy:getHp() < 2 and self:originalHegemonySlashIsEffective(card,enemy,from) then return true end
	else
		if card:isKindOf("NatureSlash") and enemy:isChained() and not self:originalHegemonyIsGoodChainTarget(enemy, from, nature, nil, card) and self:originalHegemonySlashIsEffective(card,enemy,from) then
			return true
		end
	end

	return not self:originalHegemonySlashIsEffective(card,enemy,from) -- @todo: param of slashIsEffective
end

function SmartAIView:originalHegemonyCanLiuli(heg_daqiao, another)
if not hs_shown(self,heg_daqiao,"liuli") then return false end
	if type(another) == "table" and not AIValue.isPlayer(another) then
		if #another == 0 then return false end
		for _, target in ipairs(another) do
			if target:getHp() < 3 and self:originalHegemonyCanLiuli(heg_daqiao,target) then return true end
		end
		return false
	end

	if not self:needToLoseHp(another,self.player,true) or not self:needDamagedEffects(another,self.player,true) then return false end
	if hs_shown(self,another,"xiangle") then return false end
	local n = heg_daqiao:getHandcardNum()
	if n > 0 and (heg_daqiao:distanceTo(another) <= heg_daqiao:getAttackRange()) then return true
	elseif heg_daqiao:getWeapon() and heg_daqiao:getOffensiveHorse() and (heg_daqiao:distanceTo(another) <= heg_daqiao:getAttackRange()) then return true
	elseif heg_daqiao:getWeapon() or heg_daqiao:getOffensiveHorse() then return heg_daqiao:distanceTo(another) <= 1
	else return false end
end

function SmartAIView:originalHegemonySlashIsEffective(slash, to, from, ignore_armor)
	if not slash or not to then return end
	from = from or self.player
	if hs_shown(self,to,"heg_kongcheng") and to:isKongcheng() then return false end
	if to:isRemoved() then return false end

	local nature = sgs.Slash_Natures[slash:getClassName()]
	local damage = {}
	damage.from = from
	damage.to = to
	damage.nature = nature
	damage.damage = 1
	if not hs_both_shown(self,from) and hs_shown(self,to,"heg_mingshi") then
		local dummy_use = { to = AIList.new({}) }
		dummy_use.to:append(to)
		local analeptic = self:originalHegemonySearchForAnaleptic(dummy_use, to, slash)
		if analeptic and self:originalHegemonyShouldUseAnaleptic(to, dummy_use) and analeptic:getEffectiveId() ~= slash:getEffectiveId() then
			damage.damage = damage.damage + 1
		end
	end
	if not self:originalHegemonyDamageIsEffective_(damage) then return false end

	if to:hasSkill("jgyizhong") and not to:getArmor() and slash:isBlack() then
		if (from:hasWeapon("DragonPhoenix") or from:hasWeapon("DoubleSword") and (from:isMale() and to:isFemale() or from:isFemale() or to:isMale()))
			and (to:getCardCount(true) == 1 or #self:getEnemies(from) == 1) then
		else
			return false
		end
	end

	if not ignore_armor and  to:hasArmorEffect("IronArmor") and slash:isKindOf("FireSlash") then return false end

	if not (ignore_armor or hs_ignore_armor(self,from, to)) then
		if to:hasArmorEffect("RenwangShield") and slash:isBlack() then
			if (from:hasWeapon("DragonPhoenix") or from:hasWeapon("DoubleSword") and (from:isMale() and to:isFemale() or from:isFemale() or to:isMale()))
				and (to:getCardCount(true) == 1 or #self:getEnemies(from) == 1) then
elseif hs_shown(self,from,"tenyearjianchu") or (hs_shown(self,from,"kuangfu") and not hs_q(from,"hasFlag","kuangfuUsed")) then--需要配合单独判断弃防具
				return true
			else
				return false
			end
		end

		if to:hasArmorEffect("Vine") and not slash:isKindOf("NatureSlash") then
			if (from:hasWeapon("DragonPhoenix") or from:hasWeapon("DoubleSword") and (from:isMale() and to:isFemale() or from:isFemale() or to:isMale()))
				and (to:getCardCount(true) == 1 or #self:getEnemies(from) == 1) then
elseif hs_shown(self,from,"tenyearjianchu") or (hs_shown(self,from,"kuangfu") and not hs_q(from,"hasFlag","kuangfuUsed")) then
				return true
			else
				local skill_name = slash:getSkillName() or ""
				local can_convert = false
				local skill = hs_skill(self,skill_name)
				if not skill or skill:inherits("FilterSkill") then
					can_convert = true
				end
				if not can_convert or not from:hasWeapon("Fan") then return false end
			end
		end
	end

	if slash:isKindOf("ThunderSlash") then
		local f_slash = self:getCard("FireSlash")
		if f_slash and self:hasHeavySlashDamage(from,f_slash,to,true) > self:hasHeavySlashDamage(from,slash,to,true)
			and (not to:isChained() or self:originalHegemonyIsGoodChainTarget(to, from, sgs.DamageStruct_Fire, nil, f_slash)) then
			return self:originalHegemonySlashProhibit(f_slash,to,from)
		end
	elseif slash:isKindOf("FireSlash") then
		local t_slash = self:getCard("ThunderSlash")
		if t_slash and self:hasHeavySlashDamage(from,t_slash,to,true) > self:hasHeavySlashDamage(from,slash,to,true)
			and (not to:isChained() or self:originalHegemonyIsGoodChainTarget(to, from, sgs.DamageStruct_Thunder, nil, t_slash)) then
			return self:originalHegemonySlashProhibit(t_slash,to,from)
		end
	end

	return true
end

function SmartAIView:originalHegemonySlashIsAvailable(player, slash) -- @todo: param of slashIsAvailable
	player = player or self.player
	if slash and not slash:isKindOf("Slash") then
	end
	slash = slash or self:getEvaluationCard("slash")
	return slash:isAvailable(player)
end

function SmartAIView:originalHegemonyFindWeaponToUse(enemy)
	local weaponvalue = {}
	local hasweapon
	for _, c in sgs.qlist(self.player:getHandcards()) do
		if c:isKindOf("Weapon") then
			local dummy_use = { isDummy = true, to = AIList.new({}) }
			self:useEquipCard(c, dummy_use)
			if dummy_use.card then
				weaponvalue[c] = self:originalHegemonyEvaluateWeapon(c,self.player,enemy)
				hasweapon = true
			end
		end
	end
	if not hasweapon then return end
	if self.player:getWeapon() then weaponvalue[self.player:getWeapon()] = self:originalHegemonyEvaluateWeapon(self.player:getWeapon(),self.player,enemy) end
	local max_value, max_card = -1000, nil
	for c, v in pairs(weaponvalue) do
		if v > max_value then
			max_card = c
			max_value = v
		end
	end
	if self.player:getWeapon() and self.player:getWeapon():getEffectiveId() == max_card:getEffectiveId() then return false end
	return max_card
end

function SmartAIView:originalHegemonyIsPriorFriendOfSlash(friend, card, source)
	source = source or self.player
	local heg_huatuo = hs_find_shown(self,"jijiu")
	if source:hasSkill("heg_zhiman") then
		local promo = self:findPlayerToDiscard("ej",false,sgs.Card_MethodGet,nil,true)
		if table.contains(promo, friend) then
			return true
		end
	end
	if not self:hasHeavySlashDamage(source,card,friend)
		and ((self:findLeijiTarget(friend, 50, source) and not hs_shown(self,source,"wushuang"))
		or (hs_shown(self,friend,"heg_jieming") and hs_shown(self,source,"rende") and heg_huatuo and self:isFriend(heg_huatuo,source))) then
		return true
	end
	if card:isKindOf("NatureSlash") and friend:isChained() and self:originalHegemonyIsGoodChainTarget(friend, source, nil, nil, card) then return true end
	return
end

function SmartAIView:originalHegemonyUseCardSlash(card, use)
	if card:getClassName() == "HAocaiCard" then
		card = self:getEvaluationCard("slash")
	end
	if card:getClassName() == "HMiewuCard" then
		card = self:evaluateOriginalHegemonySlashWrapper(card)
	end
	if not use.isDummy and not self:originalHegemonySlashIsAvailable(self.player,card) then return end
	if self.player:hasSkill("heg_xiaoji") and hs_visible(self,card:getEffectiveId()) and hs_visible(self,card:getEffectiveId()):isKindOf("EquipCard")
		and self.room:getCardPlace(card:getEffectiveId()) == sgs.Player_PlaceHand then return end
	local cards = self.player:getCards("he")
	cards = sgs.QList2Table(cards)
	local no_distance = hs_target_mod(self,card,"distance") > 50
						or hs_q(self.player,"hasFlag","slashNoDistanceLimit") or self:originalHegemonyHasWenjiBuff(card)
	local slash_tgnum = 1 + hs_target_mod(self,card,"extra")
	local rangefix = 0
	if card:isVirtualCard() then
		if self.player:getWeapon() and card:getSubcards():contains(self.player:getWeapon():getEffectiveId()) then
			if self.player:getWeapon():getClassName() ~= "Weapon" then
				rangefix = hs_known(self:originalHegemonyWeaponRange(self.player:getWeapon():getClassName()),"Original weapon range") - self.player:getAttackRange(false)
			end
		end
		if self.player:getOffensiveHorse() and card:getSubcards():contains(self.player:getOffensiveHorse():getEffectiveId()) then
			rangefix = rangefix + 1
		end
	end

	local function canAppendTarget(target)
		if self.player:hasSkill("heg_paoxiao") then--咆哮屯杀
			local enough_pxslash = false
			if self:getCardsNum("Slash") > 0 then
			  local yongjue_slash = 0
			  if hs_q(self.player,"getMark","GlobalPlayCardUsedTimes") == 0 then
				for _, p in ipairs(self.friends) do
					if hs_shown(self,p,"heg_yongjue") and hs_public_friend(self,self.player,p) then--hs_fact(self,"owner_slash_count") == 0
					yongjue_slash = 1
					break
					end
				end
			  end
			  if yongjue_slash + hs_fact(self,"owner_slash_count") + self:getCardsNum("Slash") >= 2 then
				enough_pxslash = true
			  end
			end
			if not enough_pxslash and self:getOverflow() <= 0 and not (target:getHp() == 1 and self:isWeak(target))
			and not (self.player:hasSkill("heg_jili") and hs_fact(self,"owner_card_used_times") + hs_fact(self,"owner_card_responded_times") + 1 == self.player:getAttackRange()) then
				return false
			end
		end
		local targets = AIList.new({})
		if use.to and not use.to:isEmpty() then
			if use.to:contains(target) then return false end
			for _, to in sgs.qlist(use.to) do
				targets:append(to)
			end
		end
		return self:cardTargetFilter(card,targets,target)
	end

	for _, friend in ipairs(self.friends_noself) do
		if self:originalHegemonyIsPriorFriendOfSlash(friend, card) and not self:originalHegemonySlashProhibit(card,friend) then
			if (not use.current_targets or not table.contains(use.current_targets, friend:objectName()))
				and (self.player:canSlash(friend,card,not no_distance,rangefix)
				or (use.isDummy and (self.player:distanceTo(friend,rangefix) <= self.predictedRange)))
				and self:originalHegemonySlashIsEffective(card,friend) then
				use.card = card
				if use.to and canAppendTarget(friend) then
					use.to:append(friend)
				end
				if not use.to or slash_tgnum <= use.to:length() then
					return
				end
			end
		end
	end

	local targets = {}
	local forbidden = {}
	self:originalHegemonySort(self.enemies, "defenseSlash")
	for _, enemy in ipairs(self.enemies) do
		if not self:originalHegemonySlashProhibit(card,enemy) and self:originalHegemonyIsGoodTarget(enemy,self.enemies,true) then
			if not self:needDamagedEffects(enemy,self.player,true) then
				table.insert(targets, enemy)
			else
				table.insert(forbidden, enemy)
			end
		end
	end
	if #targets == 0 and #forbidden > 0 then targets = forbidden end
	local canSlashTargets = {}

	for _, target in ipairs(targets) do
		local canliuli = false
		for _, friend in ipairs(self.friends_noself) do
			if self:originalHegemonyCanLiuli(target,friend) and self:originalHegemonySlashIsEffective(card,friend) and #targets > 1 and friend:getHp() < 3 then canliuli = true end
		end
		if (not use.current_targets or not table.contains(use.current_targets, target:objectName()))
			and (self.player:canSlash(target,card,not no_distance,rangefix)
				or (use.isDummy and self.predictedRange and self.player:distanceTo(target,rangefix) <= self.predictedRange))
			and self:objectiveLevel(target) > 3
			and not canliuli then


			if target:getHp() > 1 and hs_shown(self,target,"nosjianxiong") and self.player:hasWeapon("Spear") and card:getSkillName() == "Spear" then
				local ids, isGood = card:getSubcards(), true
				for _, id in sgs.qlist(ids) do
					local c = hs_visible(self,id)
					if isCard("Peach", c, target) or isCard("Analeptic", c, target) then isGood = false break end
				end
				if not isGood then continue end
			end

			-- fill the card use struct
			local usecard = card
			if not use.to or use.to:isEmpty() then
				if self.player:hasWeapon("Spear") and card:getSkillName() == "Spear" then
				elseif self.player:hasWeapon("Crossbow") and self:getCardsNum("Slash") > 0 then
				elseif not use.isDummy then
					local weapon = self:originalHegemonyFindWeaponToUse(target)
					if weapon then
						use.card = weapon
						return
					end
				end

				if target:isChained() and self:originalHegemonyIsGoodChainTarget(target, nil, nil, nil, card) and not use.card then
					if self:hasCrossbowEffect() and card:isKindOf("NatureSlash") then
						for _, slash in ipairs(self:getCards("Slash")) do
							if not slash:isKindOf("NatureSlash") and self:originalHegemonySlashIsEffective(slash,target)
								and not self:originalHegemonySlashProhibit(slash,target) then
								usecard = slash
								break
							end
						end
					elseif not card:isKindOf("NatureSlash") then
						local slash = self:getCard("NatureSlash")
						if slash and self:originalHegemonySlashIsEffective(slash,target) and not self:originalHegemonySlashProhibit(slash,target) then usecard = slash end
					end
				end
				local godsalvation = self:getCard("GodSalvation")
				if not use.isDummy and godsalvation and godsalvation:getId() ~= card:getId() and self:willUseGodSalvation(godsalvation) and
					(not target:isWounded() or not self:originalHegemonyTrickIsEffective(godsalvation,target,self.player)) then
					use.card = godsalvation
					return
				end
			end

			use.card = use.card or usecard
			if not use.isDummy and canAppendTarget(target) then--酒和技能配合处理？
				local analeptic = self:originalHegemonySearchForAnaleptic(use, target, use.card or usecard)
				if analeptic and self:originalHegemonyShouldUseAnaleptic(target, use) and analeptic:getEffectiveId() ~= card:getEffectiveId() then
					use.card = analeptic
					if use.to then use.to = AIList.new({}) end
					return
				end
			end

			if self.player:hasSkill("heg_duanbing") or (self.player:hasSkills("tenyearkuanggu|heg_kuanggu_xh") and self:hasCrossbowEffect()) then--需要额外筛选目标的技能，但是酒怎么处理？
				table.insert(canSlashTargets, target)
				continue
			end

			if use.to and canAppendTarget(target) then
				use.to:append(target)
			end
			if not use.to or slash_tgnum <= use.to:length() then
				return
			end
		end
	end

	if self.player:hasSkill("heg_duanbing") and #canSlashTargets > 0 then
		for _, target in ipairs(canSlashTargets) do
			if self.player:distanceTo(target) > 1 then--短兵先选远的目标
				if use.to and canAppendTarget(target) then
					use.to:append(target)
				end
				if not use.to or slash_tgnum <= use.to:length() then
					return
				end
			end
		end
		for _, target in ipairs(canSlashTargets) do
			if use.to and canAppendTarget(target) then
				use.to:append(target)
			end
			if not use.to or slash_tgnum <= use.to:length() then
				return
			end
		end
	end

	if self.player:hasSkills("tenyearkuanggu|heg_kuanggu_xh") and self:hasCrossbowEffect() and #canSlashTargets > 0 then
		for _, target in ipairs(canSlashTargets) do
			if self.player:distanceTo(target) < 2 then--狂骨先选距离1的目标，残血回复的情况？
				if use.to and canAppendTarget(target) then
					use.to:append(target)
				end
				if not use.to or slash_tgnum <= use.to:length() then
					return
				end
			end
		end
		for _, target in ipairs(canSlashTargets) do
			if use.to and canAppendTarget(target) then
				use.to:append(target)
			end
			if not use.to or slash_tgnum <= use.to:length() then
				return
			end
		end
	end

	for _, friend in ipairs(self.friends_noself) do
		if (not use.current_targets or not table.contains(use.current_targets, friend:objectName()))
			and not self:originalHegemonySlashProhibit(card,friend) and not self:hasHeavySlashDamage(self.player,card,friend)
			and (self:needDamagedEffects(friend,self.player) or self:needToLoseHp(friend,self.player,true,true))
			and (self.player:canSlash(friend,card,not no_distance,rangefix)
				or (use.isDummy and self.predictedRange and self.player:distanceTo(friend,rangefix) <= self.predictedRange)) then
			use.card = card
			if use.to and canAppendTarget(friend) then use.to:append(friend) end
			if not use.to or slash_tgnum <= use.to:length() then
				return
			end
		end
	end
	if use.to and use.to:isEmpty() then
		use.card = nil
	end
end

function SmartAIView:originalHegemonyShouldUseAnaleptic(target, card_use)
	if self:originalHegemonyEvaluateKingdom(target) == "unknown" then return false end

	if not hs_ignore_armor(self,self.player, target) then
		if target:hasArmorEffect("SilverLion") then return false end
		if target:hasArmorEffect("Breastplate") and target:getHp() <= 2 then return false end
	end

	for _, p in sgs.qlist(self.room:getAlivePlayers()) do
		if hs_shown(self,p,"heg_qianhuan") and not p:getPile("sorcery"):isEmpty() and p:getKingdom() == target:getKingdom() and card_use.to:length() <= 1 then
			return false
		end
	end
	if ((hs_shown(self,target,"heg_buqu") and target:getPile("scars"):length()<=4) or (hs_shown(self,target,"heg_niepan") and hs_q(target,"getMark","@nirvana")>0 or hs_shown(self,target,"heg_jizhao") and hs_q(target,"getMark","@heg_jizhao")>0)) and target:getHp() == 1 then
		return false
	end
	if hs_shown(self,target,"heg_gongqing") and self.player:getAttackRange() < 3 then
		return false
	end

	if hs_shown(self,target,"xiangle") then
		local basicnum = 0
		for _, acard in sgs.qlist(self.player:getHandcards()) do
			if acard:getTypeId() == sgs.Card_TypeBasic and not acard:isKindOf("Peach") then basicnum = basicnum + 1 end
		end
		if basicnum < 3 then return false end
	end

	if card_use.card then
		if target:hasArmorEffect("PeaceSpell") and card_use.card and card_use.card:isKindOf("NatureSlash") then return false end

		local noresponse = hs_no_response(self,card_use.card)--新增卡牌无法响应
		if noresponse and (table.contains(noresponse,target:objectName()) or table.contains(noresponse,"_ALL_PLAYERS")) then
			return true
		end
	end

	if self:originalHegemonyCanLiegong(target, self.player) then
		return true
	end
	if self.player:hasWeapon("Axe") and self.player:getCardCount(true) > 4 then
		return true
	end
	if self.player:hasSkills("wushuang|heg_wushuang_lvlingqi") then
		if hs_private_jink(self,target) >= 2 then return false end
		return getCardsNum("Jink", target, self.player) < 2
	end
	if self.player:hasSkills("heg_tieqi|heg_tieqi_xh") then
		return true
	end
if hs_shown(self,self.player,"tenyearjianchu") and (target:hasEquip() or target:getCardCount(true) == 1) then
		return true
	end
	if hs_q(target,"getMark","##heg_qianxi+no_suit_red") > 0 and not hs_shown(self,target,"qingguo") then
		return true
	end
	if self.player:hasWeapon("DragonPhoenix") and target:getCardCount(true) == 1 then
		return true
	end
	if getKnownCard(target, self.player, "Jink", true, "he") >= 1 and not (self:getOverflow() > 0 and self:getCardsNum("Analeptic") > 1) then return false end
	return self:getCardsNum("Analeptic") > 1 or getCardsNum("Jink", target, self.player) < 1 or hs_original_lack(self,target,"Jink") == 1 or self:getOverflow() > 0
end

function SmartAIView:originalHegemonySearchForAnaleptic(use, enemy, slash)
    local sourceToUse=self:getOriginalHegemonyCurrentTurnUse()
	if not sourceToUse then return nil end
	if not use.to then return nil end

	local analeptic = self:getCard("Analeptic")
	if not analeptic then return nil end

	local analepticAvail = 1 + hs_target_mod(self,analeptic,"residue")
	local slashAvail = 0

	for _, card in ipairs(sourceToUse) do
		if analepticAvail == 1 and card:getEffectiveId() ~= slash:getEffectiveId() and card:isKindOf("Slash") then return nil end
		if card:isKindOf("Slash") then slashAvail = slashAvail + 1 end
	end

	if analepticAvail > 1 and analepticAvail < slashAvail then return nil end
	if not hs_fact(self,"owner_analeptic_available") then return nil end

	local cards = self.player:getHandcards()
	cards = sgs.QList2Table(cards)
	self:fillSkillCards(cards)
	local allcards = self.player:getCards("he")
	allcards = sgs.QList2Table(allcards)

	local card_str = self:getCard("Analeptic")
	if card_str then return card_str end

	for _, anal in ipairs(cards) do
		if (anal:getClassName() == "Analeptic") and anal:getEffectiveId() ~= slash:getEffectiveId() then
			return anal
		end
	end
end

function SmartAIView:originalHegemonyUseBasicCard(card, use)
	if not card then  return end
	if self:originalHegemonyNeedRende() then return end
	self:useCardByClassName(card, use)
end

function SmartAIView:originalHegemonyNeedRende()
	return self.player:getLostHp() > 1 and self:originalHegemonyFindFriendsByType(sgs.Friend_Draw) and (self.player:hasSkill("rende") and hs_q(self.player,"getMark","rende") < 3)
end

function SmartAIView:originalHegemonyHasWenjiBuff(card)
	if self.player:hasSkill("heg_wenji") then
    local record_ids = hs_fact(self,"owner_wenji_record"):split("+")
    for _, id in sgs.qlist(card:getSubcards()) do
      if table.contains(record_ids, tostring(id)) then
        return true
      end
    end
    if table.contains(record_ids, tostring(card:getEffectiveId())) then
      return true
    end
  end
	return false
end

function SmartAIView:originalHegemonyCanLiegong(to, from)
	from = from or self.room:getCurrent()
	to = to or self.player
	if not from then return false end
	if hs_shown_skills(self,from, "heg_liegong|heg_liegong_xh") and to:getHp() >= from:getHp() then return true end
	return false
end

function SmartAIView:originalHegemonyDamageIsEffective_(data)
    return self:originalHegemonyDamageIsEffectiveStruct(data)
end

function SmartAIView:originalHegemonyIsGoodTarget(player, targets, isSlash)
	if not self then  end
	local arr = { "heg_jieming", "heg_yiji", "mobilefangzhu" }--其他卖血技能？
	local m_skill = false
	local attacker = self.room:getCurrent()

	if targets and type(targets)=="table" then
		if #targets == 1 then return true end
		local foundtarget = false
		for i = 1, #targets, 1 do
			if self:originalHegemonyIsGoodTarget(targets[i]) and not self:cantbeHurt(targets[i]) then
				foundtarget = true
				break
			end
		end
		if not foundtarget then return true end
	end

	for _, masochism in ipairs(arr) do
		if hs_shown(self,player,masochism) then
			if masochism == "heg_jieming" and self and self:originalHegemonyGetJiemingDrawNum(player) < 2 then m_skill = false
			elseif masochism == "heg_yiji" and self and not self:originalHegemonyFindFriendsByType(sgs.Friend_Draw, player) then m_skill = false
			else
				m_skill = true
				break
			end
		end
	end

	if isSlash and self and (self:hasCrossbowEffect() or self:getCardsNum("Crossbow") > 0) and self:getCardsNum("Slash") > player:getHp() then
		return true
	end

	if isSlash and self and self.player:hasWeapon("Crossbow") and hs_shown_skills(self,player, hs_fact(self,"throw_crossbow_skill")) then
		return false
	end

	if m_skill and self:originalHegemonyGoodHp(player) and not self.player:hasSkills("heg_tieqi|heg_tieqi_xh|heg_yinbing") then
		return false
	else
		return true
	end
end

function SmartAIView:originalHegemonyGetDefenseSlash(player)
	if not player or not self then  return 0 end
	local attacker = self.player
	local unknownJink = getCardsNum("Jink", player, attacker)
	local defense = unknownJink

	local knownJink = getKnownCard(player, attacker, "Jink", true, "he")

	if hs_original_lack(self,player,"Jink") == 1 and knownJink == 0 then defense = 0 end

	defense = defense + knownJink * 1.2

	if self:originalHegemonyCanLiegong(player, attacker) then
		defense = 0
	end

	local niaoxiang_BA = false
	local heg_jiangqin = hs_find_shown(self,"heg_niaoxiang")
	if heg_jiangqin then
		if hs_siege(self,heg_jiangqin,player) then
			niaoxiang_BA = true
		end
	end
	local need_double_jink = hs_shown_skills(self,attacker, "wushuang|heg_wushuang_lvlingqi") or niaoxiang_BA
	if need_double_jink and knownJink < 2 and unknownJink < 1.5 then
		defense = 0
	end

if hs_shown(self,attacker,"tenyearjianchu") and (player:hasEquip() or player:getCardCount(true) == 1) then
		defense = 0
	end

	local jink = self:classProbe("Jink")
	if hs_jink_limited(self,player,jink) then defense = 0 end

	if hs_q(player,"getMark","##heg_qianxi+no_suit_red") > 0 then
		if hs_shown(self,player,"qingguo") then
			defense = defense - 0.5
		else
			defense = 0
		end
	elseif hs_q(player,"getMark","##heg_qianxi+no_suit_black") > 0 then
		if hs_shown(self,player,"qingguo") then
			defense = defense - 1
		end
	end

	if hs_q(player,"getMark","##heg_boyan") > 0 or hs_q(player,"getMark","command4_effect") > 0 then
		defense = 0
	end

	if attacker:hasWeapon("DragonPhoenix") or attacker:hasSkills("heg_tieqi|heg_tieqi_xh") then
		if player:getCardCount(true) <= 1 then
			defense = 0
		elseif player:getCardCount(true) <= 3 then
			defense = defense - 1
		end
	end

	if attacker:hasWeapon("Axe") and attacker:getCardCount(true) > 4 then
		defense = 0
	end

	defense = defense + math.min(player:getHp() * 0.45, 10)
	if not hs_known(hs_row(self,player).shown_one,"shown one") then defense = defense - 1 end

	local hasEightDiagram = false

	if player:hasArmorEffect("EightDiagram") and not hs_ignore_armor(self,attacker, player) then
		hasEightDiagram = true
	end

	if hasEightDiagram then
		defense = defense + (self:hasCrossbowEffect(attacker) and 4 or 1.5)
		if hs_shown_skills(self,player, "qingguo+tiandu") then defense = defense + 10
		elseif hs_shown_skills(self,player, "tiandu|heg_zhuwei") then defense = defense + 1 end
		if hs_shown(self,player,"nosleiji") then defense = defense + 0.6 end
		if hs_shown_skills(self,player, "hongyan|guicai|heg_huanshi") then defense = defense + 0.5 end
	end
	if player:hasArmorEffect("RenwangShield") and not hs_ignore_armor(self,attacker, player) and hs_shown(self,player,"heg_jiang") then
		defense = defense + 1.6
	end

	if hs_shown(self,player,"heg_tuntian") and hs_shown(self,player,"heg_jixi") and unknownJink >= 1 and not attacker:hasSkills("heg_tieqi|heg_tieqi_xh") then
		defense = defense + 1.5
	end

	if not attacker:hasSkills("heg_tieqi|heg_tieqi_xh|heg_yinbing") then
		for _, masochism in ipairs(hs_fact(self,"masochism_skill"):split("|")) do
			if hs_shown(self,player,masochism) and self:originalHegemonyGoodHp(player) then
				defense = defense + 1
			end
		end
		if hs_shown(self,player,"heg_fudi") and player:getHandcardNum() > 1 and attacker:getHp() + 1 >= player:getHp() then
			defense = defense + 1
		end
	end

	if not self:originalHegemonyIsGoodTarget(player) then defense = defense + 10 end

	if hs_shown(self,player,"rende") and player:getHp() > 2 then defense = defense + 1 end
	if hs_shown(self,player,"tenyearkuanggu") and player:getHp() > 1 then defense = defense + 0.2 end
	if hs_shown(self,player,"heg_zaiqi") and player:getHp() > 1 then defense = defense + 0.35 end

	if player:getHp() <= 2 then defense = defense - 0.4 end

	local playernum = self.room:alivePlayerCount()
	if (player:getSeat()-attacker:getSeat()) % playernum >= playernum-2 and playernum>3 and player:getHandcardNum()<=2 and player:getHp()<=2 then
		defense = defense - 0.4
	end

	if hs_shown(self,player,"heg_tianxiang") then defense = defense + player:getHandcardNum() * 0.8 end
	local isInPile = function()
		for _,pile in sgs.list(player:getPileNames())do
			if pile:startsWith("&") or pile == "wooden_ox" then
				if not player:getPile(pile):isEmpty() then
					return false
				end
			end
		end
		return true
	end
	if player:isKongcheng() and player:getHandPile():isEmpty() and not hs_shown_skills(self,player, "heg_kongcheng") then
		if player:getHp() <= 1 then defense = defense - 2.5 end
		if player:getHp() == 2 then defense = defense - 1.5 end
		if not hasEightDiagram then defense = defense - 2 end
	end

	local has_fire_slash
	local cards = sgs.QList2Table(attacker:getHandcards())
	for i = 1, #cards, 1 do
		if (attacker:hasWeapon("Fan") and (cards[i]):objectName() == "slash" and not (cards[i]):isKindOf("ThunderSlash")) or (cards[i]):isKindOf("FireSlash")  then
			has_fire_slash = true
			break
		end
	end

	if player:hasArmorEffect("Vine") and not hs_ignore_armor(self,attacker, player) and has_fire_slash then
		defense = defense - 0.6
	end

	if player:hasTreasure("JadeSeal") then defense = defense - 0.4 end

	if player:isLord() then defense = defense - 0.5 end
	if hs_careerist(self,player) and hs_head_kingdom(self,player) == "careerist" then
		defense = defense - 0.5
	end

	if not player:faceUp() then defense = defense - 0.35 end

	if player:containsTrick("indulgence") then defense = defense - 0.25 end
	if player:containsTrick("supply_shortage") then defense = defense - 0.15 end

	if not hasEightDiagram then


		local priority = hs_fact(self,"priority_skill"):split("|")
		for _, skill in ipairs(priority) do
			if hs_shown(self,player,skill) then
				defense = defense - 0.6
			elseif hs_null_skill(self,skill,player) then
				defense = defense - 1
			end
		end

		local masochism = hs_fact(self,"masochism_skill"):split("|")
		for _, skill in ipairs(masochism) do
			if hs_null_skill(self,skill,player) then
				defense = defense - 1
			end
		end
	end
	return defense
end

function SmartAIView:originalHegemonyGetDefense(player)
	if not player then return 0 end
	local hp = player:getHp()
	if hs_shown(self,player,"heg_benghuai") and player:getHp() > 4 then hp = 4 end
	local defense = math.min(hp * 2 + player:getHandcardNum(), hp * 3)
	local hasEightDiagram = false
	if player:hasArmorEffect("EightDiagram") or player:hasArmorEffect("bazhen") then
		hasEightDiagram = true
	end

	if player:getArmor() and player:hasArmorEffect(player:getArmor():objectName()) then defense = defense + 2 end
	if player:getDefensiveHorse() then defense = defense + 0.5 end

	if player:hasTreasure("JadeSeal") then defense = defense + 2 end
	if player:hasTreasure("WoodenOx") then defense = defense + player:getPile("wooden_ox"):length() end

	if hasEightDiagram then
		if hs_shown(self,player,"tiandu") then defense = defense + 1 end
		if hs_shown(self,player,"nosleiji") then defense = defense + 1 end
		if hs_shown(self,player,"hongyan") then defense = defense + 1 end
	end

	local m = hs_fact(self,"masochism_skill"):split("|")
	for _, masochism in ipairs(m) do
		if hs_shown(self,player,masochism) then
			local goodHp = player:getHp() > 1 or getCardsNum("Peach", player,self.player) >= 1 or getCardsNum("Analeptic", player,self.player) >= 1
							or (hs_shown(self,player,"heg_buqu") and player:getPileCount("heg_buqu")<=4) or (hs_shown(self,player,"heg_niepan") and hs_q(player,"getMark","@nirvana")>0 or hs_shown(self,player,"heg_jizhao") and hs_q(player,"getMark","@heg_jizhao")>0)
			if goodHp then defense = defense + 1 end
		end
	end

	if hs_shown(self,player,"heg_jieming") then defense = defense + 3 end
	if hs_shown(self,player,"heg_yiji") then defense = defense + 2 end
	if hs_shown(self,player,"tenyeartuxi") then defense = defense + 0.5 end
	if hs_shown(self,player,"heg_luoshen") then defense = defense + 1 end

	if hs_shown(self,player,"rende") and player:getHp() > 2 then defense = defense + 1 end
	if hs_shown(self,player,"heg_zaiqi") and player:getHp() > 1 then defense = defense + player:getLostHp() * 0.5 end
	if hs_shown_skills(self,player, "heg_tieqi|heg_liegong|tenyearkuanggu") then defense = defense + 0.5 end
	if hs_shown(self,player,"xiangle") then defense = defense + 1 end
	if hs_shown(self,player,"shushen") then defense = defense + 1 end
	if hs_shown(self,player,"heg_kongcheng") and player:isKongcheng() then defense = defense + 2 end
	if hs_shown(self,player,"heg_shouyue") then
		for _, p in sgs.qlist(self.room:getAlivePlayers()) do
			if p:getKingdom() == "shu" then
				if hs_shown(self,p,"tenyearwusheng") then defense = defense + 1 end
				if hs_shown(self,p,"heg_paoxiao") then defense = defense + 1 end
				if hs_shown(self,p,"heg_longdan") then defense = defense + 1 end
				if hs_shown(self,p,"heg_liegong") then defense = defense + 1 end
				if hs_shown(self,p,"heg_tieqi") then defense = defense + 1 end
			end
		end
	end

	if hs_shown_skills(self,player, "heg_yinghun_sunjian|heg_yinghun_sunce") and player:getLostHp() > 0 then defense = defense + player:getLostHp() - 0.5 end
	if hs_shown(self,player,"heg_tianxiang") then defense = defense + player:getHandcardNum() * 0.5 end
	if hs_shown(self,player,"heg_buqu") then defense = defense + math.max(4 - player:getPile("heg_buqu"):length(), 0) end
	if hs_shown(self,player,"guzheng") then defense = defense + 1 end
	if hs_shown(self,player,"dimeng") then defense = defense + 2 end
	if hs_shown(self,player,"heg_keji") then defense = defense + player:getHandcardNum() * 0.5 end
	if hs_shown(self,player,"jieyin") and player:getHandcardNum() > 1 then defense = defense + 2 end

	if hs_shown(self,player,"heg_qianhuan") then defense = defense + (player:getPile("sorcery"):length() + 1) * 2 end
	if hs_shown(self,player,"jijiu") then defense = defense + 2 end
	if hs_shown(self,player,"lijian") then defense = defense + 0.5 end
	if player:hasLordSkill("heg_hongfa") then
		for _, p in sgs.qlist(self.room:getAlivePlayers()) do
			if hs_public_kingdom(self,p) == "qun" then defense = defense + 1 end
		end
	end

	if not player:faceUp() then defense = defense - 0.5 end
	if player:containsTrick("indulgence") then defense = defense - 0.5 end
	if player:containsTrick("supply_shortage") then defense = defense - 0.5 end

	if self.room:getCurrent() then
		defense = defense + (self.room:alivePlayerCount() - (player:getSeat() - self.room:getCurrent():getSeat()) % self.room:alivePlayerCount()) / 4
	end

	return defense
end

function SmartAIView:originalHegemonyGetValue(player)
	if not player then  end
	return player:getHp() * 2 + player:getHandcardNum()
end

function SmartAIView:originalHegemonySort(players, key)
	if type(players) ~= "table" then end
	if #players == 0 then return players end
	local func
	if not key or key == "defense" or key == "defenseSlash" then
		func = function(a, b)
			local c1 = self:originalHegemonyGetDefenseSlash(a)
			local c2 = self:originalHegemonyGetDefenseSlash(b)
			if c1 == c2 then
				return self:originalHegemonyGetDefense(a) < self:originalHegemonyGetDefense(b)
			else
				return c1 < c2
			end
		end
	elseif key == "hp" then
		func = function(a, b)
			local c1 = a:getHp()
			local c2 = b:getHp()
			if c1 == c2 then
				return self:originalHegemonyGetDefenseSlash(a) < self:originalHegemonyGetDefenseSlash(b)
			else
				return c1 < c2
			end
		end
	elseif key == "handcard" then
		func = function(a, b)
			local c1 = a:getHandcardNum()
			local c2 = b:getHandcardNum()
			if c1 == c2 then
				return self:originalHegemonyGetDefenseSlash(a) < self:originalHegemonyGetDefenseSlash(b)
			else
				return c1 < c2
			end
		end
	elseif key == "handcard_defense" then
		func = function(a, b)
			local c1 = a:getHandcardNum()
			local c2 = b:getHandcardNum()
			if c1 == c2 then
				return self:originalHegemonyGetDefenseSlash(a) < self:originalHegemonyGetDefenseSlash(b)
			else
				return c1 < c2
			end
		end
	elseif key == "equip_defense" then
		func = function(a, b)
			local c1 = a:getCards("e"):length()
			local c2 = b:getCards("e"):length()
			if c1 == c2 then
				return self:originalHegemonyGetDefenseSlash(a) < self:originalHegemonyGetDefenseSlash(b)
			else
				return c1 < c2
			end
		end
	elseif key == "chaofeng" then
		func = function(a, b)
			local c1 = self:originalHegemonyGetDefense(a)
			local c2 = self:originalHegemonyGetDefense(b)
			if c1 == c2 then
				return self:originalHegemonyGetDefenseSlash(a) < self:originalHegemonyGetDefenseSlash(b)
			else
				return c1 < c2
			end
		end
	else
		func = key=="value" and function(a,b)return self:originalHegemonyGetValue(a)<self:originalHegemonyGetValue(b)end
	end

	if not func then return end

	local function _sort(players)
		table.sort(players, func)
	end
	local ok,err=pcall(_sort,players);if not ok and AIUnsupported.is(err)then error(err,0)end
    return players
end


function SmartAIView:originalHegemonyTrickIsEffective(card, to, from)
    -- Current native card legality owns the shared card rules.
    return self:hasTrickEffective(card,to,from)
end

function SmartAIView:originalHegemonyGetJiemingDrawNum(player)
	local max_x = 0
	for _, friend in ipairs(self:getFriends(player)) do
		local x = math.min(friend:getMaxHp(), 5) - friend:getHandcardNum()
		if x > max_x then
			max_x = x
		end
	end
	return max_x
end

function SmartAIView:originalHegemonyFindFriendsByType(prompt, player)
	player = player or self.player
	local friends = self:getFriendsNoself(player)
	if #friends < 1 then return false end
	if prompt == sgs.Friend_Draw then
		for _, friend in ipairs(friends) do
			if not self:needKongcheng(friend,true) then return true end
		end
	elseif prompt == sgs.Friend_Male then
		for _, friend in ipairs(friends) do
			if friend:isMale() then return true end
		end
	elseif prompt == sgs.Friend_MaleWounded then
		for _, friend in ipairs(friends) do
			if friend:isMale() and friend:isWounded() then return true end
		end
	elseif prompt == sgs.Friend_All then
		return true
	else

		return
	end
	return false
end


SmartAIView.originalHegemonyIsGoodChainTarget=SmartAIView.originalHegemonyChainTarget

-- Original common3798–3847. Preserve literal objectName registry lookup and
-- source range defaults; do not substitute ordinary class-name callbacks.
function SmartAIView:originalHegemonyEvaluateWeapon(card,player,target)
    player=player or self.player
    local score,inRange=0,nil
    local enemies=target and{target}or self:getEnemies(player)
    if not card then return -1 end
    local range=self:originalHegemonyWeaponRange(card:getClassName()) or 0
    local rows=known(heg_facts(self).weapon_values,"Original weapon metadata")
    local valueName=card:objectName()
    local valueHook=known(known(rows[valueName],"Original weapon row").value_callback,"Original weapon callback")
    local filterName=card:objectName()
    local filterHook=known(known(rows[filterName],"Original weapon row").filter_callback,"Original weapon filter")
    for _,enemy in ipairs(enemies)do
        if player:distanceTo(enemy)<=range then
            inRange=true
            local defense=self:originalHegemonyGetDefenseSlash(enemy)/2
            if defense<0 then defense=6-defense elseif defense<=1 then defense=6 else defense=6/defense end
            score=score+defense
            if valueHook then ai_unsupported("Original object-name weapon value callback is not migrated",valueName)end
            if filterHook then
                -- Original resets ai_weapon_value, but retains these six
                -- effective ordinary object-name filter bodies. Reuse their
                -- actual migrated registrations, with the exact callback ABI.
                local admitted={double_sword=true,qinggang_sword=true,guding_blade=true,axe=true,fan=true,kylin_bow=true}
                local callback=admitted[filterName]and sgs.ai_slash_weaponfilter[filterName]
                if type(callback)~="function"then ai_unsupported("Original object-name weapon filter is not migrated",filterName)end
                local answer=callback(self,enemy,player)
                if AIUnsupported.is(answer)then error(answer,0)end
                if answer then score=score+1 end
            end
        end
    end
    if card:isKindOf("Crossbow")and not shown(self,player,"heg_paoxiao")and inRange then
        local function count(class)return player:objectName()==self.player:objectName()and self:getCardsNum(class)or getCardsNum(class,player,self.player)end
        local slash,wine,peach=count("Slash"),count("Analeptic"),count("Peach")
        score=score+slash*3-2
        if shown(self,player,"heg_kurou")then score=score+peach+wine+self.player:getHp()end
        if original_equipment(player,"getWeapon")and not hegemony_source_query(self,'hasCrossbowEffect',player)then
            local without
            if player:objectName()==self.player:objectName()then without=self:originalHegemonyOwnerFact("owner_can_slash_without_crossbow")
            else without=self:useKnowledgeEstimate({value=true,status="estimate",viewer=self.player:objectName(),target=player:objectName(),
                basis="foreign_slash_history_and_private_residue_unobserved; remaining_use_prior"},"Original.evaluateWeapon.crossbow")end
            if not without and slash>0 then
                for _,enemy in ipairs(enemies)do
                    if player:distanceTo(enemy)<=range then
                        local lack=self:getOriginalHegemonyCardLack(enemy,"Jink")
                        if lack==1 or slash>=enemy:getHp()then score=score+10 end
                    end
                end
            end
        end
    end
    if shown(self,player,"jijiu")and card:isRed()then score=score+0.5 end
    if original_shown_skills(self,player,"qixi|guidao")and card:isBlack()then score=score+0.5 end
    return score,inRange
end

-- Fixed heg-common-ai.lua:3346-3379. Caller supplies lawful counters in donor
-- enumeration order and num AFTER cardsView count. Do not clamp hidden: donor
-- shownum includes WoodenOx while hand_count is the ordinary hand count.
local function original_hegemony_count_formula(c)
    local num = c.num
    if not c.observer_is_target then
        if c.class_name == 'Slash' then
            local slashnum
            if c.wusheng then
                slashnum = c.redslash + num + (c.hand_count - c.shownum) * 0.69
            elseif c.longdan then
                slashnum = c.slashjink + (c.hand_count - c.shownum) * 0.72
            else
                slashnum = num + (c.hand_count - c.shownum) * 0.35
            end
            if c.spear then
                local slashnum2 = math.floor((c.hand_count - c.shownum) / 2) + num
                return math.max(slashnum, slashnum2)
            end
            return slashnum
        elseif c.class_name == 'Jink' then
            if c.qingguo then
                return c.blackcard + num + (c.hand_count - c.shownum) * 0.85
            elseif c.longdan then
                return c.slashjink + (c.hand_count - c.shownum) * 0.72
            else
                return num + (c.hand_count - c.shownum) * 0.6
            end
        elseif c.class_name == 'Peach' then
            if c.jijiu then
                return num + c.redpeach + (c.hand_count - c.shownum) * 0.6
            else
                return num
            end
        elseif c.class_name == 'Nullification' then
            if c.kanpo then
                return num + c.blacknull + (c.hand_count - c.shownum) * 0.5
            else
                return num
            end
        end
    end
    return num
end

-- Fixed b6025acc callbacks; pure proposed identity, never an action receipt.
-- factory receives strict value-query and readonly request reason/lord providers.
local original_owner_view_as_factory=function(query, constants, current_reason, current_lord)
 local function material(card)
  return {suit=query(card,'getSuit'),number=query(card,'getNumber'),subcards={query(card,'getEffectiveId')}}
 end
 local function result(key,name,m,skill)
  return {source_key=key,skill=skill or key,name=name,suit=m.suit,number=m.number,subcards=m.subcards}
 end
 local function in_hand(card,player,place,m)
  return place==constants.Player_PlaceHand or query(query(player,'getHandPile'),'contains',m.subcards[1])
 end
 local function outside_special(player,place,m)
  return place~=constants.Player_PlaceSpecial or query(query(player,'getHandPile'),'contains',m.subcards[1])
 end
 local callbacks={}
 callbacks.qingguo=function(card,player,place)
  local m=material(card)
  if query(card,'isBlack') and in_hand(card,player,place,m) then return result('qingguo','jink',m) end
 end
 for _,key in ipairs{'tenyearwusheng','heg_wusheng_xh'} do
  callbacks[key]=function(card,player,place)
   local m=material(card)
   if outside_special(player,place,m) then
    local lord=current_lord(player)
    if (lord and query(lord,'hasShownSkill','heg_shouyue') or query(card,'isRed'))
      and not query(card,'isKindOf','Peach') and not query(card,'hasFlag','using') then return result(key,'slash',m) end
   end
  end
 end
 for _,key in ipairs{'heg_longdan','heg_longdan_xh'} do
  callbacks[key]=function(card,player,place)
   local m=material(card)
   if in_hand(card,player,place,m) then
    if query(card,'isKindOf','Jink') then return result(key,'slash',m)
    elseif query(card,'isKindOf','Slash') then return result(key,'jink',m) end
   end
  end
 end
 callbacks.heg_kanpo=function(card,player,place)
  local m=material(card)
  if in_hand(card,player,place,m) and query(card,'isBlack') and not query(card,'isKindOf','HegNullification')
   and not (query(player,'hasSkill','heg_jizhi') and query(card,'isKindOf','Nullification')) then return result('heg_kanpo','nullification',m) end
 end
 callbacks.jijiu=function(card,player,place)
  local m=material(card)
  if outside_special(player,place,m) and query(card,'isRed') and query(player,'getPhase')==constants.Player_NotActive
   and not query(player,'hasFlag','Global_PreventPeach')
   and (query(player,'getMark','##heg_qianxi+no_suit_red')==0 or query(card,'isEquipped')) then return result('jijiu','peach',m) end
 end
 callbacks.fan=function(card,player,place)
  local m=material(card)
  if current_reason()~=constants.CardUseStruct_CARD_USE_REASON_RESPONSE and place~=constants.Player_PlaceSpecial
   and query(card,'objectName')=='slash' then return result('fan','fire_slash',m,'Fan') end
 end
 callbacks.heg_aozhan=function(card,player,place,class)
  if query(player,'getMark','GlobalBattleRoyalMode')==0 then return end
  local m=material(card)
  if in_hand(card,player,place,m) and query(card,'isKindOf','Peach') then
   if class=='Slash' then return result('heg_aozhan','slash',m)
   elseif class=='Jink' then return result('heg_aozhan','jink',m) end
  end
 end
 callbacks.heg_miewu=function(card,player,place)
  if not query(player,'hasShownSkill','heg_miewu') then return end
  if query(player,'getMark','#heg_wuku')==0 or query(player,'hasFlag','MiewuUsed') or query(player,'isNude') or query(player,'isRemoved') then return end
  if current_reason()~=constants.CardUseStruct_CARD_USE_REASON_RESPONSE_USE and current_reason()~=constants.CardUseStruct_CARD_USE_REASON_RESPONSE then
   if query(player,'getPhase')==constants.Player_Play then return end
  end
  local indulged=query(player,'getPhase')==constants.Player_Judge and not query(player,'isSkipped',constants.Player_Judge)
   and not query(player,'isSkipped',constants.Player_Play) and query(player,'containsTrick','indulgence')
   and (query(player,'getHandcardNum')>3 or query(player,'getHandcardNum')>query(player,'getHp')-1)
  if not indulged then return end
  local m=material(card)
  if outside_special(player,place,m) and not query(card,'isKindOf','Nullification') then return result('heg_miewu','nullification',m) end
 end
 return callbacks
end

function SmartAIView:originalHegemonyEvaluateViewAsSpec(spec)
    -- Keep the old wrapper shape for Original callbacks, but use the same
    -- owner-scoped pure-value evaluator as the current isolated providers.
    -- It returns an evaluation-only card; final payment still goes through the
    -- request-local conversion binder in materializeOriginalSelectedCard.
    if type(spec)~='table' then ai_unsupported('Original view-as spec is malformed','Original.view_as')end
    local card=self:evaluateOwnerViewAsCard(spec)
    if not card then return nil end
    -- Retain only the exact source identity needed by the later, request-local
    -- authority binder.  This does not authorize or pay the conversion.
    self._original_selected_specs=self._original_selected_specs or {}
    self._original_selected_specs[card]={spec=spec,class_name=card:getClassName(),
        source_key=spec.source_key or spec.skill,request=self.request}
    return {card=card}
end
function SmartAIView:materializeOriginalSelectedCard(card)
    if not card or type(card.isEvaluationOnly)~='function'or not card:isEvaluationOnly()then return card end
    if self:isReadonlyTurnConversion(card) then return self:materializeTurnSelectedCard(card) end
    local entry=self._original_selected_specs and self._original_selected_specs[card]
    if type(self.request)~='table'or type(entry)~='table'or entry.request~=self.request then ai_unsupported('selected Original evaluation has no current request-local conversion identity','Original.materialize')end
    if not entry.authority then
        if type(self.bindOriginalSelectedConversion)~='function'then ai_unsupported('Original final conversion binder unavailable',entry.source_key)end
        entry.authority=self:bindOriginalSelectedConversion(entry.spec,entry.class_name,entry.source_key,card)
        if not entry.authority then ai_unsupported('Original selected conversion was not authorized',entry.source_key)end
    end
    return entry.authority
end

function SmartAIView:originalHegemonyViewAsCard(key,class,card,player,place)
    if player:objectName()~=self.player:objectName()then ai_unsupported('Original owner view-as query rejects a foreign actor',key)end
    local callbacks=original_owner_view_as_factory(function(object,method,...)
        if method=="hasShownSkill"then return shown(self,object,...)end
        return hegemony_source_query(object,method,...)
    end,sgs,function()
        return self:originalHegemonyOwnerFact('owner_current_card_use_reason')
    end,function()
        local name=self:originalHegemonyOwnerFact("owner_hegemony_lord")
        if name==""then return nil end
        return known(self.room:findPlayerByObjectName(name),"owner Hegemony lord roster")
    end)
    local callback=callbacks[key]
    if not callback then ai_unsupported('Original view-as callback is not migrated',key)end
    local id=card:getKnownEffectiveId()
    local owner=self.room:getCardOwner(id)
    place=place or(owner and owner:objectName()==player:objectName()and known(self.room:getCardPlace(id),'owner material place')or sgs.Player_PlaceHand)
    local spec=callback(card,player,place,class)
    if not spec then return nil end
    local evaluated=self:originalHegemonyEvaluateViewAsSpec(spec)
    if evaluated and evaluated.card:isKindOf(class)and not evaluated.limited then return evaluated.card end
end
function SmartAIView:originalHegemonyViewAsMatch(key,class,card,player)
    return self:originalHegemonyViewAsCard(key,class,card,player)~=nil
end

local function original_count_class(self,class,card,player)
    if card:isKindOf(class)then
        local limited=player:isCardLimited(card,card:getHandlingMethod())
        if limited==nil and player:objectName()~=self.player:objectName()then
            limited=self:useKnowledgeEstimate({value=false,status="estimate",viewer=self.player:objectName(),target=player:objectName(),
                basis="foreign_private_card_limitation_unobserved; printed_response_prior"},"Original.getCardsNum.limited")
        end
        if known(limited,"Original card limitation")then return false end
        if card:isKindOf("Peach")and hegemony_source_query(player,'hasFlag',"Global_PreventPeach")then return false end
        return true
    end
    local presence=known(heg_facts(self).view_as_presence,"Original view-as callback metadata")
    for _,skill in ipairs(player:getVisibleSkillList(true))do
        local name=skill:objectName()
        if (player:objectName()==self.player:objectName()or shown(self,player,name))
            and(player:hasSkill(name)or player:hasLordSkill(name))
            and known(presence[name],"Original view-as callback:"..name)then
            if player:objectName()==self.player:objectName()then
                if self:originalHegemonyViewAsMatch(name,class,card,player)then return true end
            else
                local estimate=self:estimateCardClass(card,player,class)
                return self:useKnowledgeEstimate(estimate,"Original.getCardsNum.public_conversion"),estimate
            end
        end
    end
    return false
end
function SmartAIView:originalHegemonyIsCard(class,card,player)
    return original_count_class(self,class,card,player)
end
function SmartAIView:originalHegemonyAocaiPattern()
    self.scratch=self.scratch or{}
    local row=self.scratch.original_aocai_pattern
    if row==nil then
        -- The live card-use pattern is this use/respond request's own pattern while
        -- it answers a response; any other request does not carry it.
        local r=self.request
        if type(r)~="table"or(r.kind~="respond_card"and r.kind~="use_card")or type(r.pattern)~="string"
            or(r.reason~=sgs.CardUseStruct_CARD_USE_REASON_RESPONSE and r.reason~=sgs.CardUseStruct_CARD_USE_REASON_RESPONSE_USE)then
            ai_unsupported("Original Aocai current pattern is outside the authorized viewer scope","Original.aocai_pattern")
        end
        row={kind="original_aocai_pattern",known=true,slash=r.pattern=="slash",jink=r.pattern=="jink"}
        self.scratch.original_aocai_pattern=row
    end
    if row.slash then return "slash"elseif row.jink then return "jink"end
end
local function original_cardsview_count(self,class,player,other)
    local presence=known(heg_facts(self).cardsview_presence,"Original cardsView callback metadata")
    for _,skill in ipairs(player:getVisibleSkillList(true))do
        local name=skill:objectName()
        if(player:objectName()==self.player:objectName()or shown(self,player,name))
            and(player:hasSkill(name)or player:hasLordSkill(name))
            and known(presence[name],"Original cardsView callback:"..name)then
            if name=="spear"then
                if class=="Slash"then
                    if #other<2 then return 0 end
                    self:sortByKeepValue(other)
                    local count=0
                    for _,card in ipairs(other)do
                        local owner=self.room:getCardOwner(card:getKnownEffectiveId())
                        if owner and owner:objectName()==player:objectName()and self.room:getCardPlace(card:getEffectiveId())==sgs.Player_PlaceHand
                            and not original_count_class(self,"Peach",card,player)
                            and not(original_count_class(self,"ExNihilo",card,player)and player:getPhase()==sgs.Player_Play)then count=count+1 end
                    end
                    return math.floor(count/2)
                end
            elseif name=="heg_companion"or name=="heg_careerman"then
                if class=="Peach"and hegemony_source_query(player,'getMark',name=="heg_companion"and"@companion"or"@careerist")>0 and not hegemony_source_query(player,'hasFlag',"Global_PreventPeach")then
                    -- Actual callback returns a string. Donor #cardsView takes
                    -- its byte length; do not silently repair it to one card.
                    return #(name=="heg_companion"and"peach:heg_companion[no_suit:0]=."or"peach:heg_careerman[no_suit:0]=.")
                end
            elseif name=="heg_aocai"then
                if player:objectName()==self.player:objectName()and player:hasSkill("heg_aocai")and not hegemony_source_query(player,'hasFlag',"Global_AocaiFailed")and player:getPhase()==sgs.Player_NotActive then
                    local reason=self:originalHegemonyOwnerFact("owner_current_card_use_reason")
                    if (reason==sgs.CardUseStruct_CARD_USE_REASON_RESPONSE_USE or reason==sgs.CardUseStruct_CARD_USE_REASON_RESPONSE)
                        and(class=="Slash"or class=="Jink")then
                        local pattern=self:originalHegemonyAocaiPattern()
                        if pattern then return #("@HAocaiCard=.&heg_aocai:"..pattern)end
                    end
                    if class=="Peach"or class=="Analeptic"then
                        local dying=self.room:getCurrentDyingPlayer()
                        return #("@HAocaiCard=.&heg_aocai:"..(dying and dying:objectName()==player:objectName()and"peach+analeptic"or class=="Analeptic"and"analeptic"or"peach"))
                    end
                end
            elseif name=="heg_miewu"or name=="heg_yigui"or name=="huangjinsymbol"or name=="heg_huangjinsymbol"then
                local value=self:originalHegemonyCardsViewProvider(name,class,player,other,true)
                if value then return #value end
            else ai_unsupported("Original cardsView counting callback is not migrated",name)end
        end
    end
    return 0
end
function SmartAIView:originalHegemonyCardsNum(class,player,observer)
    if not player then return 0 end
    local cards=self:originalHegemonyKnownCard(player,self.player,"Card",false,"h",true)
    local c={class_name=class,num=0,shownum=0,redslash=0,slashjink=0,blackcard=0,redpeach=0,blacknull=0,hand_count=player:getHandcardNum(),
        observer_is_target=observer and observer:objectName()==player:objectName()or false}
    local other={}
    for _,card in ipairs(cards)do
        c.shownum=c.shownum+1
        if original_count_class(self,class,card,player)then c.num=c.num+1 else other[#other+1]=card end
        if card:isKindOf("Slash")or card:isKindOf("Jink")then c.slashjink=c.slashjink+1 end
        if card:isRed()then
            if not card:isKindOf("Slash")then c.redslash=c.redslash+1 end
            if not card:isKindOf("Peach")then c.redpeach=c.redpeach+1 end
        end
        if card:isBlack()then c.blackcard=c.blackcard+1;if not card:isKindOf("Nullification")then c.blacknull=c.blacknull+1 end end
    end
    for _,card in ipairs(player:getEquips())do
        other[#other+1]=card
        if card:isRed()then c.redslash=c.redslash+1;c.redpeach=c.redpeach+1 end
    end
    c.num=c.num+original_cardsview_count(self,class,player,other)
    if not c.observer_is_target then
        if class=="Slash"then c.wusheng=shown(self,player,"tenyearwusheng");if not c.wusheng then c.longdan=shown(self,player,"heg_longdan")end;c.spear=player:hasWeapon("Spear")
        elseif class=="Jink"then c.qingguo=shown(self,player,"qingguo");if not c.qingguo then c.longdan=shown(self,player,"heg_longdan")end
        elseif class=="Peach"then c.jijiu=shown(self,player,"jijiu")
        elseif class=="Nullification"then c.kanpo=shown(self,player,"heg_kanpo")end
    end
    local value=original_hegemony_count_formula(c)
    if not c.observer_is_target and c.hand_count~=c.shownum then
        return self:useKnowledgeEstimate({value=value,status="estimate",viewer=self.player:objectName(),observer=observer and observer:objectName()or self.player:objectName(),target=player:objectName(),
            source_equivalent_estimate=true,basis="Original source density formula over viewer-visible cards"},"Original.getCardsNum.density")
    end
    return value
end

-- Original Hegemony source subtree, fixed b6025acc. Install these methods only
-- after the admitted Original bundle mode gate; never overwrite ordinary mode.
local ht_known = AIValue.requireKnown
local function ht_q(object,method,...)
    if AIValue.isPlayer(object)then
        if method=='getMark'then method='getStrategyMark'elseif method=='hasFlag'then method='getStrategyFlag'end
    end
    if not object or type(object[method])~='function'then ai_unsupported('Original Slash dependency unavailable',method)end
    return ht_known(object[method](object,...),method)
end
local function ht_facts(self)return ht_known(AIHegemony.facts(self.world),'hegemony facts')end
local function ht_fact(self,key)
    if key:match('^owner_')then return self:originalHegemonyOwnerFact(key)end
    return ht_known(ht_facts(self)[key],key)
end
local function ht_row(self,p)return ht_known(ht_fact(self,'players')[p:objectName()],'public Hegemony player')end
local function ht_shown(self,p,name)return ht_known(ht_row(self,p).shown_skills,'shown skills')[name]~=nil end
local ht_skill_aliases = {
    nosganglie = {"heg_ganglie"}, nostuxi = {"tenyeartuxi"}, nosluoyi = {"heg_luoyi"},
    nosyiji = {"heg_yiji"}, shensu = {"heg_shensu"},
    duanliang = {"heg_duanliang"}, nosjushou = {"heg_jushou"}, qiangxi = {"heg_qiangxi"},
    jieming = {"heg_jieming"}, fangzhu = {"mobilefangzhu"}, luoshen = {"heg_luoshen"},
    guicai = {"heg_guicai"},
    paoxiao = {"heg_paoxiao"}, kongcheng = {"heg_kongcheng"}, longdan = {"heg_longdan"},
    tieqi = {"heg_tieqi"}, jizhi = {"heg_jizhi"}, liegong = {"heg_liegong"},
    wusheng = {"tenyearwusheng"}, kuanggu = {"tenyearkuanggu"}, huoshou = {"heg_huoshou"}, juxiang = {"heg_juxiang"},
    keji = {"heg_keji"},
    kurou = {"heg_kurou"}, yingzi = {"heg_yingzi_sunce", "heg_yingzi_zhouyu"},
    qicai = {"nosqicai"},
    fanjian = {"heg_fanjian"}, guose = {"heg_guose"}, qianxun = {"heg_qianxun"},
    xiaoji = {"heg_xiaoji"}, yinghun = {"heg_yinghun_sunjian", "heg_yinghun_sunce"},
    tianxiang = {"heg_tianxiang"}, buqu = {"heg_buqu"}, guzheng = {"heg_guzheng"},
    duanbing = {"heg_duanbing"}, fenxun = {"heg_fenxun"}, luanji = {"heg_luanji"},
     weimu = {"heg_weimu"},
	leiji = {"nosleiji"}, duanchang = {"heg_duanchang"},
    wushuang = {"heg_wushuang"}, jiang = {"heg_jiang"},
}
local function ht_shown_skills(self,p,names)
    for group in names:gmatch('[^|]+')do
        local all=true;for name in group:gmatch('[^+]+')do
            local found=false;for _,actual in ipairs(ht_skill_aliases[name]or{name})do if ht_shown(self,p,actual)then found=true;break end end
            if not found then all=false;break end
        end
        if all then return true end
    end
    return false
end
local function ht_find_shown(self,name)
    for _,p in ipairs(self.room:getAllPlayers())do if ht_shown(self,p,name)then return p end end
end
hooks_pending.ht_both_shown = function(self,p)local r=ht_row(self,p);return ht_known(r.shown_head,'shown head')and ht_known(r.shown_deputy,'shown deputy')end
local function ht_public_friend(self,a,b)return a:isPublicHegemonyFriend(b)end
hooks_pending.ht_visible = function(self,id)
    -- Negative virtual IDs have no engine physical card; source getCard returns
    -- no physical card there. Positive IDs must remain in the lawful domain.
    if type(id)=='number'and id<0 then return nil end
    return ht_known(self:getKnownCardById(id),'lawful source card '..tostring(id))
end
hooks_pending.ht_target_mod = function(self,card,kind)
    local method=({distance='getTargetModDistance',extra='getTargetModExtra',residue='getTargetModResidue'})[kind]
    return ht_q(card,ht_known(method,'target modifier kind'),self.player)
end
local function ht_no_response(self,card)return self:cardNoResponseNames(card)end
hooks_pending.ht_skill = function(self,name)
    if name==''then return nil end
    return ht_known(self.room:getPublicSkill(name),'skill definition outside the visible roster')
end
hooks_pending.ht_ignore_armor = function(self,from,to)
    if not from or not to then return end
    local armor=to:getArmor()
    if not armor then return true end
    if not to:hasArmorEffect(armor:objectName())or from:hasWeapon('QinggangSword')then return true end
end
hooks_pending.ht_private_jink = function(self,target)
    -- Fixed donor cardIsVisible always uses current_self.player even when the
    -- caller passes target as observer. This is a visible count, not full-hand estimation.
    return getKnownCard(target,target,'Jink',true,'he')
end

local function ht_original_lack(self,target,kind)
    return self:getOriginalHegemonyCardLack(target,kind)
end
hooks_pending.ht_damage_callbacks = function(self)
    return original_damage_effect_callbacks(self)
end

hooks_pending.ht_head_kingdom = function(self,player)
    local row=ht_row(self,player)
    if player:objectName()==self.player:objectName()then return ht_known(ht_facts(self).owner_head_kingdom,'owner head kingdom')end
    if row.head_kingdom~=nil then return row.head_kingdom end
    return self:useKnowledgeEstimate({value='unknown',status='estimate',basis='unrevealed_head_kingdom_unavailable',viewer=self.player:objectName(),target=player:objectName()},'OriginalDefense.careerist_head')
end
hooks_pending.ht_public_kingdom = function(self,player)
    local kingdom=ht_known(ht_row(self,player).public_kingdom,'public kingdom')
    return kingdom~=''and kingdom or'unknown'
end

hooks_pending.ht_null_skill = function(self,skill,player)
    local value=player:hasSkill(skill)
    if value~=nil then return not value end
    return self:useKnowledgeEstimate({value=true,status='estimate',basis='foreign_unseen_skill_absence_prior',viewer=self.player:objectName(),target=player:objectName(),skill=skill},'OriginalDefense.hasNullSkill')
end

hooks_pending.ht_siege = function(self,holder,target)
    return ht_known(ht_known(ht_row(self,holder).siege_targets,'public siege targets')[target:objectName()],'public siege relation')
end
hooks_pending.ht_jink_limited = function(self,player,jink)
    local result=player:isCardLimited(jink,sgs.Card_MethodUse)
    if result~=nil then return result end
    if player:objectName()==self.player:objectName()then return ht_known(nil,'owner Jink limitation')end
    return self:useKnowledgeEstimate({value=false,status='estimate',basis='foreign_unprojected_jink_limitation_prior',viewer=self.player:objectName(),target=player:objectName()},'OriginalDefense.JinkLimited')
end

hooks_pending.ht_careerist = function(self,player)
    if player:objectName()==self.player:objectName()then return player:getRole()=='careerist'end
    local row=ht_row(self,player)
    if ht_known(row.shown_one,'shown one')then return ht_known(row.public_careerist,'public careerist')end
    return self:useKnowledgeEstimate({value=false,status='estimate',basis='unrevealed_careerist_role_prior',viewer=self.player:objectName(),target=player:objectName()},'OriginalDefense.careerist_role')
end

local function ht_known_hand(self,player)
    local cards=player:objectName()==self.player:objectName() and player:getHandcards()or player:getKnownCards()
    return sgs.QList2Table(cards)
end
local function ht_same_kingdom(self,player)
    -- Player.cpp4091/ServerPlayer.cpp3359, reason AI never triggers modifiers.
    local kingdom
    if player:objectName()==self.player:objectName()then kingdom=player:getKingdom()
    elseif ht_known(ht_row(self,player).shown_one,'shown one')then kingdom=player:getKingdom()
    else return self:useKnowledgeEstimate({value=0,status='estimate',basis='unrevealed_equipment_holder_kingdom_prior',viewer=self.player:objectName(),target=player:objectName()},'OriginalDangerousCard.PeaceSpellKingdom')end
    if kingdom==''then kingdom=ht_known(ht_row(self,self.player).public_kingdom,'owner seeming kingdom')end
    local count=0
    for _,p in ipairs(self.room:getAlivePlayers())do
        local faction=ht_known(ht_row(self,p).public_kingdom,'public seeming kingdom')
        if faction~=''then if faction=='careerist'then if kingdom=='careerist'then count=1 end elseif faction==kingdom then count=count+1 end end
    end
    return count
end
local function ht_native_equip(self,card)
    -- TrustAI::useCard(ai.cpp256) tail: all callers here have already excluded
    -- Weapon and Armor. Occupied horses are rejected; other equip locations
    -- reach native switch's true default. Do not use this for arbitrary cards.
    if card:isKindOf('OffensiveHorse')then return original_equipment(self.player,'getOffensiveHorse')==nil end
    if card:isKindOf('DefensiveHorse')then return original_equipment(self.player,'getDefensiveHorse')==nil end
    if card:isKindOf('EquipCard')then return true end
    ai_unsupported('non-equipment TrustAI policy requires native relationship contract','OriginalEquipment')
end

function SmartAIView:originalHegemonyUseEquipCard(card, use)
	if not card then  return end
	if self.player:hasSkill("heg_xiaoji") and self:evaluateArmor(card) > -5 then
		local armor = original_equipment(self.player,"getArmor")
		if armor and armor:objectName() == "PeaceSpell" and card:isKindOf("Armor") then
			if (self:getAllPeachNum() == 0 and self.player:getHp() < 3) and not (self.player:getHp() < 2 and self:getCardsNum("Analeptic") > 0) then
				return
			end
		end
		use.card = card
		return
	end
	if self.player:hasSkills(ht_fact(self,"lose_equip_skill")) and self:evaluateArmor(card) > -5 and #self.enemies > 1 then
		local armor = original_equipment(self.player,"getArmor")
		if armor and armor:objectName() == "PeaceSpell" and card:isKindOf("Armor") then
			if (self:getAllPeachNum() == 0 and self.player:getHp() < 3) and not (self.player:getHp() < 2 and self:getCardsNum("Analeptic") > 0) then
				return
			end
		end
		use.card = card
		return
	end
	if self.player:getHandcardNum() == 1 and self:needKongcheng() and self:evaluateArmor(card) > -5 then
		local armor = original_equipment(self.player,"getArmor")
		if armor and armor:objectName() == "PeaceSpell" and card:isKindOf("Armor") then
			if (self:getAllPeachNum() == 0 and self.player:getHp() < 3) and not (self.player:getHp() < 2 and self:getCardsNum("Analeptic") > 0) then
				return
			end
		end
		use.card = card
		return
	end
	if card:isKindOf("Armor") and card:objectName() == "PeaceSpell" then
		local heg_lord_zhangjiao = ht_find_shown(self,"heg_wendao") --有君张角在其他人（受伤/有防具）则不装备太平要术
		if heg_lord_zhangjiao and heg_lord_zhangjiao:isAlive() and not self:isWeak(heg_lord_zhangjiao) then
			if self.player:objectName() ~= heg_lord_zhangjiao:objectName() and (self.player:isWounded() or original_equipment(self.player,"getArmor")) then
				return
			end
		end
	end
	if card:isKindOf("Weapon") and card:objectName() == "DragonPhoenix" then
		local heg_lord_liubei = ht_find_shown(self,"heg_zhangwu") --有君刘备在（其他势力/除他以外有武器）的人不装备龙凤剑
		if heg_lord_liubei and heg_lord_liubei:isAlive() then
			if not ht_public_friend(self,self.player,heg_lord_liubei) or (self.player:objectName() ~= heg_lord_liubei:objectName() and original_equipment(self.player,"getWeapon")) then
				return
			end
		end
	end
	local same = self:getSameEquip(card)
	local zzzh, isfriend_zzzh, isenemy_zzzh = ht_find_shown(self,"guzheng")
	if zzzh then
		if self:isFriend(zzzh) then isfriend_zzzh = true
		else isenemy_zzzh = true
		end
	end
	if same then
		if (self.player:hasSkill("rende") and self:findFriendsByType(sgs.Friend_Draw))
			or (self.player:hasSkills("qixi|heg_duanliang") and (card:isBlack() or same:isBlack()))
			or (self.player:hasSkills("heg_guose") and (card:getSuit() == sgs.Card_Diamond or same:getSuit() == sgs.Card_Diamond))
			or (self.player:hasSkill("jijiu") and (card:isRed() or same:isRed()))
			or (self.player:hasSkill("guidao") and same:isBlack() and card:isRed())
			or isfriend_zzzh
			then return end
	end
	local canUseSlash = self:getCardId("Slash") and self:slashIsAvailable(self.player)
	self:useCardByClassName(card, use)
	if use.card then return end
	if card:isKindOf("Weapon") then
		if same and self.player:hasSkill("heg_qiangxi") and not self.player:hasUsed("HQiangxiCard") then
			local dummy_use = { isDummy = true }
			self:useSkillCard(self:evaluateSkillCard("heg_qiangxi","HQiangxiCard",{same:getEffectiveId()}), dummy_use)
			if dummy_use.card and dummy_use.card:getSubcards():length() == 1 then return end
		end
		if self.player:hasSkill("rende") then
			for _, friend in ipairs(self.friends_noself) do
				if not original_equipment(friend,"getWeapon") then return end
			end
		end
		if self.player:hasSkills("heg_paoxiao") and card:isKindOf("Crossbow") then return end
		if not self:needKongcheng() and not self.player:hasSkills(ht_fact(self,"lose_equip_skill")) and self:getOverflow() <= 0 and not canUseSlash then return end
		if self.player:hasSkill("heg_zhiheng") and not self.player:hasUsed("HZhihengCard") and original_equipment(self.player,"getWeapon") and not card:isKindOf("Crossbow") then return end
		if not self:needKongcheng() and self.player:getHandcardNum() <= self.player:getHp() - 2 then return end
		if not original_equipment(self.player,"getWeapon") or self:evaluateWeapon(card) > self:evaluateWeapon(original_equipment(self.player,"getWeapon")) then
			use.card = card
		end
	elseif card:isKindOf("Armor") then
		local lion = self:getCard("SilverLion")
		if lion and self.player:isWounded() and not self.player:hasArmorEffect("SilverLion") and not card:isKindOf("SilverLion")
			and not (self.player:hasSkills("bazhen|jgyizhong") and not original_equipment(self.player,"getArmor")) then
			use.card = lion
			return
		end
		if self.player:hasSkill("rende") and self:evaluateArmor(card) < 4 then
			for _, friend in ipairs(self.friends_noself) do
				if not original_equipment(friend,"getArmor") then return end
			end
		end
		if self:evaluateArmor(card) > self:evaluateArmor() or isenemy_zzzh and self:getOverflow() > 0 then use.card = card end
		return
	elseif card:isKindOf("OffensiveHorse") then
		if self.player:hasSkill("rende") then
			for _,friend in ipairs(self.friends_noself) do
				if not original_equipment(friend,"getOffensiveHorse") then return end
			end
			use.card = card
			return
		else
			if not self.player:hasSkills(ht_fact(self,"lose_equip_skill")) and self:getOverflow() <= 0 and not (canUseSlash or self:getCardId("Snatch")) then
				return
			else
				if ht_native_equip(self,card) then
					use.card = card
					return
				end
			end
		end
	elseif card:isKindOf("DefensiveHorse") then
		local heg_tiaoxin = true
		if self.player:hasSkill("heg_tiaoxin") then
			local dummy_use = { isDummy = true, defHorse = true }
			self:useSkillCard(self:evaluateSkillCard("heg_tiaoxin","HTiaoxinCard",{}), dummy_use)
			if not dummy_use.card then heg_tiaoxin = false end
		end
		if heg_tiaoxin and ht_native_equip(self,card) then
			use.card = card
		end
	elseif card:isKindOf("Treasure") then
		if not card:isKindOf("wooden_ox") and not original_equipment(self.player,"getTreasure")then
			for _, friend in ipairs(self.friends) do
				if (original_equipment(friend,"getTreasure") and friend:getPile("wooden_ox"):length() > 1) then
					return
				end
			end
		end
		if not original_equipment(self.player,"getTreasure") or card:isKindOf("JadeSeal") then
			use.card = card
		end
	elseif ht_native_equip(self,card) then
		use.card = card
	end
end

function SmartAIView:originalHegemonyWillUseGodSalvation(card)
	if not card then return false end
	local good, bad = 0, 0
	local wounded_friend = 0
	local wounded_enemy = 0

	local noresponse = false
	local noresponselist = ht_no_response(self,card)--新增卡牌无法响应
	if noresponselist and table.contains(noresponselist,"_ALL_PLAYERS") then
		noresponse = true
	end

	local heg_xuyou = ht_find_shown(self,"heg_chenglve")
	local aoedraw = heg_xuyou and ht_public_friend(self,self.player,heg_xuyou)
	if self.player:hasSkill("heg_jizhi") or aoedraw then good = good + 6 end
	if (self.player:hasSkill("heg_kongcheng") and self.player:getHandcardNum() == 1) or not self:originalHegemonyHasLoseHandcardEffective() then good = good + 5 end

	for _, friend in ipairs(self.friends) do
		if noresponselist and table.contains(noresponselist,friend:objectName()) then
			noresponse = true
		end
		if not noresponse then
			good = good + 10 * getCardsNum("Nullification", friend, self.player)
		end
		if self:originalHegemonyTrickIsEffective(card,friend,self.player) then
			if friend:canRecover() then
				wounded_friend = wounded_friend + 1
				good = good + 10
				if friend:isLord() then good = good + 10 / math.max(friend:getHp(), 1) end
				if ht_shown_skills(self,friend, ht_fact(self,"masochism_skill")) then
					good = good + 5
				end
				if friend:getHp() <= 1 and self:isWeak(friend) then
					good = good + 5
					if friend:isLord() then good = good + 10 end
				else
					if friend:isLord() then good = good + 5 end
				end
				if self:needToLoseHp(friend,nil,nil,true,true) then good = good - 3 end
			end
		end
	end

	for _, enemy in ipairs(self.enemies) do
		if noresponselist and table.contains(noresponselist,enemy:objectName()) then
			noresponse = true
		end
		if not noresponse then
			bad = bad + 10 * getCardsNum("Nullification", enemy, self.player)
		end
		if self:originalHegemonyTrickIsEffective(card,enemy,self.player) then
			if enemy:canRecover() then
				wounded_enemy = wounded_enemy + 1
				bad = bad + 10
				if enemy:isLord() then
					bad = bad + 10 / math.max(enemy:getHp(), 1)
				end
				if ht_shown_skills(self,enemy, ht_fact(self,"masochism_skill")) then
					bad = bad + 5
				end
				if enemy:getHp() <= 1 and self:isWeak(enemy) then
					bad = bad + 5
					if enemy:isLord() then bad = bad + 10 end
				else
					if enemy:isLord() then bad = bad + 5 end
				end
				if self:needToLoseHp(enemy,nil,nil,true,true) then bad = bad - 3 end
			end
		end
	end
	return good - bad > 5 and wounded_friend > 0
end

function SmartAIView:originalHegemonyFindLeijiTarget(player, leiji_value, slasher)
	if not ht_shown(self,player,"nosleiji") then return end
	if slasher then
		-- Query the pure-value printed Slash; native factories are unavailable in this VM.
		if not self:originalHegemonySlashIsEffective(known(self:getEvaluationCard("slash"),"printed Slash"),player,slasher,slasher:hasWeapon("QinggangSword")) then return nil end
		if self:originalHegemonyCanLiegong(player, slasher) and self:isEnemy(player,slasher) then
			return nil
		end
		if not self:originalHegemonyHasSuit("spade",true,player) and player:getHandcardNum() < 3 then return nil end
		local hasJink
		if getKnownCard(player, self.player, "Jink", true) > 0 then hasJink = true end
		if not hasJink and player:getHandcardNum() >= 3 and getCardsNum("Jink", player, self.player) >= 1 and ht_original_lack(self,player,"Jink") ~= 1 then hasJink = true end
		if not hasJink and not self:isWeak(player) and self:originalHegemonyHasEightDiagramEffect(player) and not slasher:hasWeapon("QinggangSword") then hasJink = true end
		if not hasJink then return end
	end
	local getCmpValue = function(enemy)
		local value = 0
		local damage = {}
		damage.to = enemy
		damage.from = player
		damage.nature = sgs.DamageStruct_Thunder
		damage.damage = 2
		if not self:originalHegemonyDamageIsEffective_(damage) then return 99 end
		if ht_shown(self,enemy,"hongyan") then return 99 end
		if self:cantbeHurt(enemy,player,2) or self:objectiveLevel(enemy) < 3
			or (enemy:isChained() and not self:originalHegemonyChainTargetStruct(damage)) then return 100 end
		if not self:originalHegemonyIsGoodTarget(enemy,self.enemies) then value = value + 50 end
		if enemy:hasArmorEffect("SilverLion") then value = value + 20 end
		if ht_shown_skills(self,enemy, ht_fact(self,"exclusive_skill")) then value = value + 10 end
		if ht_shown_skills(self,enemy, ht_fact(self,"masochism_skill")) then value = value + 5 end
		if enemy:isChained() and self:originalHegemonyChainTargetStruct(damage) and #(self:originalHegemonyGetChainedEnemies(player)) > 1 then value = value - 25 end
		if enemy:isLord() then value = value - 5 end
		value = value + enemy:getHp() + self:originalHegemonyGetDefenseSlash(enemy) * 0.01
		return value
	end

	local cmp = function(a, b)
		return getCmpValue(a) < getCmpValue(b)
	end

	local enemies = self:getEnemies(player)
	table.sort(enemies, cmp)
	for _, enemy in ipairs(enemies) do
		if getCmpValue(enemy) < leiji_value then return enemy end
	end
	return nil
end

function SmartAIView:originalHegemonyNeedLeiji(to, from)
	return self:originalHegemonyFindLeijiTarget(to, 50, from)
end


function SmartAIView:originalHegemonyDoNotDiscard(to, flags, conservative, n, cant_choose)
	if not to then  return end
	n = n or 1
	flags = flags or "he"
	if to:isNude() then return true end
	conservative = conservative or (self.room:getTurnCount() <= 2 and self.room:alivePlayerCount() > 2)
	local enemies = self:getEnemies(to)
	if #enemies == 1 and ht_shown_skills(self,enemies[1], "heg_qianxun|heg_weimu") and self.room:alivePlayerCount() == 2 then conservative = false end

	if cant_choose then
		if self:needKongcheng(to) and to:getHandcardNum() <= n then return true end
		if self:originalHegemonyGetLeastHandcardNum(to) <= n then return true end
		if ht_shown_skills(self,to, ht_fact(self,"lose_equip_skill")) and to:hasEquip() then return true end
		if self:needToThrowArmor(to) then return true end
	else
		if flags:match("e") then
			if ht_shown_skills(self,to, "jieyin+heg_xiaoji") and to:getDefensiveHorse() then return false end
			if ht_shown_skills(self,to, "jieyin+heg_xiaoji") and to:getArmor() and not to:getArmor():isKindOf("SilverLion") then return false end
		end
		if flags == "h" or (flags == "he" and not to:hasEquip()) then
			if to:isKongcheng() or not self.player:canDiscard(to,"h") then return true end
			if not self:originalHegemonyHasLoseHandcardEffective(to) then return true end
			if to:getHandcardNum() == 1 and self:needKongcheng(to) then return true end
			if #self.friends > 1 and to:getHandcardNum() == 1 and ht_shown(self,to,"sijian") then return false end
		elseif flags == "e" or (flags == "he" and to:isKongcheng()) then
			if not to:hasEquip() then return true end
			if ht_shown_skills(self,to, ht_fact(self,"lose_equip_skill")) then return true end
			if to:getCardCount(true) == 1 and self:needToThrowArmor(to) then return true end
		end
		if flags == "he" and n == 2 then
			if not self.player:canDiscard(to,"e") then return true end
			if to:getCardCount(true) < 2 then return true end
			if not to:hasEquip() then
				if not self:originalHegemonyHasLoseHandcardEffective(to) then return true end
				if to:getHandcardNum() <= 2 and self:needKongcheng(to) then return true end
			end
			if ht_shown_skills(self,to, ht_fact(self,"lose_equip_skill")) and to:getHandcardNum() < 2 then return true end
			if to:getCardCount(true) <= 2 and self:needToThrowArmor(to) then return true end
		end
	end
	if flags == "he" and n > 2 then
		if not self.player:canDiscard(to,"e") then return true end
		if to:getCardCount(true) < n then return true end
	end
	return false
end

function SmartAIView:originalHegemonyFindPlayerToDiscard(flags, include_self, isDiscard, players, return_table)
	local player_table = {}
	if isDiscard == nil then isDiscard = true end
	local friends, enemies = {}, {}
	if not players then
		friends = include_self and self.friends or self.friends_noself
		enemies = self.enemies
	else
		for _, player in sgs.qlist(players) do
			if self:isFriend(player) and (include_self or player:objectName() ~= self.player:objectName()) then table.insert(friends, player)
			elseif self:isEnemy(player) then table.insert(enemies, player) end
		end
	end
	flags = flags or "he"

	self:originalHegemonySort(enemies, "defense")
	if flags:match("e") then
		for _, enemy in ipairs(enemies) do
			if self.player:canDiscard(enemy,"e") then
				local dangerous = self:originalHegemonyGetDangerousCard(enemy)
				if dangerous and (not isDiscard or self.player:canDiscard(enemy,dangerous)) then
					table.insert(player_table, enemy)
				end
			end
		end
		for _, enemy in ipairs(enemies) do
			if enemy:hasArmorEffect("EightDiagram") and not self:needToThrowArmor(enemy) and self.player:canDiscard(enemy,enemy:getArmor():getEffectiveId()) then
				table.insert(player_table, enemy)
			end
		end
	end

	if flags:match("j") then
		for _, friend in ipairs(friends) do
			if ((friend:containsTrick("indulgence") and not ht_shown(self,friend,"heg_keji")) or friend:containsTrick("supply_shortage"))
				and not (ht_shown(self,friend,"qiaobian") and not friend:isKongcheng())
				and (not isDiscard or self.player:canDiscard(friend,"j")) then
				table.insert(player_table, friend)
			end
		end
		for _, friend in ipairs(friends) do
			if friend:containsTrick("lightning") and self:originalHegemonyHasWizard(enemies, true) and (not isDiscard or self.player:canDiscard(friend,"j")) then table.insert(player_table, friend) end
		end
		for _, enemy in ipairs(enemies) do
			if enemy:containsTrick("lightning") and self:originalHegemonyHasWizard(enemies, true) and (not isDiscard or self.player:canDiscard(enemy,"j")) then table.insert(player_table, enemy) end
		end
	end

	if flags:match("e") then
		for _, friend in ipairs(friends) do
			if self:needToThrowArmor(friend) and (not isDiscard or self.player:canDiscard(friend,friend:getArmor():getEffectiveId())) then
				table.insert(player_table, friend)
			end
		end
		for _, enemy in ipairs(enemies) do
			if self.player:canDiscard(enemy,"e") then
				local valuable = self:originalHegemonyGetValuableCard(enemy)
				if valuable and (not isDiscard or self.player:canDiscard(enemy,valuable)) then
					table.insert(player_table, enemy)
				end
			end
		end
		for _, enemy in ipairs(enemies) do
			if ht_shown_skills(self,enemy, "jijiu|beige|heg_weimu|heg_qingcheng") and not self:originalHegemonyDoNotDiscard(enemy,"e") then
				if enemy:getDefensiveHorse() and (not isDiscard or self.player:canDiscard(enemy,enemy:getDefensiveHorse():getEffectiveId())) then table.insert(player_table, enemy) end
				if enemy:getArmor() and not self:needToThrowArmor(enemy) and (not isDiscard or self.player:canDiscard(enemy,enemy:getArmor():getEffectiveId())) then table.insert(player_table, enemy) end
				if enemy:getOffensiveHorse() and (not ht_shown(self,enemy,"jijiu") or enemy:getOffensiveHorse():isRed()) and (not isDiscard or self.player:canDiscard(enemy,enemy:getOffensiveHorse():getEffectiveId())) then
					table.insert(player_table, enemy)
				end
				if enemy:getWeapon() and (not ht_shown(self,enemy,"jijiu") or enemy:getWeapon():isRed()) and (not isDiscard or self.player:canDiscard(enemy,enemy:getWeapon():getEffectiveId())) then
					table.insert(player_table, enemy)
				end
			end
		end
	end

	if flags:match("h") then
		for _, enemy in ipairs(enemies) do
			local cards = ht_known_hand(self,enemy)
			if enemy:getHandcardNum() <= 2 and not enemy:isKongcheng() and not (ht_shown(self,enemy,"heg_tuntian") and enemy:getPhase() == sgs.Player_NotActive) then
				for _, cc in ipairs(cards) do
					if true and (cc:isKindOf("Peach") or cc:isKindOf("Analeptic")) and (not isDiscard or self.player:canDiscard(enemy,cc:getId())) then
						table.insert(player_table, enemy)
					end
				end
			end
		end
	end

	if flags:match("e") then
		for _, enemy in ipairs(enemies) do
			if enemy:hasEquip() and not self:originalHegemonyDoNotDiscard(enemy,"e") and (not isDiscard or self.player:canDiscard(enemy,"e")) then
				table.insert(player_table, enemy)
			end
		end
	end

	if flags:match("h") then
		self:originalHegemonySort(enemies, "handcard")
		for _, enemy in ipairs(enemies) do
			if (not isDiscard or self.player:canDiscard(enemy,"h")) and not self:originalHegemonyDoNotDiscard(enemy,"h") then
				table.insert(player_table, enemy)
			end
		end
	end

	if flags:match("h") then
		local heg_zhugeliang = ht_find_shown(self,"heg_kongcheng")
		if heg_zhugeliang and self:isFriend(heg_zhugeliang) and heg_zhugeliang:getHandcardNum() == 1 and self:originalHegemonyGetEnemyNumBySeat(self.player,heg_zhugeliang) > 0
			and heg_zhugeliang:getHp() <= 2 and (not isDiscard or self.player:canDiscard(heg_zhugeliang,"h")) then
			table.insert(player_table, heg_zhugeliang)
		end
	end
	if return_table then return player_table
	else
		if #player_table == 0 then return nil else return player_table[1] end
	end
end

function SmartAIView:originalHegemonyGetDangerousCard(who)
	local weapon = who:getWeapon()
	local armor = who:getArmor()
	local treasure = who:getTreasure()
--有优先顺序
	if weapon and (weapon:isKindOf("Crossbow") or weapon:isKindOf("GudingBlade")) and self:isEnemy(who) then
		for _, friend in ipairs(self.friends) do
			if weapon:isKindOf("Crossbow") and who:distanceTo(friend) <= 1 and getCardsNum("Slash", who, self.player) > 0 then
				return weapon:getEffectiveId()
			end
			if weapon:isKindOf("GudingBlade") and who:inMyAttackRange(friend) and friend:isKongcheng() and not ht_shown(self,friend,"heg_kongcheng") and getCardsNum("Slash", who) > 0 then
				return weapon:getEffectiveId()
			end
		end
	end
	if weapon and weapon:isKindOf("Axe") and ht_shown_skills(self,who, "heg_luoyi|heg_suzhi") then
		return weapon:getEffectiveId()
	end

	if treasure and treasure:isKindOf("HJadeSeal") then
		return treasure:getEffectiveId()
	end
	if treasure and treasure:isKindOf("HLuminousPearl") and ht_shown_skills(self,who, ht_fact(self,"lose_equip_skill") .. "|heg_zhiheng|lirang") then
		return treasure:getEffectiveId()
	end
	if treasure and treasure:isKindOf("WoodenOx") and who:getPile("wooden_ox"):length() > 1 then
		return treasure:getEffectiveId()
	end

	if weapon and weapon:isKindOf("HHalberd") and ht_shown_skills(self,who, ht_fact(self,"force_slash_skill") .. "|heg_paoxiao|heg_paoxiao_xh|heg_baolie|heg_xiongnve|heg_kuangcai") then
		return weapon:getEffectiveId()
	end
	if weapon and weapon:isKindOf("Spear") and ht_shown_skills(self,who, "heg_paoxiao|heg_paoxiao_xh|heg_baolie|heg_xiongnve|heg_kuangcai") and who:getHandcardNum() >= 1 then
		return weapon:getEffectiveId()
	end
	if weapon and weapon:isKindOf("HDragonPhoenix") and ht_shown_skills(self,who, "heg_paoxiao|heg_paoxiao_xh|heg_baolie|heg_suzhi|heg_xiongnve|heg_kuangcai") then
		return weapon:getEffectiveId()
	end

	if armor and armor:isKindOf("EightDiagram") and ht_shown_skills(self,who, ht_fact(self,"wizard_skill")) then
		return armor:getEffectiveId()
	end
	if armor and armor:isKindOf("RenwangShield") and ht_shown(self,who,"heg_jiang") then
		return armor:getEffectiveId()
	end
	if armor and armor:isKindOf("HPeaceSpell") and ht_same_kingdom(self,who) > 2
	and not ht_find_shown(self,"heg_wendao") then
		return armor:getEffectiveId()
	end



	if weapon and self:isEnemy(who) then
		for _, friend in ipairs(self.friends) do
			if who:distanceTo(friend) < who:getAttackRange(false) and self:isWeak(friend) and not self:originalHegemonyDoNotDiscard(who,"e",true) then return weapon:getEffectiveId() end
		end
	end
end

function SmartAIView:originalHegemonyGetValuableCard(who)
	local weapon = who:getWeapon()
	local armor = who:getArmor()
	local offhorse = who:getOffensiveHorse()
	local defhorse = who:getDefensiveHorse()
	local treasure = who:getTreasure()
	self:originalHegemonySort(self.friends, "hp")
	local friend
	if #self.friends > 0 then friend = self.friends[1] end
	if friend and self:isWeak(friend) and who:distanceTo(friend) <= who:getAttackRange(false) and not self:originalHegemonyDoNotDiscard(who,"e",true) then
		if weapon and (who:distanceTo(friend) > 1) then
			return weapon:getEffectiveId()
		end
		if offhorse and who:distanceTo(friend) > 1 then
			return offhorse:getEffectiveId()
		end
	end

	if treasure and not self:originalHegemonyDoNotDiscard(who,"e") then
		return treasure:getEffectiveId()
	end

	if defhorse and not self:originalHegemonyDoNotDiscard(who,"e")
		and not (self.player:hasWeapon("KylinBow") and self.player:canSlash(who) and self:originalHegemonySlashIsEffective(known(self:getEvaluationCard("slash"),"printed Slash"),who,self.player)
				and (getCardsNum("Jink", who, self.player) < 1 or ht_original_lack(self,who,"Jink") == 1 )) then
		return defhorse:getEffectiveId()
	end

	if armor and self:evaluateArmor(armor,who) > 3  and not self:needToThrowArmor(who)  and not self:originalHegemonyDoNotDiscard(who,"e")
	and (not armor:isKindOf("HPeaceSpell") or not ht_find_shown(self,"heg_wendao")) then
		return armor:getEffectiveId()
	end

	if offhorse and ht_shown_skills(self,who, "tenyearkuanggu|heg_duanbing|heg_qianxi") then
		return offhorse:getEffectiveId()
	end

	local equips = sgs.QList2Table(who:getEquips())
	for _,equip in ipairs(equips) do
		if ht_shown(self,who,"heg_guose") and equip:getSuit() == sgs.Card_Diamond then  return equip:getEffectiveId() end
		if ht_shown_skills(self,who, "qixi|heg_duanliang|guidao") and equip:isBlack() then  return equip:getEffectiveId() end
		if ht_shown_skills(self,who, "tenyearwusheng|jijiu") and equip:isRed() then  return equip:getEffectiveId() end
		if ht_shown_skills(self,who, ht_fact(self,"need_equip_skill")) and not ht_shown_skills(self,who, ht_fact(self,"lose_equip_skill")) then return equip:getEffectiveId() end
	end

	if armor and not self:needToThrowArmor(who) and not self:originalHegemonyDoNotDiscard(who,"e")
	and (not armor:isKindOf("HPeaceSpell") or not ht_find_shown(self,"heg_wendao")) then
		return armor:getEffectiveId()
	end

	if offhorse and who:getHandcardNum() > 1 then
		if not self:originalHegemonyDoNotDiscard(who,"e",true) then
			for _,f in ipairs(self.friends) do
				if who:distanceTo(f) == who:getAttackRange() and who:getAttackRange() > 1 then
					return offhorse:getEffectiveId()
				end
			end
		end
	end

	if weapon and who:getHandcardNum() > 1 then
		if not self:originalHegemonyDoNotDiscard(who,"e",true) then
			for _,f in ipairs(self.friends) do
				if (who:distanceTo(f) <= who:getAttackRange()) and (who:distanceTo(f) > 1) then
					return weapon:getEffectiveId()
				end
			end
		end
	end
end

function SmartAIView:originalHegemonyGetLeastHandcardNum(player)
	player = player or self.player
	local least = 0
	local jwfy = ht_find_shown(self,"heg_shoucheng")
	if least < 1 and jwfy and self:isFriend(jwfy,player) then least = 1 end
	return least
end

function SmartAIView:originalHegemonyHasLoseHandcardEffective(player)
	player = player or self.player
	return player:getHandcardNum() > self:originalHegemonyGetLeastHandcardNum(player)
end

function SmartAIView:originalHegemonyHasWizard(players, onlyharm)
	local skill
	if onlyharm then skill = ht_fact(self,"wizard_harm_skill") else skill = ht_fact(self,"wizard_skill") end
	for _, player in ipairs(players) do
		if ht_shown_skills(self,player, skill) then
			return true
		end
	end
end

function SmartAIView:originalHegemonyHasSuit(suit_strings, include_equip, player)
	return self:originalHegemonyGetSuitNum(suit_strings,include_equip,player) > 0
end

function SmartAIView:originalHegemonyGetSuitNum(suit_strings, include_equip, player)
	player = player or self.player
	local n = 0
	local flag = include_equip and "he" or "h"
	local allcards
	if player:objectName() == self.player:objectName() then
		allcards = sgs.QList2Table(player:getCards(flag))
	else
		allcards = include_equip and sgs.QList2Table(player:getEquips()) or {}
		local handcards = ht_known_hand(self,player)
		for i = 1, #handcards, 1 do
			if true then
				table.insert(allcards, handcards[i])
			end
		end
	end
	for _, card in ipairs(allcards) do
		for _, suit_string in ipairs(suit_strings:split("|")) do
			if card:getSuitString() == suit_string
				or (suit_string == "black" and card:isBlack()) or (suit_string == "red" and card:isRed()) then
				n = n + 1
			end
		end
	end
	return n
end

function SmartAIView:originalHegemonyGetEnemyNumBySeat(from, to, target, include_neutral)
	target = target or from
	local players = sgs.QList2Table(self.room:getAllPlayers())
	local to_seat = (to:getSeat() - from:getSeat()) % #players
	local enemynum = 0
	for _, p in ipairs(players) do
		if  (self:isEnemy(target,p) or (include_neutral and not self:isFriend(target,p))) and ((p:getSeat() - from:getSeat()) % #players) < to_seat then
			enemynum = enemynum + 1
		end
	end
	return enemynum
end

function SmartAIView:originalHegemonyGetChainedEnemies(player)
	player = player or self.player
	local chainedEnemies = {}
	for _, enemy in ipairs(self:getEnemies(player)) do
		if enemy:isChained() then
			table.insert(chainedEnemies,enemy)
		end
	end
	return chainedEnemies
end

function SmartAIView:originalHegemonyGetSameEquip(card, player)
	player = player or self.player
	if not card then return end
	if card:isKindOf("Weapon") then return player:getWeapon()
	elseif card:isKindOf("Armor") then return player:getArmor()
	elseif card:isKindOf("DefensiveHorse") then return player:getDefensiveHorse()
	elseif card:isKindOf("OffensiveHorse") then return player:getOffensiveHorse() end
end

function SmartAIView:originalHegemonyGetAllPeachNum(player)
	player = player or self.player
	local n = 0
	for _, friend in ipairs(self:getFriends(player)) do
		local num = self.player:objectName() == friend:objectName() and self:getCardsNum("Peach") or getCardsNum("Peach", friend, self.player)
		n = n + num
	end
	return n
end
function SmartAIView:originalHegemonyHasEightDiagramEffect(player)
	player = player or self.player
	return player:hasArmorEffect("EightDiagram") or player:hasArmorEffect("bazhen")
end


