-- Fixed-source catalog is an immutable local table. false means explicit nil.
function SmartAIView:originalHegemonyPrintedValue(table_name,key,card,fallback)
    local catalog=original_hegemony_printed_catalog[table_name]
    if type(catalog)~='table' then ai_unsupported('Original printed registry is not admitted',table_name) end
    local value,override
    if table_name=='ai_use_priority' then
        local state,present=self:getStrategyMemory('priority_overrides')
        if present and type(state)=='table'then override=state[key]end
        if override~=nil then
            if type(override)~='table' then ai_unsupported('Original priority override is invalid',key) end
            if override.removed==true then
                self:useKnowledgeEstimate({value=false,status='estimate',priority_key=key,
                    source=override.source,viewer=self.player:objectName(),observer=self.player:objectName(),
                    basis='original_viewer_local_priority_without_private_cross_viewer_propagation'},'Original.printed_priority')
                return fallback
            end
            if type(override.value)~='number'then ai_unsupported('Original priority override is invalid',key)end
            value=override.value
        end
    end
    if override==nil then
        value=rawget(catalog,key)
        if value==false then return nil end
        if value==nil then
            local base=sgs[table_name]
            if type(base)~='table'then ai_unsupported('Original fallback registry unavailable',table_name)end
            value=base[key]
        end
    end
    if table_name=='ai_suit_priority'then
        if value~=nil and type(value)~='string'and type(value)~='function'then ai_unsupported('Original suit priority invalid',key)end
        return value
    end
    if type(value)=='function'then value=value(self,card)end
    if value==nil then value=fallback end
    if value~=nil and(type(value)~='number'or value~=value or value==math.huge or value==-math.huge)then ai_unsupported('Original printed value invalid',key)end
    if table_name=='ai_use_priority'and value~=nil then
        value=self:useKnowledgeEstimate({value=value,status='estimate',priority_key=key,
            source=override and override.source or 'fixed_original_loader_metadata',
            viewer=self.player:objectName(),observer=self.player:objectName(),
            basis='original_viewer_local_priority_without_private_cross_viewer_propagation'},'Original.printed_priority')
    end
    return value
end

-- Original Hegemony source subtree, fixed b6025acc. Install these methods only
-- after the admitted Original bundle mode gate; never overwrite ordinary mode.
local hv_known = AIValue.requireKnown
local function hv_q(object,method,...)
    if AIValue.isPlayer(object)then
        if method=='getMark'then method='getStrategyMark'elseif method=='hasFlag'then method='getStrategyFlag'end
    end
    if not object or type(object[method])~='function'then ai_unsupported('Original Slash dependency unavailable',method)end
    return hv_known(object[method](object,...),method)
end
local function hv_facts(self)return hv_known(AIHegemony.facts(self.world),'hegemony facts')end
local function hv_fact(self,key)
    -- Both fixed Original initializers (common349/5080) assign this exact category.
    if key=="need_kongcheng"then return "heg_kongcheng"end
    if key:match('^owner_')then return self:originalHegemonyOwnerFact(key)end
    return hv_known(hv_facts(self)[key],key)
end
local function hv_row(self,p)return hv_known(hv_fact(self,'players')[p:objectName()],'public Hegemony player')end
local function hv_shown(self,p,name)return hv_known(hv_row(self,p).shown_skills,'shown skills')[name]~=nil end
local hv_skill_aliases = {
    nosganglie = {"heg_ganglie"}, nostuxi = {"tenyeartuxi"}, nosluoyi = {"heg_luoyi"},
    nosyiji = {"heg_yiji"}, shensu = {"heg_shensu"},
    duanliang = {"heg_duanliang"}, nosjushou = {"heg_jushou"}, qiangxi = {"heg_qiangxi"},
    jieming = {"heg_jieming"}, fangzhu = {"mobilefangzhu"}, luoshen = {"heg_luoshen"},
    guicai = {"heg_guicai"},
    paoxiao = {"heg_paoxiao"}, kongcheng = {"heg_kongcheng"}, longdan = {"heg_longdan"},
    tieqi = {"heg_tieqi"}, jizhi = {"heg_jizhi"}, liegong = {"heg_liegong"},
    wusheng = {"tenyearwusheng"}, kuanggu = {"tenyearkuanggu"}, huoshou = {"heg_huoshou"}, juxiang = {"heg_juxiang"},
    keji = {"heg_keji"},
    kurou = {"heg_kurou"}, yingzi = {"heg_yingzi_sunce", "heg_yingzi_zhouyu"},
    qicai = {"nosqicai"},
    fanjian = {"heg_fanjian"}, guose = {"heg_guose"}, qianxun = {"heg_qianxun"},
    xiaoji = {"heg_xiaoji"}, yinghun = {"heg_yinghun_sunjian", "heg_yinghun_sunce"},
    tianxiang = {"heg_tianxiang"}, buqu = {"heg_buqu"}, guzheng = {"heg_guzheng"},
    duanbing = {"heg_duanbing"}, fenxun = {"heg_fenxun"}, luanji = {"heg_luanji"},
     weimu = {"heg_weimu"},
	leiji = {"nosleiji"}, duanchang = {"heg_duanchang"},
    wushuang = {"heg_wushuang"}, jiang = {"heg_jiang"},
}
local function hv_shown_skills(self,p,names)
    for group in names:gmatch('[^|]+')do
        local all=true;for name in group:gmatch('[^+]+')do
            local found=false;for _,actual in ipairs(hv_skill_aliases[name]or{name})do if hv_shown(self,p,actual)then found=true;break end end
            if not found then all=false;break end
        end
        if all then return true end
    end
    return false
end
local function hv_find_shown(self,name)
    for _,p in ipairs(self.room:getAllPlayers())do if hv_shown(self,p,name)then return p end end
end
hooks_pending.hv_both_shown = function(self,p)local r=hv_row(self,p);return hv_known(r.shown_head,'shown head')and hv_known(r.shown_deputy,'shown deputy')end
local function hv_public_friend(self,a,b)return a:isPublicHegemonyFriend(b)end
hooks_pending.hv_visible = function(self,id)
    -- Negative virtual IDs have no engine physical card; source getCard returns
    -- no physical card there. Positive IDs must remain in the lawful domain.
    if type(id)=='number'and id<0 then return nil end
    return hv_known(self:getKnownCardById(id),'lawful source card '..tostring(id))
end
local function hv_target_mod(self,card,kind)
    local method=({distance='getTargetModDistance',extra='getTargetModExtra',residue='getTargetModResidue'})[kind]
    return hv_q(card,hv_known(method,'target modifier kind'),self.player)
end
hooks_pending.hv_no_response = function(self,card)return self:cardNoResponseNames(card)end
hooks_pending.hv_skill = function(self,name)
    if name==''then return nil end
    return hv_known(self.room:getPublicSkill(name),'skill definition outside the visible roster')
end
hooks_pending.hv_ignore_armor = function(self,from,to)
    if not from or not to then return end
    local armor=to:getArmor()
    if not armor then return true end
    if not to:hasArmorEffect(armor:objectName())or from:hasWeapon('QinggangSword')then return true end
end
hooks_pending.hv_private_jink = function(self,target)
    -- Fixed donor cardIsVisible always uses current_self.player even when the
    -- caller passes target as observer. This is a visible count, not full-hand estimation.
    return getKnownCard(target,target,'Jink',true,'he')
end

hooks_pending.hv_original_lack = function(self,target,kind)
    local state,present=self:getStrategyMemory('original_hegemony.card_lack')
    local row=present and type(state)=='table'and state[target:objectName()]
    if type(row)=='table'and type(row[kind])=='number'then return row[kind]end
    return self:useKnowledgeEstimate({value=0,status='estimate',basis='no_observed_original_hegemony_card_lack_prior',
        viewer=self.player:objectName(),target=target:objectName(),class=kind},'OriginalAnaleptic.card_lack')
end
hooks_pending.hv_damage_callbacks = function(self)
    return original_damage_effect_callbacks(self)
end

hooks_pending.hv_head_kingdom = function(self,player)
    local row=hv_row(self,player)
    if player:objectName()==self.player:objectName()then return hv_known(hv_facts(self).owner_head_kingdom,'owner head kingdom')end
    if row.head_kingdom~=nil then return row.head_kingdom end
    return self:useKnowledgeEstimate({value='unknown',status='estimate',basis='unrevealed_head_kingdom_unavailable',viewer=self.player:objectName(),target=player:objectName()},'OriginalDefense.careerist_head')
end
hooks_pending.hv_public_kingdom = function(self,player)
    local kingdom=hv_known(hv_row(self,player).public_kingdom,'public kingdom')
    return kingdom~=''and kingdom or'unknown'
end

hooks_pending.hv_null_skill = function(self,skill,player)
    local value=player:hasSkill(skill)
    if value~=nil then return not value end
    return self:useKnowledgeEstimate({value=true,status='estimate',basis='foreign_unseen_skill_absence_prior',viewer=self.player:objectName(),target=player:objectName(),skill=skill},'OriginalDefense.hasNullSkill')
end

hooks_pending.hv_siege = function(self,holder,target)
    return hv_known(hv_known(hv_row(self,holder).siege_targets,'public siege targets')[target:objectName()],'public siege relation')
end
hooks_pending.hv_jink_limited = function(self,player,jink)
    local result=player:isCardLimited(jink,sgs.Card_MethodUse)
    if result~=nil then return result end
    if player:objectName()==self.player:objectName()then return hv_known(nil,'owner Jink limitation')end
    return self:useKnowledgeEstimate({value=false,status='estimate',basis='foreign_unprojected_jink_limitation_prior',viewer=self.player:objectName(),target=player:objectName()},'OriginalDefense.JinkLimited')
end

hooks_pending.hv_careerist = function(self,player)
    if player:objectName()==self.player:objectName()then return player:getRole()=='careerist'end
    local row=hv_row(self,player)
    if hv_known(row.shown_one,'shown one')then return hv_known(row.public_careerist,'public careerist')end
    return self:useKnowledgeEstimate({value=false,status='estimate',basis='unrevealed_careerist_role_prior',viewer=self.player:objectName(),target=player:objectName()},'OriginalDefense.careerist_role')
end

function SmartAIView:originalHegemonyGetUseValue(card)
	local class_name = card:isKindOf("LuaSkillCard") and card:objectName() or card:getClassName()
	local v = self:originalHegemonyPrintedValue("ai_use_value",class_name,card) or 0

	if card:getTypeId() == sgs.Card_TypeSkill then
		return v
	elseif card:getTypeId() == sgs.Card_TypeEquip then
		if self.player:hasEquip(card) then
			if card:isKindOf("OffensiveHorse") and self.player:getAttackRange() > 2 then return 5.5 end
			if card:isKindOf("DefensiveHorse") and self:hasEightDiagramEffect() then return 5.5 end
			return 9
		end
		if not self:getSameEquip(card) then v = 6.7 end
		if self.weaponUsed and card:isKindOf("Weapon") then v = 2 end
		if self.player:hasSkills("heg_qiangxi") and card:isKindOf("Weapon") then v = 2 end
		if self.player:hasSkill("heg_kurou") and card:isKindOf("Crossbow") then return 9 end
		if self.player:hasSkills("bazhen|jgyizhong") and card:isKindOf("Armor") then v = 2 end

		if self.player:hasSkills(hv_fact(self,"lose_equip_skill")) then return 10 end
	elseif card:getTypeId() == sgs.Card_TypeBasic then
		if card:isKindOf("Slash") then
			if hv_q(self.player,"hasFlag","TianyiSuccess") or self:hasHeavySlashDamage(self.player,card) then v = 8.7 end
			if self.player:getPhase() == sgs.Player_Play and self:slashIsAvailable() and #self.enemies > 0 and self:getCardsNum("Slash") == 1 then v = v + 5 end
			if self:hasCrossbowEffect() then v = v + 4 end
			if card:getSkillName() == "Spear" then v = v - 1 end
		elseif card:isKindOf("Jink") then
			if self:getCardsNum("Jink") > 1 then v = v - 6 end
		elseif card:isKindOf("Peach") then
			if self.player:isWounded() then v = v + 6 end
		end
	elseif card:getTypeId() == sgs.Card_TypeTrick then
		if self.player:getPhase() == sgs.Player_Play and not card:isAvailable(self.player) then v = 0 end
		if original_equipment(self.player,"getWeapon") and not self.player:hasSkills(hv_fact(self,"lose_equip_skill")) and card:isKindOf("Collateral") then v = 2 end
		if card:getSkillName() == "shuangxiong" then v = 6 end
		if card:isKindOf("Duel") then v = v + self:getCardsNum("Slash") * 2 end
		if self.player:hasSkill("heg_jizhi") then v = v + 4 end
	end

	if self.player:hasSkills(hv_fact(self,"need_kongcheng")) then
		if self.player:getHandcardNum() == 1 then v = 10 end
	end

	if self.player:getPile("wooden_ox"):contains(card:getEffectiveId()) then
		v = v + 1
	end

	if card:isKindOf("HHalberdCard") then v = v + 20 end

	if self.player:getPhase() == sgs.Player_Play then v = self:adjustUsePriority(card,v) end
	return v
end

function SmartAIView:originalHegemonyGetUsePriority(card)
	local class_name = card:getClassName()
	local v = 0
	if card:isKindOf("EquipCard") then
		if self.player:hasSkills(hv_fact(self,"lose_equip_skill")) then return 15 end
		if card:isKindOf("Armor") and not original_equipment(self.player,"getArmor") then v = (self:originalHegemonyPrintedValue("ai_use_priority",class_name,card) or 0) + 5.2
		elseif card:isKindOf("Weapon") and not original_equipment(self.player,"getWeapon") then v = (self:originalHegemonyPrintedValue("ai_use_priority",class_name,card) or 0) + 3
		elseif card:isKindOf("DefensiveHorse") and not original_equipment(self.player,"getDefensiveHorse") then v = 5.8
		elseif card:isKindOf("OffensiveHorse") and not original_equipment(self.player,"getOffensiveHorse") then v = 5.5
		elseif card:isKindOf("Treasure") and not original_equipment(self.player,"getTreasure") then
			v = 5.6
			if card:isKindOf("JadeSeal") then v = v + 0.1 end
		end
		return v
	end

	v = self:originalHegemonyPrintedValue("ai_use_priority",class_name,card) or 0
	if class_name == "LuaSkillCard" and card:isKindOf("LuaSkillCard") then
		v = self:originalHegemonyPrintedValue("ai_use_priority",card:objectName(),card) or 0
	end
	return self:adjustUsePriority(card,v)
end

function SmartAIView:originalHegemonyAdjustUsePriority(card, v)
	local suits = {"club", "spade", "diamond", "heart"}

	if card:getTypeId() == sgs.Card_TypeSkill then return v end
	if card:getTypeId() == sgs.Card_TypeEquip then return v end

	for _, askill in sgs.qlist(self.player:getVisibleSkillList(true)) do
		local callback = self:originalHegemonyPrintedValue("ai_suit_priority",askill:objectName(),card)
		if type(callback) == "function" then
			suits = callback(self, card):split("|")
			break
		elseif type(callback) == "string" then
			suits = callback:split("|")
			break
		end
	end

	table.insert(suits, "no_suit")
	if card:isKindOf("Slash") then
		if card:getSkillName() == "Spear" then v = v - 0.1 end
		if card:isRed() then
			v = v - 0.05
		end
		if card:isKindOf("NatureSlash") then
			if self.slashAvail == 1 then
				v = v + 0.05
				if card:isKindOf("FireSlash") then
					for _, enemy in ipairs(self.enemies) do
						if enemy:hasArmorEffect("Vine") or hv_q(enemy,"getMark","@gale") > 0 then v = v + 0.07 break end
					end
				elseif card:isKindOf("ThunderSlash") then
					for _, enemy in ipairs(self.enemies) do
						if hv_q(enemy,"getMark","@fog") > 0 then v = v + 0.06 break end
					end
				end
			else v = v - 0.05
			end
		end
		if self.player:hasSkill("heg_jiang") and card:isRed() then v = v + 0.21 end
		if self.slashAvail == 1 then
			v = v + math.min(hv_target_mod(self,card,"extra") * 0.1, 0.5)
			v = v + math.min(hv_target_mod(self,card,"distance") * 0.05, 0.5)
		end
	end

	if card:isKindOf("HHalberdCard") then v = v + 1 end

	if self.player:getPile("wooden_ox"):contains(card:getEffectiveId()) then
		v = v + 0.1
	end

	local suits_value = {}
	for index, suit in ipairs(suits) do
		suits_value[suit] = -index
	end
	v = v + (suits_value[card:getSuitString()] or 0) / 1000
	v = v + (13 - card:getNumber()) / 10000
	return v
end

function SmartAIView:originalHegemonyGetDynamicUsePriority(card)
	if not card then return 0 end
	if self:hasStrategyCardFlag(card,"AIGlobal_KillOff") then return 15 end

	if card:isKindOf("Slash") then
		for _, p in ipairs(self.friends) do
			if hv_shown(self,p,"heg_yongjue") and hv_public_friend(self,self.player,p) then return 12 end
		end
	elseif card:isKindOf("AmazingGrace") then
		local heg_zhugeliang = hv_find_shown(self,"heg_kongcheng")
		if heg_zhugeliang and self:isEnemy(heg_zhugeliang) and heg_zhugeliang:isKongcheng() then
			return math.max(self:originalHegemonyPrintedValue("ai_use_priority","Slash",card), self:originalHegemonyPrintedValue("ai_use_priority","Duel",card)) + 0.1
		end
	elseif card:isKindOf("Peach") and self.player:hasSkill("tenyearkuanggu") then return 1.01
	elseif card:isKindOf("DelayedTrick") and #card:getSkillName() > 0 then
		return (self:originalHegemonyPrintedValue("ai_use_priority",card:getClassName(),card) or 0.01) - 0.01
	elseif card:isKindOf("Duel") then
		if self:hasCrossbowEffect()
			or hv_fact(self,"owner_can_slash_without_crossbow")
			or hv_target_mod(self,self:getEvaluationCard("slash"),"residue") > 0
			or self.player:hasUsed("HFenxunCard") then
			return self:originalHegemonyPrintedValue("ai_use_priority","Slash",card) - 0.1
		end
	elseif card:isKindOf("AwaitExhausted") and self.player:hasSkills("heg_guose|heg_duanliang") then
		return 0
	end

	local value = self:originalHegemonyGetUsePriority(card) or 0
	if card:getTypeId() == sgs.Card_TypeEquip then
		if self.player:hasSkills("heg_xiaoji+qixi") and self:originalHegemonyGetSameEquip(card) then return 3 end
		if self.player:hasSkills(hv_fact(self,"lose_equip_skill")) then value = value + 12 end
		if card:isKindOf("Weapon") and self.player:getPhase() == sgs.Player_Play and #self.enemies > 0 then
			self:originalHegemonySort(self.enemies)
			local enemy = self.enemies[1]
			local v, inAttackRange = self:originalHegemonyEvaluateWeapon(card,self.player,enemy) / 20
			value = value + string.format("%3.2f", v)
			if inAttackRange then value = value + 0.5 end
		end
	end

	if card:isKindOf("AmazingGrace") then
		local dynamic_value = 10
		for _, player in sgs.qlist(self.room:getOtherPlayers(self.player)) do
			dynamic_value = dynamic_value - 1
			if self:isEnemy(player) then dynamic_value = dynamic_value - ((player:getHandcardNum() + player:getHp()) / player:getHp()) * dynamic_value
			else dynamic_value = dynamic_value + ((player:getHandcardNum() + player:getHp()) / player:getHp()) * dynamic_value
			end
		end
		value = value + dynamic_value
	elseif card:isKindOf("ArcheryAttack") and self.player:hasSkill("heg_luanji") then
		value = value + 5.5
	elseif card:isKindOf("Duel") and self.player:hasSkill("shuangxiong") then
		value = value + 6.3
	elseif card:isKindOf("HWendaoCard") and hv_shown_skills(self,self.player, "heg_wendao+heg_hongfa") and not self.player:getPile("heavenly_army"):isEmpty()
		and self.player:getArmor() and self.player:getArmor():objectName() == "PeaceSpell" then
		value = value + 8
	end

	return value
end

function SmartAIView:originalHegemonySortByUseValue(cards, inverse)
	cards = sgs.QList2Table(cards)
	local compare_func = function(a, b)
		local value1 = self:originalHegemonyGetUseValue(a)
		local value2 = self:originalHegemonyGetUseValue(b)

		if value1 ~= value2 then
			if not inverse then return value1 > value2 end
			return value1 < value2
		else
			if not inverse then return a:getNumber() > b:getNumber() end
			return a:getNumber() < b:getNumber()
		end
	end

	table.sort(cards, compare_func)
	return cards
end

function SmartAIView:originalHegemonySortByUsePriority(cards)
	cards = sgs.QList2Table(cards)
	local compare_func = function(a, b)
		local value1 = self:originalHegemonyGetUsePriority(a)
		local value2 = self:originalHegemonyGetUsePriority(b)

		if value1 ~= value2 then
			return value1 > value2
		else
			return a:getNumber() > b:getNumber()
		end
	end
	table.sort(cards, compare_func)
	return cards
end

function SmartAIView:originalHegemonySortByDynamicUsePriority(cards)
	cards = sgs.QList2Table(cards)
	local compare_func = function(a,b)
		local value1 = self:originalHegemonyGetDynamicUsePriority(a)
		local value2 = self:originalHegemonyGetDynamicUsePriority(b)

		if value1 ~= value2 then
			return value1 > value2
		else
			return a and a:getTypeId() ~= sgs.Card_TypeSkill and not (b and b:getTypeId() ~= sgs.Card_TypeSkill)
		end
	end

	table.sort(cards, compare_func)
	return cards
end


