function SmartAIView:originalHegemonyPrintedTable(table_name)
    local catalog=original_hegemony_printed_catalog[table_name]
    if type(catalog)~='table'or type(sgs[table_name])~='table'then ai_unsupported('Original printed table unavailable',table_name)end
    local result={}
    for key,value in pairs(sgs[table_name])do result[key]=value end
    for key,value in pairs(catalog)do if value==false then result[key]=nil else result[key]=value end end
    if table_name=='ai_use_priority'then
        local state,present=self:getStrategyMemory('priority_overrides')
        if present and type(state)=='table'then
            for key in pairs(state)do result[key]=self:originalHegemonyPrintedValue(table_name,key)end
        end
    end
    return result
end
function SmartAIView:originalHegemonySkillValueTable(skill,kind)
    if type(skill)~='string'or(kind~='keep'and kind~='suit'and kind~='number')then ai_unsupported('Original skill value table selector invalid',tostring(skill))end
    local key=skill..'_'..kind..'_value'
    local value=original_hegemony_skill_value_catalog[key]
    if value==nil then value=sgs[key]end
    if value==nil then return nil end
    if type(value)~='table'then ai_unsupported('Original skill value table invalid',key)end
    local copy={}
    for k,v in pairs(value)do copy[k]=v end
    return copy
end

-- Fixed Original Hegemony keep pipeline (b6025acc); mode installer only.

local function hkeep_fact(self,key)
 local facts=AIHegemony.facts(self.world)
 local value=facts and facts[key]
 if value==nil then ai_unsupported('Original keep metadata unavailable',key)end
 return value
end
function SmartAIView:originalHegemonyAssignKeep(start)
	self.keepValue = {}
	self.kept = {}

	if start then


		self.keepdata = {}
		for k, v in pairs(self:originalHegemonyPrintedTable("ai_keep_value")) do
			self.keepdata[k] = v
		end

		for _, askill in sgs.qlist(self.player:getVisibleSkillList(true)) do
			local skilltable = self:originalHegemonySkillValueTable(askill:objectName(),"keep")
			if skilltable then
				for k, v in pairs(skilltable) do
					self.keepdata[k] = v
				end
			end
		end
	end

	if self.room:getTurnCount() <= 1 and #self.enemies == 0 then
		self.keepdata.Jink = 4.2
	end

	if not self:isWeak() or self.player:getHandcardNum() >= 4 then
		for _, friend in ipairs(self.friends_noself) do
			if self:willSkipDrawPhase(friend) or self:willSkipPlayPhase(friend) then
				self.keepdata.Nullification = 5.5
				break
			end
		end
	end

	if self:getOverflow(self.player,true) == 1 then
		self.keepdata.Analeptic = (self.keepdata.Jink or 5.2) + 0.1
		-- 特殊情况下还是要留闪，待补充...
	end

	if not self:isWeak() then
		local needDamaged = false
		if not needDamaged and not self:originalHegemonyIsGoodTarget(self.player,self.friends) then needDamaged = true end
		if not needDamaged then
			for _, skill in sgs.qlist(self.player:getVisibleSkillList(true)) do
				local callback = self:originalHegemonyNeedDamagedCallback(skill:objectName())
				if type(callback) == "function" and callback(self, nil, self.player) then
					needDamaged = true
					break
				end
			end
		end
		if needDamaged then
			self.keepdata.ThunderSlash = 5.2
			self.keepdata.FireSlash = 5.1
			self.keepdata.Slash = 5
			self.keepdata.Jink = 4.5
		end
	end

	for _, card in sgs.qlist(self.player:getCards("he")) do
		self.keepValue[card:getEffectiveId()] = self:originalHegemonyWriteKeepValue(card)
	end

	local cards = sgs.QList2Table(self.player:getHandcards())
	self:originalHegemonySortByKeepValue(cards,true)

	local resetCards = function(allcards)
		local result = {}
		for _, a in ipairs(allcards) do
			local found
			for _, b in ipairs(self.kept) do
				if a:getEffectiveId() == b:getEffectiveId() then
					found = true
					break
				end
			end
			if not found then table.insert(result, a) end
		end
		return result
	end

	for i = 1, self.player:getHandcardNum() do
		for _, card in ipairs(cards) do
			local v = self:originalHegemonyGetKeepValue(card,self.kept)
			self.keepValue[card:getEffectiveId()] = v
			self.keepdata[card:getClassName()] = v
			table.insert(self.kept, card)
			break
		end
		cards = resetCards(cards)
	end

    self:persistKeepState()
end

function SmartAIView:originalHegemonyWriteKeepValue(card)
	local maxvalue = self.keepdata[card:getClassName()] or self:originalHegemonyPrintedValue("ai_keep_value",card:getClassName(),card) or 0
	local mostvaluable_class = card:getClassName()
	for k, v in pairs(self.keepdata) do
		if isCard(k, card, self.player) and v > maxvalue then
			maxvalue = v
			mostvaluable_class = k
		end
	end
	local cardPlace = self.room:getCardPlace(card:getEffectiveId())
	if cardPlace == sgs.Player_PlaceEquip then
		if card:isKindOf("Armor") and self:needToThrowArmor() then return -10
		elseif self.player:hasSkills(hkeep_fact(self,"lose_equip_skill")) then
			if card:isKindOf("OffensiveHorse") then return -10
			elseif card:isKindOf("Weapon") then return -9.9
			elseif card:isKindOf("OffensiveHorse") then return -9.8
			else return -9.7
			end
		elseif self.player:hasSkills("bazhen|jgyizhong") and card:isKindOf("Armor") then return -8
		elseif self:needKongcheng() then return 5.0
		end
		local value = 0
		if card:isKindOf("Armor") then value = self:isWeak() and 5.2 or 3.2
		elseif card:isKindOf("DefensiveHorse") then value = self:isWeak() and 4.3 or 3.19
		elseif card:isKindOf("Weapon") then value = self.player:getPhase() == sgs.Player_Play and self:slashIsAvailable() and 3.39 or 3.2
		elseif card:isKindOf("JadeSeal") then value = 5
		elseif card:isKindOf("WoodenOx") then
			value = 3.19
			for _, id in sgs.qlist(self.player:getPile("wooden_ox")) do
				local c = self:getKnownCardById(id)
				value = value + (self:originalHegemonyPrintedValue("ai_keep_value",c:getClassName(),c) or 0)
			end
		else value = 3.19
		end
		if not card:isKindOf(mostvaluable_class) then
			value = value + maxvalue
		end
		return value
	elseif cardPlace == sgs.Player_PlaceHand then
		local value_suit, value_number, newvalue = 0, 0, 0
		local suit_string = card:getSuitString()
		local number = card:getNumber()
		local i = 0

		for _, askill in sgs.qlist(self.player:getVisibleSkillList(true)) do
			if self:originalHegemonySkillValueTable(askill:objectName(),"suit") then
				local v = self:originalHegemonySkillValueTable(askill:objectName(),"suit")[suit_string]
				if v then
					i = i + 1
					value_suit = value_suit + v
				end
			end
		end
		if i > 0 then value_suit = value_suit / i end

		i = 0
		for _, askill in sgs.qlist(self.player:getVisibleSkillList(true)) do
			if self:originalHegemonySkillValueTable(askill:objectName(),"number") then
				local v = self:originalHegemonySkillValueTable(askill:objectName(),"number")[tostring(number)]
				if v then
					i = i + 1
					value_number = value_number + v
				end
			end
		end

		if i > 0 then value_number = value_number / i end
			newvalue = maxvalue + value_suit + value_number
			if not card:isKindOf(mostvaluable_class) then 	newvalue = newvalue + 0.1 end
		newvalue = self:adjustKeepValue(card,newvalue)
			return newvalue
	else
		return self.keepdata[card:getClassName()] or self:originalHegemonyPrintedValue("ai_keep_value",card:getClassName(),card) or 0
	end
end

function SmartAIView:originalHegemonyGetKeepValue(card, kept)
	local cardPlace = self.room:getCardPlace(card:getEffectiveId())
	local v = self.keepValue[card:getEffectiveId()] or self.keepdata[card:getClassName()] or self:originalHegemonyPrintedValue("ai_keep_value",card:getClassName(),card) or 0
	if not kept then
		if cardPlace ~= sgs.Player_PlaceHand and cardPlace ~= sgs.Player_PlaceEquip then
			v = self:adjustKeepValue(card,v)
		end
		return v
	end

	local maxvalue = self.keepdata[card:getClassName()] or self:originalHegemonyPrintedValue("ai_keep_value",card:getClassName(),card) or 0
	local mostvaluable_class = card:getClassName()
	for k, v in pairs(self.keepdata) do
		if isCard(k, card, self.player) and v > maxvalue then
			maxvalue = v
			mostvaluable_class = k
		end
	end

	if cardPlace == sgs.Player_PlaceHand then
		local dec = 0
		for _, acard in ipairs(kept) do
			if isCard(mostvaluable_class, acard, self.player) then
				v = v - 1.2 - dec
				dec = dec + 0.1
			elseif acard:isKindOf("Slash") and card:isKindOf("Slash") then
				v = v - 1.2 - dec
				dec = dec + 0.1
			end
		end
	end
	return v
end

function SmartAIView:originalHegemonyAdjustKeepValue(card, v)
	local suits = {"club", "spade", "diamond", "heart"}
	for _, askill in sgs.qlist(self.player:getVisibleSkillList(true)) do
		local callback = self:originalHegemonyPrintedValue("ai_suit_priority",askill:objectName(),card)
		if type(callback) == "function" then
			suits = callback(self, card):split("|")
			break
		elseif type(callback) == "string" then
			suits = callback:split("|")
			break
		end
	end
	table.insert(suits, "no_suit")

	if card:isKindOf("Slash") then
		if card:isRed() then v = v + 0.02 end
		if card:isKindOf("NatureSlash") then v = v + 0.03 end
		if self.player:hasSkill("heg_jiang") and card:isRed() then v = v + 0.04 end
	elseif card:isKindOf("HegNullification") then v = v + 0.02
	end

	if self.player:getPile("wooden_ox"):contains(card:getEffectiveId()) then
		v = v - 0.1
	end

	local suits_value = {}
	for index,suit in ipairs(suits) do
		suits_value[suit] = index * 2
	end
	v = v + (suits_value[card:getSuitString()] or 0) / 100
	v = v + card:getNumber() / 500
	return v
end

function SmartAIView:originalHegemonySortByKeepValue(cards, inverse, kept)
	cards = sgs.QList2Table(cards)
	local compare_func = function(a, b)
		local v1 = self:originalHegemonyGetKeepValue(a)
		local v2 = self:originalHegemonyGetKeepValue(b)

		if v1 ~= v2 then
			if inverse then return v1 > v2 end
			return v1 < v2
		else
			if not inverse then return a:getNumber() > b:getNumber() end
			return a:getNumber() < b:getNumber()
		end
	end

	table.sort(cards, compare_func)
	return cards
end


-- Original common3784 resets the complete range table; no ordinary fallback.
local original_hegemony_weapon_range={Axe=3,Crossbow=1,DoubleSword=2,Fan=4,GudingBlade=2,HBlade=3,HDragonPhoenix=2,HHalberd=4,HSixSwords=2,HTriblade=3,IceSword=2,KylinBow=5,QinggangSword=2,Spear=3,Weapon=1}
function SmartAIView:originalHegemonyWeaponRange(class)
    return original_hegemony_weapon_range[class]
end

-- Four actual Original cardsView bodies. D resolves only lawful snapshots;
-- D.convert returns a policy wire for Miewu, D.slash a readonly policy card
-- for army providers. Neither callback allocates action authority.
local function original_extra_cardsview_factory(D)
 local C=D.constants
 local callbacks={}
 callbacks.heg_miewu=function(self,class,player,cards)
  if not D.shown(self,player,'heg_miewu')then return end
  if hegemony_source_query(player,'getMark','#heg_wuku')==0 or hegemony_source_query(player,'hasFlag','MiewuUsed')or player:isNude()or player:isRemoved()then return end
  if D.reason()~=C.CardUseStruct_CARD_USE_REASON_RESPONSE_USE and D.reason()~=C.CardUseStruct_CARD_USE_REASON_RESPONSE then
   if player:getPhase()==C.Player_Play then return end
  end
  if class~='Peach'and class~='Analeptic'and class~='Slash'and class~='Jink'and class~='Nullification'then return end
  if not cards then
   cards={}
   for _,c in ipairs(player:getCards('he'))do if D.visible(self,c,player)and not c:isKindOf(class)then cards[#cards+1]=c end end
   for _,id in ipairs(player:getHandPile())do local c=D.card(self,id);if D.visible(self,c,player)and not c:isKindOf(class)then cards[#cards+1]=c end end
  else
   local own={}
   for _,c in ipairs(cards)do
    local place=self.room:getCardPlace(c:getKnownEffectiveId())
    if place~=C.Player_PlaceSpecial or (player:getHandPile()):contains(c:getKnownEffectiveId())then own[#own+1]=c end
   end
   cards=own
  end
  if #cards<1 then return {}end
  if hegemony_source_query(player,'getMark','#heg_wuku')==1 and player:getCardCount(true)>1 and(class=='Slash'or class=='Jink')then
   for _,c in ipairs(cards)do if c:isKindOf(class)then return {}end end
  end
  self:sortByKeepValue(cards)
  local name=({Peach='peach',Analeptic='analeptic',Slash='slash',Jink='jink',Nullification='heg_nullification'})[class]
  if class=='Slash'then name=({'slash','fire_slash','thunder_slash'})[D.random(1,3)]end
  local prototype=D.prototype(self,name)
  local value=self:getKeepValue(prototype)
  local indulgence=player:getPhase()==C.Player_Judge and not player:isSkipped(C.Player_Judge)and not player:isSkipped(C.Player_Play)
   and class=='Nullification'and player:containsTrick('indulgence')and(player:getHandcardNum()>3 or player:getHandcardNum()>player:getHp()-1)
  for _,c in ipairs(cards)do
   local cost=self:getKeepValue(c)
   if cost<value or indulgence or(cost<=4.1 and player:getCardCount(true)==1)then return D.convert(self,'heg_miewu',name,c)end
  end
 end
 callbacks.heg_yigui=function(self,class,player)
  if not D.shown(self,player,'heg_yigui')then return end
  local souls=D.souls(self,player)
  if #souls==0 then return end
  if class=='Peach'or class=='Analeptic'then
   local soul,product
   local dying=self.room:getCurrentDyingPlayer()
   if dying then
    for _,name in ipairs(souls)do local general=D.general(self,name)
     if not general:isDoubleKingdoms()and general:getKnownKingdom()==dying:getKnownKingdom()then soul=name;break end
    end
    if not soul then for _,name in ipairs(souls)do local general=D.general(self,name)
     if general:isDoubleKingdoms()and D.contains(general:getKingdoms(),dying:getKnownKingdom())then soul=name;break end
    end end
    if dying:objectName()==player:objectName()then
     if not hegemony_source_query(player,'hasFlag','Yigui_Analeptic')then product='analeptic'
     elseif not hegemony_source_query(player,'hasFlag','Yigui_Peach')then product='peach'end
    elseif not hegemony_source_query(player,'hasFlag','Yigui_Peach')then product='peach'end
    if soul and product then return '@HYiguiCard=.&:'..product..'+'..soul end
   end
  end
 end
 callbacks.huangjinsymbol=function(self,class,player)
  if class~='Slash'then return end
  local lord=D.lord(self,player)
  if not lord or (lord:getPile('heavenly_army')):isEmpty()or not D.willFriend(self,self.player,lord)then return end
  local ids=lord:getPile('heavenly_army');local cards={};local armor,equipment
  for _,id in ipairs(ids)do
   local c=D.card(self,id)
   if c:isKindOf('HPeaceSpell')then armor=D.slash(self,'huangjinsymbol',c)
   elseif c:isKindOf('HDragonPhoenix')or c:isKindOf('HLuminousPearl')or c:isKindOf('HSixDragons')then equipment=D.slash(self,'huangjinsymbol',c)
   else cards[#cards+1]=D.slash(self,'huangjinsymbol',c)end
  end
  if armor then table.insert(cards,1,armor)end
  if equipment then cards[#cards+1]=equipment end
  return cards
 end
 callbacks.heg_huangjinsymbol=function(self,class,player)
  if class~='Slash'then return end
  local lord=D.lord(self,player)
  if not player:hasShownOneGeneral()or not lord or (lord:getPile('heavenly_army')):isEmpty()or not D.friend(self,player,lord)then return end
  local cards={}
  for _,id in ipairs(lord:getPile('heavenly_army'))do cards[#cards+1]=D.slash(self,'heg_huangjinsymbol',D.card(self,id))end
  return cards
 end
 return callbacks
end

local original_extra_cardsview_keys={heg_miewu=true,heg_yigui=true,huangjinsymbol=true,heg_huangjinsymbol=true}
local function hc_lord(self,player)
    if player:objectName()==self.player:objectName()then
        local name=self:originalHegemonyOwnerFact('owner_hegemony_lord')
        if name==''then return nil end
        return known(self.room:findPlayerByObjectName(name),'Original owner lord roster')
    end
    local row=heg_player(self,player)
    local kingdom=row.shown_head and known(row.head_kingdom,'Original shown head kingdom')or known(row.public_kingdom,'Original public kingdom')
    local result
    if player:isAlive()and player:isLord()then result=player
    else
        for _,other in ipairs(self.room:getAlivePlayers())do
            local other_row=heg_player(self,other)
            if other:objectName()~=player:objectName()and other_row.shown_head
                and other:getKnownKingdom()==kingdom and other:isLord()then result=other;break end
        end
    end
    if not row.shown_head then
        self:useKnowledgeEstimate({value=result and result:objectName()or'',status='estimate',viewer=self.player:objectName(),target=player:objectName(),
            basis='Original Player:getLord: public kingdom substitutes unobserved foreign head; concealed sovereign absent prior'},'Original.cardsView.foreign_lord')
    end
    return result
end
local function hc_wire(skill,name,card)
    -- Pure legacy equality/count key only; never passed to a parser/resolver.
    -- Card::toString634 has no ampersand. Heavenly-army source explicitly adds it.
    return name..':'..skill..'['..card:getSuitString()..':'..card:getNumberString()..']='..card:getKnownEffectiveId()
end
function SmartAIView:originalHegemonyCardsViewProvider(key,class,player,other,count_only)
    if not original_extra_cardsview_keys[key]then ai_unsupported('Original cardsView provider is not audited',key)end
    local presence=known(heg_facts(self).cardsview_presence,
        'Original cardsView callback metadata')
    if type(presence)~='table' or type(presence[key])~='boolean' then
        ai_unsupported('Original cardsView callback presence missing',key)
    end
    if not presence[key] then return nil end
    player=player or self.player
    local callbacks=original_extra_cardsview_factory{
        constants=sgs,shown=shown,
        reason=function()return self:originalHegemonyOwnerFact('owner_current_card_use_reason')end,
        visible=function(_,card,subject)
            -- Every enumerated card is in the viewer's disclosed snapshot; no
            -- unknown foreign hand is turned into an identity here.
            return subject:objectName()==self.player:objectName()or self.room:isCardKnown(card:getKnownEffectiveId())
        end,
        card=function(_,id)return known(self:getKnownCardById(id),'Original cardsView disclosed cost')end,
        random=math.random,
        prototype=function(_,name)return known(self:getEvaluationCard(name),'Original Miewu printed clone')end,
        convert=function(_,skill,name,cost)
            if player:objectName()~=self.player:objectName()then
                -- The source's global count evaluates a hypothetical clone over
                -- viewer-known foreign costs, but creates no selectable result.
                if not count_only then ai_unsupported('foreign Miewu selection is not authorized',key)end
                return hc_wire(skill,name,cost)
            end
            local spec={source_key=skill,skill=skill,name=name,suit=cost:getSuit(),number=cost:getNumber(),subcards={cost:getKnownEffectiveId()}}
            local evaluated=self:originalHegemonyEvaluateViewAsSpec(spec)
            return evaluated and evaluated.card and evaluated.card:getLegacyStringKey() or nil
        end,
        souls=function(_,subject)
            local piles=known(heg_facts(self).soul_piles,'Original disclosed soul piles')
            local row=known(piles[subject:objectName()],'Original soul pile subject')
            if row.known~=true or type(row.visible)~='boolean'or type(row.names)~='table'then ai_unsupported('Original soul pile visibility unknown','soul')end
            if not row.visible then return {}end
            return row.names
        end,
        general=function(_,name)
            local definitions=known(heg_facts(self).soul_general_definitions,'Original soul definitions')
            local row=known(definitions[name],'Original disclosed soul definition')
            if row.exists~=true then ai_unsupported('Original source soul definition does not exist',name)end
            if type(row.double_kingdoms)~='boolean'or type(row.kingdom)~='string'or type(row.kingdoms)~='string'then ai_unsupported('Original soul metadata native type is incomplete',name)end
            return {isDoubleKingdoms=function()return known(row.double_kingdoms,'soul double kingdom')end,
                getKingdom=function()return known(row.kingdom,'soul kingdom')end,
                getKingdoms=function()return known(row.kingdoms,'soul native kingdom string')end}
        end,
        contains=function(values,value)for _,entry in ipairs(values)do if entry==value then return true end end;return false end,
        lord=hc_lord,
        willFriend=function(_,from,to)
            if from:objectName()~=self.player:objectName()then ai_unsupported('Original prospective relationship is owner-only',key)end
            return known(known(heg_facts(self).owner_prospective_friends,'Original owner prospective relationships')[to:objectName()],'Original prospective target')
        end,
        friend=function(_,from,to)return from:isPublicHegemonyFriend(to)end,
        slash=function(_,skill,cost)
            if count_only then return hc_wire(skill,'slash',cost)..'&'end
            local spec={source_key=skill,skill=skill,name='slash',suit=cost:getSuit(),number=cost:getNumber(),subcards={cost:getKnownEffectiveId()}}
            local evaluated=self:originalHegemonyEvaluateViewAsSpec(spec)
            return evaluated and evaluated.card or nil
        end,
    }
    return callbacks[key](self,class,player,other)
end

-- Original common3095--3225/3382; policy cards remain readonly until selected.
local function ho_list(cards)return AIList.asLuaTable and AIList.asLuaTable(cards)or cards end
local function ho_pile(self,name,cards)
    for _,id in ipairs(self.player:getPile(name))do
        cards[#cards+1]=known(self:getKnownCardById(id),'Original own pile card '..tostring(id))
    end
end
local function ho_cards(self,flags,all_piles)
    local cards={}
    for _,card in ipairs(self.player:getCards(flags))do cards[#cards+1]=card end
    if all_piles then for _,name in ipairs(self.player:getPileNames())do ho_pile(self,name,cards)end
    elseif flags:find('h')then ho_pile(self,'wooden_ox',cards)end
    return ho_list(cards)
end
local function ho_prohibited(self,card)
    if known(self.player:isCardLimited(card,card:getHandlingMethod()),'Original direct-card limitation')then return true end
    return card:isKindOf('Peach')and hegemony_source_query(self.player,'hasFlag','Global_PreventPeach')
end
function SmartAIView:originalHegemonySkillViewCard(card,class,place)
    local presence=known(heg_facts(self).view_as_presence,'Original view-as callback metadata')
    for _,skill in ipairs(self.player:getVisibleSkillList(true))do
        local key=skill:objectName()
        if(self.player:hasSkill(key)or self.player:hasLordSkill(key))and known(presence[key],'Original view-as callback:'..key)then
            local converted=self:originalHegemonyViewAsCard(key,class,card,self.player,place)
            if converted then return converted end
        end
    end
end
function SmartAIView:originalHegemonyCardsViewValue(class,other)
    local player=self.player
    local presence=known(heg_facts(self).cardsview_presence,'Original cardsView callback metadata')
    for _,skill in ipairs(player:getVisibleSkillList(true))do
        local key=skill:objectName()
        if(player:hasSkill(key)or player:hasLordSkill(key))and known(presence[key],'Original cardsView callback:'..key)then
            if key=='spear'then
                if class=='Slash'then
                    local cards=other
                    if not cards then
                        cards={}
                        for _,card in ipairs(player:getHandcards())do if not card:isKindOf('Slash')then cards[#cards+1]=card end end
                        for _,id in ipairs(player:getHandPile())do local card=known(self:getKnownCardById(id),'Original Spear handpile face');if not card:isKindOf('Slash')then cards[#cards+1]=card end end
                        cards=ho_list(cards)
                    end
                    if #cards<2 then return {}end
                    self:sortByKeepValue(cards)
                    local selected={}
                    for _,card in ipairs(cards)do
                        local id=card:getKnownEffectiveId();local owner=self.room:getCardOwner(id)
                        if owner and owner:objectName()==player:objectName()and self.room:getCardPlace(id)==sgs.Player_PlaceHand
                            and not self:originalHegemonyIsCard('Peach',card,player)
                            and not(self:originalHegemonyIsCard('ExNihilo',card,player)and player:getPhase()==sgs.Player_Play)then selected[#selected+1]=card end
                    end
                    local products={}
                    for i=1,#selected-1,2 do
                        local spec={source_key='spear',name='slash',skill='Spear',suit=-1,number=0,
                            subcards={(selected[i]):getKnownEffectiveId(),(selected[i+1]):getKnownEffectiveId()}}
                        -- The source cardsView callback does not apply limitation.
                        local evaluated=self:originalHegemonyEvaluateViewAsSpec(spec)
                        if evaluated and evaluated.card then products[#products+1]=evaluated.card end
                    end
                    return products
                end
            elseif key=='heg_companion'or key=='heg_careerman'then
                if class=='Peach'and hegemony_source_query(player,'getMark',key=='heg_companion'and'@companion'or'@careerist')>0 and not hegemony_source_query(player,'hasFlag','Global_PreventPeach')then
                    -- Source returns a string, whose ipairs is empty and [1] nil.
                    -- Preserve that observed source shape instead of creating a card.
                    return key=='heg_companion'and'peach:heg_companion[no_suit:0]=.'or'peach:heg_careerman[no_suit:0]=.'
                end
            elseif key=='heg_aocai'then
                if player:hasSkill('heg_aocai')and not hegemony_source_query(player,'hasFlag','Global_AocaiFailed')and player:getPhase()==sgs.Player_NotActive then
                    local reason=self:originalHegemonyOwnerFact('owner_current_card_use_reason')
                    if (reason==sgs.CardUseStruct_CARD_USE_REASON_RESPONSE_USE or reason==sgs.CardUseStruct_CARD_USE_REASON_RESPONSE)
                        and(class=='Slash'or class=='Jink')then
                        local pattern=self:originalHegemonyAocaiPattern()
                        if pattern then return '@HAocaiCard=.&heg_aocai:'..pattern end
                    end
                    if class=='Peach'or class=='Analeptic'then
                        local dying=self.room:getCurrentDyingPlayer()
                        return '@HAocaiCard=.&heg_aocai:'..(dying and dying:objectName()==player:objectName()and'peach+analeptic'or class=='Analeptic'and'analeptic'or'peach')
                    end
                end
            elseif original_extra_cardsview_keys[key]then
                local value=self:originalHegemonyCardsViewProvider(key,class,player,other,false)
                if value then return value end
            else ai_unsupported('Original cardsView selector callback is not migrated',key)end
        end
    end
    return {}
end
function SmartAIView:originalHegemonyGetCards(class,flag)
    if flag and type(flag)~='string'then return ho_list({})end
    local cards,other={},{}
    for _,card in ipairs(ho_cards(self,flag or'he',not flag))do
        local id=card:getKnownEffectiveId();local place=self.room:getCardPlace(id)
        if self:hasStrategyCardFlag(card,'AI_Using')then
        elseif class=='.'and place~=sgs.Player_PlaceSpecial then cards[#cards+1]=card
        else
            local physical=card:isKindOf(class)and not ho_prohibited(self,card)
                and(place~=sgs.Player_PlaceSpecial or (self.player:getPile('wooden_ox')):contains(id))
            local converted=self:originalHegemonySkillViewCard(card,class,place)
            if converted then
                if physical and self:adjustUsePriority(card,0)>=self:adjustUsePriority(converted,0)then cards[#cards+1]=card
                else cards[#cards+1]=converted end
            elseif physical then cards[#cards+1]=card
            else other[#other+1]=card end
        end
    end
    local extra=self:originalHegemonyCardsViewValue(class,ho_list(other))
    if #extra>0 then for _,card in ipairs(extra)do cards[#cards+1]=card end end
    return ho_list(cards)
end
function SmartAIView:originalHegemonySelectCard(class,acard)
    local cards=acard and ho_list({acard})or ho_cards(self,'he',true)
    local reason=self:originalHegemonyOwnerFact('owner_current_card_use_reason')
    local cardask=class~='Slash'or reason==sgs.CardUseStruct_CARD_USE_REASON_RESPONSE
    if cardask then
        if self.player:getPhase()==sgs.Player_Play then self:sortByUseValue(cards,true)
        else self:sortByKeepValue(cards)end
    end
    local converted,physical={},{}
    for _,card in ipairs(cards)do
        local id=card:getKnownEffectiveId();local place=self.room:getCardPlace(id)
        local viewas=self:originalHegemonySkillViewCard(card,class,place)
        local direct=card:isKindOf(class)and not ho_prohibited(self,card)
            and(place~=sgs.Player_PlaceSpecial or (self.player:getPile('wooden_ox')):contains(id))
        if viewas then
            if direct and self:adjustUsePriority(card,0)>=self:adjustUsePriority(viewas,0)then physical[#physical+1]=card
            else converted[#converted+1]=viewas end
        elseif direct then physical[#physical+1]=card end
    end
    if not cardask then self:sortByUsePriority(ho_list(converted));self:sortByUsePriority(ho_list(physical))end
    if #converted>0 or #physical>0 then return physical[1]or converted[1]end
    local values=self:originalHegemonyCardsViewValue(class)
    if #values>0 then return values[1]end
end
function SmartAIView:originalHegemonyGetCard(class,islist)
    if islist then return self:sortByUsePriority(self:originalHegemonyGetCards(class))end
    return self:materializeOriginalSelectedCard(self:originalHegemonySelectCard(class))
end
function SmartAIView:originalHegemonyGetCardId(class,acard)
    local card=self:materializeOriginalSelectedCard(self:originalHegemonySelectCard(class,acard))
    if not card then return nil end
    if type(card.getAuthorityCard)=='function'then card=card:getAuthorityCard()or card end
    if AIValue.isConversion(card)then return card:toCardSpec()end
    local id=card:getKnownEffectiveId()
    if id<0 or(type(card.isEvaluationOnly)=='function'and card:isEvaluationOnly())then ai_unsupported('Original card ID is not an authorized physical card','Original.getCardId')end
    return id
end
function SmartAIView:originalHegemonyGetCardsNum(class,flag)
    if type(class)=='table'then local total=0;for _,each in ipairs(class)do total=total+self:originalHegemonyGetCardsNum(each,flag)end;return total end
    return #self:originalHegemonyGetCards(class,flag)
end

-- Original common4263-4482: draw recipients and delayed-trick phase forecasts.
-- The separate nullification loops intentionally allow both friend and enemy
-- predicates to match (the source two-player predicates are not an enum).
local function hg_phase_skipped(self, player, phase)
    local value=player:isSkipped(phase)
    if value~=nil then return value end
    if player:objectName()==self.player:objectName()then
        ai_unsupported("owner skipped-phase state missing","Original.phase_skipped")
    end
    return self:useKnowledgeEstimate({value=false,status="estimate",viewer=self.player:objectName(),
        target=player:objectName(),phase=phase,
        basis="unobserved_private_skip_state_assumed_absent_public_skip_causes_evaluated_below"},"Original.phase_skipped")
end
local function hg_phase_nullifications(self, player)
    local total=0
    for _,p in ipairs(self.room:getAllPlayers())do
        if self:isFriend(p,player)then total=total+getCardsNum("Nullification",p,self.player)end
        if self:isEnemy(p,player)then total=total-getCardsNum("Nullification",p,self.player)end
    end
    return total
end
local function hg_phase_removals(self, player, current)
    local total=0
    if current and self.player:objectName()==current:objectName()
        and self.player:objectName()~=player:objectName() and self:isFriend(player)then
        for _,card in ipairs(self.player:getCards("he"))do
            if isCard("Snatch",card,self.player) and self.player:distanceTo(player)==1
                or isCard("Dismantlement",card,self.player)then
                -- Source clones the ORIGINAL material name/suit/rank; an evaluated
                -- same-face clone (suit-dependent effectiveness) is not projected.
                ai_unsupported("owner same-face phase-removal clone is not projected","Original.phase_trick_probe")
            end
        end
    end
    return total
end
function SmartAIView:originalHegemonyWillSkipPlayPhase(player, NotContains_Null)
    player=player or self.player
    if hg_phase_skipped(self,player,sgs.Player_Play)then return true end
    if hegemony_source_query(player,'hasFlag',"willSkipPlayPhase")then return true end
    local current=self.room:getCurrent()
    local removal=hg_phase_removals(self,player,current)
    local nullifications=0
    if not NotContains_Null then nullifications=hg_phase_nullifications(self,player)end
    if player:containsTrick("indulgence")then
        if self.player:hasSkill("heg_keji") or shown(self,player,"qiaobian") and not player:isKongcheng()then return false end
        if nullifications+removal>1 then return false end
        return true
    end
    return false
end
function SmartAIView:originalHegemonyWillSkipDrawPhase(player, NotContains_Null)
    player=player or self.player
    if hg_phase_skipped(self,player,sgs.Player_Draw)then return true end
    local current=self.room:getCurrent()
    local nullifications=0
    if not NotContains_Null then nullifications=hg_phase_nullifications(self,player)end
    local removal=hg_phase_removals(self,player,current)
    if player:containsTrick("supply_shortage")then
        if self.player:hasSkill("heg_shensu") or shown(self,player,"qiaobian") and not player:isKongcheng()then return false end
        if nullifications+removal>1 then return false end
        return true
    end
    return false
end
function SmartAIView:originalHegemonyAssistTarget()
    local state=self:getStrategyMemory("original_assist_target")
    if type(state)~="table"then state={}end
    if state.off then return nil end
    if not state.player_name then
        local count,player=0,nil
        for _,p in ipairs(self.room:getAlivePlayers())do
            if p:getState()~="robot"then count=count+1;player=p end
        end
        if count==1 and player then state.player_name=player:objectName()else state.off=true end
        self:setStrategyMemory("original_assist_target",state)
    end
    local player=state.player_name and self.room:findPlayerByObjectName(state.player_name,true)
    if not player then return nil end
    local control=self:getAIControlAvailability(player)
    local has_ai
    if control.status=="exact"then has_ai=control.value
    elseif player:objectName()==self.player:objectName()then
        ai_unsupported("owner AI availability is not projected","Original.AssistTarget.getAI")
    else
        has_ai=self:useKnowledgeEstimate({value=true,status="estimate",viewer=self.player:objectName(),target=player:objectName(),
            basis="Original AssistTarget non-online controller availability prior; private controller/onsole-owner AI state excluded"},"Original.AssistTarget.getAI")
    end
    if not has_ai and player:isAlive() and self:isFriend(player) and player:objectName()~=self.player:objectName()then return player end
end
function SmartAIView:originalHegemonyFindPlayerToDraw(include_self, drawnum)
    drawnum=drawnum or 1
    local players=include_self and self.room:getAllPlayers()or self.room:getOtherPlayers(self.player)
    local friends={}
    for _,player in ipairs(players)do
        if self:isFriend(player) and not(shown(self,player,"heg_kongcheng") and player:isKongcheng() and drawnum<=2)then friends[#friends+1]=player end
    end
    if #friends==0 then return nil end
    self:sortInPlace(friends, "defense")
    for _,friend in ipairs(friends)do
        if friend:getHandcardNum()<2 and not hegemony_source_query(self,'needKongcheng',friend) and not self:willSkipPlayPhase(friend)then return friend end
    end
    local assist=self:AssistTarget()
    if assist and(assist:getHandcardNum()<10 or self.player:getHandcardNum()>assist:getHandcardNum())then
        for _,friend in ipairs(friends)do
            if friend:objectName()==assist:objectName() and not self:willSkipPlayPhase(friend)then return friend end
        end
    end
    local category=original_category(self,"Active_cardneed_skill").."|"..original_category(self,"notActive_cardneed_skill")
    for _,friend in ipairs(friends)do
        if original_shown_skills(self,friend,category) and not self:willSkipPlayPhase(friend)then return friend end
    end
    self:sortInPlace(friends, "handcard")
    for _,friend in ipairs(friends)do
        if not hegemony_source_query(self,'needKongcheng',friend) and not self:willSkipPlayPhase(friend)then return friend end
    end
    return nil
end
function SmartAIView:originalHegemonyImitateResultDrawNCards(player, skills)
    if not player then return 0 end
    if hg_phase_skipped(self,player,sgs.Player_Draw)then return 0 end
    skills=skills or player:getVisibleSkillList(true)
    local draw_skills={}
    for _,skill in ipairs(skills)do
        local name=skill:objectName()
        if shown(self,player,name)then draw_skills[#draw_skills+1]=name end
    end
    local count=2
    if player:hasTreasure("JadeSeal") and known(heg_player(self,player).shown_one,"shown one general")then count=count+1 end
    for _,name in pairs(draw_skills)do
        if name=="tenyeartuxi"then return math.min(2,#self.room:getOtherPlayers(player))
        elseif name=="shuangxiong"then return 1
        elseif name=="heg_zaiqi"then return math.floor(player:getLostHp()*3/4)
        elseif name=="heg_luoyi"then count=count-1
        elseif name=="heg_yingzi_sunce"then count=count+1
        elseif name=="heg_yingzi_zhouyu"then count=count+1
        elseif name=="haoshi"then count=count+2 end
    end
    return count
end

-- heg-standard_cards-ai.lua:3605. Preserve both return values and query order.
sgs.ai_nullification.HAwaitExhausted = function(self, card, from, to, positive, keep)
    if not original_enabled(self) then return nil end
    local context = self:getDecisionContext()
    local facts = known(context.choice_body and context.choice_body.await_exhausted, "HAwaitExhausted.context")
    local targets = {}
    for _, name in ipairs(known(facts.targets, "HAwaitExhausted.targets")) do
        targets[#targets+1] = known(self.room:findPlayerByObjectName(name), "HAwaitExhausted.target")
    end
    if keep then return false end
    if positive then
        local hegnull = self:getCard("HegNullification")
        if not hegnull then
            local chain=known(context.original26_nullification,"HAwaitExhausted native chain")
            hegnull=known(chain.times,"HAwaitExhausted.times")>0 and known(chain.type,"HAwaitExhausted.type")
        end
        if self:isEnemy(to) and #targets > 1 and hegnull then
            for _, p in ipairs(targets) do
                if (hs_shown_skills(self, p, sgs.lose_equip_skill) and #p:getEquips() > 0)
                    or (p:getArmor() and hegemony_source_query(self,'needToThrowArmor',p)) then return true, false end
            end
        else
            if self:isEnemy(to) and self:originalHegemonyEvaluateKingdom(to) ~= "unknown" then
                if hs_shown_skills(self, to, sgs.lose_equip_skill) and #to:getEquips() > 0 then return true, true end
                if to:getArmor() and hegemony_source_query(self,'needToThrowArmor',to) then return true, true end
            end
        end
    else
        if self:isFriend(to) and (hegemony_source_query(self,'getOverflow') > 0 or self:getCardsNum("Nullification") > 1) then return true, true end
    end
end

-- Original heg-standard_cards:3715-3809. Planner memory is observer-local;
-- native KnownBoth disclosure alone owns concealed general identities.
local function kb_choices(self,value)
    self.knownboth_choice=value
    self:setStrategyMemory("original_known_both_choice",value)
end
local function kb_seen(self,target)
    local name=target:objectName()
    local state=self:getStrategyMemory("original_known_both_seen")
    if type(state)=="table" and state[name]~=nil then
        local epochs=AIWorldLifecycle.epochs(self.world,"all_mark")
        local epoch=known(type(epochs)=="table" and epochs[name],"KnownBoth all-mark clear epoch")
        if state[name].epoch==epoch then return state[name].value end
    end
    -- The observer's KnownBoth marker is a mark on the target; PlayerView:getMark
    -- raises when that mark is not visible to this observer.
    return known(target:getMark("KnownBoth_"..self.player:objectName().."_"..name),"KnownBoth observer mark")
end
local function kb_known_count(self,player)
    local hand,ox=self:originalHegemonyVisibleCount(player)
    return hand+ox
end
function SmartAIView:originalHegemonyUseCardKnownBoth(card,use)
    kb_choices(self,{})
    if not card:isAvailable(self.player)then return false end
    local targets={}
    local total=1+card:getTargetModExtra(self.player)
    local function append(p,choice)
        targets[#targets+1]=p
        if use.to then use.to:append(p)end
        self.knownboth_choice[p:objectName()]=choice
        -- Source mutates immediately, including dummy planning and early errors.
        self:setStrategyMemory("original_known_both_choice",self.knownboth_choice)
    end
    local function contains(p)for _,v in ipairs(targets)do if v==p then return true end end;return false end
    for _,p in ipairs(self.room:getOtherPlayers(self.player))do
        if self:cardTargetFilter(card,targets,p)
            and not known(heg_player(self,p).shown_one,"KnownBoth isAnjiang") and not contains(p)
            and kb_seen(self,p)==0 and self:trickIsEffective(card,p,self.player)then
            use.card=card;append(p,"head_general")
        end
    end
    if total>#targets then
        self:sortInPlace(self.enemies, "handcard", true)
        for _,enemy in ipairs(self.enemies)do
            if self:cardTargetFilter(card,targets,enemy)
                and enemy:getHandcardNum()-kb_known_count(self,enemy)>3 and not contains(enemy)
                and self:trickIsEffective(card,enemy,self.player)then
                use.card=card;append(enemy,"handcards")
            end
        end
    end
    if total>#targets and #targets>0 then
        self:sortInPlace(self.friends_noself, "handcard", true)
        for _,friend in ipairs(self.friends_noself)do
            if kb_known_count(self,friend)~=friend:getHandcardNum()
                and self:cardTargetFilter(card,targets,friend) and not contains(friend)
                and self:trickIsEffective(card,friend,self.player)then append(friend,"handcards")end
        end
    end
    if not use.card and not self.player:isCardLimited(card,sgs.Card_MethodRecast)and card:canRecast()then
        use.card=card
        if use.to then use.to=AIList.new({})end
    end
end
ai_skill_choice.known_both=function(self,options,request)
    if not original_enabled(self)then ai_unsupported("Original KnownBoth provider not loaded","known_both")end
    local target=self:getDecisionContext(request).original_known_both_target
    if type(target)~="string"or target==""then ai_unsupported("KnownBoth choice target not projected","known_both")end
    local choices=known(options and options.choices,"KnownBoth offered choices")
    local memory=self.knownboth_choice or self:getStrategyMemory("original_known_both_choice")
    local planned=type(memory)=="table"and memory[target]
    for _,choice in ipairs(choices)do
        if choice==planned then return ai_choice_result(choice,options)end
    end
    -- The target may have emptied its hand or revealed a slot since planning.
    -- Select a still-offered view instead of relying on native random repair.
    for _,preferred in ipairs({"handcards","head_general","deputy_general"})do
        for _,choice in ipairs(choices)do
            if choice==preferred then return ai_choice_result(choice,options)end
        end
    end
    ai_unsupported("KnownBoth has no supported offered choice","known_both")
end
sgs.ai_nullification.HKnownBoth=function(self)
    if not original_enabled(self)then ai_unsupported("Original KnownBoth provider not loaded","HKnownBoth")end
    return false
end
sgs.ai_choicemade_filter.skillChoice.known_both=function(self,from,promptlist)
    if not original_enabled(self)then return end
    if promptlist[#promptlist]=="handcards"then return end
    if from:objectName()~=self.player:objectName()then return end
    -- Events have their own pure input, not a fabricated decision request.
    -- Native binds this private witness to the exact published choice payload.
    local event=self._event_input
    local details=type(event)=="table"and event.details
    local target=type(details)=="table"and event.from==from:objectName()
        and event.reason=="known_both"and details.choice_kind=="skillChoice"
        and details.answer==promptlist[#promptlist]and details.original_known_both_target
    if type(target)~="string"or target==""then ai_unsupported("KnownBoth event target witness missing","known_both")end
    if target then
        local memory=self:getStrategyMemory("original_known_both_seen")or{}
        local epochs=AIWorldLifecycle.epochs(self.world,"all_mark")
        local epoch=known(type(epochs)=="table" and epochs[target],"KnownBoth all-mark clear epoch")
        memory[target]={value=1,epoch=epoch};self:setStrategyMemory("original_known_both_seen",memory)
    end
    -- Donor computes a local general-name array but no longer stores it.
    -- Native HKnownBoth performs the actual recipient-only disclosure afterwards.
end

-- Exact one-argument global ABI used by Lolihime dandiao. Do not inject an
-- artificial third `self` argument into heg-standard_cards.lua:61.
function SmartAIView:originalHegemonyGlobalGoodTargetWithoutSelf(player)
    self.room:getCurrent() -- original global resolves attacker before skill scan
    local masochism=false
    for _,name in ipairs({"heg_jieming","heg_yiji","mobilefangzhu"})do
        if shown(self,player,name)then masochism=true;break end
    end
    if masochism and self:originalHegemonyGoodHp(player)then
        -- Fixed provider reaches `self.player` while self is nil. Preserve its
        -- ordinary donor error, rather than converting it into success/Pass or
        -- a different policy with this observer injected as the missing self.
        error("Original sgs.isGoodTarget: attempt to index a nil value (local 'self')",0)
    end
    return true
end

-- Original formation377–439: one native Yicheng chain (owner invoke, ally
-- choice, then recipient discard). Preserve the independent ordinary provider.
local previous_yicheng_invoke=ai_skill_invoke.heg_yicheng
local previous_yicheng_discard=sgs.ai_skill_discard.heg_yicheng
local previous_yicheng_choice=ai_skill_choice.heg_yicheng
local function yicheng_other_provider(previous,key,...)
    if type(previous)=="function"then return previous(...)end
    if type(previous)=="boolean"then return previous end
    ai_unsupported("ordinary Yicheng provider is not installed",key)
end
ai_skill_invoke.heg_yicheng=function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

    if not original_enabled(self)then return (yicheng_other_provider(previous_yicheng_invoke,"heg_yicheng.invoke",self,options,request)) or false end
    if not show_defence(self)and not show_attack(self)then return (false) or false  end
    return (true) or false 
end
sgs.ai_skill_discard.heg_yicheng=function(self,discard_num,min_num,optional,include_equip)
    if not original_enabled(self)then return yicheng_other_provider(previous_yicheng_discard,"heg_yicheng.discard",self,discard_num,min_num,optional,include_equip)end
    if self.player:hasSkill("hongyan")then
        return self:askForDiscard("dummyreason",discard_num,min_num,false,true)
    end
    local unwanted={}
    local cards={};for _,card in ipairs(self.player:getHandcards())do cards[#cards+1]=card end
    if hegemony_source_query(self,'needToThrowArmor')then unwanted[#unwanted+1]=(self.player:getArmor()):getKnownId()end
    if self:getCardsNum("Slash")>1 then
        cards=self:sortByKeepValue(cards)
        for _,card in ipairs(cards)do if card:isKindOf("Slash")then unwanted[#unwanted+1]=card:getKnownId()end end
        -- Source removes the first accumulated item, even if it was the armor.
        table.remove(unwanted,1)
    end
    local num=self:getCardsNum("Jink")-1
    if self.player:getArmor()then num=num+1 end
    if num>0 then
        for _,card in ipairs(cards)do
            if card:isKindOf("Jink")and num>0 then unwanted[#unwanted+1]=card:getKnownId();num=num-1 end
        end
    end
    for _,card in ipairs(cards)do
        if(card:isKindOf("Weapon")and self.player:getHandcardNum()<3)or card:isKindOf("OffensiveHorse")
            or self:getSameEquip(card,self.player)or card:isKindOf("AmazingGrace")or card:isKindOf("Lightning")then
            unwanted[#unwanted+1]=card:getKnownId()
        end
    end
    if self.player:getWeapon()and self.player:getHandcardNum()<3 then unwanted[#unwanted+1]=(self.player:getWeapon()):getKnownId()end
    if self.player:getOffensiveHorse()and self.player:getWeapon()then unwanted[#unwanted+1]=(self.player:getOffensiveHorse()):getKnownId()end
    for i=#unwanted,1,-1 do
        local card=known(self:getKnownCardById(unwanted[i]),"heg_yicheng owner cost")
        if not self.player:isJilei(card)then return{unwanted[i]}end
    end
    return self:askForDiscard("dummyreason",discard_num,min_num,false,true)
end
ai_skill_choice.heg_yicheng=function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end
    local data=request and self:getDecisionData(request) or nil

    if not original_enabled(self)then return  ai_choice_result((yicheng_other_provider(previous_yicheng_choice,"heg_yicheng.choice",self,{reason='heg_yicheng',choices=options and options.choices or (choices~=nil and {} or nil),inquiry_scope='ordinary_internal'},request)),options)end
    local owner=data and data:toPlayer()
    if owner and self:isFriend(owner)then return  ai_choice_result(("yes"),options)end
    return  ai_choice_result(("no"),options)
end

-- Original newsgs138 and mol308: complete draw/replenishment invocation policies.
local previous_duannian=ai_skill_invoke.heg_duannian
ai_skill_invoke.heg_duannian=function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

    if not original_enabled(self)then return (yicheng_other_provider(previous_duannian,"heg_duannian",self,options,request)) or false end
    local has_peach=false
    for _,card in ipairs(self.player:getHandcards())do
        if self:originalHegemonyIsCard("Peach",card,self.player)
            or(self:originalHegemonyIsCard("Analeptic",card,self.player)and hegemony_source_query(self,'isWeak'))then has_peach=true end
    end
    if not has_peach then
        if self.player:getHandcardNum()<self.player:getMaxHp()then return (true) or false  end
        if self.player:getHandcardNum()==self.player:getMaxHp()and self:getCardsNum("Jink")==0 then return (true) or false  end
        if self.player:getHandcardNum()>self.player:getMaxHp()and hegemony_source_query(self,'getOverflow')>0 and self:getCardsNum("Jink")==0 then return (true) or false  end
    end
    return (false) or false 
end
