-- Round23: fixed effective Original newsgs159/194–262/552 and
-- transformation450. These are separate from the ordinary-mode providers.
local function original_policy(registry,key,body)
    local previous=registry[key]
    registry[key]=function(self,...)
        if not original_enabled(self)then
            if type(previous)=="function"then return previous(self,...)end
            if previous~=nil then return previous end
            ai_unsupported("ordinary provider is not installed",key)
        end
        return body(self,...)
    end
end

-- heg-common4688: preserve even the source's unused weak/distance queries and
-- unreachable final showRate test; they determine query/RNG ordering.
function SmartAIView:originalHegemonyWillShowForMasochism()
    if self.room:getMode()=="jiange_defense"then return true end
    if known(heg_player(self,self.player).shown_one,"shown_one")then return true end
    if #self.room:getAlivePlayers()<3 then return true end
    local notshown,shown_count,f,e,eAtt=0,0,0,0,0
    for _,p in ipairs(self.room:getAlivePlayers())do
        if not known(heg_player(self,p).shown_one,"shown_one")then notshown=notshown+1 end
        if known(heg_player(self,p).shown_one,"shown_one")then
            shown_count=shown_count+1
            if heg_kingdom(self,p)==known(heg_facts(self).own_kingdom,"own kingdom")then f=f+1
            else
                e=e+1
                if hegemony_source_query(self,'isWeak',p)and p:getHp()==1 and self.player:distanceTo(p)<=self.player:getAttackRange()then eAtt=eAtt+1 end
            end
        end
    end
    local showRate=math.random()-self.player:getHp()/10+e/10+shown_count/20+self.room:getTurnCount()/10
    local firstShowReward=false
    if known(heg_facts(self).first_show_reward,"first show reward")then
        if shown_count==0 then firstShowReward=true end
    end
    if firstShowReward and showRate>0.9 then return true end
    if showRate<0.2 then return false end
    if self.player:getLostHp()==0 and self:getCardsNum("Peach")>0 and showRate<0.2 then return false end
    return true
end

