-- Original formation family, fixed b6025acc. Only lawful facade values enter
-- these bodies; source card construction is separated from native authority.
do
local function face(self,id)return known(self:getKnownCardById(id),'formation disclosed card '..tostring(id))end
local function physical(card)return tostring(card:getKnownEffectiveId())end
local function seed(self,name,request)
    return self:evaluateTurnSkillCard(name,'ActiveSkillCard',{},request)
end
local function response(self,name,id,target)
    local request=self.request
    local card=self:bindSkillCard(name,{id},request,nil,'ActiveSkillCard')
    local use=AIUsePlan.new();use.card=card;use.to=AIList.new(target and{target}or{})
    return known(use:toAnswer(),'formation response')
end
local function known_skill(self,name,p)
    -- Original hasKnownSkill means owner hasSkill, otherwise publicly shown.
    if p:objectName()==self.player:objectName()and p:hasSkill(name)then return true end
    return shown(self,p,name)
end
local function ziliang_card(self,target)
    if not(target:getPhase()==sgs.Player_NotActive and hegemony_source_query(self,'needKongcheng',target,true))then
        local cards={};for _,id in ipairs(self.player:getPile('field'))do cards[#cards+1]=face(self,id)end
        if target:getPhase()==sgs.Player_NotActive and hegemony_source_query(self,'isWeak',target)then
            for _,card in ipairs(cards)do if card:isKindOf('Peach')or card:isKindOf('Analeptic')then return card:getKnownEffectiveId()end end
            for _,card in ipairs(cards)do if card:isKindOf('Jink')then return card:getKnownEffectiveId()end end
            self:sortByKeepValue(cards,true)
        else self:sortByUseValue(cards)end
        -- Preserve the donor's ordinary empty-field indexing error.
        return cards[1]:getEffectiveId()
    end
end
