    for _,kind in ipairs({'DefensiveHorse','OffensiveHorse','Weapon'})do
        for _,card in ipairs(cards)do if card:isKindOf(kind)then local p=huyuan_validate(self,kind,true);if p then return response(self,'heg_huyuan',card:getKnownEffectiveId(),p)end end end
