original_policy(sgs.ai_skill_cardask,'@heg_qianhuan-put',function(self)
    local function can_put(card)
        local suits={'heart','diamond','spade','club'}
        for _,id in ipairs(self.player:getPile('sorcery'))do table.removeOne(suits,(face(self,id)):getSuitString())end
        for _,suit in ipairs(suits)do if card:getSuitString()==suit then return true end end;return false
