        for _,name in ipairs(known(row.to,'formation qianhuan targets'))do use.to[#use.to+1]=known(self.room:findPlayerByObjectName(name),'formation qianhuan target')end
        cancel=use.card and #use.to>0 and invoke_qianhuan(self,use)
    end
    if not cancel then local fields=prompt:split(':');local target=fields[3]and self.room:findPlayerByObjectName(fields[3]);cancel=target and self:isFriend(target)end
    if cancel then return response(self,'heg_qianhuan',pile[1])end;return'.'
end)
