original_policy(sgs.ai_skill_discard,'heg_DragonPhoenix',function(self,discard_num)
    local cards=sgs.QList2Table(self.player:getCards('he'));if #cards==1 then return{(cards[1]):getKnownEffectiveId()}end
    local function aux(card)
        local place=self.room:getCardPlace(card:getKnownEffectiveId())
        if place==sgs.Player_PlaceEquip then
            local few=self.player:getHandcardNum()<discard_num+2 and not hegemony_source_query(self,'needKongcheng')
            if card:isKindOf('Weapon')then return few and 0 or 2
            elseif card:isKindOf('OffensiveHorse')then return few and 0 or 1
            elseif card:isKindOf('DefensiveHorse')then return 3
            elseif card:isKindOf('Armor')then if self.player:getHp()==1 and card:isKindOf('HBreastplate')then return 99 end;return hegemony_source_query(self,'needToThrowArmor')and-2 or 4
            elseif card:isKindOf('Treasure')then if card:isKindOf('WoodenOx')then if #self.player:getPile('wooden_ox')==0 then return few and 0 or 2 else return 6 end end;return few and 1 or 4
            else return 0 end
        else
            if hegemony_source_query(self.player,'getMark','##heg_qianxi+no_suit_red')>0 and card:isRed()and not card:isKindOf('Peach')then return 0 end
            if hegemony_source_query(self.player,'getMark','##heg_qianxi+no_suit_black')>0 and card:isBlack()then return 0 end
            return hegemony_source_query(self,'isWeak')and 5 or 0
        end
