    for _,enemy in ipairs(self.enemies)do for _,slash in ipairs(self:getCards('Slash'))do
        if not self:slashProhibit(slash,enemy)and self:slashIsEffective(slash,enemy)and self:originalHegemonyIsGoodTarget(enemy,self.enemies)then goodtarget=goodtarget+1;break end
    end end
