local function hongfa_card(self,pile)
    for _,id in ipairs(pile)do
        local card=face(self,id)
        if card:isKindOf('HPeaceSpell')then return id
        elseif card:isKindOf('HDragonPhoenix')then local lord=self.room:getLord('shu');if not lord or self:isFriend(lord)then return id end
        elseif card:isKindOf('HLuminousPearl')then local lord=self.room:getLord('wu');if not lord or self:isFriend(lord)then return id end
        elseif card:isKindOf('HSixDragons')then local lord=self.room:getLord('wei');if not lord or self:isFriend(lord)then return id end
        else return id end
    end
    if #pile>0 then return pile[1]end
end
