-- Fixed heg-formation-ai.lua:22-129 is a distinct ordinary-mode provider.
-- Keep its gate separate from admitted Original and preserve optional delegates.
do
local function ordinary(reg,key,body)
    local prior=reg[key]
    reg[key]=function(self,...)
        if known(heg_facts(self).enabled,'hegemony mode')==false then return body(self,...)end
        if type(prior)=='function'then return prior(self,...)end
        if prior~=nil then return prior end
        ai_unsupported('provider outside ordinary Formation domain',key)
    end
end
local function use_context(self)
    local raw=known(known(self:getDecisionContext().original_formation,'formation context').qianhuan_use,'qianhuan use')
    if raw==false then return{to=AIList.new{}}end
    local to=AIList.new{};for _,name in ipairs(known(raw.to,'qianhuan targets'))do to:append(known(self.room:findPlayerByObjectName(name),'qianhuan target'))end
    return{card=raw.card and CardView.new(raw.card),from=raw.from and known(self.room:findPlayerByObjectName(raw.from),'qianhuan source'),to=to}
end
local function respond(self,skill,costs,targets)
    local request=self.request
    local card=self:bindSkillCard(skill,costs,request,nil,'ActiveSkillCard')
    local use=AIUsePlan.new();use.card=card;use.to=AIList.new(targets or{})
    return known(use:toAnswer(),'ordinary Formation response')
end
