sgs.ai_skill_exchange["weimeng_giveback"] = function(self,pattern,max_num,min_num,expand_pile)
  local weimeng_give = {}
  local to
	for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
		if hegemony_source_query(p,'hasFlag',"WeimengTarget") then
			to = p
			break
		end
	end
  local visibleflag = string.format("%s_%s_%s", "visible", self.player:objectName(), to:objectName())

  local function weiming_insert(card)
    local c_id = card:getKnownEffectiveId()
    if #weimeng_give < max_num and not table.contains(weimeng_give, c_id) then
      if not hegemony_source_query(card,'hasFlag',"visible")then r25_observe_given_card(self,card,to)end
      table.insert(weimeng_give, c_id)
    end
  end

  local cards = self.player:getCards("he")
	cards = sgs.QList2Table(cards)
	self:sortByUseValue(cards,true)
  if self:isFriend(to) then
    if self.player:getHp() > 1 and hegemony_source_query(self,'isWeak',to) and self:getCardsNum("Analeptic") > 0 then
      weiming_insert(self:getCard("Analeptic"))
    end
    if not hegemony_source_query(self,'isWeak') and hegemony_source_query(self,'isWeak',to) and self:getCardsNum("Peach") > 0 then
      weiming_insert(self:getCard("Peach"))
    end
    local c, friend = self:getCardNeedPlayer(cards, {to})
    if friend and friend:objectName() == to:objectName() then
      weiming_insert(c)
    end
    if self:getCardsNum("Jink") > 1 then
      weiming_insert(self:getCard("Jink"))
    end
    if self:getCardsNum("Slash") > 1 and not hegemony_source_query(self,'hasCrossbowEffect') then
      weiming_insert(self:getCard("Slash"))
    end
  end

  for _, c in ipairs(cards) do
    weiming_insert(c)
  end
	return weimeng_give
end

