  self:sortInPlace(self.friends_noself, "handcard", true)
  for _, friend in ipairs(self.friends_noself) do
    if not friend:isKongcheng() and friend:getJudgingArea():length() > (hegemony_source_query(self,'needToThrowArmor',friend) and 0 or 1) then
      local friend_min_card = self:getMinNumberCard(friend)
      local friend_number = friend_min_card and friend_min_card:getNumber() or 100
      if friend_min_card and shown(self,friend,"heg_yingyang") then friend_number = math.max(friend_number - 3, 1) end
      if max_point> friend_number then
        local hcards = sgs.QList2Table(self.player:getHandcards())
        self:sortByUseValue(hcards,true)
        for _, c in ipairs(hcards) do
          if c:getNumber() + (shown(self,self.player,"heg_yingyang") and 3 or 0) > friend_number then
            self:setPriorityValue("HFenglveCard",4.2,"original.manoeuvre")

            self.fenglve_card = c:getKnownEffectiveId()
            use.card = FLCard
            if use.to then
              use.to:append(friend)
              return
            end
          end
        end
      end
      if not friend_min_card and max_point > 8 then
        self:setPriorityValue("HFenglveCard",4.2,"original.manoeuvre")

        self.fenglve_card = max_card:getKnownEffectiveId()
        use.card = FLCard
        if use.to then
          use.to:append(friend)
          return
        end
      end
    end
  end

  if #self.enemies == 0 then return end
  local notlose = hegemony_source_query(self,'getOverflow') > 1
  if self.player:getCardCount(true) < (hegemony_source_query(self,'needToThrowArmor') and 2 or 1) and not self:isValuableCard(max_card) then
    notlose = true
  end
	self:sortInPlace(self.enemies, "handcard")
	for _, enemy in ipairs(self.enemies) do
		if not enemy:isKongcheng() and enemy:getCardCount(true) > 2 then
			local enemy_max_card = self:getMaxNumberCard(enemy)
			local enemy_number = enemy_max_card and enemy_max_card:getNumber() or 100
			if enemy_max_card and shown(self,enemy,"heg_yingyang") then enemy_number = math.min(enemy_number + 3, 13) end
			local allknown = false
			if self:getKnownNum(enemy) == enemy:getHandcardNum() then
				allknown = true
			end
			if (not enemy_max_card and (max_point > 11)) or notlose
				or (max_point > enemy_number and not allknown and max_point > 10)
				or (max_point > enemy_number and allknown) then
          if notlose or (max_point > enemy_number and allknown) or max_point > 11 then
            self:setPriorityValue("HFenglveCard",5,"original.manoeuvre")
          end
					self.fenglve_card = max_card:getKnownEffectiveId()
					use.card = FLCard
					if use.to then
            use.to:append(enemy)
            return
          end
			end
		end
	end
end

