sgs.ai_skill_exchange["fenglve_give"] = function(self,pattern,max_num,min_num,expand_pile)
  local fenglve_give = {}
  local to
	for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
		if hegemony_source_query(p,'hasFlag',"FenglveTarget") then
			to = p
			break
		end
	end
  local visibleflag = string.format("%s_%s_%s", "visible", self.player:objectName(), to:objectName())

  local function fenglve_insert(card)
    local c_id = card:getKnownEffectiveId()
    if #fenglve_give < max_num and not table.contains(fenglve_give, c_id) then
      if not hegemony_source_query(card,'hasFlag',"visible")then r25_observe_given_card(self,card,to)end
      table.insert(fenglve_give, c_id)
    end
  end

  if self:isFriend(to) and hegemony_source_query(self,'isWeak',to) then
    if self.player:getHp() > 1 and self:getCardsNum("Analeptic") > 0 then
      fenglve_insert(self:getCard("Analeptic"))
    end
    if not hegemony_source_query(self,'isWeak') and self:getCardsNum("Peach") > 0 then
      fenglve_insert(self:getCard("Peach"))
    end
    if self:getCardsNum("Jink") > 1 then
      fenglve_insert(self:getCard("Jink"))
    end
  end
  local cards = self.player:getCards("he")
	cards = sgs.QList2Table(cards)
	self:sortByUseValue(cards,true)
  for _, c in ipairs(cards) do
    fenglve_insert(c)
  end
	return fenglve_give
end

