ai_skill_invoke.heg_anyong =  function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

  if not self:willShowForAttack() then
    return (false) or false 
  end
  local damageStruct = r25_context(self,"AnyongDamagedata","damage")
  if not self:damageIsEffective_(damageStruct) then
    return (false) or false 
  end
  local card = damageStruct.card
  local original_num = damageStruct.damage
  local from = damageStruct.from
  local target = damageStruct.to
  if not target or (self:isFriend(target) and not target:isChained()) then
    return (false) or false 
  end

  local function damageCount(tp,num,chained)
    local n = num
    if shown(self,tp,"heg_mingshi") and not known(heg_player(self,from).shown_all,"shown_all") then
      n = n - 1
    end
    if hegemony_source_query(tp,'getMark',"##xiongnve_avoid") > 0 then
      n = n - 1
    end
    local gongqing_avoid = false
    if shown(self,tp,"heg_gongqing") then
      if from:getAttackRange() < 3 then
        gongqing_avoid = true
      end
      if from:getAttackRange() > 3 then
        n = n + 1
      end
    end
    if (tp:hasArmorEffect("SilverLion") and (not card or not card:isKindOf("Slash") or not self:ignoreArmor(from, tp)))
    or gongqing_avoid then
      n = 1
    else
      if not chained then
        n = n * 2
      end
      if damageStruct.nature == sgs.DamageStruct_Fire and (tp:hasArmorEffect("Vine")) then
        n = n + 1
      end
    end

    return n
  end

  local anyong_damage = damageCount(target ,original_num)
  if target:hasArmorEffect("Breastplate") and anyong_damage >= target:getHp() then
    return (false) or false 
  end

  local allshown_invoke = known(heg_player(self,target).shown_all,"shown_all")
                      and (self.player:getHp() > 1 or (self:getCardsNum("Peach") + self:getCardsNum("Analeptic")) > 0)
  local oneshown_invoke = not known(heg_player(self,target).shown_all,"shown_all") and known(heg_player(self,target).shown_one,"shown_one")
                      and (self.player:getHandcardNum() < 2 or hegemony_source_query(self,'getOverflow') > 1 or self.player:hasSkill("lirang"))
  local chained_invoke = false

  if target:isChained() and damageStruct.nature ~= sgs.DamageStruct_Normal then
    local tDamageNum = damageCount(target ,original_num)
    local enemy_dnum = self:isEnemy(target) and tDamageNum or 0
    local friend_dnum = self:isFriend(target) and tDamageNum or 0
    local neutrality_dum = (not self:isFriend(target) and not self:isEnemy(target)) and tDamageNum or 0

    for _, p in sgs.qlist(self.room:getOtherPlayers(target)) do
      if p:isChained() then
        damageStruct.to = p
        if self:damageIsEffective_(damageStruct) then
          if from:hasSkill("heg_xinghuo") and damageStruct.nature == sgs.DamageStruct_Fire then
            tDamageNum = tDamageNum + 1
          end
          damageStruct.damage = tDamageNum
          local damage_num = damageCount(p, tDamageNum, true)
          if self:isEnemy(p) then
            enemy_dnum = enemy_dnum + damage_num
          elseif self:isFriend(p) then
            friend_dnum = friend_dnum + damage_num
          else
            neutrality_dum = neutrality_dum + damage_num
          end
        end
      end
    end
    if enemy_dnum > 3 and enemy_dnum + neutrality_dum > friend_dnum then
      chained_invoke = true
    end
  end

  if chained_invoke or (not self:isFriend(target) and not known(heg_player(self,target).shown_one,"shown_one") and anyong_damage > 1)
  or (self:isEnemy(target) and anyong_damage > 1 and ((hegemony_source_query(self,'isWeak',target) and target:getHp() == 1)
      or oneshown_invoke or (anyong_damage > 2 and allshown_invoke))) then
    return (true) or false 
  end
	return (false) or false 
end

