ai_card_use.HMingfaCard = function(self,card,use)
  local target

  local compare_func = function(a, b)
    local amax = hegemony_source_query(self,'getOverflow',a,true)
    local bmax = hegemony_source_query(self,'getOverflow',b,true)
    if amax == bmax then
      return a:getHandcardNum() < b:getHandcardNum()
    else
      return amax < bmax
    end
	end

  table.sort(self.enemies, compare_func)
  if math.min(self.player:getHandcardNum(), hegemony_source_query(self,'getOverflow',self.player,true)) < 2 then

    self.enemies = sgs.reverse(self.enemies)
  end
  if #self.enemies == 0 then
    local targets = {}
    for _, p in sgs.qlist(self.room:getAlivePlayers()) do
      if not self.player:willBeFriendWith(p) and hegemony_source_query(p,'getMark',"##heg_mingfa") < 1 then
        table.insert(targets, p)
      end
    end
    table.sort(targets, compare_func)
    if math.min(self.player:getHandcardNum(), hegemony_source_query(self,'getOverflow',self.player,true)) < 2 then
      targets = sgs.reverse(targets)
    end
    target = targets[1]
  else
    for _, p in ipairs(self.enemies) do
      if hegemony_source_query(p,'getMark',"##heg_mingfa") < 1 then
        target = p
        break
      end
    end
  end
  if target and self:isFriend(target) and
  (math.min(self.player:getHandcardNum(), hegemony_source_query(self,'getOverflow',self.player,true))
    > math.min(target:getHandcardNum() + 1, hegemony_source_query(self,'getOverflow',target,true))) then
    target = nil
  end
  if target then

	  use.card = card
    if use.to then
      use.to:append(target)
    end
  end
end

