ai_fill_skill.heg_qice = function(self,options,request)
    local inclusive=(options or {}).inclusive

	if self.player:getStrategyHasUsed("HQiceCard") or self.player:isKongcheng() then return end
	local handcardnum = self.player:getHandcardNum()
	self.qicenum = {}
	self.qice_to = nil

	local cardsavailable = function(use_card, hcardnum)
		local target_num = 0
		if use_card:isKindOf("HAllianceFeast") then
			for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
				if not p:isRemoved() and not self.player:isProhibited(p, use_card) and r25_role(self,p) == "careerist" then
					return 2 <= hcardnum
				end
			end
			local kingdoms = {wei = 0,shu = 0,wu = 0,qun = 0}
			local kingdoms_num = {}
			for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
				if not p:isRemoved() and not self.player:isProhibited(p, use_card) and known(heg_player(self,p).shown_one,"shown_one")
				and (r25_role(self,self.player) == "careerist" or self:originalHegemonyOwnKingdom() ~= p:getKingdom()) then
					kingdoms[p:getKingdom()] = kingdoms[p:getKingdom()] + 1
				end
			end
			for key, value in pairs(kingdoms) do
				
				if key and value > 0 then
					table.insert(kingdoms_num,value)
				end
			end
			if #kingdoms_num > 0 then
				target_num = 1 + math.min(table.unpack(kingdoms_num))

			end
			return false
		elseif use_card:isKindOf("HAwaitExhausted") then
			for _, p in sgs.qlist(self.room:getAlivePlayers()) do
				if not p:isRemoved() and not self.player:isProhibited(p, use_card)
				and known(heg_player(self,self.player).shown_one,"shown_one") and r25_role(self,self.player) ~= "careerist"
				and r25_role(self,p) ~= "careerist" and known(heg_player(self,p).shown_one,"shown_one") and p:getKingdom() == self:originalHegemonyOwnKingdom() then
					target_num = target_num + 1
				end
			end
		elseif use_card:getSubtype() == "global_effect" and not use_card:isKindOf("HFightTogether") then
			for _, p in sgs.qlist(self.room:getAlivePlayers()) do
				if not p:isRemoved() and not self.player:isProhibited(p, use_card) then
					target_num = target_num + 1
				end
			end
		elseif use_card:getSubtype() == "aoe" and not use_card:isKindOf("HBurningCamps") then
			for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
				if not p:isRemoved() and not self.player:isProhibited(p, use_card) then
					target_num = target_num + 1
				end
			end
		elseif use_card:isKindOf("HBurningCamps") then
			local np = self.player:getNextAlive()
			if not self.player:isFriendWith(np) then
				local players = r25_formation(self,np)
				for _, p in sgs.qlist(players) do
					if not p:isRemoved() and not self.player:isProhibited(p, use_card) then
						target_num = target_num + 1
					end
				end
			end
		else
			target_num = 1
		end
		self.qicenum[use_card:objectName()] = target_num
		return target_num <= hcardnum
	end

	local trickcards = {"alliance_feast","burning_camps","god_salvation","savage_assault","archery_attack",
	"befriend_attacking","ex_nihilo","duel","snatch","dismantlement","drowning",
	"iron_chain","await_exhausted","amazing_grace","fight_together","lure_tiger","imperial_order",
	"collateral","known_both","fire_attack","heg_threaten_emperor"}
	local available_tricks = {}
	for _,cardname in ipairs(trickcards) do
		local use_card = r25_clone(self,cardname)
		if cardsavailable(use_card,handcardnum) then
			table.insert(available_tricks, cardname)
		end
	end

	local has_peach = false
	local usevalue = 0
	local keepvalue = 0
	local id
	local cards = self.player:getHandcards()
	cards = sgs.QList2Table(cards)
	for _,card in ipairs(cards) do
		if card:canRecast() then return end
		if self:isCard("Peach", card, self.player) then
			has_peach = true
		end
		if card:isKindOf("HThreatenEmperor") and self:originalHegemonyIsBigKingdomPlayer(self.player) then
			return
		end
		if card:isAvailable(self.player) then
			if card:isKindOf("EquipCard") and not self:getSameEquip(card) and handcardnum > 1 then
				local use = sgs.CardUseStruct(card, self.player, self.player, true)
				self:useEquipCard(card, use)
			end
			usevalue = self:getUseValue(card) + usevalue
		end
		if not id then
			id = tostring(card:getKnownId())
		else
			id = id .. "+" .. tostring(card:getKnownId())
		end
	end
	self:sortByKeepValue(cards)
	for i = 1, #cards, 1 do
		if i > hegemony_source_query(self,'getOverflow',self.player) then
			keepvalue = self:getKeepValue(cards[i]) + keepvalue
		end
	end
	local str = "@HQiceCard=" .. id .. ":"
	self:setPriorityValue("HQiceCard",0.05,"original.transformation")
	if handcardnum == 1 then
		self:setPriorityValue("HQiceCard",3,"original.transformation")
	end

	if hegemony_source_query(self.player,'getMark',"GlobalBattleRoyalMode") > 0 and self.player:isWounded() then
		local enemy_wounded = false
		local known_null = false
		for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
			if not p:isRemoved() and p:isWounded() then
				enemy_wounded = true
			end
			if not p:isRemoved() and not self:isFriend(p) and self:originalHegemonyCardsNum("Nullification", p, self.player) > 0 then
				known_null = true
			end
		end
		if table.contains(available_tricks,"god_salvation") and not enemy_wounded and not known_null then
			if self.qicenum["god_salvation"] and self.qicenum["god_salvation"] == handcardnum then
				self:setPriorityValue("HQiceCard",3,"original.transformation")
			end

			return r25_parse(self,str .. "god_salvation")
		end
		if table.contains(available_tricks,"alliance_feast") and not known_null then
			local dummyuse = { isDummy = true, to = AIList.new{} }
			self:useCardAllianceFeast(r25_clone(self,"alliance_feast"), dummyuse)
			if dummyuse.card then
				if self.qicenum["alliance_feast"] and self.qicenum["alliance_feast"] == handcardnum then
					self:setPriorityValue("HQiceCard",8,"original.transformation")
				end

				return r25_parse(self,str .. "alliance_feast")
			end
		end
	end

	if not has_peach and table.contains(available_tricks,"god_salvation") then
		local cloneg = r25_clone(self,"god_salvation")
		if self:willUseGodSalvation(cloneg) then
			if self.qicenum["god_salvation"] and self.qicenum["god_salvation"] == handcardnum then
				self:setPriorityValue("HQiceCard",3,"original.transformation")
			end

			return r25_parse(self,str .. "god_salvation")
		end
	end

	if not has_peach and table.contains(available_tricks,"alliance_feast") and self.player:getLostHp() > 1 then
		local dummyuse = { isDummy = true, to = AIList.new{} }
		self:useCardAllianceFeast(r25_clone(self,"alliance_feast"), dummyuse)
		if dummyuse.card then
			if self.qicenum["alliance_feast"] and self.qicenum["alliance_feast"] == handcardnum and self:getAllPeachNum() < 1 then
				self:setPriorityValue("HQiceCard",8,"original.transformation")
			end

			return r25_parse(self,str .. "alliance_feast")
		end
	end

	if not has_peach and table.contains(available_tricks,"burning_camps") then
		local np = self.player:getNextAlive()
		local can_burn = self:isEnemy(np) and r25_formation(self,np):length() == #self.enemies
		local dummyuse = { isDummy = true, to = AIList.new{} }
		self:useCardBurningCamps(r25_clone(self,"burning_camps"), dummyuse)
		if dummyuse.card and can_burn then
			if self.qicenum["burning_camps"] and self.qicenum["burning_camps"] == handcardnum then
				self:setPriorityValue("HQiceCard",1.5,"original.transformation")
			end

			return r25_parse(self,str .. "burning_camps")
		end
	end

	if (table.contains(available_tricks,"archery_attack") or table.contains(available_tricks,"savage_assault")) then
		local clonea = r25_clone(self,"archery_attack")
		local clones = r25_clone(self,"savage_assault")
		local heg_zhurong = original_find_shown(self,"heg_juxiang")
		local heg_caocao = original_find_shown(self,"nosjianxiong")
		local heg_mengda = original_find_shown(self,"heg_qiuan")

		if not has_peach and self:getAoeValue(clonea) > 0
		and (not heg_caocao or self:isFriend(heg_caocao))
		and (not heg_mengda or self:isFriend(heg_mengda)) then
			if self.qicenum["archery_attack"] and self.qicenum["archery_attack"] == handcardnum then
				self:setPriorityValue("HQiceCard",1.5,"original.transformation")
			end

			return r25_parse(self,str .. "archery_attack")
		end
		if not has_peach and self:getAoeValue(clones) > 0
		and (not heg_caocao or self:isFriend(heg_caocao))
		and (not heg_mengda or self:isFriend(heg_mengda))
		and (not heg_zhurong or self:isFriend(heg_zhurong)) then
			if self.qicenum["savage_assault"] and self.qicenum["savage_assault"] == handcardnum then
				self:setPriorityValue("HQiceCard",1.5,"original.transformation")
			end

			return r25_parse(self,str .. "savage_assault")
		end
	end

	if not has_peach and table.contains(available_tricks,"burning_camps") then
		local can_burn = false
		local burn_weak = 0
		local players = r25_formation(self,self.player:getNextAlive())
		for _, p in sgs.qlist(players) do
			if p:getHp() == 1 and self:trickIsEffective(r25_clone(self,"burning_camps"), p, self.player) then
				can_burn = true
				break
			end
			if hegemony_source_query(self,'isWeak',p) and self:trickIsEffective(r25_clone(self,"burning_camps"), p, self.player) then
				burn_weak = burn_weak + 1
			end
		end
		if burn_weak > 1 or burn_weak == #self.enemies then
			can_burn = true
		end
		local dummyuse = { isDummy = true, to = AIList.new{} }
		self:useCardBurningCamps(r25_clone(self,"burning_camps"), dummyuse)
		if dummyuse.card and can_burn then
			if self.qicenum["burning_camps"] and self.qicenum["burning_camps"] == handcardnum then
				self:setPriorityValue("HQiceCard",1.5,"original.transformation")
			end

			return r25_parse(self,str .. "burning_camps")
		end
	end

	if not has_peach and table.contains(available_tricks,"duel") then
		local dummyuse = { isDummy = true, to = AIList.new{} }
		self:useCardDuel(r25_clone(self,"duel"), dummyuse)
		if not dummyuse.to:isEmpty() then
			local enemy = dummyuse.to:first()
			if enemy:getHp() == 1 and enemy:getHandcardNum() < 2 and self:originalHegemonyCardsNum("Slash", enemy, self.player) < 1 then

				return r25_parse(self,str .. "duel")
			end
		end
	end

	if not has_peach and table.contains(available_tricks,"drowning") and self.player:getHp() > 1 then
		local dummyuse = { isDummy = true, to = AIList.new{} }
		self:useCardDrowning(r25_clone(self,"drowning"), dummyuse)
		if not dummyuse.to:isEmpty() then
			local enemy = dummyuse.to:first()
			if (hegemony_source_query(self,'isWeak',enemy) or (enemy:getHp() == 1 and not enemy:hasArmorEffect("Breastplate")))
			and enemy:getEquips():length() > 3 and not enemy:hasArmorEffect("PeaceSpell") then

				return r25_parse(self,str .. "drowning")
			end
		end
	end

	if not has_peach and table.contains(available_tricks,"befriend_attacking") and (usevalue < 6 or handcardnum < 3) then
		local dummyuse = { isDummy = true, to = AIList.new{} }
		self:useCardBefriendAttacking(r25_clone(self,"befriend_attacking"), dummyuse)
		if dummyuse.card then

			return r25_parse(self,str .. "befriend_attacking")
		end
	end

end

ai_card_use.HQiceCard = function(self,card,use)
	-- Read the readonly face's projected declaration directly.  Native
	-- SkillCard and the readonly facade use different legacy wire shapes, so
	-- declaration recovery must never reparse the legacy sort key.
	local view=type(card)=='table' and rawget(card,'_view')
	local userstring=type(view)=='table' and (view.user_string or view.declared_name) or nil
	if userstring==nil and type(card.getUserString)=='function' then
		userstring=card:getUserString()
	end
	if type(userstring)~='string' or userstring=='' then
		ai_unsupported('HQice declaration is not projected','heg_qice declaration')
	end
	-- Hegemony Qice must consume the complete hand.  The selected HQiceCard
	-- remains the final skill card; this evaluation is only the readonly
	-- declared trick used to choose legal targets and policy.
	local ids=sgs.QList2Table(card:getSubcards())
	local hand=self.player:handCards()
	if #ids~=self.player:getHandcardNum() then
		ai_unsupported('HQice source material is not the complete hand','heg_qice material')
	end
	for _,id in ipairs(ids) do
		if not hand:contains(id) then
			ai_unsupported('HQice source material is outside the owner hand','heg_qice material')
		end
	end
	local evaluated=self:originalHegemonyEvaluateViewAsSpec{
		source_key='heg_qice',skill='heg_qice',name=userstring,
		suit=sgs.Card_NoSuit,number=0,subcards=ids}
	local qicecard=known(evaluated and evaluated.card,'HQice declared trick evaluation')
	if self.player:isCardLimited(qicecard,sgs.Card_MethodUse) then return end
	r25_use_by_class(self,qicecard,use)
	if use.card then use.card=card end
end

ai_skill_choice["transform_qice"] = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end


	local importantsklii = {"heg_yiji", "guicai", "mobilefangzhu", "heg_luoshen", "heg_jieming", "heg_jieyue", "heg_shicai", "heg_wanggui", "heg_sidi"}
	local skills = r25_slot_skills(self,self.player, false)
	for _, skill in ipairs(skills) do
		if table.contains(importantsklii, skill:objectName()) then
			return  ai_choice_result(("no"),options)
		end
		if skill:objectName() == "heg_qice" and not (r25_player_general(self,self.player, true):getKingdom() == "careerist" and hegemony_source_query(self,'isWeak')) then
			return  ai_choice_result(("no"),options)
		end
		if skill:getFrequency() == sgs.Skill_Limited and not (skill:getLimitMark() ~= "" and hegemony_source_query(self.player,'getMark',skill:getLimitMark()) == 0) then
			return  ai_choice_result(("no"),options)
		end
	end
	local g2name = r25_player_general(self,self.player, false):objectName()
	if g2name:match("sujiang") or (sgs.general_value[g2name] and sgs.general_value[g2name] < 7) then
		return  ai_choice_result(("yes"),options)
	end
	choices = choices:split("+")
	return  ai_choice_result((choices[math.random(1,#choices)]),options)
end

ai_skill_invoke.heg_zhiyu = function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

	if not self:willShowForMasochism() then return (false) or false  end
	local damage = data:toDamage()
	local from = damage.from
	local cards = self.player:getHandcards()
	cards = sgs.QList2Table(cards)
	local first
	local difcolor = false
	for _, card in ipairs(cards)  do
		if not first then first = card end
		if (first:isRed() and card:isBlack()) or (card:isRed() and first:isBlack()) then
			difcolor = true
			break
		end
	end
	if not difcolor and from then
		if self:isFriend(from) and not from:isKongcheng() then
			return (false) or false 
		elseif not self:isFriend(from) then
			if self:doNotDiscard(from, "h") and not from:isKongcheng() then return (false) or false  end
			return (true) or false 
		end
	end
	return (true) or false 
end

ai_skill_invoke.heg_wanwei = true

sgs.ai_skill_exchange["_wanwei"] = function(self,pattern,max_num,min_num,expand_pile)
	local result = {}
	local cards = self.player:getCards("he")
	cards=sgs.QList2Table(cards)
	self:sortByKeepValue(cards)
	for _, c in ipairs(cards) do
		table.insert(result, c:getKnownId())
		if #result == max_num then
			return result
		end
	end
	return result
end

ai_skill_invoke.heg_yuejian = function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

	local target = self.room:getCurrent()
	if target:getHandcardNum() > target:getMaxCards() and target:isWounded() then return (true) or false  end
	return (false) or false 
end

ai_fill_skill.heg_xiongsuan = function(self,options,request)
    local inclusive=(options or {}).inclusive


	if hegemony_source_query(self.player,'getMark',"@fierce") < 1 or not self.player:canDiscard(self.player,"h") then return end
	if hegemony_source_query(self.player,'getMark',"Global_TurnCount") < 2 and not known(heg_player(self,self.player).shown_one,"shown_one") then return end
	local cards = self.player:getHandcards()
	cards = sgs.QList2Table(cards)
	self:sortByUseValue(cards, true)
	for _, acard in ipairs(cards) do
		if not self:isValuableCard(acard) then
			return r25_parse(self,"@HXiongsuanCard=".. acard:getKnownEffectiveId() .."&heg_xiongsuan")
		end
	end
end

ai_card_use.HXiongsuanCard = function(self,card,use)
	
	local target
	for _, friend in ipairs(self.friends) do
		if self:isFriendWith(friend) and friend:hasSkill("xiongyi") and hegemony_source_query(friend,'getMark',"@arise") < 1 and friend:getHp() > 1 then
			self.xiongsuan_skill = "xiongyi"
			target = friend
			break
		end
	end
	for _, friend in ipairs(self.friends) do
		if self:isFriendWith(friend) and friend:hasSkill("luanwu") and hegemony_source_query(friend,'getMark',"@chaos") < 1 and friend:getHp() > 1 then
			local good, bad = 0, 0
			local alive = self.room:alivePlayerCount()
			if good < alive/4 then break end

			for _, player in sgs.qlist(self.room:getOtherPlayers(self.player)) do do 
				if player:isRemoved() then
					goto package_continue_1
				end
				local hp = math.max(player:getHp(), 1)
				if self:originalHegemonyCardsNum("Analeptic", player, self.player) > 0 then
					if self:isFriend(player) then good = good + 1.0 / hp
					else bad = bad + 1.0 / hp
					end
				end

				local has_slash = (self:originalHegemonyCardsNum("Slash", player, self.player) > 0)
				local can_slash = false
				if not can_slash then
					for _, p in sgs.qlist(self.room:getOtherPlayers(player)) do
						if player:distanceTo(p) <= player:getAttackRange() then can_slash = true break end
					end
				end
				if not has_slash or not can_slash then
					if self:isFriend(player) then good = good + math.max(self:originalHegemonyCardsNum("Peach", player, self.player), 1)
					else bad = bad + math.max(self:originalHegemonyCardsNum("Peach", player, self.player), 1)
					end
				end

				if self:originalHegemonyCardsNum("Jink", player, self.player) == 0 then
					local lost_value = 0
					if original_shown_skills(self,player, sgs.masochism_skill) then lost_value = player:getHp() / 2 end
					if self:isFriend(player) then bad = bad + (lost_value + 1) / hp
					else good = good + (lost_value + 1) / hp
					end
				end
			end ::package_continue_1:: end
			if good > bad and not target then
				self.xiongsuan_skill = "luanwu"
				target = friend
				break
			end
		end
	end
	if not target then
		local can_xiongsuan = false
		if (self.player:getHp() > 3 and hegemony_source_query(self,'getOverflow',self.player,false) < 2)
		or (self.player:getHp() > 2 and hegemony_source_query(self,'getOverflow',self.player,false) < -1)
		or (self.player:getHp() == 1 and self:getCardsNum("Analeptic") >= 1) then
			can_xiongsuan = true
		end
		local slash = r25_clone(self,"slash")
		if hegemony_source_query(self,'hasCrossbowEffect',self.player) and self.player:getHp() > 1 then
			for _, enemy in ipairs(self.enemies) do
				if known(heg_player(self,enemy).shown_one,"shown_one") then
					if self.player:canSlash(enemy,nil,true) and self:slashIsEffective(slash, enemy)
						and not (shown(self,enemy,"heg_kongcheng") and enemy:isKongcheng())
						and not (original_shown_skills(self,enemy, "nosfankui") and self.player:hasWeapon("Crossbow"))
						and self:originalHegemonyIsGoodTarget(enemy, self.enemies) and not self:slashProhibit(slash, enemy) then
							can_xiongsuan = true
					end
				end
			end
		end
		if self.player:getHp() > 1 and
			((self.player:hasSkill("heg_luanji") and self:getAoeValue(r25_clone(self,"archery_attack")) > 0)
			or (self.player:hasSkill("shuangxiong") and hegemony_source_query(self.player,'hasFlag',"shuangxiong"))) then
			can_xiongsuan = true
		end
		if self.player:hasSkills("heg_qianhuan|heg_jihun|heg_bushi|heg_chenglve") and self:getCardsNum("Peach") >= 1 then
			can_xiongsuan = true
		end
		if self.player:hasSkill("heg_congjian") then
			can_xiongsuan = false
		end
		if self.player:hasSkill("heg_yuanyu") then
			can_xiongsuan = true
		end
		if can_xiongsuan then
			self.xiongsuan_skill = "heg_xiongsuan"
			target = self.player
		end
	end
	if target then
		use.card = card
		if use.to then
			use.to:append(target)
			
		end
	end
end

ai_skill_choice.heg_xiongsuan = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end
    local data=request and self:getDecisionData(request) or nil

	return  ai_choice_result((self.xiongsuan_skill),options)
end

sgs.ai_card_intention.HXiongsuanCard = -40
sgs.ai_use_priority.HXiongsuanCard = 6.8

ai_fill_skill.heg_yigui = function(self,options,request)
    local inclusive=(options or {}).inclusive

	if not shown(self,self.player,"heg_yigui") then return end
	local huashens = r25_general_pile(self,self.player, "soul")
	if #huashens == 0 then return end

	local trickcards = {"alliance_feast","burning_camps","god_salvation","savage_assault","archery_attack",
	"befriend_attacking","ex_nihilo","duel","snatch","dismantlement","drowning",
	"iron_chain","await_exhausted","amazing_grace","fight_together","lure_tiger","imperial_order",
	"collateral","known_both","fire_attack","heg_threaten_emperor"}

	self.yigui_to = nil
	local soul_name
	local class_string
	local str = "@HYiguiCard=.&" .. ":"
	local yigui_kingdom = {["wei"] = {}, ["shu"] = {}, ["wu"] = {}, ["qun"] = {}, ["careerist"] = {}, ["double"] = {}}
	for _, name in ipairs(huashens) do
		local general = r25_general(self,name)
		if not general:isDoubleKingdoms() then
			table.insert(yigui_kingdom[general:getKingdom()],name)
		else
			table.insert(yigui_kingdom["double"],name)
		end
	end

	local weak_count, wounded_count = 0,0
	for _, p in ipairs(self.friends) do
		if self.player:isFriendWith(p) and not p:isRemoved() and hegemony_source_query(self,'isWeak',p) then
			weak_count = weak_count + 1
		end
		if self.player:isFriendWith(p) and not p:isRemoved() and p:isWounded() then
			wounded_count = wounded_count + 1
		end
	end
	if #yigui_kingdom[self:originalHegemonyOwnKingdom()] > 0 and not hegemony_source_query(self.player,'hasFlag',"Yigui_GodSalvation") then
		if (#yigui_kingdom[self:originalHegemonyOwnKingdom()] < 3 and (weak_count > 1 or wounded_count > 2))
		or (#yigui_kingdom[self:originalHegemonyOwnKingdom()] >=3 and wounded_count > 1) then
			soul_name = yigui_kingdom[self:originalHegemonyOwnKingdom()][1]
			class_string = "god_salvation"

			return r25_parse(self,str .. class_string .. "+" .. soul_name)
		end
	end

	local kingdoms = {wei = 0, shu = 0, wu = 0, qun = 0, careerist = 0}
	local kingdom_players = {wei = {}, shu = {}, wu = {}, qun = {}, careerist = {}}
	for _, p in sgs.qlist(self.room:getAlivePlayers()) do
		if not p:isRemoved() and known(heg_player(self,p).shown_one,"shown_one") then
			local p_kingdom = p:getKingdom()
			if p_kingdom == "god" then
				p_kingdom = "careerist"
			end
			kingdoms[p_kingdom] = kingdoms[p_kingdom] + (self:isFriend(p) and -1 or 1)
			table.insert(kingdom_players[p_kingdom], p)
		end
	end
	local max_friend_kingom
	local max_enemy_kingdom = "careerist"
	local f_num, e_num = 0,0
	for key, value in pairs(kingdoms) do
		
		if key and value > e_num then
			max_enemy_kingdom = key
			e_num = value
		end
		if key and self:originalHegemonyOwnKingdom() ~= key and value < f_num then
			max_friend_kingom = key
			f_num = value
		end
	end

	local function getYiguiTargetByKingdom(kingdom, key, inverse)
		kingdom = kingdom or "careerist"
		key = key or "hp"
		if #kingdom_players[kingdom] > 0 then
			self:sortInPlace(kingdom_players[kingdom], key, inverse)
			return kingdom_players[kingdom][1]
		end
		return nil
	end

	local function getYiguiAoeValue(AOE_name,kingdom,kingdom2)
		if not (AOE_name == "archery_attack" or AOE_name == "savage_assault") then
			return -1
		end
		kingdom = kingdom or "unknown"
		kingdom2 = kingdom2 or kingdom
		local clone_trick = r25_clone(self,AOE_name)
		if clone_trick:isKindOf("SavageAssault") then
			local heg_menghuo = original_find_shown(self,"heg_huoshou")
			if heg_menghuo and not self:isFriend(heg_menghuo) and heg_menghuo:hasSkill("heg_zhiman") then
				return 0
			end
		end
		local value = 0
		if kingdom == "unknown" then
			for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
				if not p:isRemoved() and not known(heg_player(self,p).shown_one,"shown_one") and self:aoeIsEffective(clone_trick, p, self.player) then
					if self:evaluateKingdom(p) == "unknown"then
						value = value + 0.5
					elseif string.find(self:evaluateKingdom(p), self:originalHegemonyOwnKingdom()) then
						value = value - 1
					else
						value = value + 1
					end
				end
			end
		else
			for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
				if not p:isRemoved() and known(heg_player(self,p).shown_one,"shown_one") and (p:getKingdom() == kingdom or p:getKingdom() == kingdom2)
				and self:aoeIsEffective(clone_trick, p, self.player) then
					value = value +  (kingdoms[p:getKingdom()] >= 0 and 1 or -1 )
				end
				if not p:isRemoved() and not known(heg_player(self,p).shown_one,"shown_one") and self:aoeIsEffective(clone_trick, p, self.player) then
					if self:evaluateKingdom(p) == "unknown"then
						value = value + 0.5
					elseif string.find(self:evaluateKingdom(p), self:originalHegemonyOwnKingdom()) then
						value = value - 1
					else
						value = value + 1
					end
				end
			end
		end
		return value
	end

	if #yigui_kingdom["double"] > 0 then
		for _, name in ipairs(yigui_kingdom["double"]) do
			local general = r25_general(self,name)
			local double_kingdoms = general:getKingdoms()
			if kingdoms[double_kingdoms[1]] >= 0 and kingdoms[double_kingdoms[2]] >= 0
			and kingdoms[double_kingdoms[1]] + kingdoms[double_kingdoms[2]] >= kingdoms[max_enemy_kingdom] then
				if not hegemony_source_query(self.player,'hasFlag',"Yigui_ArcheryAttack") then
					class_string = "archery_attack"
					if getYiguiAoeValue(class_string,double_kingdoms[1],double_kingdoms[2]) >0 then
						soul_name = name

						return r25_parse(self,str .. class_string .. "+" .. soul_name)
					end
				end
				if not hegemony_source_query(self.player,'hasFlag',"Yigui_SavageAssault") then
					class_string = "savage_assault"
					if getYiguiAoeValue(class_string,double_kingdoms[1],double_kingdoms[2]) >0 then
						soul_name = name

						return r25_parse(self,str .. class_string .. "+" .. soul_name)
					end
				end
			end
			if table.contains(double_kingdoms,self:originalHegemonyOwnKingdom()) then
				table.removeOne(double_kingdoms,self:originalHegemonyOwnKingdom())
				if not hegemony_source_query(self.player,'hasFlag',"Yigui_AllianceFeast") and
					((math.abs(kingdoms[double_kingdoms[1]]) >= self.player:getLostHp() and self.player:getLostHp() > 1)
					or (kingdoms[double_kingdoms[1]] < 0 and self.player:isWounded())) then
						local to = getYiguiTargetByKingdom(double_kingdoms[1], "handcard")
						if to then
							self.yigui_to = AIList.new{}
							self.yigui_to:append(to)
							soul_name = name
							class_string = "alliance_feast"

							return r25_parse(self,str .. class_string .. "+" .. soul_name)
						end
				end
			end
		end
	end
	if not hegemony_source_query(self.player,'hasFlag',"Yigui_BurningCamps") and #yigui_kingdom[max_enemy_kingdom] > 0 then
		local np = self.player:getNextAlive()
		if np:getKingdom() == max_enemy_kingdom and r25_formation(self,np):length() == kingdoms[max_enemy_kingdom] then
			local dummyuse = { isDummy = true, to = AIList.new{} }
			self:useCardBurningCamps(r25_clone(self,"burning_camps"), dummyuse)
			if dummyuse.card then
				soul_name = yigui_kingdom[max_enemy_kingdom][1]
				class_string = "burning_camps"

				return r25_parse(self,str .. class_string .. "+" .. soul_name)
			end
		end
	end
	if #yigui_kingdom[max_enemy_kingdom] > 0 and not hegemony_source_query(self.player,'hasFlag',"Yigui_ArcheryAttack") then
		class_string = "archery_attack"
		if getYiguiAoeValue(class_string,max_enemy_kingdom) >0 then
			soul_name = yigui_kingdom[max_enemy_kingdom][1]

			return r25_parse(self,str .. class_string .. "+" .. soul_name)
		end
	end
	if #yigui_kingdom[max_enemy_kingdom] > 0 and not hegemony_source_query(self.player,'hasFlag',"Yigui_SavageAssault") then
		class_string = "savage_assault"
		if getYiguiAoeValue(class_string,max_enemy_kingdom) >0 then
			soul_name = yigui_kingdom[max_enemy_kingdom][1]

			return r25_parse(self,str .. class_string .. "+" .. soul_name)
		end
	end
	if not hegemony_source_query(self.player,'hasFlag',"Yigui_BurningCamps") then
		local np = self.player:getNextAlive()
		if #yigui_kingdom[np:getKingdom()] > 0 then
			local can_burn = false
			local burn_weak = 0
			local players = r25_formation(self,np)
			for _, p in sgs.qlist(players) do
				if p:getHp() == 1 and self:trickIsEffective(r25_clone(self,"burning_camps"), p, self.player) then
					can_burn = true
					break
				end
				if hegemony_source_query(self,'isWeak',p) and self:trickIsEffective(r25_clone(self,"burning_camps"), p, self.player) then
					burn_weak = burn_weak + 1
				end
			end
			if burn_weak > 1 or burn_weak == #self.enemies then
				can_burn = true
			end
			local dummyuse = { isDummy = true, to = AIList.new{} }
			self:useCardBurningCamps(r25_clone(self,"burning_camps"), dummyuse)
			if dummyuse.card and can_burn then
				soul_name = yigui_kingdom[np:getKingdom()][1]
				class_string = "burning_camps"

				return r25_parse(self,str .. class_string .. "+" .. soul_name)
			end
		end
	end
	if hegemony_source_query(self.player,'hasFlag',"Yigui_ArcheryAttack") and hegemony_source_query(self.player,'hasFlag',"Yigui_SavageAssault") and not hegemony_source_query(self.player,'hasFlag',"Yigui_Duel") then
		local dummyuse = { isDummy = true, to = AIList.new{} }
		self:useCardDuel(r25_clone(self,"duel"), dummyuse)
		if not dummyuse.to:isEmpty() then
			local duel_t = dummyuse.to:first()
			if duel_t:getHp() == 1 and #yigui_kingdom[duel_t:getKingdom()] > 0 then
				soul_name = yigui_kingdom[duel_t:getKingdom()][1]
				class_string = "duel"
				self.yigui_to = dummyuse.to

				return r25_parse(self,str .. class_string .. "+" .. soul_name)
			end
		end
	end
	if not hegemony_source_query(self.player,'hasFlag',"Yigui_BefriendAttacking") then
		if max_friend_kingom and #yigui_kingdom[max_friend_kingom] > 0 and (self.player:getHandcardNum() < 3 or #yigui_kingdom[max_friend_kingom] > 1) then
			local to = getYiguiTargetByKingdom(max_friend_kingom, "handcard")
			if to then
				self.yigui_to = AIList.new{}
				self.yigui_to:append(to)
				soul_name = yigui_kingdom[max_friend_kingom][1]
				class_string = "befriend_attacking"

				return r25_parse(self,str .. class_string .. "+" .. soul_name)
			end
		end
		for key, value in pairs(kingdoms) do
			if #yigui_kingdom[key] > 1 and value > 0 and key ~= max_enemy_kingdom then
				local to = getYiguiTargetByKingdom(key, "handcard")
				if to then
					self.yigui_to = AIList.new{}
					self.yigui_to:append(to)
					soul_name = yigui_kingdom[key][1]
					class_string = "befriend_attacking"

					return r25_parse(self,str .. class_string .. "+" .. soul_name)
				end
			end
		end
		if #yigui_kingdom[max_enemy_kingdom] > kingdoms[max_enemy_kingdom] and #yigui_kingdom[max_enemy_kingdom] > 0 then
			local to = getYiguiTargetByKingdom(max_enemy_kingdom, "handcard")
			if to then
				self.yigui_to = AIList.new{}
				self.yigui_to:append(to)
				soul_name = yigui_kingdom[max_enemy_kingdom][1]
				class_string = "befriend_attacking"

				return r25_parse(self,str .. class_string .. "+" .. soul_name)
			end
		end
	end

	if soul_name and class_string then
		return r25_parse(self,str .. class_string .. "+" .. soul_name)
	end
end

ai_card_use.HYiguiCard = function(self,card,use)
	local userstring = card:getLegacyStringKey()
	userstring = (userstring:split(":"))[3]
	userstring = (userstring:split("+"))[1]

	if self.player:isCardLimited(r25_clone(self,userstring),sgs.Card_MethodUse) then
        return
    end
	use.card = card
	if use.to and self.yigui_to then
		use.to = self.yigui_to
		self.yigui_to = nil
	end
end

sgs.ai_use_priority.HYiguiCard = 2.8

ai_skill_invoke.heg_jihun=true
ai_skill_invoke.heg_jili=function(self,options,request)
    local data=request and self:getDecisionData(request) or nil
if not self:willShowForAttack()and not self:willShowForDefence()then return (false) or false  end;return (true) or false  end
function SmartAI:shamokeUseWeaponPriority(card)
	local class_name = card:getClassName()
	local v = self:getUsePriority(card)
	if self.player:hasSkill("heg_jili") and not self.player:isKongcheng()
	and card:isKindOf("Weapon") and not card:isKindOf("Crossbow") then
		local hcards = self.player:getHandcards()
		hcards = sgs.QList2Table(hcards)
		self:sortByUsePriority(hcards)
		local firstcard = hcards[1]
		if self:originalHegemonyOwnerFact('owner_card_used_times') + self:originalHegemonyOwnerFact('owner_card_responded_times') + 2 == sgs.weapon_range[class_name] + r25_fact(self,'owner_attack_range_correction')
		and v ~= self:getUsePriority(firstcard) then
			if not (firstcard:isKindOf("Weapon") and sgs.weapon_range[class_name] == sgs.weapon_range[firstcard:getClassName()]) then
				v = self:getUsePriority(firstcard) + 0.1

			end
		end
	end
	return v
end

sgs.ai_cardneed.heg_jili = sgs.ai_cardneed.weapon

ai_skill_invoke.heg_zhiman = function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

	local damage = r25_context(self,"zhiman_data","damage")
	local target = damage.to
	local can_get = self:findPlayerToDiscard("ej", false, sgs.Card_MethodGet, nil, true)
	if self:isFriend(target) and (table.contains(can_get, target) or not self:needToLoseHp(target, self.player)) then
		return (true) or false 
	end
	if not self:isFriend(target) and not self:damageIsEffective_(damage) then
		return (true) or false 
	end
	if not self:isFriend(target) and damage.damage > 1 and not target:hasArmorEffect("SilverLion") then
		return (false) or false 
	end
	if table.contains(can_get, target) and not hegemony_source_query(self,'isWeak',target) then
		return (true) or false 
	end
	if self:hasKnownSkill(sgs.masochism_skill,target) and self.player:canGet(target,"e")
	and self:needDamagedEffects(target, self.player) and not hegemony_source_query(self,'isWeak',target) then

		return (true) or false 
	end
	return (false) or false 
end

sgs.ai_choicemade_filter.skillInvoke.heg_zhiman = function(self, player, promptlist)
	local damage = r25_current_damage(self)
	if damage.from and damage.to then
		if promptlist[#promptlist] == "yes" then
			if not damage.to:hasEquip() and damage.to:getJudgingArea():isEmpty() then
				self:updateIntention(damage.from, damage.to, -40)
			end
		elseif self:canAttack(damage.to) then
			self:updateIntention(damage.from, damage.to, 30)
		end
	end
end

ai_skill_choice.heg_zhiman = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end


	return  ai_choice_result(("yes"),options)
end

ai_skill_choice["transform_zhiman"] = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end


	if r25_aoe_frame(self) then
		local use = r25_aoe_frame(self)
		local save_transform = false
		for _, p in sgs.qlist(use.to) do
			if self.player:isFriendWith(p) and self:playerGetRound(p) > self:playerGetRound(self.player) then
				local p_skills = r25_slot_skills(self,p, false)
				for _, skill in ipairs(p_skills) do
					if skill:getFrequency() == sgs.Skill_Limited and (skill:getLimitMark() ~= "" and hegemony_source_query(p,'getMark',skill:getLimitMark()) == 0) then
						save_transform = true
						break
					end
				end
				if r25_player_general(self,p, false):objectName():match("sujiang") then
					save_transform = true
				end
			end
			if save_transform then

				return  ai_choice_result(("no"),options)
			end
		end
	end
	local importantsklii = {"heg_xuanhuo", "heg_paoxiao", "tenyearkuanggu", "heg_tieqi", "heg_jizhi", "heg_shengxi",  "heg_jili", "heg_tongdu"}
	local skills = r25_slot_skills(self,self.player, false)
	for _, skill in ipairs(skills) do
		if table.contains(importantsklii, skill:objectName()) then
			return  ai_choice_result(("no"),options)
		end
		if skill:getFrequency() == sgs.Skill_Limited and not (skill:getLimitMark() ~= "" and hegemony_source_query(self.player,'getMark',skill:getLimitMark()) == 0) then
			return  ai_choice_result(("no"),options)
		end
	end
	if self.player:hasSkills("heg_paoxiao+tenyearwusheng") then
		return  ai_choice_result(("no"),options)
	end
	if self.player:hasSkill("heg_congcha") then
		local congcha_draw = true
		for _, p in sgs.qlist(self.room:getAlivePlayers()) do
			if not known(heg_player(self,p).shown_one,"shown_one") then
				congcha_draw = false
				break
			end
		end
		if congcha_draw then
			return  ai_choice_result(("no"),options)
		end
	end
	return  ai_choice_result(("yes"),options)

end

sgs.ai_choicemade_filter.cardChosen.heg_zhiman = function(self, player, promptlist)
	local intention = 10
	local id = promptlist[3]
	local card = r25_card(self,id)
	local target = self.room:findPlayerByObjectName(promptlist[5])
	if hegemony_source_query(self,'needToThrowArmor',target) and self.room:getCardPlace(id) == sgs.Player_PlaceEquip and card:isKindOf("Armor") then
		intention = -intention
	elseif self:doNotDiscard(target) then intention = -intention
	elseif self:hasKnownSkill(sgs.lose_equip_skill,target) and not target:getEquips():isEmpty() and
		self.room:getCardPlace(id) == sgs.Player_PlaceEquip and card:isKindOf("EquipCard") then
			intention = -intention
	elseif self.room:getCardPlace(id) == sgs.Player_PlaceJudge then
		intention = -intention
	end
	self:updateIntention(player, target, intention)
end

ai_fill_skill.heg_sanyao = function(self,options,request)
    local inclusive=(options or {}).inclusive

	if not self:willShowForAttack() then return end
	if self.player:getStrategyHasUsed("HSanyaoCard") then return end
	if self.player:isNude() then return end
	return r25_parse(self,"@HSanyaoCard=.&heg_sanyao")
end

ai_card_use.HSanyaoCard = function(self,card,use)
	local targets = AIList.new{}
	local maxhp = 0
    for _, p in sgs.qlist(self.room:getAlivePlayers()) do
		if maxhp < p:getHp() then maxhp = p:getHp() end
	end
    for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
		if p:getHp() == maxhp and not p:isRemoved() then
			targets:append(p)
		end
	end
	local target
	if hegemony_source_query(self.player,'getMark',"zhimantransformUsed") == 0 then
		for _, p in sgs.qlist(targets) do
			if self.player:isFriendWith(p) then
				if r25_player_general(self,p, false):objectName():match("sujiang") then
					target = p

					break
				end
				local skills = r25_slot_skills(self,p, false)
				for _, skill in ipairs(skills) do
					if skill:getFrequency() == sgs.Skill_Limited and (skill:getLimitMark() ~= "" and hegemony_source_query(p,'getMark',skill:getLimitMark()) == 0) then
						target = p
						break
					end
				end
				if target then

					break
				end
			end
		end
	end
	if not target then
		target = self:findPlayerToDiscard("ej", false, sgs.Card_MethodGet, targets)
	end
	if not target then
		for _, p in sgs.qlist(targets) do
			if self:isEnemy(p) and hegemony_source_query(self,'isWeak',p) then target = p break end
		end
	end
	if not target then
		for _, p in sgs.qlist(targets) do
			if not self:isFriend(p) and self:getDangerousCard(p) and self.player:canGet(p,self:getDangerousCard(p)) then
				target = p
				break
			end
		end
	end
	if not target then
		for _, p in sgs.qlist(targets) do
			if self:isEnemy(p) and not self:hasKnownSkill(sgs.masochism_skill,p) and hegemony_source_query(self,'getOverflow') > 0 then target = p break end
		end
	end

	if hegemony_source_query(self,'needToThrowArmor') then
		use.card = r25_parse(self,"@HSanyaoCard=" .. self.player:getArmor():getId() .. "&heg_sanyao")
		if targets:length() == 0 then use.card = nil return end
		if use.to then
			if target then
				use.to:append(target)
			else
				use.to:append(targets:first())
			end
			return
		end
	else
		if not target then use.card = nil return end
		local cards = sgs.QList2Table(self.player:getCards("he"))
		self:sortByUseValue(cards,true)

		local card_id
		for _, c in ipairs(cards) do
			if c:isKindOf("Lightning") and not self:isCard("Peach", c, self.player) and not self:willUseLightning(c) then
				card_id = c:getKnownEffectiveId()
				break
			end
		end

		if not card_id then
			for _, c in ipairs(cards) do
				if not self:isCard("Peach", c, self.player)
					and (c:isKindOf("AmazingGrace") or c:isKindOf("GodSalvation") and not self:willUseGodSalvation(c)) then
					card_id = c:getKnownEffectiveId()
					break
				end
			end
		end
		if not card_id then
			for _, c in ipairs(cards) do
				if (not self:isCard("Peach", c, self.player) or self:getCardsNum("Peach") > 1)
						and (not self:isCard("Jink", c, self.player) or self:getCardsNum("Jink") > 1 or hegemony_source_query(self,'isWeak'))
					or hegemony_source_query(self.player,'getMark',"GlobalBattleRoyalMode") > 0 then
					card_id = c:getKnownEffectiveId()
					break
				end
			end
		end
		if card_id then
			use.card = r25_parse(self,"@HSanyaoCard=" .. card_id .. "&heg_sanyao")
			if use.to then
				if use.to:isEmpty() then use.to:append(target) return end
			end
		end
	end
end

sgs.ai_skill_playerchosen.heg_xuanlue = function(self, targets)
	if not (self:willShowForAttack() or self:willShowForDefence()) then return nil end
	return self:findPlayerToDiscard()
end

sgs.ai_choicemade_filter.cardChosen.heg_xuanlue = function(self, player, promptlist)
	local intention = 10
	local id = promptlist[3]
	local card = r25_card(self,id)
	local target = self.room:findPlayerByObjectName(promptlist[5])
	if hegemony_source_query(self,'needToThrowArmor',target) and self.room:getCardPlace(id) == sgs.Player_PlaceEquip and card:isKindOf("Armor") then
		intention = -intention
	elseif self:doNotDiscard(target) then intention = -intention
	elseif self:hasKnownSkill(sgs.lose_equip_skill,target) and not target:getEquips():isEmpty() and
		self.room:getCardPlace(id) == sgs.Player_PlaceEquip and card:isKindOf("EquipCard") then
			intention = -intention
	elseif hegemony_source_query(self,'getOverflow',target) > 2 then intention = 0
	end
	self:updateIntention(player, target, intention)
end

