ai_skill_invoke.heg_haoshi_flamemap = ai_skill_invoke.haoshi

ai_skill_invoke.heg_shelie = function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

	if self.player:hasSkills("haoshi|heg_haoshi_flamemap") and self.player:getHandcardNum() < 2 then return (false) or false  end
	local extra = 0
	if self.player:hasTreasure("JadeSeal") then
		extra = extra+1
	end
	if self.player:hasSkill("heg_yingzi_zhouyu") then
		extra = extra+1
	end
	if self.player:hasSkill("heg_yingzi_sunce") then
		extra = extra+1
	end
	if self.player:hasSkill("heg_yingzi_flamemap") then
		extra = extra+1
	end
	if ai_skill_invoke.haoshi(self,{},nil) then
		if self.player:hasSkill("haoshi") then
			extra = extra+2
		end
		if self.player:hasSkill("heg_haoshi_flamemap") then
			extra = extra+2
		end
	end
	if self.player:hasSkill("heg_congcha") then
		local congcha_draw = true
		for _, p in sgs.qlist(self.room:getAlivePlayers()) do
			if not known(heg_player(self,p).shown_one,"shown_one") then
				congcha_draw = false
				break
			end
		end
		if congcha_draw then
		extra = extra+2
		end
	end
	if extra > 1 then return (false) or false  end
	return (true) or false 
end

sgs.ai_skill_movecards.heg_shelie = function(self, upcards, downcards, min_num, max_num)
	local upcards_copy, enableds, down = r25_copy(upcards), r25_copy(upcards), {}
	while #enableds ~= 0 do
		local card = self:askForAG(enableds, false, "heg_shelie")
		for _, card_id in ipairs(upcards_copy) do
		    if r25_card(self,card_id):getSuit() == r25_card(self,card):getSuit() then
			    table.removeOne(enableds, card_id)
			end
		end
		table.removeOne(upcards_copy, card)
		table.insert(down, card)
	end
	return upcards_copy, down
end

ai_fill_skill.heg_duoshi_flamemap = function(self,options,request)
    local inclusive=(options or {}).inclusive

	local DuoTime = 1
	if self.player:hasSkills("hongyan|heg_yingzi_zhouyu|heg_yingzi_sunce|heg_yingzi_flamemap|haoshi|heg_haoshi_flamemap") then
		DuoTime = 2
	end
	for _, player in ipairs(self.friends) do
		if original_shown_skills(self,player, "heg_xiaoji|heg_xuanlue|heg_diaodu") then
			DuoTime = 2
			break
		end
	end
	if self.player:hasSkills("heg_xiaoji|heg_xuanlue|heg_diaodu") then
		DuoTime = 2
		for _,card in sgs.qlist(self.player:getCards("he")) do
			if card:isKindOf("EquipCard") then
				DuoTime = DuoTime + 1
			end
		  end
	end
	if self.player:getHandcardNum() > 4 then
		DuoTime = DuoTime + 1
	end

	if self.player:usedTimes("ViewAsSkill_duoshi_flamemapCard") >= DuoTime or hegemony_source_query(self,'getOverflow') < 0 then return end
	if self.player:usedTimes("ViewAsSkill_duoshi_flamemapCard") >= 4 then return end

	if self.room:getTurnCount() <= 1 and #self.friends_noself == 0 and not hegemony_source_query(self,'isWeak') and hegemony_source_query(self,'getOverflow') <= 0 then return end
	local cards = self.player:getCards("h")
	for _, id in sgs.qlist(self.player:getHandPile()) do
		cards:prepend(r25_card(self,id))
	end
	cards = sgs.QList2Table(cards)
	self:sortByUseValue(cards, true)
	for _, card in ipairs(cards) do
		if self:getUseValue(card) >= 4.5 and card:isAvailable(self.player) then
			local dummy_use = {isDummy = true}
			if not card:targetFixed() then dummy_use.to = AIList.new{} end
			if card:isKindOf("EquipCard") then
				self:useEquipCard(card, dummy_use)
			else
				r25_use_by_class(self,card, dummy_use)
			end
			if dummy_use.card and self:getUsePriority(card) >= 2.8 then
				return
			end
		end
	end

	if (hegemony_source_query(self,'hasCrossbowEffect') or self:getCardsNum("Crossbow") > 0) and self:getCardsNum("Slash") > 0 then
		self:sortInPlace(self.enemies, "defense")
		for _, enemy in ipairs(self.enemies) do
			local inAttackRange = self.player:distanceTo(enemy) == 1 or self.player:distanceTo(enemy) == 2 and self:getCardsNum("OffensiveHorse") > 0 and not self.player:getOffensiveHorse()
			if inAttackRange  and self:originalHegemonyIsGoodTarget(enemy, self.enemies) then
				local slashes = self:getCards("Slash")
				local slash_count = 0
				for _, slash in ipairs(slashes) do
					if not self:slashProhibit(slash, enemy) and self:slashIsEffective(slash, enemy) then
						slash_count = slash_count + 1
					end
				end
				if slash_count >= enemy:getHp() then return end
			end
		end
	end

	local red_card
	if self.player:getHandcardNum() <= 1 then return end
	self:sortByUseValue(cards, true)

	for _, card in ipairs(cards) do
		if card:isRed() then
			local shouldUse = true
			if card:isKindOf("Slash") then
				local dummy_use = { isDummy = true }
				if self:getCardsNum("Slash") == 1 then
					self:useBasicCard(card, dummy_use)
					if dummy_use.card then shouldUse = false end
				end
			end

			if self:getUseValue(card) > known(SmartAIView.originalHegemonyPrintedValue(self,'ai_use_value','HAwaitExhausted'),'Original AwaitExhausted use value') and card:isKindOf("TrickCard") then
				local dummy_use = { isDummy = true }
				self:useTrickCard(card, dummy_use)
				if dummy_use.card then shouldUse = false end
			end

			if shouldUse and not card:isKindOf("Peach") then
				red_card = card
				break
			end

		end
	end

	if red_card then
		local card_id = red_card:getKnownEffectiveId()
		local card_str = string.format("await_exhausted:heg_duoshi_flamemap[%s:%d]=%d&heg_duoshi_flamemap",red_card:getSuitString(), red_card:getNumber(), red_card:getKnownEffectiveId())
		local await = r25_parse(self,card_str)
		assert(await)
		return await
	end
end

