function sgs.readGeneralValuefromtxt()
    local values = {}
    for key, value in pairs(sgs.general_value) do values[key] = value end
    return values
end

function sgs.readGeneralPairValuefromtxt()
    local values = {}
    for key, value in pairs(sgs.general_pair_value) do values[key] = value end
    return values
end

function SmartAI:getGeneralValue(player, position)
	local general
	if position then
		general = r25_player_general(self,player,true,true)
	else
		general = r25_player_general(self,player,false,true)
	end
	if general:objectName() == "anjiang" then
		if self.player:objectName() ~= player:objectName() then return 3 end
	else
		if position then
			general = r25_player_general(self,player, true)
		else
			general = r25_player_general(self,player, false)
		end
	end
	local ajust = 0
	for _, skill in sgs.qlist(general:getVisibleSkillList(true, position)) do
		if skill:getFrequency() == sgs.Skill_Limited and skill:getLimitMark() ~= "" and hegemony_source_query(player,'getMark',skill:getLimitMark()) == 0 then
            ajust = ajust - 1
		end
	end
	for name, value in pairs(sgs.general_value) do
		if general:objectName() == name then
			return value + ajust
		end
	end
	return 3
end

function SmartAI:needToTransform()
	local g1 = r25_player_general(self,self.player, true)
	local g2 = r25_player_general(self,self.player, false)
	local current_value = 0
	for name, value in pairs(sgs.general_pair_value) do
		if g1:objectName() .. "+" .. g2:objectName() == name or g2:objectName() .. "+" .. g1:objectName() == name then
			current_value = value
			break
		end
	end
	local oringin_g1 = 3
	local oringin_g2 = 3
	for name, value in pairs(sgs.general_value) do
		if g1:objectName() == name then oringin_g1 = value end
		if g2:objectName() == name then oringin_g2 = value end
	end
	if current_value == 0 then current_value = oringin_g1 + oringin_g2 end
	local g2_v = current_value - (oringin_g2 - self:getGeneralValue(self.player, false)) - oringin_g1
	return g2_v < 3
end

ai_skill_invoke.transform = function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

	return (self:needToTransform()) or false 
end

ai_skill_choice.transform = function(self,options,request)
    local generals
    if options and options.choices~=nil then generals=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then generals=''end


	generals = generals:split("+")
	for _, g2name in ipairs(generals) do
		if not sgs.general_value[g2name] then
			sgs.general_value[g2name] = 5
		end
	end

	local g1name = r25_player_general(self,self.player, true):objectName()
	local choice
	local pairvalue = 0
	local pairchoice
	for _, g2name in ipairs(generals) do

		for pairname, value in pairs(sgs.general_pair_value) do do 
			if (g1name .. "+" .. g2name == pairname or g2name .. "+" .. g1name == pairname) then
				if value < 10 and #generals > 0 then
					table.removeOne(generals, g2name)
				elseif pairname == "heg_xunyou+heg_xiahouyuan" or pairname == "heg_lvfan+heg_sunjian"
				or pairname == "heg_masu+heg_menghuo" or pairname == "heg_masu+heg_zhurong" then
					goto package_continue_2
				elseif value > pairvalue  then

					pairvalue = value
					pairchoice = g2name
				end
			end
		end ::package_continue_2:: end
	end
	local singlevalue = 0
	local singlechoice
	for _, g2name in ipairs(generals) do
		if hegemony_source_query(self,'isWeak') and (g2name == "heg_pangtong" or g2name == "heg_xushu" or g2name == "heg_zhoutai" or g2name == "heg_sunce" or g2name == "heg_lukang") then
			if sgs.general_value[g2name] and sgs.general_value[g2name] + 2 > singlevalue then
				singlevalue = sgs.general_value[g2name] + 2
				singlechoice = g2name
			end
		end
		if sgs.general_value[g2name] and sgs.general_value[g2name] > singlevalue then
			singlevalue = sgs.general_value[g2name]
			singlechoice = g2name
		end
	end
	if pairchoice and sgs.general_value[g1name] and sgs.general_value[g1name] + singlevalue + 5 <= pairvalue then
		choice = pairchoice
	else
		choice = singlechoice
	end
	if choice then

		return  ai_choice_result((choice),options)
	end

	return  ai_choice_result((generals[math.random(1,#generals)]),options)
end

ai_card_use.HZhihengLPCard = function(self,card,use,request)
    local selected=r25_zhiheng_costs(self,card)
    if not selected then return end
    local ids={};local treasure=self.player:getTreasure()
    for _,id in ipairs(selected)do
        if(not treasure or id~=treasure:getKnownEffectiveId())and#ids<self.player:getMaxHp()then ids[#ids+1]=id end
    end
    if#ids>0 then use.card=self:inheritLegacyCardIdentity(self:evaluateTurnSkillCard('heg_LuminousPearl','HZhihengLPCard',ids,request),card)end
end
sgs.ai_use_priority.HZhihengLPCard = sgs.ai_use_priority.heg_zhiheng or 2.61


local selfarg={ai_card_use=1,ai_cardneed=3,ai_skill_pindian=2,ai_view_as=4}
local function wrap(body,old,key,reg)
    local index=selfarg[reg]or 1
    return function(...)
        local args=table.pack(...);local self=reg=='ai_view_as'and args[2]and args[2]._room and args[2]._room._ai or args[index]
        if not original_enabled(self)then if type(old)=='function'then return old(...)elseif old~=nil then return old end;ai_unsupported('ordinary provider missing',key)end
        r25_restore(self)
        local previous=r25_active
        r25_active={self=self,request=(reg=='ai_fill_skill'and args[3]or reg=='ai_card_use'and args[4]or reg=='ai_skill_use'and args[3]or reg=='ai_skill_choice'and args[3]or nil)}
        local result=table.pack(pcall(body,...));r25_active=previous;r25_save(self)
        if not result[1]then error(result[2],0)end
        if reg=='ai_skill_use'then result[2]=r25_response(self,key,result[2],args[3])end
        return table.unpack(result,2,result.n)
    end
end
for _,reg in ipairs(regs)do
    if reg~='ai_skill_use'and reg~='ai_card_use'and reg~='ai_skill_invoke'and reg~='ai_fill_skill'and reg~='ai_skill_choice'then base[reg]=base[reg]or{}end
    for key,body in pairs(local_registry(reg))do
        if reg=='ai_choicemade_filter'and type(body)=='table'then
            base_registry(reg)[key]=base_registry(reg)[key]or{}
            for name,cb in pairs(body)do if cb~=base_registry(reg)[key][name]then base_registry(reg)[key][name]=wrap(cb,base_registry(reg)[key][name],name,reg)end end
        elseif body~=base_registry(reg)[key]then
            if type(body)=='function'then base_registry(reg)[key]=wrap(body,base_registry(reg)[key],key,reg)else base_registry(reg)[key]=body end
        end
    end
end
for name,body in pairs(SmartAI)do SmartAIView[name]=wrap(body,SmartAIView[name],name,'SmartAI')end
if sgs.general_value~=nil then base.general_value=sgs.general_value end
if sgs.general_pair_value~=nil then base.general_pair_value=sgs.general_pair_value end
if sgs.readGeneralValuefromtxt~=nil then base.readGeneralValuefromtxt=sgs.readGeneralValuefromtxt end
if sgs.readGeneralPairValuefromtxt~=nil then base.readGeneralPairValuefromtxt=sgs.readGeneralPairValuefromtxt end
if sgs.duoshi_flamemap_suit_value~=nil then base.duoshi_flamemap_suit_value=sgs.duoshi_flamemap_suit_value end
base.xuanlue_keep_value=sgs.xuanlue_keep_value
end
