local base_fill=ai_fill_skill
local ai_fill_skill={}
local base_invoke=ai_skill_invoke
local ai_skill_invoke={}
local base_card_use=ai_card_use
local ai_card_use={}
local base_use=ai_skill_use
local ai_skill_use={}
local base=sgs
local SmartAI={}
local regs={'ai_card_intention','ai_cardneed','ai_fill_skill','ai_need_damaged','ai_skill_cardask','ai_skill_choice','ai_skill_discard','ai_skill_exchange','ai_skill_invoke','ai_skill_playerchosen','ai_skill_use','ai_card_use','ai_slash_prohibit','ai_suit_priority','ai_use_priority','ai_use_value','ai_view_as'}
local sgs=setmetatable({},{__index=base})
-- Preserve loader-local provider selection while publishing native use callbacks.
local function base_registry(reg)return reg=='ai_skill_choice'and base_choice or reg=='ai_fill_skill'and base_fill or reg=='ai_skill_invoke'and base_invoke or reg=='ai_skill_use'and base_use or reg=='ai_card_use'and base_card_use or base[reg]end
local function local_registry(reg)return reg=='ai_skill_choice'and ai_skill_choice or reg=='ai_fill_skill'and ai_fill_skill or reg=='ai_skill_invoke'and ai_skill_invoke or reg=='ai_skill_use'and ai_skill_use or reg=='ai_card_use'and ai_card_use or sgs[reg]end
for _,reg in ipairs(regs)do if reg~='ai_skill_use'and reg~='ai_card_use'and reg~='ai_skill_invoke'and reg~='ai_fill_skill'and reg~='ai_skill_choice'then sgs[reg]={}end;for k,v in pairs(base_registry(reg)or{})do if reg=='ai_choicemade_filter'and type(v)=='table'then local c={};for a,b in pairs(v)do c[a]=b end;local_registry(reg)[k]=c else local_registry(reg)[k]=v end end end
for _,reg in ipairs(regs)do setmetatable(local_registry(reg),{__index=function(_,k)return base_registry(reg)and base_registry(reg)[k]end})end



ai_skill_use["@@heg_zhengbi"] = function(self, prompt, request)
  if self.player:isKongcheng() then
    return "."
  end
  for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
		if not self:isFriend(p) and not known(heg_player(self,p).shown_one,"shown_one") then
			if self:getCardsNum("Slash") > 1 and (p:getHp() < 3 or self:getCardsNum("HHalberd") > 0) then
        return "@HZhengbiCard=".. "->" .. p:objectName()
      end
		end
	end
  local handcards = self.player:getCards("h")
	handcards = sgs.QList2Table(handcards)
	self:sortByUseValue(handcards,true)
	local card
  local visibleflag
  for _, c in ipairs(handcards) do
    if c:getTypeId() == sgs.Card_TypeBasic then
      card = c
      break
    end
  end
  if not card then
    return "."
  end
  if card:isKindOf("Peach") then
    if self:getCardsNum("Peach") <= self.player:getLostHp()  then
      return "."
    end
    self:sortInPlace(self.friends_noself, "hp")
    for _, friend in ipairs(self.friends_noself) do
      if friend:getCardCount(true) > 1 and (friend:isWounded() or hegemony_source_query(self,'getOverflow') > 0) and known(heg_player(self,friend).shown_one,"shown_one") then
        visibleflag = string.format("%s_%s_%s", "visible", self.player:objectName(), friend:objectName())
        if not hegemony_source_query(card,'hasFlag',"visible") then r25_observe_given_card(self,card,nil,visibleflag) end
        return "@HZhengbiCard=" .. card:getKnownEffectiveId() .. "->" .. friend:objectName()
      end
    end
    return "."
  end
	self:sortInPlace(self.enemies, "handcard")
  for _, target in ipairs(self.enemies) do
    if not target:isKongcheng() and (target:getHandcardNum() < 3 or hegemony_source_query(self,'isWeak',target)) and known(heg_player(self,target).shown_one,"shown_one") then
      if not (card:isKindOf("Analeptic") and target:hasEquip() and hegemony_source_query(self,'isWeak',target)) then
        visibleflag = string.format("%s_%s_%s", "visible", self.player:objectName(), target:objectName())
        if not hegemony_source_query(card,'hasFlag',"visible") then r25_observe_given_card(self,card,nil,visibleflag) end
        return "@HZhengbiCard=" .. card:getKnownEffectiveId() .. "->" .. target:objectName()
      end
    end
  end
  return "."
end

sgs.ai_skill_cardask["@heg_zhengbi-give"] = function(self, data, pattern, target, target2)
  if not target or target:isDead() then return "." end

  local allcards = self.player:getCards("he")
	allcards = sgs.QList2Table(allcards)
	self:sortByKeepValue(allcards)
  local visibleflag = string.format("%s_%s_%s", "visible", self.player:objectName(), target:objectName())
  if #allcards == 1 then
    if not allcards[1]:hasFlag("visible") then r25_observe_given_card(self,allcards[1],nil,visibleflag) end
    return "$" .. allcards[1]:getEffectiveId()
  end
  if allcards[1]:getTypeId() ~= sgs.Card_TypeBasic then
    if not allcards[1]:hasFlag("visible") then r25_observe_given_card(self,allcards[1],nil,visibleflag) end
    return "$" .. allcards[1]:getEffectiveId()
  elseif allcards[2]:getTypeId() ~= sgs.Card_TypeBasic then
    if not allcards[2]:hasFlag("visible") then r25_observe_given_card(self,allcards[2],nil,visibleflag) end
    return "$" .. allcards[2]:getEffectiveId()
  else
    local give_cards = {}
    table.insert(give_cards, allcards[1]:getId())
    table.insert(give_cards, allcards[2]:getId())
    if not allcards[1]:hasFlag("visible") then r25_observe_given_card(self,allcards[1],nil,visibleflag) end
    if not allcards[2]:hasFlag("visible") then r25_observe_given_card(self,allcards[2],nil,visibleflag) end
    return "$" .. table.concat(give_cards, "+")
  end
end

