local function getSlashtarget(self)
  local max_range = 0
  local horse_range = 0
  local current_range = self.player:getAttackRange()
  for _,card in sgs.qlist(self.player:getCards("he")) do
    if card:isKindOf("Weapon") and max_range < sgs.weapon_range[card:getClassName()] then
      max_range = sgs.weapon_range[card:getClassName()]
    end
  end
  if self:getCardsNum("OffensiveHorse") > 0 and not self.player:getOffensiveHorse() then
    horse_range = 1
  end
  
  local range_fix = -horse_range
  if self:getCardsNum("Slash") == 0 then

    return nil end
	local slashes = self:getCards("Slash")
	self:sortByUseValue(slashes)
	self:sortInPlace(self.enemies, "defenseSlash")
	for _, slash in ipairs(slashes) do
		for _, enemy in ipairs(self.enemies) do
			if self.player:canSlash(enemy,slash,true) and not self:slashProhibit(slash, enemy)
				and self:slashIsEffective(slash, enemy) and self:originalHegemonyIsGoodTarget(enemy, self.enemies)
				and not (hegemony_source_query(self.player,'hasFlag',"slashTargetFix") and not hegemony_source_query(enemy,'hasFlag',"SlashAssignee")) then
				return enemy
			end
		end
	end
  self.need_liegong_distance = false
  local heg_liubei = self.room:getLord(self:originalHegemonyOwnKingdom())
  if heg_liubei and heg_liubei:hasLordSkill("heg_shouyue") then
    local can_chooseliegong  = true
    for _, p in sgs.qlist(self.room:getAlivePlayers()) do
      if p:hasSkill("heg_liegong") then
        can_chooseliegong = false
      end
    end
    if can_chooseliegong then
      for _, slash in ipairs(slashes) do
        for _, enemy_1 in ipairs(self.enemies) do
          if self.player:canSlash(enemy_1,slash,true,-1) and not self:slashProhibit(slash, enemy_1)
            and self:slashIsEffective(slash, enemy_1) and self:originalHegemonyIsGoodTarget(enemy_1, self.enemies)
            and not (hegemony_source_query(self.player,'hasFlag',"slashTargetFix") and not hegemony_source_query(enemy_1,'hasFlag',"SlashAssignee")) then
              self.need_liegong_distance = true
            return enemy_1
          end
        end
      end
    end
  end

  return nil
end

local function shouldUseXuanhuo(self)
  local xuanhuoskill = {"tenyearwusheng", "heg_paoxiao", "heg_longdan", "heg_tieqi", "heg_liegong", "tenyearkuanggu"}
  for _, p in sgs.qlist(self.room:getAlivePlayers()) do
    for _, skill in ipairs(xuanhuoskill) do
      if shown(self,p,skill) then
        table.removeOne(xuanhuoskill,skill)
      end
    end
  end
  for _, skill in ipairs(xuanhuoskill) do
    if self.player:hasSkill(skill) then
      table.removeOne(xuanhuoskill,skill)
    end
  end
  if #xuanhuoskill == 0 then
    return false
  end
  local xuanhuochoices = table.concat(xuanhuoskill,"+")
  local choice = ai_skill_choice.heg_xuanhuo(self,{reason='heg_xuanhuo',choices=xuanhuoskill,inquiry_scope='original_internal'},nil)

  if choice ~= "heg_paoxiao" and not self:slashIsAvailable() and hegemony_source_query(self,'getOverflow') < 1 then
    return false
  end

  if self:getCardsNum("Slash") == 0 then
    if (choice == "tenyearwusheng" or choice == "heg_longdan") and hegemony_source_query(self,'getOverflow') > 1 then
      self.need_xuanhuo_slash = true
      return true
    else

      return false
    end
  end

  if self:getCardsNum("Slash") == 1 and (choice == "tenyearwusheng" or choice == "heg_longdan") then

    return false
  end

  self.need_kuanggu_AOE = false

  local target = getSlashtarget(self)
  if not self.player:hasSkill("heg_liegong") and table.contains(xuanhuoskill,"heg_liegong") and self.need_liegong_distance then
    local heg_liubei = self.room:getLord(self:originalHegemonyOwnKingdom())
    if heg_liubei and heg_liubei:hasLordSkill("heg_shouyue") then
      self.player:speak("需要眩惑君刘备烈弓距离")

      return true
    else
      self.need_liegong_distance = false
    end
  end

  if not target then

    return false
  end
  assert(target)

  if self.player:hasSkills("heg_tieqi|heg_liegong|heg_qianxi")
  and (choice == "heg_liegong" or (choice == "heg_tieqi" and not shown(self,target,"heg_tianxiang"))) then
    return false
  end

  if hegemony_source_query(self.player,'getMark',"@strategy") >= 1 or self.player:getHandcardNum() > 4
   or (self.player:getHandcardNum() > 3 and self.player:hasEquip()) then

    return true
  end
  return false
end

