ai_skill_choice.heg_xuanhuo = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end

  choices = choices:split("+")
  local xuanhuoskill = {"tenyearwusheng", "heg_paoxiao", "heg_longdan", "heg_tieqi", "heg_liegong", "tenyearkuanggu"}
  local has_wusheng = self.player:hasSkills("tenyearwusheng|heg_wusheng_xh")
  local has_paoxiao = self.player:hasSkills("heg_paoxiao|heg_paoxiao_xh")
  local has_longdan = self.player:hasSkills("heg_longdan|heg_longdan_xh")
  local has_tieqi = self.player:hasSkills("heg_tieqi|heg_tieqi_xh")
  local has_liegong = self.player:hasSkills("heg_liegong|heg_liegong_xh")
  local has_kuanggu = self.player:hasSkills("tenyearkuanggu|heg_kuanggu_xh")
  local has_qianxi = self.player:hasSkill("heg_qianxi")
  local has_Crossbow = self:getCardsNum("Crossbow") > 0
  local has_baolie = self.player:hasSkill("heg_baolie") and self.player:getHp() < 3

  local enough_pxslash = false
  if self:getCardsNum("Slash") > 0 then
    local yongjue_slash = 0
    if hegemony_source_query(self.player,'getMark',"GlobalPlayCardUsedTimes") == 0 then
      for _, p in ipairs(self.friends) do
        if shown(self,p,"heg_yongjue") and self.player:isFriendWith(p) then
          yongjue_slash = 1
          break
        end
      end
    end
    if yongjue_slash + self.player:getSlashCount() + self:getCardsNum("Slash") >= 2 then
      enough_pxslash = true
    end
  end

  local can_paoxiao = false
  local can_wusheng = false
  local need_tieqi = false
  local can_tieqi = false
  local can_liegong = false
  local can_kuanggu = false
  local lord_longdan = false
  local can_longdan = false

  if self.need_liegong_distance then
    self.need_liegong_distance = nil
    return  ai_choice_result(("heg_liegong"),options)
  end
  if self.need_kuanggu_AOE then
    self.need_kuanggu_AOE = nil
    return  ai_choice_result(("tenyearkuanggu"),options)
  end

  if not has_longdan and table.contains(choices,"heg_longdan") and self:getCardsNum("Jink") >= 1 then

    can_longdan = true
  end

  local target = getSlashtarget(self)
  if not target then

    goto Pass_target
  end

  if not has_Crossbow and not has_paoxiao and not has_baolie and table.contains(choices,"heg_paoxiao") and enough_pxslash then

    can_paoxiao = true
  end
  if not has_wusheng and table.contains(choices,"tenyearwusheng") then

    can_wusheng = true
  end
  if not has_tieqi and table.contains(choices,"heg_tieqi") then
    local skills_name = (sgs.masochism_skill .. "|" .. sgs.save_skill .. "|" .. sgs.defense_skill .. "|" .. sgs.wizard_skill):split("|")
	  for _, skill_name in ipairs(skills_name) do
		  local skill = r25_skill(self,skill_name)
		  if shown(self,target,skill_name) and target:ownSkill(skill_name) and skill and skill:getFrequency() ~= sgs.Skill_Compulsory then

        need_tieqi = true
        break
      end
	  end
  end
  if not has_tieqi and table.contains(choices,"heg_tieqi") then

    can_tieqi = true
  end
  if not has_liegong and table.contains(choices,"heg_liegong") and target:getHp() >= self.player:getHp() then

    can_liegong = true
  end
  if not has_kuanggu and table.contains(choices,"tenyearkuanggu") and (original_shown_skills(self,self.player, "mashu_machao|mashu_madai") or self.player:distanceTo(target) < 2
  or (self.player:distanceTo(target) == 2 and self:getCardsNum("OffensiveHorse") > 0 and not self.player:getOffensiveHorse())) then

    can_kuanggu = true
  end
  if not has_longdan and table.contains(choices,"heg_longdan") and self:getCardsNum("Jink") >= 1 then
    local heg_liubei = self.room:getLord(self:originalHegemonyOwnKingdom())
    if heg_liubei and heg_liubei:hasLordSkill("heg_shouyue") then

      lord_longdan = true
    end
  end

  if self.need_xuanhuo_slash then
    self.need_xuanhuo_slash = nil
    if lord_longdan or can_longdan then
      return  ai_choice_result(("heg_longdan"),options)
    end
    if can_wusheng then
      return  ai_choice_result(("tenyearwusheng"),options)
    end
  end

  if has_kuanggu and (has_tieqi or has_liegong or has_qianxi) then
    if has_Crossbow then
      if can_wusheng then
        return  ai_choice_result(("tenyearwusheng"),options)
      elseif can_longdan then
        return  ai_choice_result(("heg_longdan"),options)
      end
    elseif can_paoxiao then
      return  ai_choice_result(("heg_paoxiao"),options)
    end
  end
  if (has_wusheng or has_longdan) and (has_paoxiao or has_Crossbow or has_baolie) then
    if can_kuanggu then
      return  ai_choice_result(("tenyearkuanggu"),options)
    elseif need_tieqi then
      return  ai_choice_result(("heg_tieqi"),options)
    elseif can_liegong then
      return  ai_choice_result(("heg_liegong"),options)
    end
  end
  if has_kuanggu and (has_paoxiao or has_baolie) then
    if can_wusheng then
      return  ai_choice_result(("tenyearwusheng"),options)
    elseif lord_longdan then
      return  ai_choice_result(("heg_longdan"),options)
    elseif need_tieqi then
      return  ai_choice_result(("heg_tieqi"),options)
    elseif can_liegong then
      return  ai_choice_result(("heg_liegong"),options)
    end
  end
  if (has_paoxiao or has_Crossbow or has_baolie) and (has_tieqi or has_liegong or has_qianxi) then
    if can_kuanggu then
      return  ai_choice_result(("tenyearkuanggu"),options)
    elseif can_wusheng then
      return  ai_choice_result(("tenyearwusheng"),options)
    elseif can_longdan then
      return  ai_choice_result(("heg_longdan"),options)
    end
  end
  if (has_wusheng or has_longdan) and (has_tieqi or has_liegong or has_qianxi) then
    if has_Crossbow and can_kuanggu then
      return  ai_choice_result(("tenyearkuanggu"),options)
    elseif can_paoxiao then
      return  ai_choice_result(("heg_paoxiao"),options)
    elseif can_kuanggu then
      return  ai_choice_result(("tenyearkuanggu"),options)
    end
  end
  if (has_wusheng or has_longdan) and has_kuanggu then
    if has_Crossbow and need_tieqi then
      return  ai_choice_result(("heg_tieqi"),options)
    elseif has_Crossbow and can_liegong then
      return  ai_choice_result(("heg_liegong"),options)
    elseif has_Crossbow and can_tieqi then
      return  ai_choice_result(("heg_tieqi"),options)
    elseif can_paoxiao then
      return  ai_choice_result(("heg_paoxiao"),options)
    elseif need_tieqi then
      return  ai_choice_result(("heg_tieqi"),options)
    elseif can_liegong then
      return  ai_choice_result(("heg_liegong"),options)
    end
  end

  if (has_tieqi or has_liegong or has_qianxi) then
    if has_Crossbow and can_kuanggu then
      return  ai_choice_result(("tenyearkuanggu"),options)
    elseif can_kuanggu and self.player:getHp() <=2 then
      return  ai_choice_result(("tenyearkuanggu"),options)
    elseif can_paoxiao then
        return  ai_choice_result(("heg_paoxiao"),options)
    elseif shown(self,target,"heg_tianxiang") and need_tieqi then
        return  ai_choice_result(("heg_tieqi"),options)
    elseif can_kuanggu then
        return  ai_choice_result(("tenyearkuanggu"),options)
    end
  end
  if(has_paoxiao or has_Crossbow or has_baolie) then
    if enough_pxslash then
      if can_kuanggu then
        return  ai_choice_result(("tenyearkuanggu"),options)
      elseif need_tieqi then
        return  ai_choice_result(("heg_tieqi"),options)
      elseif can_liegong then
        return  ai_choice_result(("heg_liegong"),options)
      elseif can_tieqi then
        return  ai_choice_result(("heg_tieqi"),options)
      end
    elseif can_wusheng then
      return  ai_choice_result(("tenyearwusheng"),options)
    elseif can_longdan then
      return  ai_choice_result(("heg_longdan"),options)
    end
  end
  if (has_wusheng or has_longdan) then
    if has_Crossbow and can_kuanggu then
      return  ai_choice_result(("tenyearkuanggu"),options)
    elseif can_paoxiao then
      return  ai_choice_result(("heg_paoxiao"),options)
    end
  end
  if has_kuanggu then
    if has_Crossbow and (self.player:distanceTo(target) < 2
    or (self.player:distanceTo(target) == 2 and self:getCardsNum("OffensiveHorse") > 0 and not self.player:getOffensiveHorse())) then
      if can_wusheng then
        return  ai_choice_result(("tenyearwusheng"),options)
      elseif lord_longdan then
        return  ai_choice_result(("heg_longdan"),options)
      end
    elseif can_paoxiao then
      return  ai_choice_result(("heg_paoxiao"),options)
    elseif self.player:getHp() <=2 then
      if need_tieqi then
        return  ai_choice_result(("heg_tieqi"),options)
      elseif can_liegong then
        return  ai_choice_result(("heg_liegong"),options)
      elseif can_tieqi then
        return  ai_choice_result(("heg_tieqi"),options)
      end
    end
  end

  :: Pass_target ::
  if can_paoxiao and not (has_baolie or has_Crossbow) then
    return  ai_choice_result(("heg_paoxiao"),options)
  end
  if can_kuanggu and ((has_Crossbow and enough_pxslash) or (self.player:getHp() < 2 and self:originalHegemonyGetDefenseSlash(target) <= 2)) then
    return  ai_choice_result(("tenyearkuanggu"),options)
  end
  if need_tieqi then
    return  ai_choice_result(("heg_tieqi"),options)
  end
  if can_liegong then
    return  ai_choice_result(("heg_liegong"),options)
  end
  if can_tieqi then
    return  ai_choice_result(("heg_tieqi"),options)
  end
  if lord_longdan then
    return  ai_choice_result(("heg_longdan"),options)
  end
  if can_kuanggu then
    return  ai_choice_result(("tenyearkuanggu"),options)
  end
  if can_wusheng then
    return  ai_choice_result(("tenyearwusheng"),options)
  end
  if can_longdan then
    return  ai_choice_result(("heg_longdan"),options)
  end

  return  ai_choice_result((choices[#choices]),options)
end

sgs.ai_view_as.heg_wusheng_xh = function(card, player, card_place)
	local suit = card:getSuitString()
	local number = card:getNumberString()
	local card_id = card:getKnownEffectiveId()
	if (card_place ~= sgs.Player_PlaceSpecial or player:getHandPile():contains(card_id)) and (player:getLord() and player:getLord():hasShownSkill("heg_shouyue") or card:isRed()) and not card:isKindOf("Peach") and not hegemony_source_query(card,'hasFlag',"using") then
		return ("slash:heg_wusheng_xh[%s:%s]=%d&heg_wusheng_xh"):format(suit, number, card_id)
	end
end

ai_fill_skill.heg_wusheng_xh = function(self,options,request)
    local inclusive=(options or {}).inclusive


	self:sortInPlace(self.enemies, "defense")
	local useAll = false
	for _, enemy in ipairs(self.enemies) do
		if enemy:getHp() == 1 and not enemy:hasArmorEffect("EightDiagram") and self.player:distanceTo(enemy) <= self.player:getAttackRange() and hegemony_source_query(self,'isWeak',enemy)
			and self:originalHegemonyCardsNum("Jink", enemy, self.player) + self:originalHegemonyCardsNum("Peach", enemy, self.player) + self:originalHegemonyCardsNum("Analeptic", enemy, self.player) == 0 then
			useAll = true
			break
		end
	end

	local disCrossbow = false
	if self:getCardsNum("Slash") < 2 or self.player:hasSkill("heg_paoxiao|heg_paoxiao_xh") or (self.player:hasSkill("heg_baolie") and self.player:getHp() < 3) then disCrossbow = true end

	local hecards = self.player:getCards("he")
	for _, id in sgs.qlist(self.player:getHandPile()) do
		hecards:prepend(r25_card(self,id))
	end
	local cards = {}
	for _, card in sgs.qlist(hecards) do
		if (self.player:getLord() and self.player:getLord():hasShownSkill("heg_shouyue") or card:isRed())
      and (not card:isKindOf("Slash") or card:isKindOf("NatureSlash"))
			and ((not self:isCard("Peach", card, self.player) and not self:isCard("ExNihilo", card, self.player)) or useAll)
      and not self:isCard("HBefriendAttacking", card, self.player) and not self:isCard("HAllianceFeast", card, self.player)
			and (not self:isCard("Crossbow", card, self.player) or disCrossbow ) then
			local suit = card:getSuitString()
			local number = card:getNumberString()
			local card_id = card:getKnownEffectiveId()
			local card_str = ("slash:heg_wusheng_xh[%s:%s]=%d&heg_wusheng_xh"):format(suit, number, card_id)
			local slash = r25_parse(self,card_str)
			assert(slash)
			if self:slashIsAvailable(self.player,slash) then
				table.insert(cards, slash)
			end
		end
	end

	if #cards == 0 then return end

	self:sortByUsePriority(cards)
	return cards[1]
end

sgs.ai_suit_priority.heg_wusheng_xh = "club|spade|heart|diamond"

ai_skill_invoke.heg_paoxiao_xh = true

ai_fill_skill.heg_longdan_xh = function(self,options,request)
    local inclusive=(options or {}).inclusive

	local cards = sgs.QList2Table(self.player:getHandcards())
	for _, id in sgs.qlist(self.player:getHandPile()) do
		table.insert(cards, r25_card(self,id))
	end
	local jink_card

	self:sortByUseValue(cards,true)

	for _,card in ipairs(cards)  do
		if card:isKindOf("Jink") then
			jink_card = card
			break
		end
	end

	if not jink_card then return nil end
	local suit = jink_card:getSuitString()
	local number = jink_card:getNumberString()
	local card_id = jink_card:getKnownEffectiveId()
	local card_str = ("slash:heg_longdan_xh[%s:%s]=%d&heg_longdan_xh"):format(suit, number, card_id)
	local slash = r25_parse(self,card_str)
	assert(slash)

	return slash
end

sgs.ai_view_as.heg_longdan_xh = function(card, player, card_place)
	local suit = card:getSuitString()
	local number = card:getNumberString()
	local card_id = card:getKnownEffectiveId()
	if card_place == sgs.Player_PlaceHand or player:getHandPile():contains(card_id) then
		if card:isKindOf("Jink") then
			return ("slash:heg_longdan_xh[%s:%s]=%d&heg_longdan_xh"):format(suit, number, card_id)
		elseif card:isKindOf("Slash") then
			return ("jink:heg_longdan_xh[%s:%s]=%d&heg_longdan_xh"):format(suit, number, card_id)
		end
	end
end

