ai_card_use.HGanluCard = function(self,card,use)
	local lost_hp = self.player:getLostHp()
	local target, min_friend, max_enemy

	local compare_func = function(a, b)
		return a:getEquips():length() > b:getEquips():length()
	end
	table.sort(self.enemies, compare_func)
	table.sort(self.friends, compare_func)

	self.friends = sgs.reverse(self.friends)

	for _, friend in ipairs(self.friends) do
		for _, enemy in ipairs(self.enemies) do
			if not original_shown_skills(self,enemy, sgs.lose_equip_skill) then
				local ee = enemy:getEquips():length()
				local fe = friend:getEquips():length()
				local value = self:evaluateArmor(enemy:getArmor(),friend) - self:evaluateArmor(friend:getArmor(),enemy)
					- self:evaluateArmor(friend:getArmor(),friend) + self:evaluateArmor(enemy:getArmor(),enemy)
				if math.abs(ee - fe) <= lost_hp and ee > 0 and (ee > fe or ee == fe and value>0) then
					if original_shown_skills(self,friend, sgs.lose_equip_skill) then
						use.card = card
						if use.to then
							use.to:append(friend)
							use.to:append(enemy)
						end
						return
					elseif not min_friend and not max_enemy then
						min_friend = friend
						max_enemy = enemy
					end
				end
			end
		end
	end
	if min_friend and max_enemy then
		use.card = card
		if use.to then
			use.to:append(min_friend)
			use.to:append(max_enemy)
		end
		return
	end

	target = nil
	for _, friend in ipairs(self.friends) do
		if hegemony_source_query(self,'needToThrowArmor',friend) or (original_shown_skills(self,friend, sgs.lose_equip_skill)	and not friend:getEquips():isEmpty()) then
				target = friend
				break
		end
	end
	if not target then return end
	for _,friend in ipairs(self.friends) do
		if friend:objectName() ~= target:objectName() and math.abs(friend:getEquips():length() - target:getEquips():length()) <= lost_hp then
			use.card = card
			if use.to then
				use.to:append(friend)
				use.to:append(target)
			end
			return
		end
	end
end

sgs.ai_use_priority.HGanluCard = 4.5 -- fixed Original initialization: Dismantlement 4.4 + 0.1
sgs.dynamic_value.control_card.HGanluCard = true

sgs.ai_card_intention.HGanluCard = function(self,card, from, to)
	local compare_func = function(a, b)
		return a:getEquips():length() < b:getEquips():length()
	end
	table.sort(to, compare_func)
	for i = 1, 2, 1 do
		if to[i]:hasArmorEffect("silver_lion") then
			self:updateIntention(from, to[i], -20)
			break
		end
	end
	if to[1]:getEquips():length() < to[2]:getEquips():length() then
		self:updateIntention(from, to[1], -80)
	end
end

ai_skill_invoke.heg_buyi = true

ai_skill_choice.startcommand_buyi= ai_skill_choice.startcommand_to

ai_skill_choice["docommand_buyi"] = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end
    local data=request and self:getDecisionData(request) or nil

  local source = data:toPlayer()
  local index = hegemony_source_query(self.player,'getMark',"command_index")
  local is_enemy = self:isEnemy(source)
  local is_friend = self:isFriend(source)
  local has_peach = false
  local count = 0
  for _, c in sgs.qlist(self.player:getHandcards()) do
    if self:isCard("Peach", c, self.player) then
      has_peach = true
    end
    if c:isAvailable(self.player) then
      count = count + 1
    end
  end

  if index == 1 then
    if not is_enemy and not is_friend then
      return  ai_choice_result(("yes"),options)
    end
    if is_friend and not hegemony_source_query(self,'isWeak',source) then
      for _, p in ipairs(self.enemies) do
        if p:getHp() == 1 and hegemony_source_query(self,'isWeak',p) and self:isEnemy(source,p) then
          return  ai_choice_result(("yes"),options)
        end
      end
    end
    if is_enemy then
      for _, p in ipairs(self.friends) do
        if hegemony_source_query(self,'isWeak',p) and self:isEnemy(source,p) then
          return  ai_choice_result(("no"),options)
        end
      end
      return  ai_choice_result(("yes"),options)
    end
  end
  if index == 2 and not is_friend then
    return  ai_choice_result(("yes"),options)
  end
  if index == 3 and is_enemy and (self.player:getHp() > (has_peach and 1 or 2)
      or self.player:isRemoved() or (self.player:hasSkill("heg_hongfa") and not self.player:getPile("heavenly_army"):isEmpty())) then
    return  ai_choice_result(("yes"),options)
  end
  if index == 4 then
    if hegemony_source_query(self.player,'getMark',"command4_effect") > 0 then
      return  ai_choice_result(("yes"),options)
    end
    if not is_friend and count < 3 then
      return  ai_choice_result(("yes"),options)
    end
  end
  if index == 5 then
    if not self.player:faceUp() then
      return  ai_choice_result(("yes"),options)
    end
    if self.player:hasSkill("heg_jushou") and self.player:getPhase() <= sgs.Player_Finish then
      return  ai_choice_result(("yes"),options)
    end
  end
