ai_card_use.HHuibianCard = function(self,card,use)
	
  local can_huibian = false
  local maixueskills = {"mobilefangzhu","heg_yiji","heg_wangxi","heg_bushi","heg_shicai","heg_zhiyu"}
  local drawcard_target, recover_target
  local targets = {}
  self:sortInPlace(self.friends, "hp")
  for _, friend in ipairs(self.friends) do
    if public_kingdom(self,friend) == "wei" then
      table.insert(targets,friend)
    end
    if public_kingdom(self,friend) == "wei" and friend:isWounded() then
      can_huibian = true
    end
  end
  if #targets < 2 or not can_huibian then return end

  local heg_xunyu = original_find_shown(self,"heg_jieming")
  if heg_xunyu and public_kingdom(self,heg_xunyu) == "wei" then
    local jieming_dnum= self:getJiemingDrawNum(self.player)
    if jieming_dnum >= 3 then
      table.insert(maixueskills, 1, "heg_jieming")
    elseif jieming_dnum == 2 then
      table.insert(maixueskills, 3, "heg_jieming")
    elseif jieming_dnum == 1 then
      table.insert(maixueskills, 5, "heg_jieming")
    end
  end
  local heg_huaxin = original_find_shown(self,"heg_wanggui")
  if heg_huaxin and public_kingdom(self,heg_huaxin) == "wei" and not hegemony_source_query(heg_huaxin,'hasFlag',"WangguiUsed") then
    local wanggui_dnum = 0
    if known(heg_player(self,heg_huaxin).shown_all,"shown_all") then
      wanggui_dnum = r25_kingdom_count(self,"wei")
    else
      wanggui_dnum = -1
    end
    if wanggui_dnum == -1 then
      if #self.enemies > 0 then
        for _, p in ipairs(self.enemies) do
          if hegemony_source_query(self,'isWeak',p) then
            table.insert(maixueskills, 1, "heg_wanggui")
          end
        end
        table.insert(maixueskills, 5, "heg_wanggui")
      end
    elseif wanggui_dnum >= 3 then
      table.insert(maixueskills, 1, "heg_wanggui")
    elseif wanggui_dnum == 2 then
      table.insert(maixueskills, 3, "heg_wanggui")
    elseif wanggui_dnum == 1 then
      table.insert(maixueskills, 5, "heg_wanggui")
    end
  end

  if self.player:getHp() == 1 and hegemony_source_query(self,'isWeak') and self.player:canRecover() then
    recover_target = self.player
    table.removeOne(targets, self.player)
  end
  for _, p in ipairs(targets) do
    if hegemony_source_query(self,'isWeak',p) and p:canRecover() and not recover_target and original_shown_skills(self,p, sgs.priority_skill) then
      recover_target = p
      table.removeOne(targets,p)
      break
    end
  end

  if not recover_target then
    for _, p in ipairs(targets) do
      if hegemony_source_query(self,'isWeak',p) and p:canRecover() and not recover_target then
        recover_target = p
        table.removeOne(targets,p)
        break
      end
    end
  end

  if not recover_target then
    for _, p in ipairs(targets) do
      if p:canRecover() and not recover_target then
        recover_target = p
        table.removeOne(targets,p)
        break
      end
    end
  end

  for _, skill in ipairs(maixueskills) do
    for _, p in ipairs(targets) do
      if shown(self,p,skill) and not drawcard_target and not self:willSkipPlayPhase(p)
      and (p:getHp() > (targets[#targets]:getHp() > 3 and 2 or 1) or (self:getAllPeachNum() +  self:originalHegemonyKnownCard(p, self.player, "Analeptic", true, "he") > 1)) then
        drawcard_target = p
        table.removeOne(targets,p)
      end
    end
  end

  if not drawcard_target then
    if targets[#targets]:getHp() > 1 or (self:getAllPeachNum() +  self:originalHegemonyKnownCard(targets[#targets], self.player, "Analeptic", true, "he") > 1) then
      drawcard_target =  targets[#targets]
      table.removeOne(targets,targets[#targets])
    end
  end

  if drawcard_target and recover_target then

	  use.card = card
    if use.to then
      use.to:append(drawcard_target)
      use.to:append(recover_target)
    end
  end
end

sgs.ai_use_priority.HHuibianCard = 5

ai_skill_invoke.heg_zongyu = true

local function shouldUseJiananByValue(self, name)
  if not sgs.general_value[name] then
    return true
  end

  if sgs.general_value[name] and sgs.general_value[name] < (self.player:getHandcardNum() < 3 and 6 or 7) then
    return true
  end
  
  return false
end

sgs.ai_skill_cardask["@heg_elitegeneralflag"] = function(self, data, pattern, target, target2)
  local jianan_skills = {"tenyeartuxi", "qiaobian", "xiaoguo", "heg_jieyue", "heg_duanliang"}
  for _, p in sgs.qlist(self.room:getAlivePlayers()) do
    for _, skill in ipairs(jianan_skills) do
      if shown(self,p,skill) or shown(self,p,skill .. "_egf") then
        table.removeOne(jianan_skills,skill)
      end
    end
  end
  if self.player:hasSkill("heg_jieyue") then
    table.insert(jianan_skills ,"heg_jieyue")
  end
  if #jianan_skills == 0 and hegemony_source_query(self.player,'getMark',"JieyueExtraDraw") < 1 then
    return "."
  end
  local choice = ai_skill_choice.jianan_skill(self,{reason='jianan_skill',choices=jianan_skills,inquiry_scope='original_internal'},nil)

  local allcards = sgs.QList2Table(self.player:getCards("he"))
  self:sortByUseValue(allcards, true)
  local discard = allcards[1]
  if hegemony_source_query(self.player,'getMark',"JieyueExtraDraw") > 0 then
    if self.player:getCardCount(true) == 1 and self:isCard("Peach", allcards[1], self.player) and hegemony_source_query(self,'isWeak') then
      return "."
    end
    if #jianan_skills == 0 then
      if self.player:getCardCount(true) < 2
      or (self:isCard("Peach", allcards[2], self.player) and hegemony_source_query(self,'isWeak')) then
        return "."
      end
    end
    return discard:getLegacyStringKey()
  end
  if (self.player:hasSkill(choice) and choice ~= "heg_jieyue") or choice == "xiaoguo" then
    return "."
  end
  if self.player:isLord() and r25_slot(self,self.player,"head","heg_sidi") and not self.player:getPile("drive"):isEmpty() then
    return "."
  end
  if choice == "qiaobian" then
    return discard:getLegacyStringKey()
  end
  if self.player:hasSkills("qiaobian|heg_qiaobian_egf") and choice == "tenyeartuxi" then
    return "."
  end
  if not self:isCard("Peach", discard, self.player) then
    local g1name = r25_player_general(self,self.player, true):objectName()
    local g2name = r25_player_general(self,self.player, false):objectName()
    if shouldUseJiananByValue(self, g1name) or shouldUseJiananByValue(self, g2name)
    or r25_duanchang(self,self.player, true) or r25_duanchang(self,self.player, false) then
      
      return discard:getLegacyStringKey()
    end
  end
	return "."
end

ai_skill_choice.jianan_hide = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end

  
  if self.player:hasSkill("heg_jieyue") then
    if r25_slot(self,self.player,"head","heg_jieyue") then
      return  ai_choice_result(("head"),options)
    else
      return  ai_choice_result(("deputy"),options)
    end
  end

	local g1name = r25_player_general(self,self.player, true):objectName()
  local g2name = r25_player_general(self,self.player, false):objectName()
  local v1 = sgs.general_value[g1name] or 5
  local v2 = sgs.general_value[g2name] or 5
  if r25_duanchang(self,self.player, true) then
    v1 = 0
  end
  if r25_duanchang(self,self.player, false) then
    v2 = 0
  end
  if shown(self,self.player,"heg_luoshen") then
    if r25_slot(self,self.player,"head","heg_luoshen") and v2 > 5 then
      v1 = v1 - 4
    elseif r25_slot(self,self.player,"deputy","heg_luoshen") and v1 > 5 then
      v2 = v2 - 4
    end
	end
  if shown(self,self.player,"heg_tuntian") then
    if r25_slot(self,self.player,"head","heg_tuntian") then
      v1 = v1 + self.player:getPile("field"):length()
    else
      v2 = v2 + self.player:getPile("field"):length() * 0.5
    end
	end
  if self.player:hasSkill("heg_sidi") then
    if r25_slot(self,self.player,"head","heg_sidi") then
      v1 = v1 + self.player:getPile("drive"):length()
    else
      v2 = v2 + self.player:getPile("drive"):length()
    end
  end
	return  ai_choice_result((v1 > v2 and "deputy" or "head"),options)
end

ai_skill_choice.jianan_skill = function(self,options,request)
    local skills
    if options and options.choices~=nil then skills=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then skills=''end

	skills = skills:split("+")
	if (self.player:hasSkill("qiaobian") or self:willSkipDrawPhase()) and #skills > 1 then
    table.removeOne(skills, "tenyeartuxi")
  end
  if table.contains(skills, "tenyeartuxi") and self:findTuxiTarget() then
    if self.player:isKongcheng() then
      return  ai_choice_result(("tenyeartuxi"),options)
    end
    if hegemony_source_query(self.player,'getMark',"JieyueExtraDraw") > 0 and not (self:willSkipPlayPhase() and hegemony_source_query(self,'getOverflow') > 1) then
      return  ai_choice_result(("tenyeartuxi"),options)
    end
	end
  if table.contains(skills, "qiaobian") then
    if self:willSkipPlayPhase() and hegemony_source_query(self,'getOverflow') > (hegemony_source_query(self.player,'getMark',"JieyueExtraDraw") > 0 and 0 or 1) then
      return  ai_choice_result(("qiaobian"),options)
    end
		if #skills > 1 then
      local lord_caocao = original_find_shown(self,"jianan")
      for _, p in ipairs(self.friends_noself) do
        if self.player:isFriendWith(p) and self:playerGetRound(p, lord_caocao) > self:playerGetRound(self.player, lord_caocao)
        and ((self:willSkipPlayPhase(p) and hegemony_source_query(self,'getOverflow',p) > 1)
          or (hegemony_source_query(self,'getOverflow',p) > 3 and p:getHandcardNum() > self.player:getHandcardNum())) then
            table.removeOne(skills, "qiaobian")
            break
        end
      end
    end
    if (hegemony_source_query(self,'getOverflow') > (hegemony_source_query(self.player,'getMark',"JieyueExtraDraw") > 0 and 2 or 4)
      or (self:willSkipDrawPhase() and hegemony_source_query(self.player,'getMark',"JieyueExtraDraw") > 0)
      or (self:willSkipPlayPhase() and not self.player:isKongcheng()))
    and table.contains(skills, "qiaobian") then
      return  ai_choice_result(("qiaobian"),options)
    end
	end
  if table.contains(skills, "heg_jieyue") then
    if ai_skill_use["@@heg_jieyue"](self,nil,nil) ~= "." and not self:willSkipDrawPhase() then
      return  ai_choice_result(("heg_jieyue"),options)
    elseif #skills > 1 then
      table.removeOne(skills, "heg_jieyue")
    end
	end
  if table.contains(skills, "heg_duanliang") then
    local duanliang_count = 0
    local kongcheng_enemy = 0
    local needcards_enemy = 0
    local cards = self.player:getCards("he")
    cards = sgs.QList2Table(cards)
    for _, id in sgs.qlist(self.player:getHandPile()) do
      table.insert(cards, r25_card(self,id))
    end
    self:sortByUseValue(cards, true)
    for _,acard in ipairs(cards)  do
      if acard:isBlack() and (acard:isKindOf("BasicCard") or acard:isKindOf("EquipCard")) and (self:getUseValue(acard) < known(SmartAIView.originalHegemonyPrintedValue(self,'ai_use_value','SupplyShortage'),'Original SupplyShortage use value')) then
        duanliang_count = duanliang_count + 1
      end
    end
    for _, p in ipairs(self.enemies) do
      if p:isKongcheng() then
        kongcheng_enemy = kongcheng_enemy + 1
      end
      if not p:isKongcheng() and p:getHandcardNum() < 3 then
        needcards_enemy = needcards_enemy + 1
      end
    end
    if duanliang_count > ((kongcheng_enemy > 0 or needcards_enemy > 1) and 0 or 1) then
      return  ai_choice_result(("heg_duanliang"),options)
    end
    if duanliang_count == 0 and #skills > 1 then
      table.removeOne(skills, "heg_duanliang")
    end
	end
  if table.contains(skills, "tenyeartuxi") and self:findTuxiTarget() then
    return  ai_choice_result(("tenyeartuxi"),options)
  end
  if known(heg_player(self,self.player).shown_all,"shown_all") and table.contains(skills, "qiaobian") then
    local g1name = r25_player_general(self,self.player, true):objectName()
    local g2name = r25_player_general(self,self.player, false):objectName()
    if not shouldUseJiananByValue(self, g1name) and not shouldUseJiananByValue(self, g2name) then
      table.removeOne(skills, "qiaobian")
    end
    if #skills == 0 then
      table.insert(skills, "xiaoguo")
    end
  end
  if self.player:getMaxCards() < 3 and #skills > 1 then
		table.removeOne(skills, "xiaoguo")
	end
  
	return  ai_choice_result((skills[math.random(1, #skills)]),options)
end

function sgs.ai_cardneed.heg_elitegeneralflag(to, card)
	return to:isNude()
