ai_fill_skill.heg_duanliang_egf = function(self,options,request)
    local inclusive=(options or {}).inclusive

	if not self:willShowForAttack() then
		return nil
	end
  if hegemony_source_query(self.player,'hasFlag',"DuanliangEGFCannot") then
    return nil
  end

	local cards = self.player:getCards("he")
	cards = sgs.QList2Table(cards)
	for _, id in sgs.qlist(self.player:getHandPile()) do
		table.insert(cards, r25_card(self,id))
	end
	local card

	self:sortByUseValue(cards, true)

	for _,acard in ipairs(cards)  do
		if acard:isBlack() and (acard:isKindOf("BasicCard") or acard:isKindOf("EquipCard")) and (self:getUseValue(acard) < known(SmartAIView.originalHegemonyPrintedValue(self,'ai_use_value','SupplyShortage'),'Original SupplyShortage use value')) then
			card = acard
			break
		end
	end

	if not card then return nil end
	local suit = card:getSuitString()
	local number = card:getNumberString()
	local card_id = card:getKnownEffectiveId()
	local card_str = ("supply_shortage:heg_duanliang_egf[%s:%s]=%d%s"):format(suit, number, card_id, "&heg_duanliang_egf")
	local skillcard = r25_parse(self,card_str)

	assert(skillcard)
	return skillcard
end

