sgs.ai_skill_exchange.command = function(self,pattern,max_num,min_num,expand_pile)
  local card_give = {}
  local to
	for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
		if hegemony_source_query(p,'hasFlag',"CommandSource") then
			to = p
			break
		end
	end
  local visibleflag = string.format("%s_%s_%s", "visible", self.player:objectName(), to:objectName())

  local function card_insert(card)
    local c_id = card:getKnownEffectiveId()
    if #card_give < max_num and not table.contains(card_give, c_id) then
      if not hegemony_source_query(card,'hasFlag',"visible") then r25_observe_given_card(self,card,nil,visibleflag) end
      table.insert(card_give, c_id)
    end
  end

  local cards = self.player:getCards("he")
	cards = sgs.QList2Table(cards)
  if self.player:getPhase() <= sgs.Player_Play then
		self:sortByUseValue(cards, true)
	else
		self:sortByKeepValue(cards)
	end
  if self:isFriend(to) then
    if self.player:getHp() > 1 and hegemony_source_query(self,'isWeak',to) and self:getCardsNum("Analeptic") > 0 then
      card_insert(self:getCard("Analeptic"))
    end
    if not hegemony_source_query(self,'isWeak') and hegemony_source_query(self,'isWeak',to) and self:getCardsNum("Peach") > 0 then
      card_insert(self:getCard("Peach"))
    end
    local c, friend = self:getCardNeedPlayer(cards, {to})
    if friend and friend:objectName() == to:objectName() then
      card_insert(c)
    end
    if self:getCardsNum("Jink") > 1 then
      card_insert(self:getCard("Jink"))
    end
    if self:getCardsNum("Slash") > 1 and not hegemony_source_query(self,'hasCrossbowEffect') then
      card_insert(self:getCard("Slash"))
    end
  end

  for _, c in ipairs(cards) do
    card_insert(c)
  end
	return card_give
end

sgs.ai_skill_cardask["@command-select"] = function(self, data, pattern, target, target2)
  local selected_h, selected_e
  if not self.player:isKongcheng() then
    local hcards = self.player:getCards("h")
    hcards = sgs.QList2Table(hcards)
    if self.player:getPhase() <= sgs.Player_Play then
      self:sortByUseValue(hcards)
    else
      self:sortByKeepValue(hcards, true)
    end
    selected_h = hcards[1]
  end
  if self.player:hasEquip() then
    local equips = sgs.QList2Table(self.player:getCards("e"))
    if self.player:getPhase() <= sgs.Player_Play then
      self:sortByUseValue(equips)
    else
      self:sortByKeepValue(equips, true)
    end
    selected_e = equips[1]
  end
  if selected_h and selected_e then
    local selected_cards = {}
    table.insert(selected_cards, selected_h:getKnownId())
    table.insert(selected_cards, selected_e:getKnownId())
    return "$" .. table.concat(selected_cards, "+")
  elseif selected_h then
    return "$" .. selected_h:getKnownEffectiveId()
  elseif selected_e then
    return "$" .. selected_e:getKnownEffectiveId()
  end
  return "."
end


local selfarg={ai_card_use=1,ai_cardneed=3,ai_skill_pindian=2,ai_view_as=4}
local function wrap(body,old,key,reg)
    local index=selfarg[reg]or 1
    return function(...)
        local args=table.pack(...);local self=reg=='ai_view_as'and args[2]and args[2]._room and args[2]._room._ai or args[index]
        if not original_enabled(self)then if type(old)=='function'then return old(...)elseif old~=nil then return old end;ai_unsupported('ordinary provider missing',key)end
        r25_restore(self)
        local previous=r25_active
        r25_active={self=self,request=(reg=='ai_fill_skill'and args[3]or reg=='ai_card_use'and args[4]or reg=='ai_skill_use'and args[3]or reg=='ai_skill_choice'and args[3]or nil)}
        local result=table.pack(pcall(body,...));r25_active=previous;r25_save(self)
        if not result[1]then error(result[2],0)end
        if reg=='ai_skill_use'then result[2]=r25_response(self,key,result[2],args[3])end
        return table.unpack(result,2,result.n)
    end
end
