function SmartAI:findTuxiTarget(max_num)
	local targets = {}
	max_num = max_num or 2

	local add_player = function (player, isfriend)
		if player:isKongcheng() or player:objectName() == self.player:objectName() then return #targets end
		if #targets < max_num then
			if not table.contains(targets, player:objectName()) then
				table.insert(targets, player:objectName())
			end
		end
		if isfriend and isfriend == 1 then
			self:setStrategyPlayerFlag(self.player,"tuxi_isfriend_"..player:objectName(),true)
		end
		return #targets
	end

	local heg_zhugeliang = original_find_shown(self,"heg_kongcheng")
	if heg_zhugeliang and self:isFriend(heg_zhugeliang) and public_kingdom(self,heg_zhugeliang) ~= "unknown" and heg_zhugeliang:getHandcardNum() == 1
		and self:getEnemyNumBySeat(self.player,heg_zhugeliang) > 0 then
		if heg_zhugeliang:getHp() <= 2 then
			if add_player(heg_zhugeliang, 1) == max_num then return targets end
		else
			local cards = sgs.QList2Table(r25_known_number_cards(self,heg_zhugeliang))
			if heg_zhugeliang:getHandcardNum()==1 and cards[1] and r25_card_visible(self,cards[1], heg_zhugeliang, self.player) then
				if cards[1]:isKindOf("TrickCard") or cards[1]:isKindOf("Slash") or cards[1]:isKindOf("EquipCard") then
					if add_player(heg_zhugeliang, 1) == max_num then return targets end
				end
			end
		end
	end

	self:sortInPlace(self.enemies, "handcard_defense")
	for _, enemy in ipairs(self.enemies) do
		local cards = sgs.QList2Table(r25_known_number_cards(self,enemy))
		for _, card in ipairs(cards) do
			if r25_card_visible(self,card, enemy, self.player) and (card:isKindOf("Peach") or card:isKindOf("Nullification") or card:isKindOf("Analeptic") ) then
				if add_player(enemy) == max_num  then return targets end
			end
		end
	end

	for _, enemy in ipairs(self.enemies) do
		if original_shown_skills(self,enemy, sgs.notActive_cardneed_skill) then
			if add_player(enemy) == max_num then return targets end
		end
	end

	for _, enemy in ipairs(self.enemies) do
		if original_shown_skills(self,enemy, sgs.Active_cardneed_skill) then
			if add_player(enemy) == max_num then return targets end
		end
	end

	for _, enemy in ipairs(self.enemies) do
		local x = enemy:getHandcardNum()
		local good_target = true
		if x == 1 and hegemony_source_query(self,'needKongcheng',enemy) then good_target = false end
		if x >= 2 and shown(self,enemy,"heg_tuntian") then good_target = false end
		if good_target and add_player(enemy) == max_num then return targets end
	end

	local others = self.room:getOtherPlayers(self.player)
	for _, other in sgs.qlist(others) do
		if self:objectiveLevel(other) >= 0 and not shown(self,other,"heg_tuntian") and add_player(other) == max_num then
			return targets
		end
	end

	if #targets > 0 then
		return targets
	end
end

function SmartAI:getMoveCardorTarget(who, return_prompt, flag)
	flag = flag or "ej"
	local card, target
	if self:isFriend(who) then
		if flag:match("j") then
			local judges = who:getJudgingArea()
			if not judges:isEmpty() then
				for _, judge in sgs.qlist(judges) do
					card = r25_card(self,judge:getKnownEffectiveId())
					for _, enemy in ipairs(self.enemies) do
						if not enemy:containsTrick(judge:objectName()) and self:trickIsEffective(judge, enemy, self.player) then
							target = enemy
							break
						end
					end
					if not target then
						for _, enemy in sgs.qlist(self.room:getAlivePlayers()) do
							if not self:isFriend(enemy) and not enemy:containsTrick(judge:objectName()) and self:trickIsEffective(judge, enemy, self.player) then
								target = enemy
								break
							end
						end
					end
					if not target then
						for _, enemy in sgs.qlist(self.room:getAlivePlayers()) do
							if not self.player:isFriendWith(enemy) and not enemy:containsTrick(judge:objectName()) and self:trickIsEffective(judge, enemy, self.player) then
								target = enemy
								break
							end
						end
					end
					if target then break end
				end
			end
		end
		if flag:match("e") then
			local equips = who:getCards("e")
			if not target and not equips:isEmpty() and original_shown_skills(self,who, sgs.lose_equip_skill) then
				for _, equip in sgs.qlist(equips) do
					if equip:isKindOf("OffensiveHorse") then card = equip break
					elseif equip:isKindOf("Weapon") then card = equip break
					elseif equip:isKindOf("Treasure") then card = equip break
					elseif equip:isKindOf("DefensiveHorse") and not hegemony_source_query(self,'isWeak',who) then
						card = equip
						break
					elseif equip:isKindOf("Armor") and (not hegemony_source_query(self,'isWeak',who) or hegemony_source_query(self,'needToThrowArmor',who)) then
						card = equip
						break
					end
				end

				if card then
					if card:isKindOf("Armor") or card:isKindOf("DefensiveHorse") then
						self:sortInPlace(self.friends, "defense")
					else
						self:sortInPlace(self.friends, "handcard", true)
					end
					for _, friend in ipairs(self.friends) do
						if not self:getSameEquip(card, friend) and friend:objectName() ~= who:objectName()
						and original_shown_skills(self,friend, sgs.need_equip_skill) and self.player:isFriendWith(friend) then
							target = friend
							break
						end
					end
					if not target then
						for _, friend in ipairs(self.friends) do
							if not self:getSameEquip(card, friend) and friend:objectName() ~= who:objectName()
							and self.player:isFriendWith(friend) then
								target = friend
								break
							end
						end
					end
					if not target then
						for _, friend in ipairs(self.friends) do
							if not self:getSameEquip(card, friend) and friend:objectName() ~= who:objectName()
								and original_shown_skills(self,friend, sgs.need_equip_skill) then
									target = friend
									break
							end
						end
					end
					if not target then
						for _, friend in ipairs(self.friends) do
							if not self:getSameEquip(card, friend) and friend:objectName() ~= who:objectName() then
								target = friend
								break
							end
						end
					end
				end
			end
		end
	else
		if flag:match("e") then
			if not card  or not target then
				if not who:hasEquip() or original_shown_skills(self,who, sgs.lose_equip_skill) then return nil end
				local card_id = self:askForCardChosen(who, "e", "move")
				if card_id >= 0 and who:hasEquip(r25_card(self,card_id)) then card = r25_card(self,card_id) end
				if card then
					if card:isKindOf("Armor") or card:isKindOf("DefensiveHorse") then
						self:sortInPlace(self.friends, "defense")
					else
						self:sortInPlace(self.friends, "handcard", true)
					end
					for _, friend in ipairs(self.friends) do
						if not self:getSameEquip(card, friend) and friend:objectName() ~= who:objectName()
						and original_shown_skills(self,friend, sgs.need_equip_skill) and self.player:isFriendWith(friend) then
							target = friend
							break
						end
					end
					if not target then
						for _, friend in ipairs(self.friends) do
							if not self:getSameEquip(card, friend) and friend:objectName() ~= who:objectName()
							and self.player:isFriendWith(friend) then
								target = friend
								break
							end
						end
					end
					if not target then
						for _, friend in ipairs(self.friends) do
							if not self:getSameEquip(card, friend) and friend:objectName() ~= who:objectName()
								and original_shown_skills(self,friend, sgs.need_equip_skill) then
									target = friend
									break
							end
						end
					end
					if not target then
						for _, friend in ipairs(self.friends) do
							if not self:getSameEquip(card, friend) and friend:objectName() ~= who:objectName() then
								target = friend
								break
							end
						end
					end
				end
			end
		end
		if flag:match("j") then

		end
	end

	if return_prompt == "card" then return card
	elseif return_prompt == "target" then return target
	else
		return (card and target)
	end
end

function SmartAI:useCardBurningCamps(card, use)
	if not card:isAvailable(self.player) then return end

	local player = self.player:getNextAlive()
	if self:isFriendWith(player) then return end

	local players = r25_formation(self,player)
	if players:isEmpty() then return end
	local shouldUse
	for i = 0 , players:length() - 1 do do 
		player = self.room:findPlayerByObjectName(players:at(i):objectName())
		if not self:trickIsEffective(card, player, self.player) then
			goto package_continue_1
		end
		local damage = {}
		damage.from = self.player
		damage.to = player
		damage.nature = sgs.DamageStruct_Fire
		damage.damage = 1
		if self:damageIsEffective_(damage) then
			if player:isChained() and self:isGoodChainTarget_(damage) then
				shouldUse = true
			elseif self:objectiveLevel(player) > 3.5 then
				shouldUse = true
			else
				return
			end
		end
	end ::package_continue_1:: end
	if shouldUse then
		local chaincard = self:getCard("HFightTogether")
		if chaincard and not chaincard:getKnownEffectiveId() == card:getKnownEffectiveId() then
			use.card = chaincard
			return
		end
		chaincard = self:getCard("IronChain")
		if chaincard and not chaincard:getKnownEffectiveId() == card:getKnownEffectiveId() and #self.enemies > 1 then
			local num = 0
			for _, p in ipairs(self.enemies) do
				if not p:isChained() and p:canBeChainedBy(self.player) then num = num + 1 end
			end
			if num > 1 then
				use.card = chaincard
				return
			end
		end
		use.card = card
	end
end

function SmartAI:useCardAllianceFeast(card, use)
	if not card:isAvailable(self.player) then return end
	local hegnullcards = self.player:getCards("HegNullification")
	local effect_kingdoms = {}

	for _, target in sgs.qlist(self.room:getOtherPlayers(self.player)) do
		if not self.player:isFriendWith(target) and known(heg_player(self,target).shown_one,"shown_one") and self:trickIsEffective(card, target, self.player)
			and not(r25_role(self,target) ~= "careerist" and table.contains(effect_kingdoms, heg_kingdom(self,target))) then
			if r25_role(self,target) == "careerist" then
				table.insert(effect_kingdoms, target:objectName())
			else
				table.insert(effect_kingdoms, heg_kingdom(self,target))
			end
		end
	end
	if #effect_kingdoms == 0 then return end

	local max_v = 0
	local winner
	for _, kingdom in ipairs(effect_kingdoms) do
		local value = 0
		if kingdom:startsWith("sgs") then
			if self.player:isWounded() then
				value = value + 1.5
			else
				value = value + 0.5
				if original_shown_skills(self,self.player, sgs.cardneed_skill) then value = value + 0.5 end
			end
			local target = self.room:findPlayerByObjectName(kingdom)
			if self:isFriend(target) then
				value = value + 0.5
				if original_shown_skills(self,target, sgs.cardneed_skill) then value = value + 0.5 end
				if target:isChained() then value = value + 0.5 end
			elseif self:isEnemy(target) then
				value = value - 0.5
				if original_shown_skills(self,target, sgs.cardneed_skill) then value = value - 0.5 end
				if target:isChained() then value = value - 0.5 end
			end
		else
			local their_num = 0
			local self_value = 0
			local enemy_value = 0
			for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
				if known(heg_player(self,p).shown_one,"shown_one") and r25_role(self,p) ~= "careerist" and heg_kingdom(self,p) == kingdom then
					their_num = their_num + 1
					if self:isFriend(p) and self:trickIsEffective(card, p, self.player) then
						self_value = self_value + 0.5
						if original_shown_skills(self,p, sgs.cardneed_skill) then self_value = self_value + 0.5 end
						if p:isChained() then self_value = self_value + 0.5 end
					elseif self:isEnemy(p) and self:trickIsEffective(card, p, self.player) then
						enemy_value = enemy_value + 0.5
						if original_shown_skills(self,p, sgs.cardneed_skill) then enemy_value = enemy_value + 0.5 end
						if p:isChained() then enemy_value = enemy_value + 0.5 end
					end
				end
			end
			if their_num > self.player:getLostHp() then
				self_value = self_value + self.player:getLostHp() * 1.5
				self_value = self_value + (their_num - self.player:getLostHp())*(original_shown_skills(self,self.player, sgs.cardneed_skill) and 1 or 0.5)
			else
				self_value = self_value + their_num * 1.5
			end
			if self_value >= 3 and enemy_value > 2.5 and hegnullcards then
				enemy_value = enemy_value / 2
			end
			value = self_value - enemy_value
		end
		if value > max_v then
			winner = kingdom
			max_v = value
		end
	end

	if winner then
		local target
		if winner:startsWith("sgs") then
			target = self.room:findPlayerByObjectName(winner)
		else
			for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
				if known(heg_player(self,p).shown_one,"shown_one") and r25_role(self,p) ~= "careerist" and heg_kingdom(self,p) == winner and self:trickIsEffective(card, p, self.player) then
					target = p
					break
				end
			end
		end
		if target then
			use.card = card
			if use.to then use.to:append(target) end
			return
		end
	end
end

function SmartAI:useCardBefriendAttacking(HBefriendAttacking, use)
	if not HBefriendAttacking:isAvailable(self.player) then return end
	local targets = AIList.new{}
	local players = sgs.QList2Table(self.room:getOtherPlayers(self.player))
	self:sortInPlace(players)
	for _, to_select in ipairs(players) do do 
		if shown(self,to_select,"heg_luanji") and to_select:getHandcardNum() > 3 then goto package_continue_2 end
		if self:isFriend(to_select) and self:cardTargetFilter(HBefriendAttacking,targets,to_select) and not targets:contains(to_select)
			and self:trickIsEffective(HBefriendAttacking, to_select, self.player) then
			targets:append(to_select)
			if use.to then use.to:append(to_select) end
		end
	end ::package_continue_2:: end

	if targets:isEmpty() then															
		for _, to_select in ipairs(players) do do 
			if shown(self,to_select,"heg_luanji") and to_select:getHandcardNum() > 3 then goto package_continue_3 end
			if self:cardTargetFilter(HBefriendAttacking,targets,to_select) and not targets:contains(to_select)
				and self:trickIsEffective(HBefriendAttacking, to_select, self.player) and r25_role(self,to_select) == "careerist" then
				targets:append(to_select)
				if use.to then use.to:append(to_select) end
			end
		end ::package_continue_3:: end
	end

	local kingdoms = {"wei","shu","wu","qun"}											
	if r25_role(self,self.player) ~= "careerist" then
		table.removeOne(kingdoms, self:originalHegemonyOwnKingdom())
	end
	local num = 10
	local targetKingdom
	for _, kingdom in ipairs(kingdoms) do
		if r25_kingdom_count(self,kingdom) < num and r25_kingdom_count(self,kingdom) > 0 then
			num = r25_kingdom_count(self,kingdom)
			targetKingdom = kingdom
		end
	end

	if targets:isEmpty() then															
		for _, to_select in ipairs(players) do do 
			if shown(self,to_select,"heg_luanji") and to_select:getHandcardNum() > 3 then goto package_continue_4 end
			if self:cardTargetFilter(HBefriendAttacking,targets,to_select) and not targets:contains(to_select)
				and self:trickIsEffective(HBefriendAttacking, to_select, self.player) and heg_kingdom(self,to_select) == targetKingdom then
				targets:append(to_select)
				if use.to then use.to:append(to_select) end
			end
		end ::package_continue_4:: end
	end
	if targets:isEmpty() then
		for _, to_select in ipairs(players) do do 
			if shown(self,to_select,"heg_luanji") and to_select:getHandcardNum() > 3 then goto package_continue_5 end
			if self:cardTargetFilter(HBefriendAttacking,targets,to_select) and not targets:contains(to_select)
				and self:trickIsEffective(HBefriendAttacking, to_select, self.player) then
				targets:append(to_select)
				if use.to then use.to:append(to_select) end
			end
		end ::package_continue_5:: end
	end
	if not targets:isEmpty() then
		use.card = HBefriendAttacking
		return
	end
end
function SmartAI:useCardDrowning(card, use)
	if not card:isAvailable(self.player) then return end

	self:sortInPlace(self.enemies, "equip_defense")

	local players = AIList.new{}
	for _, enemy in ipairs(self.enemies) do
		if self:cardTargetFilter(card,players,enemy) and not players:contains(enemy) and enemy:hasEquip()
			and self:trickIsEffective(card, enemy) and self:damageIsEffective(enemy, sgs.DamageStruct_Thunder, self.player) and self:canAttack(enemy)
			and not self:needDamagedEffects(enemy, self.player) and not self:needToLoseHp(enemy, self.player) and not hegemony_source_query(self,'needToThrowArmor',enemy)
			and not (enemy:hasArmorEffect("PeaceSpell") and (enemy:getHp() > 1 or self:needToLoseHp(enemy, self.player)))
			and not (enemy:hasArmorEffect("Breastplate") and enemy:getHp() == 1) then
			local dangerous
			local chained = {}
			if enemy:isChained() then
				for _, p in sgs.qlist(self.room:getOtherPlayers(enemy)) do
					if not self:isGoodChainTarget(enemy, p, sgs.DamageStruct_Thunder) and self:damageIsEffective(p, sgs.DamageStruct_Thunder) and self:isFriend(p) then
						table.insert(chained, p)
						if hegemony_source_query(self,'isWeak',p) then dangerous = true end
					end
				end
			end
			if #chained >= 2 then dangerous = true end
			if not dangerous then
				players:append(enemy)
				if use.to then use.to:append(enemy) end
			end
		end
	end

	for _, friend in ipairs(self.friends_noself) do
		if self:cardTargetFilter(card,players,friend) and not players:contains(friend) and friend:getEquips():length() == 1
		and (hegemony_source_query(self,'needToThrowArmor',friend) or (original_shown_skills(self,friend, sgs.lose_equip_skill) and not friend:getArmor() and not friend:getTreasure())) then
			players:append(friend)
			if use.to then use.to:append(friend) end
		end
	end

	if not players:isEmpty() then
		use.card = card
		return
	end
end

function SmartAI:useCardDuel(duel, use)

	local enemies = self:exclude(self.enemies, duel)
	local friends = self:exclude(self.friends_noself, duel)
	self:setStrategyCardFlag(duel,"AI_Using",true)
	local n1 = self:getCardsNum("Slash")
	self:setStrategyCardFlag(duel,"AI_Using",false)
	if self.player:hasSkills("wushuang|heg_wushuang_lvlingqi") then n1 = n1 * 2 end
	local heg_huatuo = original_find_shown(self,"jijiu")
	local targets = {}

	local canUseDuelTo=function(target)
		return self:trickIsEffective(duel, target) and self:damageIsEffective(target,sgs.DamageStruct_Normal)
	end

	for _, friend in ipairs(friends) do do 
		if not canUseDuelTo(friend) then goto package_continue_6 end
		if friend:hasSkill("heg_jieming") and self.player:hasSkill("rende") and (heg_huatuo and self:isFriend(heg_huatuo)) then
			table.insert(targets, friend)
		end
		if self.player:hasSkill("heg_zhiman") and (self.player:canGet(friend,"j") or ((original_shown_skills(self,friend, sgs.lose_equip_skill) or hegemony_source_query(self,'needToThrowArmor',friend)) and self.player:canGet(friend,"e"))) then
			table.insert(targets, friend)
		end
	end ::package_continue_6:: end

	for _, enemy in ipairs(enemies) do
		if hegemony_source_query(self.player,'hasFlag',"duelTo_" .. enemy:objectName()) and canUseDuelTo(enemy) then
			table.insert(targets, enemy)
		end
	end

	local cmp = function(a, b)
		local v1 = self:originalHegemonyCardsNum("Slash", a, self.player) + a:getHp()
		local v2 = self:originalHegemonyCardsNum("Slash", b, self.player) + b:getHp()

		if self:needDamagedEffects(a, self.player) then v1 = v1 + 20 end
		if self:needDamagedEffects(b, self.player) then v2 = v2 + 20 end

		if not hegemony_source_query(self,'isWeak',a) and a:hasSkill("nosjianxiong") then v1 = v1 + 10 end
		if not hegemony_source_query(self,'isWeak',b) and b:hasSkill("nosjianxiong") then v2 = v2 + 10 end

		if self:needToLoseHp(a) then v1 = v1 + 5 end
		if self:needToLoseHp(b) then v2 = v2 + 5 end

		if original_shown_skills(self,a, sgs.masochism_skill) then v1 = v1 + 5 end
		if original_shown_skills(self,b, sgs.masochism_skill) then v2 = v2 + 5 end

		if not hegemony_source_query(self,'isWeak',a) and a:hasSkill("heg_jiang") then v1 = v1 + 5 end
		if not hegemony_source_query(self,'isWeak',b) and b:hasSkill("heg_jiang") then v2 = v2 + 5 end

		if v1 == v2 then return self:originalHegemonyGetDefenseSlash(a) < self:originalHegemonyGetDefenseSlash(b) end

		return v1 < v2
	end

	table.sort(enemies, cmp)

	local noresponse = false
	local noresponselist = duel:getTag("NoResponse"):toStringList()
	if noresponselist and table.contains(noresponselist,"_ALL_PLAYERS") then
		noresponse = true
	end

	for _, enemy in ipairs(enemies) do
		local useduel
		local n2 = self:originalHegemonyCardsNum("Slash", enemy, self.player)
		if enemy:hasSkills("wushuang|heg_wushuang_lvlingqi") then n2 = n2 * 2 end
		if self:getOriginalHegemonyCardLack(self.room:findPlayerByObjectName(enemy:objectName()),"Slash") == 1 then n2 = 0 end
		if noresponselist and table.contains(noresponselist,enemy:objectName()) then
			noresponse = true
		end
		useduel = n1 >= n2 or self:needToLoseHp(self.player, nil, nil, true) or noresponse
					or self:needDamagedEffects(self.player, enemy) or (n2 < 1 and r25_good_hp(self,self.player, self.player))
					or ((self.player:hasSkill("nosjianxiong") or hegemony_source_query(self.player,'hasFlag',"shuangxiong")) and r25_good_hp(self,self.player, self.player)
						and n1 + self.player:getHp() >= n2 and hegemony_source_query(self,'isWeak',enemy))

		if self:objectiveLevel(enemy) > 3 and canUseDuelTo(enemy) and not self:cantbeHurt(enemy) and useduel and self:originalHegemonyIsGoodTarget(enemy, enemies) then
			if not table.contains(targets, enemy) then table.insert(targets, enemy) end
		end
	end

	if #targets > 0 then

		local godsalvation = self:getCard("GodSalvation")
		if godsalvation and godsalvation:getKnownId() ~= duel:getKnownId() and self:willUseGodSalvation(godsalvation) then
			local use_gs = true
			for _, p in ipairs(targets) do
				if not p:isWounded() or not self:trickIsEffective(godsalvation, p, self.player) then break end
				use_gs = false
			end
			if use_gs then
				use.card = godsalvation
				return
			end
		end

		local targets_num = 1 + duel:getTargetModExtra(self.player)
		if use.isDummy and use.xiechan then targets_num = 100 end
		local enemySlash = 0
		local setFlag = false

		use.card = duel

		for i = 1, #targets, 1 do
			local n2 = self:originalHegemonyCardsNum("Slash", targets[i], self.player)
			if self:getOriginalHegemonyCardLack(targets[i],'Slash') == 1 then n2 = 0 end
			if self:isEnemy(targets[i]) then enemySlash = enemySlash + n2 end

			if use.to then
				if i == 1 then
					use.to:append(targets[i])
				end
				if not setFlag and self.player:getPhase() == sgs.Player_Play and self:isEnemy(targets[i]) then
					self:setStrategyMemory('original.duelTo.'..targets[i]:objectName(),true)
					setFlag = true
				end
				if use.to:length() == targets_num then return end
			end
		end
	end

end

function SmartAI:askForSkillInvoke(skill_name,options,request,query_scope)
    skill_name=string.gsub(skill_name,'%-','_')
    -- Internal Original inquiries retain their strict result and provider visibility.
    local inquiry_options={}
    for key,value in pairs(options or {})do inquiry_options[key]=value end
    inquiry_options.reason=skill_name
    if query_scope~='top_level'then inquiry_options.inquiry_scope='original_internal'end
    local invoke=ai_skill_invoke[skill_name]
    if ai_audited_aliases then invoke=ai_audited_aliases.resolve(self,invoke)end
    if type(invoke)=='boolean'then return invoke end
    if type(invoke)=='function'then
        local value=invoke(self,inquiry_options,request)
        if AIUnsupported.is(value)then error(value,0)end
        if value~=nil then return value==true end
    end
    local skill=self.room:getPublicSkill(skill_name)
    if skill==nil then ai_unsupported('Original skill definition outside the visible roster','Original askForSkillInvoke')end
    local frequency=skill:getFrequency()
    if type(frequency)~='number'then ai_unsupported('Original skill frequency unknown','Original askForSkillInvoke')end
    if frequency==sgs.Skill_Frequent then return true end
    return nil
end
function SmartAI:getCardRandomly(who,flags)return r25_random_hand(self,who,flags)end

function SmartAI:askForCardChosen(who, flags, reason, method)
	local isDiscard = (method == sgs.Card_MethodDiscard)
	local key=string.gsub(reason,'%-','_');local cardchosen=sgs.ai_skill_cardchosen[key]
	local card
	if type(cardchosen) == "function" then
		card = cardchosen(self, who, flags, method)
        if AIUnsupported.is(card)then error(card,0)end
        if self:isOriginalOpaqueCardChoice(card)then return card end
		if type(card) == "number" then return card
		elseif card then return card:getEffectiveId() end
	elseif type(cardchosen) == "number" then
		sgs.ai_skill_cardchosen[key]=nil -- source consumption occurs before membership scan/error
        if who:objectName()~=self.player:objectName()and flags:find('h',1,true)then
            -- The source loop only tests unique physical IDs. A disclosed
            -- match proves membership without enumerating unrelated hidden IDs.
            for _,acard in ipairs(known(who:getKnownCards(),'Original known hand identities'))do
                if acard:getEffectiveId()==cardchosen then return cardchosen end
            end
            for _,zone in ipairs({'e','j'})do if flags:find(zone,1,true)then
                for _,acard in ipairs(who:getCards(zone))do
                    if acard:getEffectiveId()==cardchosen then return cardchosen end
                end
            end end
        end
		for _, acard in sgs.qlist(r25_cards(self,who,flags)) do
			if acard:getEffectiveId() == cardchosen then return cardchosen end
		end
	end

	if ("snatch|dismantlement"):match(reason) then
        local ctx=self:getDecisionContext()
        local request=self.request
        if (reason=='snatch'or reason=='dismantlement')and request and request.kind=='card_chosen'
            and request.options and request.options.question=='askForCardChosen'
            and ctx.who==who:objectName()and ctx.flags==flags then
            local remembered=self:readOriginalSDChoice(who,flags,reason)
            if remembered then return remembered end
        else
		local flag = "AIGlobal_SDCardChosen_" .. reason
		local to_choose
		for _, card in sgs.qlist(r25_cards(self,who,flags)) do
			if r25_card_flag(self,card,flag) then
				self:setStrategyCardFlag(card,flag,false)
				to_choose = card:getId()
				break
			end
		end
		if to_choose then return to_choose end
        end
	end

	if self:isFriend(who) then
		if flags:match("j") and not (shown(self,who,"qiaobian") and who:getHandcardNum() > 0) then
			local tricks = who:getCards("j")
			local lightning, indulgence, supply_shortage
			for _, trick in sgs.qlist(tricks) do
				if trick:isKindOf("Lightning") and (not isDiscard or self.player:canDiscard(who, trick:getId())) then
					lightning = trick:getId()
				elseif trick:isKindOf("Indulgence") and (not isDiscard or self.player:canDiscard(who, trick:getId()))  then
					indulgence = trick:getId()
				elseif not trick:isKindOf("Disaster") and (not isDiscard or self.player:canDiscard(who, trick:getId())) then
					supply_shortage = trick:getId()
				end
			end

			if self:hasWizard(self.enemies) and lightning then
				return lightning
			end

			if indulgence and supply_shortage then
				if who:getHp() < who:getHandcardNum() then
					return indulgence
				else
					return supply_shortage
				end
			end

			if indulgence or supply_shortage then
				return indulgence or supply_shortage
			end
		end

		if flags:match("e") then
			if who:getArmor() and self:evaluateArmor(who:getArmor(), who) < -5 and (not isDiscard or self.player:canDiscard(who, who:getArmor():getEffectiveId())) then
				return who:getArmor():getEffectiveId()
			end
			if original_shown_skills(self,who, sgs.lose_equip_skill) and self:isWeak(who) then
				if who:getWeapon() and (not isDiscard or self.player:canDiscard(who, who:getWeapon():getEffectiveId())) then return who:getWeapon():getEffectiveId() end
				if who:getOffensiveHorse() and (not isDiscard or self.player:canDiscard(who, who:getOffensiveHorse():getEffectiveId())) then return who:getOffensiveHorse():getEffectiveId() end
			end
		end
	else
		local dangerous = self:getDangerousCard(who)
		if flags:match("e") and dangerous and (not isDiscard or self.player:canDiscard(who, dangerous)) then return dangerous end
		if flags:match("e") and who:getTreasure() and (who:getPile("wooden_ox"):length() > 1 or who:hasTreasure("JadeSeal")) and (not isDiscard or self.player:canDiscard(who, who:getTreasure():getId())) then
			return who:getTreasure():getId()
		end
		if flags:match("e") and who:hasArmorEffect("EightDiagram") and not self:needToThrowArmor(who) and (not isDiscard or self.player:canDiscard(who, who:getArmor():getId())) then return who:getArmor():getId() end
		if flags:match("e") and original_shown_skills(self,who, "jijiu|beige|heg_weimu|heg_qingcheng") and not self:doNotDiscard(who, "e", false, 1, reason) then
			if who:getDefensiveHorse() and (not isDiscard or self.player:canDiscard(who, who:getDefensiveHorse():getEffectiveId())) then return who:getDefensiveHorse():getEffectiveId() end
			if who:getArmor() and (not isDiscard or self.player:canDiscard(who, who:getArmor():getEffectiveId())) then return who:getArmor():getEffectiveId() end
			if who:getOffensiveHorse() and (not shown(self,who,"jijiu") or who:getOffensiveHorse():isRed()) and (not isDiscard or self.player:canDiscard(who, who:getOffensiveHorse():getEffectiveId())) then
				return who:getOffensiveHorse():getEffectiveId()
			end
			if who:getWeapon() and (not shown(self,who,"jijiu") or who:getWeapon():isRed()) and (not isDiscard or self.player:canDiscard(who, who:getWeapon():getEffectiveId())) then
				return who:getWeapon():getEffectiveId()
			end
		end
		if flags:match("e") then
			local valuable = self:getValuableCard(who)
			if valuable and (not isDiscard or self.player:canDiscard(who, valuable)) then
				return valuable
			end
		end
		if flags:match("h") and (not isDiscard or self.player:canDiscard(who, "h")) then
			if original_shown_skills(self,who, "jijiu|qingnang|qiaobian|jieyin|beige")
				and not who:isKongcheng() and who:getHandcardNum() <= 2 and not self:doNotDiscard(who, "h", false, 1, reason) then
				return r25_random_hand(self,who)
			end
			if who:getHp() == 1 and not self:needKongcheng(who)
				and not who:isKongcheng() and who:getHandcardNum() <= 2 and not self:doNotDiscard(who, "h", false, 1, reason) then
				return r25_random_hand(self,who)
			end
			local cards = sgs.QList2Table(r25_known_number_cards(self,who))
			if who:getHandcardNum() <= 2 and not self:doNotDiscard(who, "h", false, 1, reason) then
				for _, cc in ipairs(cards) do
					if r25_card_visible(self,cc, who, self.player) and (cc:isKindOf("Peach") or cc:isKindOf("Analeptic")) then
						return r25_random_hand(self,who)
					end
				end
			end
		end

		if flags:match("j") then
			local tricks = who:getCards("j")
			local lightning
			for _, trick in sgs.qlist(tricks) do
				if trick:isKindOf("Lightning") and (not isDiscard or self.player:canDiscard(who, trick:getId())) then
					lightning = trick:getId()
				end
			end
			if self:hasWizard(self.enemies, true) and lightning then
				return lightning
			end
		end

		if flags:match("h") and not self:doNotDiscard(who, "h") then
			if (who:getHandcardNum() == 1 and self:originalHegemonyGetDefenseSlash(who) < 3 and who:getHp() <= 2) or original_shown_skills(self,who, sgs.cardneed_skill) then
				return r25_random_hand(self,who)
			end
		end

		if flags:match("e") and not self:doNotDiscard(who, "e") then
			if who:getDefensiveHorse() and (not isDiscard or self.player:canDiscard(who, who:getDefensiveHorse():getEffectiveId())) then return who:getDefensiveHorse():getEffectiveId() end
			if who:getArmor() and not self:needToThrowArmor(who) and (not isDiscard or self.player:canDiscard(who, who:getArmor():getEffectiveId())) then return who:getArmor():getEffectiveId() end
			if who:getOffensiveHorse() and (not isDiscard or self.player:canDiscard(who, who:getOffensiveHorse():getEffectiveId())) then return who:getOffensiveHorse():getEffectiveId() end
			if who:getWeapon() and (not isDiscard or self.player:canDiscard(who, who:getWeapon():getEffectiveId())) then return who:getWeapon():getEffectiveId() end
			if who:getTreasure() and (not isDiscard or self.player:canDiscard(who, who:getTreasure():getEffectiveId())) then return who:getTreasure():getEffectiveId() end
		end

		if flags:match("h") then
			if (not who:isKongcheng() and who:getHandcardNum() <= 2) and not self:doNotDiscard(who, "h", false, 1, reason) then
				return r25_random_hand(self,who)
			end
		end
	end
	return -1
end

function SmartAI:askForAG(card_ids, refusable, reason)
	local cardchosen = sgs.ai_skill_askforag[string.gsub(reason, "%-", "_")]
	if type(cardchosen) == "function" then
		local card_id = cardchosen(self, card_ids)
		if card_id then return card_id end
	end

	local ids = card_ids
	local cards = {}
	for _, id in ipairs(ids) do
		table.insert(cards, r25_card(self,id))
	end
	for _, card in ipairs(cards) do
		if card:isKindOf("Peach") then return card:getEffectiveId() end
	end
	for _, card in ipairs(cards) do
		if card:isKindOf("Indulgence") and not (self:isWeak() and self:getCardsNum("Jink") == 0) then return card:getEffectiveId() end
		if card:isKindOf("AOE") and not (self:isWeak() and self:getCardsNum("Jink") == 0) then return card:getEffectiveId() end
	end
	self:sortByCardNeed(cards, true)

	return cards[1]:getEffectiveId()
end


for name,body in pairs(SmartAI)do local old=SmartAIView[name];SmartAIView[name]=function(self,...)
 if not original_enabled(self)then if old then return old(self,...)end;ai_unsupported('ordinary helper unavailable',name)end
 r25_restore(self);return body(self,...)
end end
end
