local jinghe_skill = {}
jinghe_skill.name = "heg_jinghe"
table.insert(sgs.ai_skills, jinghe_skill)
jinghe_skill.getTurnUseCard = function(self,options,request)
    local inclusive=(options or {}).inclusive

	if self.player:isKongcheng() or self.player:getStrategyHasUsed("HJingheCard") then return end
	local jinghe_show = {}
	local num = math.min(#self.friends, self.player:getMaxHp())

	local function canJingheShow(to_select)
		for _, id in ipairs(jinghe_show) do
			local selected = r25_card(self,id)
			if to_select:isKindOf("Slash") and selected:isKindOf("Slash") then
				return false
			end
			if to_select:isKindOf("Nullification") and selected:isKindOf("Nullification") then
				return false
			end
			if to_select:objectName() == selected:objectName() then
				return false
			end
		end
		return true
	end

	local cards = self.player:getHandcards()
	cards = sgs.QList2Table(cards)
	self:sortByUseValue(cards, true)
	for _, c in ipairs(cards) do
		if #jinghe_show < num and canJingheShow(c) then
			table.insert(jinghe_show, c:getKnownId())
		end
	end
	return r26_parse(self,"@HJingheCard=" .. table.concat(jinghe_show, "+") .."&heg_jinghe")
end

ai_card_use.HJingheCard = function(self,card,use)
	use.card = card
	if use.to then
		for _, p in ipairs(self.friends) do
			if r26_public_friend(self.player,p) and known(heg_player(self,p).shown_one,"shown_one") and use.to:length() < card:subcardsLength() then
				use.to:append(p)
			end
		end
		for _, p in ipairs(self.friends) do
			if not use.to:contains(p) and known(heg_player(self,p).shown_one,"shown_one") and use.to:length() < card:subcardsLength() then
				use.to:append(p)
			end
		end
	end
end

sgs.ai_card_intention.HJingheCard = -90
sgs.ai_use_priority.HJingheCard = 9.23

ai_skill_choice.jinghe_skill = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end
    local data=request and self:getDecisionData(request) or nil


	local current = self.room:getCurrent()
	local objnames = r26_context(self,"JingheTargets","String"):split("+")
	local targets = {}
	for _, friend in ipairs(self.friends_noself) do
		if table.contains(objnames, friend:objectName()) and self:playerGetRound(friend) > self:playerGetRound(self.player) then
			table.insert(targets, friend)
		end
	end

	choices = choices:split("+")
	table.removeOne(choices, "cancel")
	if table.contains(choices, "heg_yanzheng") then
		if self.player:objectName() == current:objectName() and #choices > 1 then
			table.removeOne(choices, "heg_yanzheng")
		end
	end
	if table.contains(choices, "heg_leiji_tianshu") then
		if self.player:hasSkills(sgs.wizard_skill) then
			return  ai_choice_result(("heg_leiji_tianshu"),options)
		end
		for _, p in ipairs(targets) do
			if p:hasSkills(sgs.wizard_skill) and #choices > 1 then
				table.removeOne(choices, "heg_leiji_tianshu")
			end
		end
	end
	if table.contains(choices, "heg_yinbing")then
		if hegemony_source_query(self,'hasCrossbowEffect') or self:getCardsNum("Crossbow") > 0 then
			return  ai_choice_result(("heg_yinbing"),options)
		end
		for _, p in ipairs(targets) do
			if (hegemony_source_query(self,'hasCrossbowEffect',p) or self:originalHegemonyKnownCard(p, self.player, "Crossbow", false) > 0) and #choices > 1 then
				table.removeOne(choices, "heg_yinbing")
			end
		end
	end
	if table.contains(choices, "heg_yinbing")then
		if self.player:hasSkills(sgs.force_slash_skill) then
			return  ai_choice_result(("heg_yinbing"),options)
		end
		for _, p in ipairs(targets) do
			if p:hasSkills(sgs.force_slash_skill) and #choices > 1 then
				table.removeOne(choices, "heg_yinbing")
			end
		end
	end
	if table.contains(choices, "heg_guizhu") then
		if self.player:hasSkills("jijiu|heg_zhendu|heg_xishe") then
			return  ai_choice_result(("heg_guizhu"),options)
		end
		for _, p in ipairs(targets) do
			if p:hasSkills("jijiu|heg_zhendu|heg_xishe") and #choices > 1 then
				table.removeOne(choices, "heg_guizhu")
			end
		end
	end
	if table.contains(choices, "heg_yanzheng") then
		local yanzheng_card = sgs.ai_skill_exchange.heg_yanzheng(self)
		if #yanzheng_card > 0 and not hegemony_source_query(self,'isWeak') then
			return  ai_choice_result(("heg_yanzheng"),options)
		end
	end
	if table.contains(choices, "heg_huoqi") then
		local min_hp = 99
		for _, p in sgs.qlist(self.room:getAlivePlayers()) do
			if p:getHp() < min_hp then
				min_hp = p:getHp()
			end
		end
		if self.player:getHp() == min_hp and r26_can_recover(self,self.player) then
			return  ai_choice_result(("heg_huoqi"),options)
		end
	end
	if table.contains(choices, "heg_xianshou") and not self.player:isWounded() then
		return  ai_choice_result(("heg_xianshou"),options)
	end
	if table.contains(choices, "heg_lundao") and self.player:getHandcardNum() < 3 then
		return  ai_choice_result(("heg_lundao"),options)
	end
	if table.contains(choices, "heg_guanyue") then
		return  ai_choice_result(("heg_guanyue"),options)
	end
	return  ai_choice_result((choices[math.random(1, #choices)]),options)
end

sgs.ai_skill_playerchosen.heg_leiji_tianshu = function(self, targets)
	self:updatePlayers()
	if not self:willShowForAttack() then return nil end
	local getCmpValue = function(enemy)
		local value = 0
		local damage = {}
		damage.to = enemy
		damage.from = self.player
		damage.nature = sgs.DamageStruct_Thunder
		damage.damage = 2
		if not self:damageIsEffective_(damage) then return 99 end
		if shown(self,enemy,"hongyan") then return 99 end
		if self:cantbeHurt(enemy, self.player, 2) or self:objectiveLevel(enemy) < 3
			or (enemy:isChained() and not self:originalHegemonyChainTargetStruct(damage)) then return 100 end
		if not r26_good_target(self,enemy, self.enemies, self) then value = value + 50 end
		if enemy:hasArmorEffect("SilverLion") then value = value + 20 end
		if original_shown_skills(self,enemy, sgs.exclusive_skill) then value = value + 10 end
		if original_shown_skills(self,enemy, sgs.masochism_skill) then value = value + 5 end
		if enemy:isChained() and self:originalHegemonyChainTargetStruct(damage) and #(self:getChainedEnemies(self.player)) > 1 then value = value - 25 end
		if enemy:isLord() then value = value - 5 end
		value = value + enemy:getHp() + r26_defense_slash(self,enemy, self) * 0.01
		return value
	end

	local cmp = function(a, b)
		return getCmpValue(a) < getCmpValue(b)
	end

	local enemies = self.enemies
	table.sort(enemies, cmp)
	for _, enemy in ipairs(enemies) do
		if getCmpValue(enemy) < 100 then return enemy end
	end
end

function sgs.ai_slash_prohibit.heg_leiji_tianshu(self, from, to, card)
	if self:isFriend(to,from) then return false end
	if self:canLiegong(to, from) then return false end
	if not original_shown_skills(self,to, sgs.wizard_skill) then return false end
	if original_shown_skills(self,from, "heg_tieqi|heg_tieqi_xh") then return false end
	if shown(self,from,"tenyearjianchu") and (to:hasEquip() or to:getCardCount(true) == 1) then
		return false
	end
	if (hegemony_source_query(to,'getMark',"##heg_qianxi+no_suit_red") + hegemony_source_query(to,'getMark',"##heg_qianxi+no_suit_black") > 0) and (not self:hasEightDiagramEffect(to) or self:ignoreArmor(from, to)) then
		return false
	end
	local hcard = to:getHandcardNum()
	if (from:getHp() >= 4 and (self:originalHegemonyCardsNum("Peach", from, to) > 0 or shown(self,from,"heg_ganglie"))) or shown(self,from,"hongyan") and #self.friends == 1 then
		return false
	end
	if self:getOriginalHegemonyCardLack(to,"Jink") == 2 then return true end
	if self:originalHegemonyKnownCard(to, self.room:getCurrent(), "Jink", true) >= 1 or (self:hasSuit("spade", true, to) and hcard >= 2) or hcard >= 4 then return true end
	if self:hasEightDiagramEffect(to) then return true end
end

