sgs.ai_skill_exchange.heg_yanzheng = function(self,pattern,max_num,min_num,expand_pile)
	if self.player:isKongcheng() then
		return {}
	end
	local can_yanzheng = false
	local valuable_num = 0
	local enemy_weak = 0
	local discard_num = self.player:getHandcardNum() - 1
	local cards = self.player:getCards("h")
	cards = sgs.QList2Table(cards)
	self:sortByUseValue(cards)
	for _, card in ipairs(cards) do
		if (self:isCard("HBefriendAttacking", card, self.player) or self:isCard("ExNihilo", card, self.player) or self:isCard("HThreatenEmperor", card, self.player))
		and card:isAvailable(self.player) then
			valuable_num = valuable_num + 1
		end
		if hegemony_source_query(self,'hasCrossbowEffect') and self:isCard("Slash", card, self.player) then
			valuable_num = valuable_num + 1
		end
	end
	for _, card in ipairs(cards) do
		if (self:isCard("HAllianceFeast", card, self.player) or self:isCard("Peach", card, self.player)) and card:isAvailable(self.player) then
			valuable_num = valuable_num + 1
			if hegemony_source_query(self,'isWeak') and valuable_num > 1 then
				valuable_num = valuable_num + 1
			end
		end
	end
	if #self.enemies > 0 then
		for _, p in ipairs(self.enemies) do
			if p:getHp() == 1 and hegemony_source_query(self,'isWeak',p) then
				enemy_weak = enemy_weak + 1
			end
		end
		if self.player:hasSkill("lirang") or (valuable_num < 2) or (valuable_num < 3 and enemy_weak > 0)
		and (discard_num <= #self.enemies + 2 or (discard_num >= enemy_weak and enemy_weak > 1)) then
			can_yanzheng = true
		end
	end
	if can_yanzheng then
		return {cards[1]:getEffectiveId()}
	end
	return {}
end

