ai_skill_invoke.heg_sidi = function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

    if not self:willShowForDefence() then
        return (false) or false 
    end
    local target = data:toPlayer()
    if not self:isFriend(target) then
        return (true) or false 
    end
    local num = 0
    for _, card in sgs.qlist(target:getHandcards()) do
		if not r25_card_visible(self,card, target, self.player)
        or not (self:isCard("Peach", card, self.player) or (card:isKindOf("Analeptic") and target:getHp() == 1)) then
			num = num + 1
		end
	end
    if hegemony_source_query(self,'needToThrowArmor',target) then
        num = num + 1
    end
    if target:getWeapon() and target:getOffensiveHorse() then
        num = num + 1
    end
    if num == 0 then
        return (false) or false 
    end
    return (true) or false 
end

sgs.ai_skill_exchange.heg_sidi = function(self,pattern,max_num,min_num,expand_pile)
    self.sidi_recover = nil
    self.sidi_skill = nil
    self.sidi_cardtype = nil

    local drivecards = {}
    local drivetypes = {}
    for _, id in sgs.qlist(self.player:getPile(expand_pile)) do
        local card = r25_card(self,id)
        table.insert(drivecards, card)
        table.insert(drivetypes, sgs.ai_type_name[card:getTypeId() + 1])
    end

    local current = self.room:getCurrent()
    if self:isFriend(current) then
        self:sortInPlace(self.friends, "hp")
        for _, friend in ipairs(self.friends) do
            if r26_public_friend(self.player,friend) and friend:getHp() == 1 then
                self.sidi_recover = true
                for _, c in ipairs(drivecards) do
                    if sgs.ai_type_name[c:getTypeId() + 1] == "EquipCard" then
                        return c:getKnownId()
                    end
                end
                return drivecards[1]:getId()
            end
        end
    end
    if self:isEnemy(current) and (not self:willSkipPlayPhase(current) or self.player:getPile("drive"):length() > 2) then

        if self:originalHegemonyCardsNum("TrickCard", current, self.player) > (shown(self,current,"heg_jizhi") and 1 or 2)
        or (original_shown_skills(self,current, "heg_guose|heg_luanji|heg_guishu") and current:getHandcardNum() > 1)
        or (shown(self,current,"heg_jixi") and current:getPile("field"):length() > 1)
        or (original_shown_skills(self,current, "heg_qice|heg_yigui")) then
            if table.contains(drivetypes, "TrickCard") then
                self.sidi_cardtype = "TrickCard"
            end
        end
        if original_shown_skills(self,current, "heg_diaodu+heg_xiaoji|heg_diaodu+heg_xuanlue") then
            if table.contains(drivetypes, "EquipCard") then
                self.sidi_cardtype = "EquipCard"
            end
        end
        if (current:getHp() == 1 and hegemony_source_query(self,'isWeak',current) and hegemony_source_query(current,'getMark',"GlobalBattleRoyalMode") == 0)
        or ((hegemony_source_query(self,'hasCrossbowEffect',current) or original_shown_skills(self,current, sgs.force_slash_skill))
                and self:originalHegemonyCardsNum("Slash", current, self.player) >= 1) then
            if table.contains(drivetypes, "BasicCard") then
                self.sidi_cardtype = "BasicCard"
            end
        end
        for _, friend in ipairs(self.friends) do
            if current:canSlash(friend,nil,true) and r26_defense_slash(self,friend, self) <= 2 then
                if table.contains(drivetypes, "BasicCard") then
                    self.sidi_cardtype = "BasicCard"
                end
                break
            end
        end

        local function findskill(skills)
            for _, skill in ipairs(skills:split("|")) do
                if shown(self,current,skill) then
                    return skill
                end
            end
            return nil
        end
        local sidi_firstskills =
"heg_suzhi|heg_jinghe|heg_miewu|heg_jieyue|heg_jili|heg_tongdu|chuli|wansha|heg_zaoyun|heg_jinfa|heg_yingzi_zhouyu|heg_zhukou|heg_boyan"
        self.sidi_skill = findskill(sidi_firstskills)
        if original_shown_skills(self,current, sgs.lose_equip_skill.."|heg_diaodu") and (not self.sidi_cardtype or self.sidi_cardtype ~= "EquipCard") then
            
        end
        if original_shown_skills(self,current, "heg_luanji|heg_guose|heg_jixi|heg_qice|heg_yigui|heg_guishu") and (not self.sidi_cardtype or self.sidi_cardtype ~= "TrickCard") then
            self.sidi_skill = findskill("heg_luanji|heg_guose|heg_jixi|heg_qice|heg_yigui|heg_guishu")
        end
        if original_shown_skills(self,current, "heg_paoxiao|tenyearkuanggu|heg_kuangcai") and (not self.sidi_cardtype or self.sidi_cardtype ~= "BasicCard") then
            self.sidi_skill = findskill("heg_paoxiao|tenyearkuanggu|heg_kuangcai")
        end
        if shown(self,current,"heg_hongfa") and current:getPile("heavenly_army"):isEmpty()
        and r25_kingdom_count(self,"qun") > 1 then
            self.sidi_skill = "heg_hongfa"
        end
        if shown(self,current,"heg_jiahe") and not current:getPile("flame_map"):isEmpty() then
            self.sidi_skill = "heg_jiahe"
        end
        if shown(self,current,"heg_zisui") and current:getPile("&disloyalty"):length() > 2 then
            self.sidi_skill = "heg_zisui"
        end
        if shown(self,current,"heg_xiongnve") and hegemony_source_query(current,'getMark',"#massacre") > (hegemony_source_query(self,'isWeak',current) and 1 or 3) then
            self.sidi_skill = "heg_xiongnve"
        end
        if shown(self,current,"heg_paiyi") and current:getPile("power_pile"):length() > 3 then
            self.sidi_skill = "heg_paiyi"
        end
    end

    local weis = {}
    for _, friend in ipairs(self.friends) do
        if r26_public_friend(self.player,friend) and r26_can_recover(self,friend) then
            table.insert(weis, friend)
        end
    end
    if #weis > 0 then
        local allweak = true
        for _, p in ipairs(weis) do
            if p:getHp() > 2 then
                allweak = false
            end
        end
        if allweak or hegemony_source_query(self.player,'getMark',"GlobalBattleRoyalMode") > 0 then
            self.sidi_recover = true
        end
    end

    local sidi_max = (self.sidi_recover and 1 or 0) + (self.sidi_skill and 1 or 0) + (self.sidi_cardtype and 1 or 0)
    sidi_max = math.min(sidi_max, #drivecards, max_num)
    local discards = {}
    if self.sidi_cardtype then
        for _, c in ipairs(drivecards) do
            if sgs.ai_type_name[c:getTypeId() + 1] == self.sidi_cardtype then
                table.insert(discards, c:getKnownId())
                break
            end
        end
    else
        for _, c in ipairs(drivecards) do
            if sgs.ai_type_name[c:getTypeId() + 1] ~= "BasicCard" and #discards < sidi_max then
                table.insert(discards, c:getKnownId())
            end
        end
    end
    for _, c in ipairs(drivecards) do
        if #discards < sidi_max and not table.contains(discards, c:getKnownId()) then
            table.insert(discards, c:getKnownId())
        end
    end
    return discards
end

sgs.ai_skill_exchange.sidi_put = function(self,pattern,max_num,min_num,expand_pile)
    local cards = self.player:getCards("he")
	cards = sgs.QList2Table(cards)
    if self.player:getPhase() <= sgs.Player_Play then
		self:sortByUseValue(cards, true)
	else
		self:sortByKeepValue(cards)
	end
    if self:isCard("Peach", cards[1], self.player) or (cards[1]:isKindOf("Analeptic") and self.player:getHp() == 1) then
        return {}
    end
    if self:matchesDiscardPattern(pattern,cards[1]) then
        return cards[1]:getEffectiveId()
    end
    return {}
end

ai_skill_choice["sidi_choice"] = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end
    local data=request and self:getDecisionData(request) or nil


    choices = choices:split("+")
    if hegemony_source_query(self.player,'getMark',"GlobalBattleRoyalMode") > 0 and self.sidi_recover and table.contains(choices, "recover") then
        return  ai_choice_result(("recover"),options)
    end
    if self.sidi_cardtype and table.contains(choices, "cardlimit") then
        return  ai_choice_result(("cardlimit"),options)
    end
    if self.sidi_skill and table.contains(choices, "skilllimit") then
        return  ai_choice_result(("skilllimit"),options)
    end
    if self.sidi_recover and table.contains(choices, "recover") then
        return  ai_choice_result(("recover"),options)
    end
    return  ai_choice_result((choices[math.random(1, #choices)]),options)
end

sgs.ai_skill_playerchosen["sidi_recover"] = function(self, targets)

    targets = sgs.QList2Table(targets)
    if self:isFriend(targets[1]) then
        self:sortInPlace(targets, "hp")
        return targets[1]
    else
        self:sortInPlace(targets, "hp", true)
        for _, p in ipairs(targets) do
            if not original_shown_skills(self,p, sgs.priority_skill) and p:getHp() > 1 then
                return p
            end
        end
        return targets[1]
    end
end

ai_skill_choice["sidi_skill"] = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end
    local data=request and self:getDecisionData(request) or nil


    choices = choices:split("+")
    if self.sidi_skill and table.contains(choices, self.sidi_skill) then

        return  ai_choice_result((self.sidi_skill),options)
    end
    return  ai_choice_result((choices[math.random(1, #choices)]),options)
end

ai_skill_choice["sidi_cardtype"] = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end
    local data=request and self:getDecisionData(request) or nil


    choices = choices:split("+")
    if self.sidi_cardtype and table.contains(choices, self.sidi_cardtype) then

        return  ai_choice_result((self.sidi_cardtype),options)
    end
    return  ai_choice_result((choices[math.random(1, #choices)]),options)
end

