ai_card_use.HHongyuanCard = function(self,hycard,use)
	local targets = AIList.new{}
    local friends = {}
    for _, p in ipairs(self.friends_noself) do
		if self:cardTargetFilter(hycard,targets,p)  then
			table.insert(friends, p)
		end
	end
	if #friends > 0 then
        local cards = sgs.QList2Table(self.player:getHandcards())
	    self:sortByUseValue(cards, true)
		local card, friend = self:getCardNeedPlayer(cards, friends, "heg_hongyuan")
		if card and friend then
            use.card = r26_parse(self,"@HHongyuanCard=" .. card:getKnownId() .. "&heg_hongyuan")

            return
		end
	end
end

