sgs.ai_skill_playerchosen.qinzhong = function(self, targets)
    targets = sgs.QList2Table(targets)
    for _, p in ipairs(targets) do
        if shown(self,p,"heg_hunshang") and self.player:getHp() == 1 then
            return p
        end
    end

    local function g2value(player)
        local g2name = r25_player_general(self,player, false):objectName()
        return sgs.general_value[g2name] or 0
    end

    local myg2_value = g2value(self.player)
    self:sortInPlace(targets, "hp")
    for _, p in ipairs(targets) do
        if self.player:getHp() >= p:getHp() and myg2_value < g2value(p) then
            return p
        end
    end
    return {}
end

ai_skill_use["@@zhaofu1"] = function(self, prompt, request)
    if not self:willShowForAttack() then return "." end

    local cards = self.player:getCards("he")
	cards = sgs.QList2Table(cards)
	self:sortByUseValue(cards, true)

    local card
    for _, acard in ipairs(cards) do
		if not self:isValuableCard(acard) then
			card = acard
            break
		end
	end

    local targets = {}
    for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
        table.insert(targets, p)
    end

    local compare_func = function(a, b)
		return (a:getHandcardNum() + math.min(1.5, a:getHp() / 2))
            > (b:getHandcardNum() + math.min(1.5, b:getHp() / 2))
	end
    table.sort(targets, compare_func)

    local target
    for _, p in ipairs(targets) do
        if not self:willSkipPlayPhase(p) and hegemony_source_query(p,'getMark',"#reward") < 2 then
            target = p
            break
        end
    end

    if card and target then
        return "@ZhaofuCard=" .. card:getKnownEffectiveId() .. "->" .. target:objectName()
    end
    return "."
end

ai_skill_invoke.zhaofu = function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

    local prompt_list = data:toString():split(":")
    local card_name = prompt_list[4]

    if card_name:match("analeptic") then
        return (false) or false 
    end
    local clonecard = r26_clone(self,card_name)
    local dummyuse = { isDummy = true, to = AIList.new{} }
    self:useCardByClassName(clonecard, dummyuse)
    if dummyuse.card then
        return (true) or false 
    end
    return (false) or false 
end

ai_skill_use["@@zhaofu2"] = function(self, prompt, request)
    local card_name = prompt:split(":")[4]

    local clonecard = r26_clone(self,card_name)
    if self:getUseValue(clonecard) >= 5.2
    or card_name == "duel"
    or (hegemony_source_query(self.player,'getMark',"GlobalBattleRoyalMode") > 0 and (card_name == "slash" or card_name == "fire_slash"or card_name == "thunder_slash")) then
        local dummyuse = { isDummy = true, to = AIList.new{} }
        self:useCardByClassName(clonecard, dummyuse)
        if dummyuse.card and not dummyuse.to:isEmpty() then
            local target_objectname = {}
            for _, p in sgs.qlist(dummyuse.to) do
                table.insert(target_objectname, p:objectName())
            end
            return "@ZhaofuVSCard=.&->" .. table.concat(target_objectname, "+")
        end
    end
    return "."
end

