sgs.ai_skill_playerchosen.huxun = function(self, _targets, max_num, min_num)

	self:sortInPlace(self.enemies, "defense")
		for _, friend in ipairs(self.friends) do
			if not friend:getCards("j"):isEmpty() and self:getMoveCardorTarget(friend, ".", "e") then
				return {friend, self:getMoveCardorTarget(friend, "target", "e")}
			end
		end

		for _, friend in ipairs(self.friends_noself) do
			if friend:hasEquip() and original_shown_skills(self,friend, sgs.lose_equip_skill) and self:getMoveCardorTarget(friend, ".", "e") then
				return {friend, self:getMoveCardorTarget(friend, "target", "e")}
			end
		end

		local targets = {}
		for _, enemy in sgs.qlist(self.room:getAlivePlayers()) do
			if not r26_public_friend(self.player,enemy) and self:getMoveCardorTarget(enemy, "." ,"e") then
				table.insert(targets, enemy)
			end
		end

		if #targets > 0 then
			self:sortInPlace(targets, "defense")
			return {targets[#targets], self:getMoveCardorTarget(targets[#targets], "target", "e")}
		end

		if self.player:hasEquip() and original_shown_skills(self,self.player, sgs.lose_equip_skill) and self:getMoveCardorTarget(self.player, ".", "e") then
			return {self.player, self:getMoveCardorTarget(self.player, "target" ,"e")}
		end

		local friends = {}
		for _, friend in ipairs(self.friends) do
			if self:getMoveCardorTarget(friend, "." ,"e") then
				table.insert(friends, friend)
			end
		end

		if #friends > 0 then
			self:sortInPlace(friends, "hp", true)
			return {friends[#friends], self:getMoveCardorTarget(friends[#friends], "target", "e")}
		end

	return {}
end

sgs.ai_skill_transfercardchosen.huxun = function(self, targets, equipArea, judgingArea)
	return self:getMoveCardorTarget(targets:first(), "card", "e")
end

sgs.ai_skill_exchange["yuancong_give"] = function(self,pattern,max_num,min_num,expand_pile)
    local num = hegemony_source_query(self,'getOverflow')
    if num > 0 then
        local cards = self.player:getCards("h")
        cards = sgs.QList2Table(cards)
        self:sortByKeepValue(cards)
        return cards[num]:getEffectiveId()
    end
    local chengpu = original_find_shown(self,"yuancong")
    if chengpu then
        if self.player:getHp() > 1 and self:getCardsNum("Analeptic") > 0 then
            return self:getCard("Analeptic"):getEffectiveId()
          end
        if not hegemony_source_query(self,'isWeak') and self:getCardsNum("Peach") > 1 then
            return self:getCard("Peach"):getEffectiveId()
        end
        local c, friend = self:getCardNeedPlayer(sgs.QList2Table(self.player:getCards("he")), {chengpu})
        if friend and friend:objectName() == chengpu:objectName() then
            return c:getKnownEffectiveId()
        end
        if self:getCardsNum("Slash") > 0 then
            return self:getCard("Slash"):getEffectiveId()
        end
        
    end
    return {}
end

ai_skill_use["@@yuancong_usecard"] = function(self, prompt, request)
    local cards = self.player:getCards("h")
	for _, id in sgs.qlist(self.player:getHandPile()) do
		cards:prepend(r25_card(self,id))
	end
	cards = sgs.QList2Table(cards)
	self:sortByUseValue(cards)

    for _, card in ipairs(cards) do
        local dummyuse = { isDummy = true }
        if not card:targetFixed() then
            dummyuse.to = AIList.new{}
        end
        local type = card:getTypeId()
        self["use" .. sgs.ai_type_name[type + 1]](self, card, dummyuse)

        if dummyuse.card and not card:isKindOf("Analeptic") then

            if not card:targetFixed() then
                if dummyuse.to and not dummyuse.to:isEmpty() then
                    local target_objectname = {}
                    for _, p in sgs.qlist(dummyuse.to) do
                        table.insert(target_objectname, p:objectName())
                    end
                    return card:getLegacyStringKey() .."->" .. table.concat(target_objectname, "+")
                else
                    return "."
                end
            end
            return card:getLegacyStringKey()
        end
    end
    return "."
end

local shefu_skill = {}
shefu_skill.name = "shefu"
table.insert(sgs.ai_skills, shefu_skill)
shefu_skill.getTurnUseCard = function(self,options,request)
    local inclusive=(options or {}).inclusive

    if self.player:getStrategyHasUsed("ShefuCard") then return end
    if self.player:isKongcheng() then return end

    local index = hegemony_source_query(self,'getOverflow')
    if index > 0 or self.player:getHandcardNum() > 2 then
        local cards = self.player:getHandcards()
        cards = sgs.QList2Table(cards)
        self:sortByUseValue(cards, true)
        if index > 1 then
            return r26_parse(self,"@ShefuCard=" .. cards[index]:getEffectiveId() .."&shefu")

        else
            return r26_parse(self,"@ShefuCard=" .. cards[1]:getEffectiveId() .."&shefu")
        end
    end
end

ai_card_use.ShefuCard = function(self,card,use)
	use.card = card
end

sgs.ai_use_priority.ShefuCard = 0.3

sgs.ai_skill_exchange.shefu = function(self,pattern,max_num,min_num,expand_pile)
    local use = r26_context(self,"ShefuUsedata","CardUse")
    local response = r26_context(self,"ShefuUsedata","CardResponse")

    if response then

        local card = response.m_card
        local who = response.m_who
        if card and who and self:isEnemy(who) and (card:isKindOf("Nullification") or card:isKindOf("Jink")) then
            for _, id in sgs.qlist(self.player:getPile(expand_pile)) do
                local c = r25_card(self,id)
                if self:matchesDiscardPattern(pattern,c) then
                    return c:getKnownEffectiveId()
                end
            end
        end
    end
    if use then

        local card = use.card
        local from = use.from
        local to = use.to
        if card and from and self:isEnemy(from) then
            for _, id in sgs.qlist(self.player:getPile(expand_pile)) do
                local c = r25_card(self,id)
                if self:matchesDiscardPattern(pattern,c) then
                    return c:getKnownEffectiveId()
                end
            end
        end
    end
    return {}
end

sgs.ai_skill_exchange["shefu_remove"] = function(self,pattern,max_num,min_num,expand_pile)
    local result = {}
    local ambushcards = {}
    for _, id in sgs.qlist(self.player:getPile(expand_pile)) do
        local card = r25_card(self,id)
        table.insert(ambushcards, card)
    end
    self:sortByUseValue(ambushcards, true)
    for _, c in ipairs(ambushcards) do
        if c:getTypeId() == sgs.Card_TypeEquip then
            table.insert(result, c)
        end
        if #result == min_num then
            return result
        end
    end
    for _, c in ipairs(ambushcards) do
        if c:getTypeId() == sgs.Card_TypeTrick then
            table.insert(result, c)
        end
        if #result == min_num then
            return result
        end
    end
    for _, c in ipairs(ambushcards) do
        table.insert(result, c)
        if #result == min_num then
            return result
        end
    end
end

ai_skill_invoke.benyu = function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

	if not self:willShowForMasochism() then return (false) or false  end
    
	return (true) or false 
end

ai_skill_choice.benyu = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end
    local data=request and self:getDecisionData(request) or nil

    local target = data:toPlayer()
    if target and not self:isFriend(target) then
        if self.player:getHandcardNum() >= 5 then

            return  ai_choice_result(("discard"),options)
        end
        if target:getHandcardNum() > 5 then
            local difference = target:getHandcardNum() - self.player:getHandcardNum()
            if (difference > 2 and self:slashIsAvailable(target)) or not hegemony_source_query(self,'isWeak') or self:getCardsNum({"Peach", "Analeptic"}) > 0 then

                return  ai_choice_result(("discard"),options)
            end
        end
    end
    return  ai_choice_result(("draw"),options)
end

