sgs.ai_skill_playerchosen.heg_tanfeng = function(self, targets)
	local need_skip_judge = false
	local need_skip_discard = (hegemony_source_query(self,'getOverflow') > 1 and not self.player:hasSkills("heg_shensu|qiaobian") and not self.player:isSkipped(sgs.Player_Discard))
	local Nullification = false
	for _, p in ipairs(self.friends) do
		if self:originalHegemonyKnownCard(p, self.player, "Nullification") > 0 then
			Nullification = true
		end
	end
	local supply_shortage = (current:containsTrick("supply_shortage") and (not self:hasWizard(self.friends) or self:hasWizard(self.enemies, true)))
	local indulgence = (current:containsTrick("indulgence") and self:getFinalRetrial() ~= 1 and hegemony_source_query(self,'getOverflow',current) > -1)
	if (indulgence or supply_shortage) and not Nullification and not self.player:isSkipped(sgs.Player_Judge) then
		need_skip_judge = true
	end
	if need_skip_judge or need_skip_discard then
		targets = sgs.QList2Table(targets)
		self:sortInPlace(targets, "hp", true)
		for _, p in ipairs(targets) do
			if self:isFriend(p) and (self:needDamagedEffects(p, self.player) or self:needToLoseHp())
				and self:damageIsEffective(p, sgs.DamageStruct_Fire, self.player)then
				return p
			end
		end
		for _, p in ipairs(targets) do
			if self:isFriend(p) and not self:damageIsEffective(p, sgs.DamageStruct_Fire, self.player) then
				return p
			end
		end
		
	end
	local prevent_skip = ((self.player:hasSkill("heg_jieyue") and self.player:getHandcardNum() > 1 and not self.player:isSkipped(sgs.Player_Draw))
						or (self.player:hasSkills("heg_wangxi|heg_qice|heg_mingfa|heg_daoshu|heg_zaoyun") and not self.player:isSkipped(sgs.Player_Play)))
	local dis_targets = {}
	for _, p in ipairs(targets) do
		if self:isFriend(p) then
			table.insert(dis_targets, p)
		elseif self:isEnemy(p) and not self:cantbeHurt(p) and self:damageIsEffective(p, sgs.DamageStruct_Fire, self.player)
			and not self:needDamagedEffects(p, self.player) and not self:needToLoseHp(p) and not prevent_skip then
			table.insert(dis_targets, p)
		end
	end
	if not next(dis_targets) then return nil end
	return self:findPlayerToDiscard("ej", false, sgs.Card_MethodDiscard, dis_targets, false)
end

sgs.ai_skill_cardchosen.heg_tanfeng = function(self, who, flags, method, disable_list)
	
	local armor = who:getArmor()
	if self:isFriend(who) then
		if armor and armor:objectName() == "Vine" then return armor:getKnownEffectiveId() end
	else
		
		if armor and armor:objectName() == "PeaceSpell" then return armor:getKnownEffectiveId() end
	end
	return self:askForCardChosen(who, flags, "tanfeng_dismantlement", method, disable_list)
end

ai_skill_choice.heg_tanfeng = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end

	
	local current = self.room:getCurrent()
	if not current then return  ai_choice_result(("cancel"),options) end
	
	if self:isFriend(current) then
		local need_skip_judge = false
		local Nullification = false
		for _, p in ipairs(self.friends) do
			if self:originalHegemonyKnownCard(p, self.player, "Nullification") > 0 then
				Nullification = true
			end
		end
		local supply_shortage = (current:containsTrick("supply_shortage") and (not self:hasWizard(self.friends) or self:hasWizard(self.enemies, true)))
		local indulgence = (current:containsTrick("indulgence") and self:getFinalRetrial() ~= 1 and hegemony_source_query(self,'getOverflow',current) > -1)
		if (indulgence or supply_shortage) and string.find(choices, "judge") and not Nullification and not self.player:isSkipped(sgs.Player_Judge) then
			need_skip_judge = true
		end
		local is_weak = hegemony_source_query(self,'isWeak') and self:damageIsEffective(self.player, sgs.DamageStruct_Fire, current)
			and not (self:needDamagedEffects(self.player, current) or self:needToLoseHp())
		if not is_weak then
			if need_skip_judge then return  ai_choice_result(("judge"),options) end
			if hegemony_source_query(self,'getOverflow',current) > 0 and not current:isSkipped(sgs.Player_Discard) and string.find(choices, "discard") then return  ai_choice_result(("discard"),options) end
		end
		if self:needDamagedEffects(self.player, current) or self:needToLoseHp() then
			
			if hegemony_source_query(self,'getOverflow',current) > 1 and not current:isSkipped(sgs.Player_Discard) and string.find(choices, "discard") then return  ai_choice_result(("discard"),options) end
			if string.find(choices, "finish") then return  ai_choice_result(("finish"),options) end
			if not self:hasKnownSkill("heg_shensu",current) and string.find(choices, "judge") then return  ai_choice_result(("judge"),options) end
		end
	elseif self:isEnemy(current) then
		local need_skip_draw = (hegemony_source_query(current,'getMark',"JieyueExtraDraw") > 0 or current:hasSkill("heg_zisui"))and string.find(choices, "draw")and not self.player:isSkipped(sgs.Player_Draw)
		local need_skip_play = self:hasKnownSkill("heg_wangxi|heg_qice|heg_mingfa|heg_daoshu|heg_zaoyun",current)and string.find(choices, "play")and not self.player:isSkipped(sgs.Player_Play)
		if self:needDamagedEffects(self.player, current) or self:needToLoseHp() or not self:damageIsEffective(self.player, sgs.DamageStruct_Fire, current) then
			
			if need_skip_play then return  ai_choice_result(("play"),options) end
			if need_skip_draw then return  ai_choice_result(("draw"),options) end
		end
	end
	return  ai_choice_result(("cancel"),options)
end

