sgs.ai_skill_exchange._midao = function(self,pattern,max_num,min_num,expand_pile)
	local discards = {}
	local cards = self.player:getCards("he")
	cards = sgs.QList2Table(cards)
	self:sortByKeepValue(cards)
	local need_spade,need_club,need_heart = false,false,false
	for _, player in sgs.qlist(self.room:getAllPlayers()) do
		if self:getFinalRetrial(to) == 1 then
			if player:containsTrick("lightning") then
				need_spade = true
			end
			if self:isFriend(player) and self:willSkipDrawPhase(player) then
				need_club = true
			end
			if self:isFriend(player) and self:willSkipPlayPhase(player) then
				need_heart = true
			end
		end
	end
	for _, card in ipairs(cards) do
		if need_spade and (card:getSuit() == sgs.Card_Spade and card:getNumber() >= 2 and card:getNumber() <= 9) then
			if #discards < 2 then
				table.insert(discards, card:getKnownEffectiveId())
			end
			need_spade = false
		elseif need_club and card:getSuit() == sgs.Card_Club then
			if #discards < 2 then
				table.insert(discards, card:getKnownEffectiveId())
			end
			need_club = false
		elseif need_heart and card:getSuit() == sgs.Card_Heart then
			if #discards < 2 then
				table.insert(discards, card:getKnownEffectiveId())
			end
			need_heart = false
		end
	end
	if #discards < 2 then
		local card_ids = self:askForDiscard("dummy_reason", 2-#discards, 2-#discards, false, true)
		for _, card_id in ipairs(card_ids) do
			table.insert(discards, card_id)
		end
	end
	return discards
end

sgs.ai_skill_cardask["@heg_midao-card"] = function(self, data)
	
	local judge = data:toJudge()
	local who = judge.who
	
	local rices = self.player:getPile("rice")
	if rices:isEmpty() then return "." end
	
	local cards = {}
	for _,id in sgs.qlist(rices)do
		local card = r25_card(self,id)
		table.insert(cards, card)
	end
	local card_id = self:getRetrialCardId(cards, judge)
	if card_id == -1 then
		if self:needRetrial(judge) and judge.reason ~= "beige" then
			if self:getUseValue(judge.card) >= 6 or self:getKeepValue(judge.card) >= 4.1 then
				return "$" .. cards[1]:getId()
			end
		end
	elseif self:needRetrial(judge) or self:getUseValue(judge.card) >= 6 or self:getKeepValue(judge.card) >= 4.1 then
		local card = r25_card(self,card_id)
		return "$" .. card_id
	end
	return "."
end

ai_skill_use["@@heg_midao"] = function(self, prompt)
	local rice = {}
	for _, id in sgs.qlist(self.player:getPile("rice")) do
		table.insert(rice, r25_card(self,id))
	end
	if #rice == 0 then return "." end

	self:sortByKeepValue(rice)
	return "$" .. rice[1]:getEffectiveId()
end

ai_skill_use["@@heg_shilu"] = function(self, prompt)
	local count = r26_general_pile(self,self.player,"massacre"):length()
	if count < 1 then return "." end
	local response = sgs.ai_skill_cardask["@heg_shilu"](self, nil, nil, nil, nil, tostring(count))
	if type(response) ~= "string" or response:sub(1, 1) ~= "$" then return "." end
	return "@DummyCard=" .. response:sub(2)
end

ai_skill_use["@@heg_chaosselect!"] = function(self)
	local cards = sgs.QList2Table(self.player:getHandcards())
	local usable = {}
	for _, card in ipairs(cards) do
		if not self.player:isJilei(card) then table.insert(usable, card) end
	end
	if #usable == 0 then return "." end
	self:sortByKeepValue(usable)
	local selected = {usable[1]}
	for index = 2, #usable do
		if usable[index]:getTypeId() ~= selected[1]:getTypeId() then
			table.insert(selected, usable[index])
			break
		end
	end
	if #selected == 1 then
		for _, card in ipairs(usable) do
			if card:getTypeId() ~= selected[1]:getTypeId() then return "." end
		end
	end
	local ids = {}
	for _, card in ipairs(selected) do table.insert(ids, card:getKnownEffectiveId()) end
	return "@DummyCard=" .. table.concat(ids, "+")
end

ai_skill_use["@@heg_tongling_usecard"] = function(self)
	local target_name = r26_property(self,self.player,"tongling_usetarget")
	local target = target_name ~= "" and self.room:findPlayerByObjectName(target_name) or nil
	for _, card in sgs.qlist(self.player:getHandcards()) do
		if card:isAvailable(self.player) then
			if card:targetFixed() then return "@HTonglingCard=" .. card:getKnownEffectiveId() end
			if target and not self.room:isProhibited(self.player, target, card) then
				local selected = AIList.new{}
				if card:targetFilter(selected, target, self.player) then
					selected:append(target)
				end
				if not selected:isEmpty() and card:targetsFeasible(selected, self.player) then
					return "@HTonglingCard=" .. card:getKnownEffectiveId() .. "->" .. target_name
				end
			end
		end
	end
	return "."
end

