sgs.ai_skill_playerchosen.heg_wenji = function(self, targets)
  local target
  targets = sgs.QList2Table(targets)
  self:sortInPlace(targets, "handcard")
  for _, p in ipairs(targets) do
    if not known(heg_player(self,p).shown_one,"shown_one") then
      target = p
    end
  end
  local weak_enemy = false
  for _, enemy in ipairs(self.enemies) do
    if hegemony_source_query(self,'isWeak',enemy) then
      weak_enemy = true
      break
    end
  end
  if not target and weak_enemy then
    self:sortInPlace(targets, "handcard", true)
    for _, p in ipairs(targets) do
      if r26_public_friend(self.player,p) and (self:originalHegemonyKnownCard(p, self.player, "Slash")
         + self:originalHegemonyKnownCard(p, self.player, "AOE") + self:originalHegemonyKnownCard(p, self.player, "Duel") > 0) then
        target = p
      end
    end
    if not target then
      for _, p in ipairs(targets) do
        if r26_public_friend(self.player,p) and p:getHandcardNum() > 2 then
          target = p
        end
      end
    end
  end
  if not target then
    for _, p in ipairs(targets) do
      if self:isFriend(p) and hegemony_source_query(self,'needToThrowArmor',p) then
        target = p
      end
    end
  end
  local give_peach = false
  if not self.player:isNude() then
    local cards = self.player:getCards("he")
    cards = sgs.QList2Table(cards)
    self:sortByUseValue(cards,true)
    if cards[1]:isKindOf("Peach") then
      give_peach = true
    end
  end
  self:sortInPlace(targets, "handcard")
  if not target and not give_peach then
    for _, p in ipairs(targets) do
      if not r26_public_friend(self.player,p) then
        target = p
      end
    end
  end
  if target then
    return target
  end
	return {}
end

sgs.ai_skill_exchange["wenji_give"] = function(self,pattern,max_num,min_num,expand_pile)
  local heg_liuqi = original_find_shown(self,"heg_wenji")
  if self:isFriendWith(heg_liuqi) then
    if self:getCardsNum("AOE") > 0 then
      local card
      card = self:getCard("SavageAssault")
      if card and self:getAoeValue(card) > 0 then
        return card:getKnownEffectiveId()
      end
      card = self:getCard("ArcheryAttack")
      if card and self:getAoeValue(card) > 0 then
        return card:getKnownEffectiveId()
      end
    end
    if self:getCardsNum("Slash") > 0 then
      return self:getCard("Slash"):getEffectiveId()
    end
    if self:getCardsNum("Duel") > 0 then
      return self:getCard("Duel"):getEffectiveId()
    end
  end
  if hegemony_source_query(self,'needToThrowArmor') then
    return self.player:getArmor():getEffectiveId()
  end
  local cards = self.player:getCards("he")
	cards = sgs.QList2Table(cards)
	self:sortByKeepValue(cards)
	return cards[1]:getEffectiveId()
end

sgs.ai_skill_exchange["wenji_giveback"] = function(self,pattern,max_num,min_num,expand_pile)
  local to
	for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
		if hegemony_source_query(p,'hasFlag',"WenjiTarget") then
			to = p
			break
		end
	end

  if self:isFriend(to) and hegemony_source_query(self,'isWeak',to) then
    if self.player:getHp() > 1 and self:getCardsNum("Analeptic") > 0 then
      return self:getCard("Analeptic"):getEffectiveId()
    end
    if not hegemony_source_query(self,'isWeak') and self:getCardsNum("Peach") > 1 then
      return self:getCard("Peach"):getEffectiveId()
    end
    if self:getCardsNum("Jink") > 1 then
      return self:getCard("Jink"):getEffectiveId()
    end
  end
  local cards = self.player:getCards("he")
	cards = sgs.QList2Table(cards)
	self:sortByUseValue(cards,true)
  for _, c in ipairs(cards) do
    if self:matchesDiscardPattern(pattern,c) then
      return c:getKnownEffectiveId()
    end
  end
end

function SmartAI:hasWenjiBuff(card)
	if self.player:hasSkill("heg_wenji") then
    local record_ids = r26_property(self,self.player,"wenji_record"):split("+")
    for _, id in sgs.qlist(card:getSubcards()) do
      if table.contains(record_ids, tostring(id)) then
        return true
      end
    end
    if table.contains(record_ids, tostring(card:getKnownEffectiveId())) then
      return true
    end
  end
	return false
end

