ai_skill_invoke.heg_fankui_simazhao = function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

	if not self:willShowForMasochism() then return (false) or false  end
	local target = data:toDamage().from
	if not target then return false end
	if sgs.ai_need_damaged.nosfankui(self, target, self.player) then return (true) or false  end

	if self:isFriend(target) then
		if hegemony_source_query(self,'getOverflow',target) > 2 then return (true) or false  end
		if self:doNotDiscard(target) then return (true) or false  end
		return ((original_shown_skills(self,target, sgs.lose_equip_skill) and not target:getEquips():isEmpty())
		  or (hegemony_source_query(self,'needToThrowArmor',target) and target:getArmor()) or self:doNotDiscard(target)) or false 
	end
	if self:isEnemy(target) then
		if self:doNotDiscard(target) then return (false) or false  end
		return (true) or false 
	end
	return (true) or false 
end

ai_skill_invoke.heg_zhaoxin = function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

  if not self:willShowForDefence() or not self:willShowForMasochism() then
    return (false) or false 
  end
  local my_hnum = self.player:getHandcardNum()
  local targets = {}
  self.zhaoxin_target = nil
  for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
    if not p:isKongcheng() and p:getHandcardNum() <= my_hnum then
      table.insert(targets, p)
    end
  end
  if #targets == 0 then
    return (false) or false 
  end
  self:sortInPlace(targets, "handcard", true)

  local my_value = 0
  for _, card in sgs.qlist(self.player:getHandcards()) do
    if self.player:getPhase() <= sgs.Player_Play then
      my_value = my_value + self:getUseValue(card)
    else
      my_value = my_value + self:getKeepValue(card)
    end
  end

  local same_card_target, one_less_target
  local same_card_value, one_less_value = 0, 0
  local mark_peach_num = hegemony_source_query(self.player,'getMark',"@companion") + hegemony_source_query(self.player,'getMark',"@careerist")
  local need_peach = (self.player:getHp() > 1 and self:getCardsNum("Peach") < 1 + mark_peach_num)
        or (self.player:getHp() == 1 and self:getCardsNum("Peach") + self:getCardsNum("Analeptic") < 1 + mark_peach_num)

  for _, p in ipairs(targets) do
    local known = 0
    local value = 0
    local p_hnum = p:getHandcardNum()
    for _, card in sgs.qlist(p:getHandcards()) do
      if r25_card_visible(self,card, p, self.player) then
        known = known + 1
        if self.player:getPhase() <= sgs.Player_Play then
          value = value + self:getUseValue(card)
        else
          value = value + self:getKeepValue(card)
        end
        if self:isCard("Peach", card, self.player) or self:isCard("Analeptic", card, self.player) then
          if need_peach and hegemony_source_query(self,'isWeak') then

            self.zhaoxin_target = p
            return (true) or false 
          end
        end
      end
    end
    if value > my_value then

      self.zhaoxin_target = p
      return (true) or false 
    end
    if p_hnum == my_hnum and not (known == p_hnum and value < my_value) and value >= same_card_value then
      same_card_value = value
      same_card_target = p
    end
    if p_hnum + 1 == my_hnum and not (known == p_hnum and value < my_value) and value >= one_less_value then
      one_less_value = value
      one_less_target = p
    end
  end
  if need_peach and same_card_target then

    self.zhaoxin_target = same_card_target
    return (true) or false 
  end
  if need_peach and self.player:isWounded() and one_less_target then

    self.zhaoxin_target = one_less_target
    return (true) or false 
  end
	return (false) or false 
end

sgs.ai_skill_playerchosen["zhaoxin_exchange"] = function(self, targets)
  targets = sgs.QList2Table(targets)
  if self.zhaoxin_target then

    return self.zhaoxin_target
  end
  self:sortInPlace(targets, "handcard", true)
	return targets[1]
end

ai_skill_invoke.heg_shilu = true

sgs.ai_skill_cardask["@heg_shilu"] = function(self, data, pattern, target, target2, arg, arg2)
  local diascard_num = tonumber(arg)
  local unpreferedCards = {}

  local function addcard(card)
    if #unpreferedCards < diascard_num and not card:canRecast() and not table.contains(unpreferedCards, card:getKnownId()) then
      if self.player:hasSkills(sgs.lose_equip_skill) then
        for _, id in ipairs(unpreferedCards) do
          if self.room:getCardPlace(id) == sgs.Player_PlaceEquip then
            return
          end
        end
      end
      if card:isKindOf("WoodenOx") and not self.player:getPile("wooden_ox"):isEmpty() then
        return
      end
      table.insert(unpreferedCards, card:getKnownId())
    end
  end

  if hegemony_source_query(self,'needToThrowArmor') then
    addcard(self.player:getArmor())
  end

  local xiongnve_nolimit = false
  self.xiongnve_choice = nil
  local name = ai_skill_choice.xiongnve_attack(self,{reason='xiongnve_attack',choices=r26_general_pile(self,self.player,"massacre"),inquiry_scope='original_internal'},nil)
  if name and self.xiongnve_choice == "nolimit" then
    self.xiongnve_choice = nil
    xiongnve_nolimit = true
  end
  local has_Crossbow = self:getCardsNum("Crossbow") > 0
	if xiongnve_nolimit or (#self.enemies > 0 and (has_Crossbow or hegemony_source_query(self,'hasCrossbowEffect')) and self.player:getCardCount(true) >= 4) then
		local allcards = sgs.QList2Table(self.player:getCards("he"))
		self:sortByUseValue(allcards, true)
		for _, acard in ipairs(allcards) do
			if not self:isCard("Peach", acard, self.player) and not self:isCard("Slash", acard, self.player)
			and not self:isCard("HBefriendAttacking", acard, self.player) and not self:isCard("HAllianceFeast", acard, self.player)
			and (self.player:getOffensiveHorse() or acard:isKindOf("OffensiveHorse") or not has_Crossbow)
			and not acard:isKindOf("Crossbow") and not self.player:isJilei(acard)
			then
				addcard(acard)
			end
		end
  end

  if self.player:getHp() < 3 then
		local use_slash, keep_jink, keep_analeptic  = false, false, false
		local keep_weapon
		local allcards = sgs.QList2Table(self.player:getCards("he"))
		self:sortByUseValue(allcards, true)
		for _, acard in ipairs(allcards) do
			if not self:isCard("Peach", acard, self.player) and not self:isCard("ExNihilo", acard, self.player)
			and not self:isCard("HBefriendAttacking", acard, self.player) and not self:isCard("HAllianceFeast", acard, self.player) then
				local shouldUse = true
				if self:isCard("Slash", acard, self.player) and not use_slash then
					local dummy_use = { isDummy = true , to = AIList.new{}}
					self:useBasicCard(acard, dummy_use)
					if dummy_use.card then
						if dummy_use.to then
							for _, p in sgs.qlist(dummy_use.to) do
								if p:getHp() <= 1 then
									shouldUse = false
									if self.player:distanceTo(p) > 1 then keep_weapon = self.player:getWeapon() end
									break
								end
							end
							if dummy_use.to:length() > 1 then shouldUse = false end
						end
						if not hegemony_source_query(self,'isWeak') then shouldUse = false end
						if not shouldUse then use_slash = true end
					end
				end
				if acard:getTypeId() == sgs.Card_TypeTrick then
					local dummy_use = { isDummy = true }
					self:useTrickCard(acard, dummy_use)
					if dummy_use.card then shouldUse = false end
				end
				if acard:getTypeId() == sgs.Card_TypeEquip and not self.player:hasEquip(acard) and not(self.player:getTreasure() or acard:isKindOf("Treasure")) then
					local dummy_use = { isDummy = true }
					self:useEquipCard(acard, dummy_use)
					if dummy_use.card then shouldUse = false end
					if keep_weapon and acard:getKnownEffectiveId() == keep_weapon:getKnownEffectiveId() then shouldUse = false end
				end
				if self.player:hasEquip(acard) and acard:isKindOf("Armor") and not hegemony_source_query(self,'needToThrowArmor') then shouldUse = false end
				if self.player:hasEquip(acard) and acard:isKindOf("DefensiveHorse") and not hegemony_source_query(self,'needToThrowArmor') then shouldUse = false end
				if self:isCard("Jink", acard, self.player) and not keep_jink then
					keep_jink = true
					shouldUse = false
				end
				if self.player:getHp() == 1 and self:isCard("Analeptic", acard, self.player) and not keep_analeptic then
					keep_analeptic = true
					shouldUse = false
				end
				if shouldUse then addcard(acard) end
			end
		end
	end

	if #unpreferedCards == 0 then
		local use_slash_num = 0
    local hcards = sgs.QList2Table(self.player:getHandcards())
		self:sortByUseValue(hcards, true)
		for _, card in ipairs(hcards) do
			if card:isKindOf("Slash") then
				local will_use = false
				if use_slash_num <= card:getTargetModResidue(self.player) then
					local dummy_use = { isDummy = true }
					self:useBasicCard(card, dummy_use)
					if dummy_use.card then
						will_use = true
						use_slash_num = use_slash_num + 1
					end
				end
				if not will_use then addcard(card) end
			end
		end

		local jink_num = self:getCardsNum("Jink") - 1
		if self.player:getArmor() then jink_num = jink_num + 1 end
		if jink_num > 0 then
			for _, card in ipairs(hcards) do
				if card:isKindOf("Jink") and jink_num > 0 then
					addcard(card)
					jink_num = jink_num - 1
				end
			end
		end
		for _, card in ipairs(hcards) do
			if (card:isKindOf("Weapon") and self.player:getHandcardNum() < 3) or card:isKindOf("OffensiveHorse")
				or self:getSameEquip(card, self.player) or card:isKindOf("AmazingGrace") then
				addcard(card)
			elseif card:getTypeId() == sgs.Card_TypeTrick then
				local dummy_use = { isDummy = true }
				self:useTrickCard(card, dummy_use)
				if not dummy_use.card then addcard(card) end
			end
		end
  end

  if self.player:getWeapon() and self.player:getHandcardNum() < 3 then
    addcard(self.player:getWeapon())
  end
  if self.player:getOffensiveHorse() and self.player:getWeapon() then
    addcard(self.player:getOffensiveHorse())
  end

  if #unpreferedCards == 0 then
    return "."
  end
  return "$" .. table.concat(unpreferedCards, "+")
end

ai_skill_invoke.heg_xiongnve = function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

  if data:toString() == "attack" then
    self.xiongnve_choice = nil
    local name = ai_skill_choice.xiongnve_attack(self,{reason='xiongnve_attack',choices=r26_general_pile(self,self.player,"massacre"),inquiry_scope='original_internal'},nil)
    if name and self.xiongnve_choice then

      return (true) or false 
    end
  end
  if data:toString() == "defence"  then
    if hegemony_source_query(self.player,'getMark',"ThreatenEmperorExtraTurn") > 0 then
      return (false) or false 
    end
    if hegemony_source_query(self.player,'getMark',"##xiongnve_avoid") > 0 then
      return (false) or false 
    end
    if hegemony_source_query(self,'isWeak') or self.player:getHp() < 2 then
      return (true) or false 
    end
    if not self.player:faceUp() then
      return (true) or false 
    end
    local useless_num = 0
    local generals = r26_general_pile(self,self.player, "massacre")
    local xiongnve_kingdom = {["wei"] = {}, ["shu"] = {}, ["wu"] = {}, ["qun"] = {}, ["careerist"] = {}, ["double"] = {}}
    for _, name in ipairs(generals) do
      local general = r26_general(self,name)
      if not general:isDoubleKingdoms() then
        table.insert(xiongnve_kingdom[general:getKingdom()],name)
      else
        table.insert(xiongnve_kingdom["double"],name)
      end
    end
    local kingdoms = {wei = 0, shu = 0, wu = 0, qun = 0, careerist = 0}
    for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
      if known(heg_player(self,p).shown_one,"shown_one") then
        local p_kingdom = p:getKnownKingdom()
        if p_kingdom == "god" then
          p_kingdom = "careerist"
        end
        kingdoms[p_kingdom] = kingdoms[p_kingdom] + (self:isFriend(p) and -1 or 1)
      end
    end
    for key, value in pairs(kingdoms) do
      if value == 0 and #xiongnve_kingdom[key] > 0 then
        useless_num = useless_num + #xiongnve_kingdom[key]
      end
      if value > 0 and #xiongnve_kingdom[key] > math.min(value*2, 5) then
        useless_num = useless_num + #xiongnve_kingdom[key] - value
      end
    end
    for _, name in ipairs(xiongnve_kingdom["double"]) do
      local general = r26_general(self,name)
      local double_kingdoms = general:getKingdoms()
      if kingdoms[double_kingdoms[1]] == 0 and kingdoms[double_kingdoms[2]] == 0 then
        useless_num = useless_num + 1
      end
    end
    if useless_num > 1 and (self.player:getLostHp() > 1 or self.player:getHp() < 3) then
      return (true) or false 
    end
    if useless_num > (self.player:isWounded() and 4 or 6) then
      return (true) or false 
    end
  end
	return (false) or false 
end

ai_skill_choice.xiongnve_attack = function(self,options,request)
    local generals
    if options and options.choices~=nil then generals=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then generals=''end

  generals = generals:split("+")
  local xiongnve_kingdom = {["wei"] = {}, ["shu"] = {}, ["wu"] = {}, ["qun"] = {}, ["careerist"] = {}, ["double"] = {}}
	for _, name in ipairs(generals) do
		local general = r26_general(self,name)
		if not general:isDoubleKingdoms() then
			table.insert(xiongnve_kingdom[general:getKingdom()],name)
		else
			table.insert(xiongnve_kingdom["double"],name)
		end
	end
  local kingdoms = {wei = 0, shu = 0, wu = 0, qun = 0, careerist = 0}
  local kingdom_players = {wei = {}, shu = {}, wu = {}, qun = {}, careerist = {}}
	for _, p in sgs.qlist(self.room:getOtherPlayers(self.player)) do
		if not p:isRemoved() and known(heg_player(self,p).shown_one,"shown_one") then
			local p_kingdom = p:getKnownKingdom()
			if p_kingdom == "god" then
				p_kingdom = "careerist"
			end
			kingdoms[p_kingdom] = kingdoms[p_kingdom] + (self:isFriend(p) and -1 or 1)
      table.insert(kingdom_players[p_kingdom], p)
		end
	end
  local function double_first(kingodm)
    for _, name in ipairs(xiongnve_kingdom["double"]) do
      local general = r26_general(self,name)
			local double_kingdoms = general:getKingdoms()
      if kingdoms[double_kingdoms[1]] >= 0 and kingdoms[double_kingdoms[2]] >= 0
      and (double_kingdoms[1] == kingodm or double_kingdoms[2] == kingodm) then
        return name
      end
    end
    if #xiongnve_kingdom[kingodm] > 0 then
      return xiongnve_kingdom[kingodm][1]
    end
    return nil
  end

  if self:getCardsNum("Slash") > 1 then
    local max_slash_kingdom
    local slash_enemy
    local e_num = 0
    local slash = r26_clone(self,"slash")
    self:sortInPlace(self.enemies, "hp")
    for _, enemy in ipairs(self.enemies) do
      if self.player:canSlash(enemy) and not self:slashProhibit(slash ,enemy) and self:slashIsEffective(slash, enemy) then
        local enemy_kingdom = enemy:getKnownKingdom()
        if enemy_kingdom == "god" then
          enemy_kingdom = "careerist"
        end
        if kingdoms[enemy_kingdom] > e_num and double_first(enemy_kingdom) then
          max_slash_kingdom = enemy_kingdom
          slash_enemy = enemy
          e_num = kingdoms[enemy_kingdom]
        end
      end
    end
    if max_slash_kingdom then
      if hegemony_source_query(self,'hasCrossbowEffect') or self:getCardsNum("Crossbow") > 0 then
        self.xiongnve_choice = "adddamage"
      else
        self.xiongnve_choice = "nolimit"
      end
      return  ai_choice_result((double_first(max_slash_kingdom)),options)
    end
  end
	if self:getCardsNum("AOE") > 0 then
    local max_aoe_kingdom
    local e_num = 0
    local aoe = self:getCard("SavageAssault")
    if aoe and self:getAoeValue(aoe) > 0 then
      for _, enemy in ipairs(self.enemies) do
        if self:aoeIsEffective(aoe, enemy, self.player) then
          local enemy_kingdom = enemy:getKnownKingdom()
          if enemy_kingdom == "god" then
            enemy_kingdom = "careerist"
          end
          if kingdoms[enemy_kingdom] > e_num and double_first(enemy_kingdom) then
            max_aoe_kingdom = enemy_kingdom
            e_num = kingdoms[enemy_kingdom]
          end
        end
      end
    end
    if max_aoe_kingdom then
      self.xiongnve_choice = "adddamage"
      return  ai_choice_result((double_first(max_aoe_kingdom)),options)
    end
    aoe = self:getCard("ArcheryAttack")
    if aoe and self:getAoeValue(aoe) > 0 then
      for _, enemy in ipairs(self.enemies) do
        if self:aoeIsEffective(aoe, enemy, self.player) then
          local enemy_kingdom = enemy:getKnownKingdom()
          if enemy_kingdom == "god" then
            enemy_kingdom = "careerist"
          end
          if kingdoms[enemy_kingdom] > e_num and double_first(enemy_kingdom) then
            max_aoe_kingdom = enemy_kingdom
            e_num = kingdoms[enemy_kingdom]
          end
        end
      end
    end
    if max_aoe_kingdom then
      self.xiongnve_choice = "adddamage"
      return  ai_choice_result((double_first(max_aoe_kingdom)),options)
    end
  end
  local burningcamps = self:getCard("HBurningCamps")
	if burningcamps and burningcamps:isAvailable(self.player) then
    local np = self.player:getNextAlive()
    if #xiongnve_kingdom[np:getKnownKingdom()] > 0 then
      local dummyuse = { isDummy = true, to = AIList.new{} }
			self:useCardBurningCamps(burningcamps, dummyuse)
			if dummyuse.card then
				self.xiongnve_choice = "adddamage"
				return  ai_choice_result((xiongnve_kingdom[np:getKnownKingdom()][1]),options)
			end
    end
  end
  local duel = self:getCard("Duel")
  if duel and duel:isAvailable(self.player) then
		local dummyuse = { isDummy = true, to = AIList.new{} }
		self:useCardDuel(duel, dummyuse)
		if not dummyuse.to:isEmpty() then
			local duel_t = dummyuse.to:first()
			if duel_t:getHp() == 1 and hegemony_source_query(self,'isWeak',duel_t) and #xiongnve_kingdom[duel_t:getKnownKingdom()] > 0 then
				self.xiongnve_choice = "adddamage"
				return  ai_choice_result((#xiongnve_kingdom[duel_t:getKnownKingdom()][1]),options)
			end
		end
	end
  return  ai_choice_result((generals[math.random(1,#generals)]),options)
end

ai_skill_choice.heg_xiongnve = function(self,options,request)
    local choices
    if options and options.choices~=nil then choices=table.concat(options.choices,'+')
    elseif options and (options.inquiry_scope=='ordinary_top_level'or options.inquiry_scope=='original_top_level')then choices=''end
    local data=request and self:getDecisionData(request) or nil

  choices = choices:split("+")

  if self.xiongnve_choice then
