ai_skill_invoke.heg_juejue = function(self,options,request)
    local data=request and self:getDecisionData(request) or nil

	if not self:willShowForAttack() then
    return (false) or false 
  end
  local friend_weak = 0
  local enemy_weak = 0
  for _, p in sgs.qlist(self.room:getAlivePlayers()) do
    if self:isFriend(p) and hegemony_source_query(self,'isWeak',p) then
      friend_weak = friend_weak + 1
    end
    if not self:isFriend(p) and hegemony_source_query(self,'isWeak',p) then
      enemy_weak = enemy_weak + 1
    end
  end
  if hegemony_source_query(self,'getOverflow') > (hegemony_source_query(self.player,'getMark',"@halfmaxhp") < 1 and 1 or 3) and self.player:getHp() > 1 then
    if enemy_weak > 2 or enemy_weak > friend_weak  then
      return (true) or false 
    end
    if (self.player:getHp() > 2 or self.player:hasSkill("heg_wangxi")) and self:getCardsNum("Peach") > 0 and (#self.enemies > 2 or #self.enemies > #self.friends) then
      return (true) or false 
    end
  end
	return (false) or false 
end

sgs.ai_skill_cardask["@heg_juejue-discard"] = function(self, data, pattern, target, target2)
  local dis_num = hegemony_source_query(self.player,'getMark',"juejue_discard_count")
	if self.player:getHandcardNum() < dis_num then
    return "."
  end
  local current = self.room:getCurrent()
  if not self:damageIsEffective(self.player, nil, current) or self:needDamagedEffects(self.player, current) or self:needToLoseHp(self.player, current) then
    return "."
  end
  if self.player:getHp() > 2 or self:getCardsNum("Peach") > 0
  or (self.player:getHp() == 1 and self:getCardsNum("Analeptic") > 0)
  or (dis_num > 3 and not hegemony_source_query(self,'isWeak')) then
    return "."
  end
  local cards = self.player:getHandcards()
  cards=sgs.QList2Table(cards) 
  local discards = {}
  self:sortByKeepValue(cards) 
  for _, c in ipairs(cards) do
    table.insert(discards, c:getKnownId())
    if #discards == dis_num then
      return "$" .. table.concat(discards, "+")
    end
  end
  return "."
end

