ai_card_use.HImperialEdictAttachCard = function(self,card,use)
  self:setPriorityValue("HImperialEdictAttachCard",0.2,"original.lord_ex")
  local attach_cards = {}
  local attach_num = 1
  if not self:originalHegemonyIsBigKingdomPlayer(self.player) then
    for _, p in sgs.qlist(self.room:getAlivePlayers()) do
      if self:originalHegemonyIsBigKingdomPlayer(p) then
        attach_num = 2
        break
      end
    end
  end
  local suits = {"heart", "diamond", "spade", "club"}
  for _, p in sgs.qlist(self.room:getAlivePlayers()) do
    if not p:getPile("HImperialEdict"):isEmpty() and r26_public_friend(self.player,p) then
      for _,id in sgs.qlist(p:getPile("HImperialEdict")) do
        local c = r25_card(self,id)
        if not c:isKindOf("HImperialEdict") then
          table.removeOne(suits, c:getSuitString())
        end
      end
    end
  end
  if #suits == 0 then
    return
  end
  local hcards = sgs.QList2Table(self.player:getHandcards())
  self:sortByUseValue(hcards, true)

  local limit = hegemony_source_query(self,'getOverflow',self.player,true)
  local peach_num = self:getCardsNum("Peach")
  local analeptic_num = self:getCardsNum("Analeptic")
  local jink_num = self:getCardsNum("Jink")

  local function can_attach(hcard)
    if peach_num + analeptic_num + jink_num <= limit and limit < 3
    and (self:isCard("Peach", hcard, self.player) or self:isCard("Analeptic", hcard, self.player) or self:isCard("Jink", hcard, self.player)) then
      return false
    end
    return true
  end

  for _, hc in ipairs(hcards) do
    if table.contains(suits, hc:getSuitString()) and #attach_cards < attach_num and can_attach(hc) then
      local dummyuse = { isDummy = true }
      self:useCardByClassName(hc, dummyuse)
      if not dummyuse.card then
        table.removeOne(suits, hc:getSuitString())
        table.insert(attach_cards, hc:getKnownEffectiveId())
      end
    end
  end
  if #attach_cards > 0 then
    if #suits == #attach_cards and not self.player:getPile("HImperialEdict"):isEmpty() then
      self:setPriorityValue("HImperialEdictAttachCard",5,"original.lord_ex")
    end
    use.card = r26_parse(self,"@HImperialEdictAttachCard=" .. table.concat(attach_cards, "+"))
  end
end

