local function install_r26_dependencies()
local SmartAI={}
local sgs=sgs

function SmartAI:useCardLureTiger(HLureTiger, use)
	self:setPriorityValue("HLureTiger",4.9,"original.dependencies")
	if not HLureTiger:isAvailable(self.player) then return end

	local players = AIList.new{}

	local card = self:getCard("HBurningCamps")
	if card and card:isAvailable(self.player) then
		local nextp = self.player:getNextAlive()
		local first
		while true do
			if self:cardTargetFilter(HLureTiger,players,nextp) and self:trickIsEffective(HLureTiger, nextp, self.player) then
				if not first then
					if self:isEnemy(nextp) then
						first = nextp
					else
						players:append(nextp)
					end
				else
					if not r26_public_friend(first,nextp) then
						players:append(nextp)
					end
				end
				nextp = nextp:getNextAlive()
			else
				break
			end
		end
		if first and not players:isEmpty() then
			use.card = HLureTiger
			if use.to then use.to = AIList.new(players) end
			return
		end
	end

	players = AIList.new{}

	card = self:getCard("ArcheryAttack")
	if card and card:isAvailable(self.player) and self:getAoeValue(card) > 0 and #self.friends_noself > 0 then
		self:sortInPlace(self.friends_noself, "hp")
		for _, friend in ipairs(self.friends_noself) do
			if self:isFriendWith(friend) and self:cardTargetFilter(HLureTiger,players,friend)
			and self:trickIsEffective(HLureTiger, friend, self.player) and self:aoeIsEffective(card, friend, self.player) then
				players:append(friend)
			end
		end
		for _, friend in ipairs(self.friends_noself) do
			if self:cardTargetFilter(HLureTiger,players,friend) and not players:contains(friend)
			and self:trickIsEffective(HLureTiger, friend, self.player) and self:aoeIsEffective(card, friend, self.player) then
				players:append(friend)
			end
		end
		if players:length() > 0 then
			self:setPriorityValue("HLureTiger",sgs.ai_use_priority.ArcheryAttack + 0.2,"original.dependencies")
			use.card = HLureTiger
			if use.to then use.to = AIList.new(players) end
			return
		end
	end

	players = AIList.new{}

	card = self:getCard("SavageAssault")
	if card and card:isAvailable(self.player) and self:getAoeValue(card) > 0 and #self.friends_noself > 0 then
		self:sortInPlace(self.friends_noself, "hp")
		for _, friend in ipairs(self.friends_noself) do
			if self:isFriendWith(friend) and self:cardTargetFilter(HLureTiger,players,friend)
			and self:trickIsEffective(HLureTiger, friend, self.player) and self:aoeIsEffective(card, friend, self.player) then
				players:append(friend)
			end
		end
		for _, friend in ipairs(self.friends_noself) do
			if self:cardTargetFilter(HLureTiger,players,friend) and not players:contains(friend)
			and self:trickIsEffective(HLureTiger, friend, self.player) and self:aoeIsEffective(card, friend, self.player) then
				players:append(friend)
			end
		end
		if players:length() > 0 then
			self:setPriorityValue("HLureTiger",sgs.ai_use_priority.SavageAssault + 0.2,"original.dependencies")
			use.card = HLureTiger
			if use.to then use.to = AIList.new(players) end
			return
		end
	end

	players = AIList.new{}

	card = self:getCard("Slash")
	if card and self:slashIsAvailable(self.player,card) then
		local dummyuse = { isDummy = true, to = AIList.new{} }
		self:withOwnerRange('slashNoDistanceLimit','original:useCardLureTiger',function() self:useCardSlash(card,dummyuse) end)
		if dummyuse.card then
			local total_num = 2 + HLureTiger:getTargetModExtra(self.player)
			local function getPlayersFromTo(one)
				local targets1 = AIList.new{}
				local targets2 = AIList.new{}
				local nextp = self.player:getNextAlive()
				while true do
					if self:cardTargetFilter(HLureTiger,targets1,nextp) and self:trickIsEffective(HLureTiger, nextp, self.player) then
						if one:objectName() ~= nextp:objectName() then
							targets1:append(nextp)
						else
							break
						end
						nextp = nextp:getNextAlive()
					else
						targets1 = AIList.new{}
						break
					end
				end
				nextp = one:getNextAlive()
				while true do
					if self:cardTargetFilter(HLureTiger,targets2,nextp) and self:trickIsEffective(HLureTiger, nextp, self.player) then
						if self.player:objectName() ~= nextp:objectName() then
							targets2:append(nextp)
						else
							break
						end
						nextp = nextp:getNextAlive()
					else
						targets2 = AIList.new{}
						break
					end
				end
				if targets1:length() > 0 and targets2:length() >= targets1:length() and targets1:length() <= total_num then
					return targets1
				elseif targets2:length() > 0 and targets1:length() >= targets2:length() and targets2:length() <= total_num then
					return targets2
				end
				return
			end

			for _, to in sgs.qlist(dummyuse.to) do
				if self.player:distanceTo(to) > self.player:getAttackRange() and self.player:distanceTo(to, -total_num) <= self.player:getAttackRange() then
					local sps = getPlayersFromTo(to)
					if sps then
						self:setPriorityValue("HLureTiger",3,"original.dependencies")
						use.card = HLureTiger
						if use.to then use.to = AIList.new(sps) end
						return
					end
				end
			end
		end

	end

	players = AIList.new{}

	card = self:getCard("GodSalvation")
	if card and card:isAvailable(self.player) and #self.enemies > 0 then
		self:sortInPlace(self.enemies, "hp")
		for _, enemy in ipairs(self.enemies) do
			if self:cardTargetFilter(HLureTiger,players,enemy) and self:trickIsEffective(HLureTiger, enemy, self.player) then
				players:append(enemy)
			end
		end
		if players:length() > 0 then
			self:setPriorityValue("HLureTiger",sgs.ai_use_priority.GodSalvation + 0.1,"original.dependencies")
			use.card = HLureTiger
			if use.to then use.to = AIList.new(players) end
			return
		end
	end

	players = AIList.new{}

	local can_slash, can_duel, can_fireattack = false,false,false
	local slash = self:getCard("Slash")
	if slash and self:slashIsAvailable(self.player,slash) then
		can_slash = true
	end
	local duel = self:getCard("Duel")
	if duel and duel:isAvailable(self.player) then
		can_duel = true
	end
	local fire_attack = self:getCard("FireAttack")
	if fire_attack and fire_attack:isAvailable(self.player) then
		can_fireattack = true
	end
	if (can_slash or can_duel or can_fireattack) and #self.enemies > 1 then
		local enemys_copy = r25_copy(self.enemies)
		self:sortInPlace(enemys_copy, "hp")
		local to
		for _, p in ipairs(enemys_copy) do
			if p:getHp() == 1 and ((can_duel and self:trickIsEffective(duel, p, self.player)) or (can_fireattack and self:trickIsEffective(fire_attack, p, self.player))
				or (can_slash and self.player:canSlash(p,slash,true) and not self:slashProhibit(slash, p)
				and self:slashIsEffective(slash, p) and r26_good_target(self,p, enemys_copy, self)
				and not (hegemony_source_query(self.player,'hasFlag',"slashTargetFix") and not hegemony_source_query(p,'hasFlag',"SlashAssignee")))) then
					to = p
					table.removeOne(enemys_copy, to)
					break
			end
		end
		if to then
			if can_slash and hegemony_source_query(self,'hasCrossbowEffect') and self:getCardsNum("Slash") > 2 then
				local slash_num = self:getCardsNum("Slash")
				for _, enemy in ipairs(enemys_copy) do
					if  (r26_defense_slash(self,enemy, self) <= 2 or (enemy:getHandcardNum() < 3 and enemy:getHp() <= slash_num))
						and self.player:canSlash(enemy,slash,true) and not self:slashProhibit(slash, enemy)
						and self:slashIsEffective(slash, enemy) and r26_good_target(self,enemy, enemys_copy, self)
						and not (hegemony_source_query(self.player,'hasFlag',"slashTargetFix") and not hegemony_source_query(enemy,'hasFlag',"SlashAssignee")) then
							slash_num = slash_num - enemy:getHp()
							table.removeOne(enemys_copy, enemy)
					end
				end
			end
			self:sortInPlace(enemys_copy, "handcard", true)
			if #enemys_copy > 0 then
				for _, enemy in ipairs(enemys_copy) do
					if self:cardTargetFilter(HLureTiger,players,enemy) and self:trickIsEffective(HLureTiger, enemy, self.player)
					and enemy:objectName() ~= to:objectName() and r26_public_friend(enemy,to) then
						players:append(enemy)
					end
				end
				local total_num = 2 + HLureTiger:getTargetModExtra(self.player)
				if players:length() < total_num then
					for _, enemy in ipairs(enemys_copy) do
						if self:cardTargetFilter(HLureTiger,players,enemy) and self:trickIsEffective(HLureTiger, enemy, self.player)
						and enemy:objectName() ~= to:objectName() and self:isFriend(enemy,to) then
							players:append(enemy)
						end
					end
				end
				if players:length() < total_num then
					for _, enemy in ipairs(enemys_copy) do
						if self:cardTargetFilter(HLureTiger,players,enemy) and self:trickIsEffective(HLureTiger, enemy, self.player)
						and enemy:objectName() ~= to:objectName() then
							players:append(enemy)
						end
					end
				end
			end
			if players:length() > 0 then
				if can_slash or can_duel then
					self:setPriorityValue("HLureTiger",sgs.ai_use_priority.Duel + 0.1,"original.dependencies")
				end
				if can_fireattack then
					self:setPriorityValue("HLureTiger",sgs.ai_use_priority.FireAttack + 0.1,"original.dependencies")
				end
				use.card = HLureTiger
				if use.to then use.to = AIList.new(players) end
				return
			end
		end
	end

	players = AIList.new{}
	card = self:getCard("AmazingGrace")
	if card and card:isAvailable(self.player) and #self.enemies > 0 then
		self:sortInPlace(self.enemies, "handcard")
		for _, enemy in ipairs(self.enemies) do
			if self:cardTargetFilter(HLureTiger,players,enemy) and self:trickIsEffective(HLureTiger, enemy, self.player) then
				players:append(enemy)
			end
		end
		if players:length() > 0 then
			self:setPriorityValue("HLureTiger",sgs.ai_use_priority.AmazingGrace + 0.1,"original.dependencies")
			use.card = HLureTiger
			if use.to then use.to = AIList.new(players) end
			return
		end
	end

	players = AIList.new{}
	local heg_xuyou = original_find_shown(self,"heg_chenglve")
	local aoedraw = heg_xuyou and r26_public_friend(self.player,heg_xuyou)

	if shown(self,self.player,"heg_jizhi") or aoedraw then
		for _, player in sgs.qlist(self.room:getOtherPlayers(self.player)) do
			if self:cardTargetFilter(HLureTiger,players,player) and self:trickIsEffective(HLureTiger, player, self.player) then
				players:append(player)
			end
		end
		if (shown(self,self.player,"heg_jizhi") and players:length() > 0) or (aoedraw and players:length() > 1) then
			self:setPriorityValue("HLureTiger",0.4,"original.dependencies")
			use.card = HLureTiger
			if use.to then use.to = AIList.new(players) end
			return
		end
	end
end

function SmartAI:getSameEquip(card, player)
	player = player or self.player
	if not card then return end
	if card:isKindOf("Weapon") then return player:getWeapon()
	elseif card:isKindOf("Armor") then return player:getArmor()
	elseif card:isKindOf("DefensiveHorse") then return player:getDefensiveHorse()
	elseif card:isKindOf("OffensiveHorse") then return player:getOffensiveHorse() end
end


