for native,source in pairs{['@midao-card']='@heg_midao-card',['@xishe-slash']='@heg_xishe-slash',['@juejue-discard']='@heg_juejue-discard',['@daoshu-give']='@heg_daoshu-give'}do
 local callback=sgs.ai_skill_cardask[source]
 original_policy(sgs.ai_skill_cardask,native,function(self,...)return callback(self,...)end)
end
sgs.ai_skill_playerschosen=sgs.ai_skill_playerschosen or{}
for _,name in ipairs{'heg_hongyuan', 'heg_juedi', 'heg_leiji_tianshu', 'heg_lianpian', 'heg_lianyou', 'heg_tanfeng', 'heg_wenji', 'heg_zhidao'}do
 local callback=sgs.ai_skill_playerchosen[name]
 original_policy(sgs.ai_skill_playerschosen,name,function(self,...)
  local value=callback(self,...)
  if AIUnsupported.is(value)then error(value,0)end
