		or (self.player:hasSkill("xiongyi") and hegemony_source_query(self.player,'getMark',"@arise") ~= 0)
		or (self.player:hasSkill("heg_yaowu") and not known(heg_player(self,self.player).shown_deputy,"shown_deputy")) then
