ai_card_use.HFirstShowCard= function(self,card,use)
	self:setPriorityValue("HFirstShowCard",0.1,"original.round27")

	local target
	local not_shown = {}
	for _, p in sgs.qlist(self.room:getAlivePlayers()) do
		if not known(heg_player(self,p).shown_all,"shown_all") then
			table.insert(not_shown, p)
		end
	end
	if #not_shown > 0 then
		for _, p in ipairs(not_shown) do
			if not self:isFriend(p) and not self:isEnemy(p) then
				target = p
				break
			end
		end
		if not target then
			for _, p in ipairs(not_shown) do
				if not known(heg_player(self,p).shown_one,"shown_one") and self:isEnemy(p) then
					target = p
					break
				end
			end
		end
		if not target then
			for _, p in ipairs(not_shown) do
				if self:isFriend(p) and not known(heg_player(self,p).shown_head,"shown_head") then
					target = p
					break
				end
			end
		end
		if not target then
			target = not_shown[1]
		end
	end

	if (self.player:getHandcardNum() < 2 and self:slashIsAvailable())
	or (math.min(self.player:getMaxCards(), 4) - self.player:getHandcardNum() > 2) then
		for _,c in sgs.qlist(self.player:getHandcards()) do
			local dummy_use = { isDummy = true }
			if c:isKindOf("BasicCard") then
				self:useBasicCard(c, dummy_use)
			elseif c:isKindOf("EquipCard") then
				self:useEquipCard(c, dummy_use)
			elseif c:isKindOf("TrickCard") then
				self:useTrickCard(c, dummy_use)
			end
			if dummy_use.card then
				return
			end
		end
		self:setPriorityValue("HFirstShowCard",2.4,"original.round27")
		use.card = card
		if target and use.to then
			use.to:append(target)
		end
		return
	end

	local freindisweak = false
	for _, friend in ipairs(self.friends) do
		if friend:getHp() == 1 and hegemony_source_query(self,'isWeak',friend) then
			freindisweak = true
			break
		end
	end
	if self.player:getHandcardNum() <= 2 and self:getCardsNum("Peach") == 0 and freindisweak then
		for _,c in sgs.qlist(self.player:getHandcards()) do
			local dummy_use = { isDummy = true }
			if c:isKindOf("BasicCard") then
				self:useBasicCard(c, dummy_use)
			elseif c:isKindOf("EquipCard") then
				self:useEquipCard(c, dummy_use)
			elseif c:isKindOf("TrickCard") then
				self:useTrickCard(c, dummy_use)
			end
			if dummy_use.card then
				return
			end
		end
		self:setPriorityValue("HFirstShowCard",0.9,"original.round27")
		use.card = card
		if target and use.to then
			use.to:append(target)
		end
		return
	end
end

