-- Original Hegemony uses distinct retrial rules.
function SmartAIView:originalHegemonyCanRetrial(player, to_retrial, reason)
    player = player or self.player
    to_retrial = to_retrial or self.player
    if shown(self,player,"guidao") then
        local blackequipnum = 0
        for _, equip in ipairs(player:getEquips()) do
            if equip:isBlack() then blackequipnum = blackequipnum + 1 end
        end
        if blackequipnum + player:getHandcardNum() > 0 then return true end
    end
    if shown(self,player,"guicai") and player:getHandcardNum() > 0 then return true end
end

function SmartAIView:originalHegemonyFinalRetrial(player, reason)
    local maxfriendseat, maxenemyseat = -1, -1
    local wizardf, wizarde
    player = player or self.room:getCurrent()
    for _, aplayer in ipairs(self.friends) do
        if ht_shown_skills(self,aplayer,ht_fact(self,"wizard_harm_skill")) and self:canRetrial(aplayer,player,reason) then
            local seat = (aplayer:getSeat() - player:getSeat()) % self.room:alivePlayerCount()
            if seat > maxfriendseat then maxfriendseat, wizardf = seat, aplayer end
        end
    end
    for _, aplayer in ipairs(self.enemies) do
        if ht_shown_skills(self,aplayer,ht_fact(self,"wizard_harm_skill")) and self:canRetrial(aplayer,player,reason) then
            local seat = (aplayer:getSeat() - player:getSeat()) % self.room:alivePlayerCount()
            if seat > maxenemyseat then maxenemyseat, wizarde = seat, aplayer end
        end
    end
    if maxfriendseat == -1 and maxenemyseat == -1 then return 0, nil
    elseif maxfriendseat > maxenemyseat then return 1, wizardf
    else return 2, wizarde end
end

local function r30_retrial_judge(self,input)
    if type(input)~="table" or type(input.reason)~="string" then ai_unsupported("Original judgment is unknown","Original.retrial")end
    local judge={};for k,v in pairs(input)do judge[k]=v end
    if type(judge.who)=="string"then judge.who=self.room:findPlayerByObjectName(judge.who,true)end
    if not judge.who then ai_unsupported("Original judged player is unknown","Original.retrial")end
    if type(judge.card)=="table"and type(judge.card.getSuit)~="function"then judge.card=CardView.new(judge.card)end
    local outcomes={}
    -- Native projects the authority's legal candidate result by effective ID.
    -- Keep the map opaque until a supplied candidate is matched; an incomplete
    -- map cannot be turned into a guessed FilterSkill face or boolean.
    if judge.outcomes_complete==true then
        local projected=known(judge.outcome_by_id,'Original retrial outcomes')
        if type(projected)~='table' then ai_unsupported('Original retrial outcomes are malformed','Original.retrial.outcome')end
        for id,value in pairs(projected) do
            if type(value)~='boolean' then ai_unsupported('Original retrial outcome is not boolean','Original.retrial.outcome')end
            outcomes[id]=value
        end
    end
    function judge:isGood(card)
        local value
        if card==nil then value=self.good else value=outcomes[card]end
        if type(value)~="boolean"then ai_unsupported("Original printed judgment outcome is unknown","Original.retrial.outcome")end
        return value
    end
    judge._r30_outcomes=outcomes
    return judge
end
local function r30_retrial_candidate(self,judge,card)
    local id=card:getKnownEffectiveId()
    if judge.outcomes_complete~=true then
        ai_unsupported("Original retrial candidate outcomes are incomplete","Original.retrial.outcome")
    end
    local rows=known(judge.outcome_by_id,'Original retrial outcomes')
    local value=rows[tostring(id)]
    if value==nil then value=rows[id] end
    if type(value)~="boolean" then
        ai_unsupported("Original legal retrial candidate outcome is unknown","Original.retrial.outcome")
    end
    -- The caller's card is the legal candidate face supplied by the engine;
    -- the native map supplies only its authoritative outcome.
    judge._r30_outcomes[card]=value
    return card
end
local function r30_retrial_damage(self,judge)
    if judge.damage_context_complete==true then
        if judge.damage_from==""then return{}end
        return{from=known(self.room:findPlayerByObjectName(judge.damage_from,true),"Original.retrial.damage.from")}
    end
    -- When the question's data is the judge, its damage context is the room's
    -- CurrentDamageStruct; absent means no damage is being resolved.
    local context=type(self.request.options)=="table"and self:getDecisionContext()
    if not context or context.judge==nil then ai_unsupported("Original current damage is unknown","Original.retrial.damage")end
    local damage=context.damage
    if damage==nil or damage.from_name==nil or damage.from_name==""then return{}end
    return{from=known(damage.from,"Original.retrial.damage.from")}
end

function SmartAIView:originalHegemonyNeedRetrial(judge)
    judge=r30_retrial_judge(self,judge)
	local reason = judge.reason
	local who = judge.who
	if reason == "lightning" then
		if shown(self,who,"hongyan") then return false end

		if who:hasArmorEffect("SilverLion") and who:getHp() > 1 then return false end

		if who:hasArmorEffect("PeaceSpell") then return false end

		if self:isFriend(who) then
			if who:isChained() and self:isGoodChainTarget(who,self.player,sgs.DamageStruct_Thunder,3) then return false end
		else
			if who:isChained() and not self:isGoodChainTarget(who,self.player,sgs.DamageStruct_Thunder,3) then return judge:isGood() end
		end
	elseif reason == "indulgence" then
		if who:isSkipped(sgs.Player_Draw) and who:isKongcheng() then
			if shown(self,who,"heg_kurou") and who:getHp() >= 3 then
				if self:isFriend(who) then
					return not judge:isGood()
				else
					return judge:isGood()
				end
			end
		end
		if self:isFriend(who) then
			local drawcardnum = self:ImitateResult_DrawNCards(who,who:getVisibleSkillList(true))
			if who:getHp() - who:getHandcardNum() >= drawcardnum and hegemony_source_query(self,'getOverflow') < 0 then return false end
			if shown(self,who,"tenyeartuxi") and who:getHp() > 2 and hegemony_source_query(self,'getOverflow') < 0 then return false end
			return not judge:isGood()
		else
			return judge:isGood()
		end
	elseif reason == "supply_shortage" then
		if self:isFriend(who) then
			if ht_shown_skills(self,who, "guidao|tiandu") then return false end
			return not judge:isGood()
		else
			return judge:isGood()
		end
	elseif reason == "heg_luoshen" then
		if self:isFriend(who) then
			if who:getHandcardNum() > 30 then return false end
			if hegemony_source_query(self,'hasCrossbowEffect',who) or self:originalHegemonyKnownCard(who, self.player, "Crossbow", false) > 0 then return not judge:isGood() end
			if hegemony_source_query(self,'getOverflow',who) > 1 and self.player:getHandcardNum() < 3 then return false end
			return not judge:isGood()
		else
			return judge:isGood()
		end
	elseif reason == "heg_tuntian" then
		if self:isFriend(who) then
			if self.player:objectName() == who:objectName() then
				return not hegemony_source_query(self,'isWeak')
			else
				return not judge:isGood()
			end
		else
			return judge:isGood()
		end
	elseif reason == "beige" then
		return true
	end

	if self:isFriend(who) then
		return not judge:isGood()
	elseif self:isEnemy(who) then
		return judge:isGood()
	else
		return false
	end
end

--- Get the retrial cards with the lowest keep value
-- @param cards the table that contains all cards can use in retrial skill
-- @param judge the JudgeStruct that contains the judge information
-- @return the retrial card id or -1 if not found
function SmartAIView:originalHegemonyRetrialCardId(cards, judge, self_card)
    judge=r30_retrial_judge(self,judge)
	if self_card == nil then self_card = true end
	local can_use = {}
	local reason = judge.reason
	local who = judge.who

	local other_suit, hasSpade = {}
	for _, card in ipairs(cards) do
		local card_x = r30_retrial_candidate(self,judge,card)
		if reason == "beige" and not isCard("Peach", card_x, self.player) then
			local damage = r30_retrial_damage(self,judge)
			if damage.from then
				if self:isFriend(damage.from) then
					if not self:toTurnOver(damage.from,0) and judge.card:getSuit() ~= sgs.Card_Spade and card_x:getSuit() == sgs.Card_Spade then
						table.insert(can_use, card)
						hasSpade = true
					elseif (not self_card or hegemony_source_query(self,'getOverflow') > 0) and judge.card:getSuit() ~= card_x:getSuit() then
						local retr = true
						if (judge.card:getSuit() == sgs.Card_Heart and who:isWounded() and self:isFriend(who))
							or (judge.card:getSuit() == sgs.Card_Club and hegemony_source_query(self,'needToThrowArmor',damage.from)) then
							retr = false
						end
						if retr
							and ((self:isFriend(who) and card_x:getSuit() == sgs.Card_Heart and who:isWounded())
								or (card_x:getSuit() == sgs.Card_Club and (hegemony_source_query(self,'needToThrowArmor',damage.from) or damage.from:isNude())))
								or (judge.card:getSuit() == sgs.Card_Spade and self:toTurnOver(damage.from,0)) then
							table.insert(other_suit, card)
						end
					end
				else
					if not self:toTurnOver(damage.from,0) and card_x:getSuit() ~= sgs.Card_Spade and judge.card:getSuit() == sgs.Card_Spade then
						table.insert(can_use, card)
					end
				end
			end
		elseif self:isFriend(who) and judge:isGood(card_x)
				and not (self_card and (self:getFinalRetrial() == 2 or self:dontRespondPeachInJudge(judge)) and isCard("Peach", card_x, self.player)) then
			table.insert(can_use, card)
		elseif self:isEnemy(who) and not judge:isGood(card_x)
				and not (self_card and (self:getFinalRetrial() == 2 or self:dontRespondPeachInJudge(judge)) and isCard("Peach", card_x, self.player)) then
			table.insert(can_use, card)
		end
	end
	if not hasSpade and #other_suit > 0 then for _,card in ipairs(other_suit)do can_use[#can_use+1]=card end end

	if reason ~= "lightning" then
		for _, aplayer in sgs.qlist(self.room:getAllPlayers()) do
			if aplayer:containsTrick("lightning") then
				for i, card in ipairs(can_use) do
					if card:getSuit() == sgs.Card_Spade and card:getNumber() >= 2 and card:getNumber() <= 9 then
						table.remove(can_use, i)
						break
					end
				end
			end
		end
	end

	if next(can_use) then
		if hegemony_source_query(self,'needToThrowArmor') then
			for _, c in ipairs(can_use) do
				if c:getEffectiveId() == self.player:getArmor():getEffectiveId() then return c:getEffectiveId() end
			end
		end
		local sorted=self:sortByKeepValue(can_use);if sorted then can_use=sorted end
		return can_use[1]:getEffectiveId()
	else
		return -1
	end
end


-- Effective heg-common:4305, distinct from ordinary Peach/retrial protection.
function SmartAIView:originalHegemonyDontRespondPeachInJudge(judge)
    judge=r30_retrial_judge(self,judge)
    local peach_num=self:getCardsNum("Peach")
    if peach_num==0 then return false end
    if self:willSkipPlayPhase() and self:getCardsNum("Peach")>hegemony_source_query(self,'getOverflow',self.player,true) then return false end
    if judge.reason=="lightning" and self:isFriend(judge.who) then return false end

    local card=self:getCard("Peach")
    local dummy_use=AIUsePlan.new();dummy_use.isDummy=true
    self:useBasicCard(card,dummy_use)
    if dummy_use.card then return true end

    if peach_num<=self.player:getLostHp() then return true end
    if peach_num>self.player:getLostHp() then
        for _,friend in ipairs(self.friends)do
            if hegemony_source_query(self,'isWeak',friend) then return true end
        end
    end
    if (judge.reason=="EightDiagram" or judge.reason=="bazhen") and
        self:isFriend(judge.who) and not hegemony_source_query(self,'isWeak',judge.who) then return true
    elseif judge.reason=="heg_tieqi" then return true
    elseif judge.reason=="heg_qianxi" then return true
    elseif judge.reason=="beige" then return true end
    return false
end

-- Fixed Original heg-common-ai.lua:2531,4388,4762. These are per-request
-- Original overrides; ordinary saver rules and foreign private limits are not substitutes.
(function()
 local strict = AIValue.requireKnown

 local function shown(self,player,name)
  local facts=self.world and AIHegemony.facts(self.world)
  if type(facts)~='table' or facts.enabled~=true or facts.original_overrides_loaded~=true then
   ai_unsupported('Original saver provider is not admitted','hegemony')
  end
  local row=type(facts.players)=='table' and facts.players[player:objectName()]
  if type(row)~='table' or type(row.shown_skills)~='table' then
   ai_unsupported('Original shown skill catalog is unknown',name)
  end
  return row.shown_skills[name]~=nil
 end
 function SmartAIView:originalHegemonyHasNiepanEffect(player)
  if shown(self,player,'heg_niepan') and player:getMark('@nirvana')>0 then return true end
  if shown(self,player,'heg_jizhao') and player:getMark('@heg_jizhao')>0 then return true end
  -- The lowercase global provider returns nil, not false, on fallthrough.
 end
 function SmartAIView:originalHegemonyDoNotSave(player)
  if self:originalHegemonyHasNiepanEffect(player) then return true end
  -- Raw flags retain exact owner/public-shadow knowledge. Do not use the
  -- foreign inactive-prior offered by getStrategyFlag.
  if player:hasFlag('AI_doNotSave') then return true end
  return false
 end
 function SmartAIView:originalHegemonyAbleToSave(saver,dying)
  local current=self.room:getCurrent()
  if AIUnsupported.is(current) then error(current,0) end
  if current==nil and (not self.world or type(self.world.current_player)~='string' or self.world.current_player~='') then
   ai_unsupported('current player absence is not known','current_player')
  end
  if current and current:getPhase()~=sgs.Player_NotActive and shown(self,current,'wansha')
   and current:objectName()~=saver:objectName() and current:objectName()~=dying:objectName() then
   return false
  end
  local peach=self:evaluateOwnerViewAsCard({source_key='original_able_to_save',skill='',name='peach',
   suit=strict(sgs.Card_NoSuitRed,'Card_NoSuitRed'),number=0,subcards={}})
  if saver:isCardLimited(peach,strict(sgs.Card_MethodUse,'Card_MethodUse'),true) then return false end
  return true
 end
end)()

