-- Fixed Original common2974–3035/4489–4503. The visibility helper at4749
-- deliberately ignores its from/observer argument and uses current_self.player.
-- An omitted/global observer in getMinCard therefore conveys no extra knowledge.
do
local r34_numbers={}
function r34_numbers.cards(self,player,cards)
    if cards then return cards end
    if player:objectName()==self.player:objectName()then return player:getHandcards()end
    -- Another player's known cards are the hand cards this viewer may see.
    return player:getKnownCards()
end
function r34_numbers.visible(self,card,player)
    if not card or not player then return false end
    if player:objectName()==self.player:objectName()then return true end
    if self:hasStrategyCardFlag(card,"visible")==true then return true end
    local flag="visible_"..self.player:objectName().."_"..player:objectName()
    if self:hasStrategyCardFlag(card,flag)==true then return true end
    for _,c in ipairs(player:getKnownCards())do if c:getKnownEffectiveId()==card:getKnownEffectiveId()then return true end end
    return false
end
function SmartAIView:originalHegemonyIsValuableCard(card,player)
    player=player or self.player
    if (isCard("Peach",card,player)and getCardsNum("Peach",player,self.player)<=2)
        or(hegemony_source_query(self,'isWeak',player)and isCard("Analeptic",card,player))
        or(player:getPhase()~=sgs.Player_Play
            and((isCard("Nullification",card,player)and getCardsNum("Nullification",player,self.player)<2 and shown(self,player,"heg_jizhi"))
                or(isCard("Jink",card,player)and getCardsNum("Jink",player,self.player)<2)))
        or(player:getPhase()==sgs.Player_Play and isCard("ExNihilo",card,player)and not player:isLocked(card))then return true end
    local dangerous=self:getDangerousCard(player)
    if AIUnsupported.is(dangerous)then error(dangerous,0)end
    if dangerous and card:getKnownEffectiveId()==dangerous then return true end
    local valuable=self:getValuableCard(player)
    if AIUnsupported.is(valuable)then error(valuable,0)end
    if valuable and card:getKnownEffectiveId()==valuable then return true end
end
function SmartAIView:originalHegemonyGetMaxCard(player,cards,observer)
    player=player or self.player
    if player:isKongcheng()then return nil end
    cards=r34_numbers.cards(self,player,cards)
    local max_card,max_point=nil,0
    for _,card in sgs.qlist(cards)do
        local allowed=false
        if player:objectName()==self.player:objectName()then
            local valuable=self:isValuableCard(card)
            if AIUnsupported.is(valuable)then error(valuable,0)end
            allowed=not valuable
        end
        if allowed or r34_numbers.visible(self,card,player)then
            local point=card:getNumber()
            if point>max_point then max_point=point;max_card=card end
        end
    end
    if player:objectName()==self.player:objectName()and not max_card then
        for _,card in sgs.qlist(cards)do local point=card:getNumber();if point>max_point then max_point=point;max_card=card end end
    end
    if player:objectName()~=self.player:objectName()then return max_card end
    if shown(self,player,"tianyi")and max_point>0 then
        for _,card in sgs.qlist(cards)do if card:getNumber()==max_point and not isCard("Slash",card,player)then return card end end
    end
    return max_card
end
function SmartAIView:originalHegemonyGetMinCard(player)
    player=player or self.player
    if player:isKongcheng()then return nil end
    local cards=r34_numbers.cards(self,player)
    local min_card,min_point=nil,14
    for _,card in sgs.qlist(cards)do
        if player:objectName()==self.player:objectName()or r34_numbers.visible(self,card,player)then
            local point=card:getNumber()
            if point<min_point then min_point=point;min_card=card end
        end
    end
    return min_card
end

end

;
do
local r35_need={}
function r35_need.callback(fn,...)
    local value=fn(...)
    if AIUnsupported.is(value)then error(value,0)end
    return value
end
function SmartAIView:originalHegemonyGetCardNeedPlayer(cards, friends_table, skillname)
	cards = cards or sgs.QList2Table(self.player:getHandcards())

	local cardtogivespecial = {}
	local keptslash = 0
	local friends = {}
	local cmpByAction = function(a,b)
		return ((a:getRoom()):getFront(a,b)):objectName() == a:objectName()
	end

	local cmpByNumber = function(a,b)
		return a:getNumber() > b:getNumber()
	end

	local AssistTarget = self:AssistTarget()
    if AIUnsupported.is(AssistTarget)then error(AssistTarget,0)end
	if AssistTarget and (hegemony_source_query(self,'needKongcheng',AssistTarget,true) or self:willSkipPlayPhase(AssistTarget) or AssistTarget:getHandcardNum() > 10) then
		AssistTarget = nil
	end

	local found
	local heg_xunyu, heg_huatuo
	local friends_table = friends_table or self.friends_noself
	for i = 1, #friends_table do
		local player = friends_table[i]
		local exclude = hegemony_source_query(self,'needKongcheng',player) or self:willSkipPlayPhase(player)
		if original_shown_skills(self,player, "heg_keji|qiaobian|heg_shensu") or player:getHp() - player:getHandcardNum() >= 3
			or (player:isLord() and hegemony_source_query(self,'isWeak',player) and self:getEnemyNumBySeat(self.player,player) >= 1) then
			exclude = false
		end
		if self:objectiveLevel(player) <= -2 and not exclude then
			if AssistTarget and AssistTarget:objectName() == player:objectName() then AssistTarget = player end
			if shown(self,player,"heg_jieming") then heg_xunyu = player end
			if shown(self,player,"jijiu") then heg_huatuo = player end
			table.insert(friends, player)
		end
	end
	if not found then AssistTarget = nil end

	if heg_xunyu and heg_huatuo and #cardtogivespecial == 0 and self.player:hasSkill("rende") and self.player:getPhase() == sgs.Player_Play then
		local no_distance = self.slash_distance_limit
		local redcardnum = 0
		for _, acard in ipairs(cards) do
			if isCard("Slash", acard, self.player) then
				if self.player:canSlash(heg_xunyu,nil,not no_distance) and self:slashIsEffective(acard,heg_xunyu) then
					keptslash = keptslash + 1
				end
				if keptslash > 0 then
					table.insert(cardtogivespecial, acard)
				end
			elseif isCard("Duel", acard, self.player) then
				table.insert(cardtogivespecial, acard)
			end
		end
		for _, hcard in ipairs(cardtogivespecial) do
			if hcard:isRed() then redcardnum = redcardnum + 1 end
		end
		if self.player:getHandcardNum() > #cardtogivespecial and redcardnum > 0 then
			for _, hcard in ipairs(cardtogivespecial) do
				if hcard:isRed() then return hcard, heg_huatuo end
				return hcard, heg_xunyu
			end
		end
	end

	local cardtogive = {}
	local keptjink = 0
	for _, acard in ipairs(cards) do
		if isCard("Jink", acard, self.player) and keptjink < 1 and not self.player:hasSkill("heg_kongcheng") then
			keptjink = keptjink + 1
		else
			table.insert(cardtogive, acard)
		end
	end

	self:sortInPlace(friends, "defense")
	for _, friend in ipairs(friends) do
		if hegemony_source_query(self,'isWeak',friend) and friend:getHandcardNum() < 3  then
			for _, hcard in ipairs(cards) do
				if isCard("Peach", hcard, friend) or (isCard("Jink", hcard, friend) and self:getEnemyNumBySeat(self.player,friend) > 0) or isCard("Analeptic", hcard, friend) then
					return hcard, friend
				end
			end
		end
	end

	if (skillname == "rende" and self.player:hasSkill("rende") and self.player:isWounded() and hegemony_source_query(self.player,'getMark',"rende") < 3) and not self.player:hasSkill("heg_kongcheng") then
		if (self.player:getHandcardNum() < 3 and hegemony_source_query(self.player,'getMark',"rende") == 0 and hegemony_source_query(self,'getOverflow') <= 0) then return end
	end

	for _, friend in ipairs(friends) do
		if friend:getHp() <= 2 and friend:faceUp() then
			for _, hcard in ipairs(cards) do
				if (hcard:isKindOf("Armor") and not original_equipment(friend,"getArmor") and not original_shown_skills(self,friend, "bazhen|jgyizhong"))
					or (hcard:isKindOf("DefensiveHorse") and not original_equipment(friend,"getDefensiveHorse")) then
					return hcard, friend
				end
			end
		end
	end

	self:sortByUseValue(cards, true)
	for _, friend in ipairs(friends) do
		if original_shown_skills(self,friend, "jijiu|jieyin") and friend:getHandcardNum() < 4 then
			for _, hcard in ipairs(cards) do
				if (hcard:isRed() and shown(self,friend,"jijiu")) or shown(self,friend,"jieyin") then
					return hcard, friend
				end
			end
		end
	end

	for _, friend in ipairs(friends) do
		if original_shown_skills(self,friend, "heg_jizhi")  then
			for _, hcard in ipairs(cards) do
				if hcard:isKindOf("TrickCard") then
					return hcard, friend
				end
			end
		end
	end

	for _, friend in ipairs(friends) do
		if original_shown_skills(self,friend, "heg_paoxiao")  then
			for _, hcard in ipairs(cards) do
				if hcard:isKindOf("Slash") then
					return hcard, friend
				end
			end
		end
	end

	--Crossbow
	for _, friend in ipairs(friends) do
		if original_shown_skills(self,friend, "heg_longdan|tenyearwusheng|heg_keji") and not hegemony_source_query(self,'hasCrossbowEffect',friend) and friend:getHandcardNum() >= 2 then
			for _, hcard in ipairs(cards) do
				if hcard:isKindOf("Crossbow") then
					return hcard, friend
				end
			end
		end
	end

	for _, friend in ipairs(friends) do
		if self:originalHegemonyKnownCard(friend, self.player, "Crossbow") > 0 then
			for _, p in ipairs(self.enemies) do
				if self:originalHegemonyIsGoodTarget(p, self.enemies) and friend:distanceTo(p) <= 1 then
					for _, hcard in ipairs(cards) do
						if isCard("Slash", hcard, friend) then
							return hcard, friend
						end
					end
				end
			end
		end
	end

	table.sort(friends, cmpByAction)

	for _, friend in ipairs(friends) do
		if friend:faceUp() then
			local can_slash = false
			for _, p in sgs.qlist(self.room:getOtherPlayers(friend)) do
				if self:isEnemy(p) and self:originalHegemonyIsGoodTarget(p, self.enemies) and friend:distanceTo(p) <= friend:getAttackRange() then
					can_slash = true
					break
				end
			end
			local flag = string.format("weapon_done_%s_%s",self.player:objectName(),friend:objectName())
			if not can_slash then
				for _, p in sgs.qlist(self.room:getOtherPlayers(friend)) do
					if self:isEnemy(p) and self:originalHegemonyIsGoodTarget(p, self.enemies) and friend:distanceTo(p) > friend:getAttackRange() then
						for _, hcard in ipairs(cardtogive) do
							if hcard:isKindOf("Weapon") and friend:distanceTo(p) <= friend:getAttackRange() + (sgs.weapon_range[hcard:getClassName()] or 0)
									and not original_equipment(friend,"getWeapon") and not hegemony_source_query(friend,'hasFlag',flag) then
								self:setStrategyPlayerFlag(friend,flag,true)
								return hcard, friend
							end
							if hcard:isKindOf("OffensiveHorse") and friend:distanceTo(p) <= friend:getAttackRange() + 1
									and not original_equipment(friend,"getOffensiveHorse") and not hegemony_source_query(friend,'hasFlag',flag) then
								self:setStrategyPlayerFlag(friend,flag,true)
								return hcard, friend
							end
						end
					end
				end
			end

		end
	end

	table.sort(cardtogive, cmpByNumber)

	for _, friend in ipairs(friends) do
		if not hegemony_source_query(self,'needKongcheng',friend,true) and friend:faceUp() then
			for _, hcard in ipairs(cardtogive) do
				for _, askill in sgs.qlist(friend:getVisibleSkillList(true)) do
					local callback = self:getHooks("ai_cardneed")[askill:objectName()]
					if type(callback) == "function" and r35_need.callback(callback,friend,hcard,self) then
						return hcard, friend
					end
				end
			end
		end
	end

	if skillname ~= "transfer" then
		self:sortInPlace(self.enemies, "defense")
		if #self.enemies > 0 and (self.enemies[1]):isKongcheng() and self.enemies[1]:hasShownSkill("heg_kongcheng") then
			for _, acard in ipairs(cardtogive) do
				if acard:isKindOf("Lightning") or acard:isKindOf("Collateral") or (acard:isKindOf("Slash") and self.player:getPhase() == sgs.Player_Play)
					or acard:isKindOf("OffensiveHorse") or acard:isKindOf("Weapon") or acard:isKindOf("AmazingGrace") then
					return acard, self.enemies[1]
				end
			end
		end
	end

	if AssistTarget then
		for _, hcard in ipairs(cardtogive) do
			return hcard, AssistTarget
		end
	end

	self:sortInPlace(friends, "defense")
	for _, hcard in ipairs(cardtogive) do
		for _, friend in ipairs(friends) do
			if not hegemony_source_query(self,'needKongcheng',friend,true) and not self:willSkipPlayPhase(friend) and original_shown_skills(self,friend, sgs.priority_skill) then
				if (hegemony_source_query(self,'getOverflow') > 0 or self.player:getHandcardNum() > 3) and friend:getHandcardNum() <= 3 then
					return hcard, friend
				end
			end
		end
	end

	local shoulduse = skillname == "rende" and self.player:isWounded() and self.player:hasSkill("rende") and hegemony_source_query(self.player,'getMark',"rende") < 3

	if #cardtogive == 0 and shoulduse then cardtogive = cards end

	self:sortInPlace(friends, "handcard")
	for _, hcard in ipairs(cardtogive) do
		for _, friend in ipairs(friends) do
			if not hegemony_source_query(self,'needKongcheng',friend,true) then
				if friend:getHandcardNum() <= 3 and (hegemony_source_query(self,'getOverflow') > 0 or self.player:getHandcardNum() > 3 or shoulduse) then
					return hcard, friend
				end
			end
		end
	end


	for _, hcard in ipairs(cardtogive) do
		for _, friend in ipairs(friends) do
			if not hegemony_source_query(self,'needKongcheng',friend,true) or #friends == 1 then
				if hegemony_source_query(self,'getOverflow') > 0 or self.player:getHandcardNum() > 3 or shoulduse then
					return hcard, friend
				end
			end
		end
	end

	for _, hcard in ipairs(cardtogive) do
		for _, friend in ipairs(friends_table) do
			if (not hegemony_source_query(self,'needKongcheng',friend,true) or #friends_table == 1) and (hegemony_source_query(self,'getOverflow') > 0 or self.player:getHandcardNum() > 3 or shoulduse) then
				return hcard, friend
			end
		end
	end

end
end

;
-- cardIsVisible uses the viewer's observed cards and ignores the supplied observer.
function SmartAIView:originalHegemonyMaxNumberCard(player,cards,observer)
    player=player or self.player
    if player:isKongcheng()then return nil end
    cards=r25_known_number_cards(self,player,cards,observer)
    observer=observer or self.player
    local max_card,max_point=nil,0
    for _,card in sgs.qlist(cards)do
        local allowed=false
        if player:objectName()==self.player:objectName()then
            local valuable=self:isValuableCard(card)
            if AIUnsupported.is(valuable)then error(valuable,0)end
            allowed=not valuable
        end
        if allowed or r25_card_visible(self,card,player,observer)then
            local point=card:getNumber()
            if point>max_point then max_point=point;max_card=card end
        end
    end
    if player:objectName()==self.player:objectName()and not max_card then
        for _,card in sgs.qlist(cards)do
            local point=card:getNumber()
            if point>max_point then max_point=point;max_card=card end
        end
    end
    if player:objectName()~=self.player:objectName()then return max_card end
    if shown(self,player,"tianyi")and max_point>0 then
        for _,card in sgs.qlist(cards)do
            if card:getNumber()==max_point and not isCard("Slash",card,player)then return card end
        end
    end
    return max_card
end
function SmartAIView:originalHegemonyMinNumberCard(player,cards,observer)
    player=player or self.player
    if player:isKongcheng()then return nil end
    cards=r25_known_number_cards(self,player,cards,observer)
    observer=observer or self.player
    local min_card,min_point=nil,14
    for _,card in sgs.qlist(cards)do
        if player:objectName()==self.player:objectName()or r25_card_visible(self,card,player,observer)then
            local point=card:getNumber()
            if point<min_point then min_point=point;min_card=card end
        end
    end
    return min_card
end

;
do
local r35_standard={}
function r35_standard.has_skill(self,player,name)
    local value=player:hasSkill(name)
    if value or player:objectName()==self.player:objectName()then return value end
    if type(player.areSkillsComplete)=="function"and player:areSkillsComplete()==true then return false end
    ai_unsupported("foreign unshown skill absence is not observable",name)
end
function SmartAIView:originalHegemonyGetLijianCard()
	local card_id
	local cards = self.player:getHandcards()
	cards = sgs.QList2Table(cards)
	self:sortByKeepValue(cards)
	local lightning = self:getCard("Lightning")
    if AIUnsupported.is(lightning)then error(lightning,0)end

	if hegemony_source_query(self,'needToThrowArmor') then
		card_id = original_equipment(self.player,"getArmor"):getId()
	elseif self.player:getHandcardNum() > self.player:getHp() then
		if lightning and not self:willUseLightning(lightning) then
			card_id = lightning:getKnownEffectiveId()
		else
			for _, acard in ipairs(cards) do
				if (acard:isKindOf("BasicCard") or acard:isKindOf("EquipCard") or acard:isKindOf("AmazingGrace"))
					and not acard:isKindOf("Peach") and not acard:isKindOf("HJadeSeal") then
					card_id = acard:getKnownEffectiveId()
					break
				end
			end
		end
	elseif not self.player:getEquips():isEmpty() then
		local player = self.player
		if original_equipment(player,"getWeapon") then card_id = original_equipment(player,"getWeapon"):getId()
		elseif original_equipment(player,"getOffensiveHorse") then card_id = original_equipment(player,"getOffensiveHorse"):getId()
		elseif original_equipment(player,"getDefensiveHorse") then card_id = original_equipment(player,"getDefensiveHorse"):getId()
		elseif original_equipment(player,"getArmor") and player:getHandcardNum() <= 1 then card_id = original_equipment(player,"getArmor"):getId()
		end
	end
	if not card_id then
		if lightning and not self:willUseLightning(lightning) then
			card_id = lightning:getKnownEffectiveId()
		else
			for _, acard in ipairs(cards) do
				if (acard:isKindOf("BasicCard") or acard:isKindOf("EquipCard") or acard:isKindOf("AmazingGrace"))
				  and not acard:isKindOf("Peach") and not acard:isKindOf("HJadeSeal") then
					card_id = acard:getKnownEffectiveId()
					break
				end
			end
		end
	end
	return card_id
end

function SmartAIView:originalHegemonyGetWoundedFriend(maleOnly)
	self:sortInPlace(self.friends, "hp")
	local list1 = {}	-- need help
	local list2 = {}	-- do not need help
	local addToList = function(p,index)
		if ( (not maleOnly) or (maleOnly and p:isMale()) ) and p:isWounded() then
			table.insert(index ==1 and list1 or list2, p)
		end
	end

	local getCmpHp = function(p)
		local hp = p:getHp()
		if p:isLord() and hegemony_source_query(self,'isWeak',p) then hp = hp - 10 end
		if shown(self,p,"heg_buqu") and p:getPile("scars"):length() > 0 then hp = hp + math.max(0, 5 - p:getPile("scars"):length()) end
		if original_shown_skills(self,p, "rende|tenyearkuanggu") and p:getHp() >= 2 then hp = hp + 5 end
		return hp
	end


	local cmp = function (a ,b)
		if getCmpHp(a) == getCmpHp(b) then
			return self:originalHegemonyGetDefenseSlash(a) < self:originalHegemonyGetDefenseSlash(b)
		else
			return getCmpHp(a) < getCmpHp(b)
		end
	end

	for _, friend in ipairs(self.friends) do
		if friend:isLord() then
			if hegemony_source_query(self,'needToLoseHp',friend,nil,nil,true,true) then
				addToList(friend, 2)
			else
				addToList(friend, 1)
			end
		else
			if hegemony_source_query(self,'needToLoseHp',friend,nil,nil,nil,true) or (original_shown_skills(self,friend, "rende|tenyearkuanggu|heg_zaiqi") and friend:getHp() >= 2) then
				addToList(friend, 2)
			else
				addToList(friend, 1)
			end
		end
	end
	table.sort(list1, cmp)
	table.sort(list2, cmp)
	return list1, list2
end

function SmartAIView:originalHegemonyToTurnOver(player, n, reason) -- @todo: param of toTurnOver
	if not player then return end -- Source diagnostics have no strategy result side effect.
	n = n or 0
	if not player:faceUp() then return false end
	if reason and reason == "mobilefangzhu" and player:getHp() == 1 and r25_aoe_frame(self) then
		local use = r25_aoe_frame(self)
		if use.to:contains(player) and self:aoeIsEffective(use.card,player)
			and self:playerGetRound(player) > self:playerGetRound(self.player)
			and player:isKongcheng() then
			return false
		end
	end
	if n > 1 then
		if ( player:getPhase() ~= sgs.Player_NotActive and (original_shown_skills(self,player, sgs.Active_cardneed_skill) or hegemony_source_query(self,'hasCrossbowEffect',player)) )
		or ( player:getPhase() == sgs.Player_NotActive and original_shown_skills(self,player, sgs.notActive_cardneed_skill) ) then
		return false end
	end
	if not self:isFriend(player) and shown(self,player,"heg_jushou") and player:getPhase() <= sgs.Player_Finish then
		return false
	end
	return true
end

function SmartAIView:originalHegemonyEnemiesContainsTrick(EnemyCount)
	local trick_all, possible_indul_enemy, possible_ss_enemy = 0, 0, 0
	local indul_num = self:getCardsNum("Indulgence")
	local ss_num = self:getCardsNum("SupplyShortage")
	local enemy_num, temp_enemy = 0, nil

	local heg_zhanghe = original_find_shown(self,"qiaobian")
	if heg_zhanghe and (not self:isEnemy(heg_zhanghe) or heg_zhanghe:isKongcheng() or not heg_zhanghe:faceUp()) then heg_zhanghe = nil end

	if self.player:hasSkill("heg_guose") then
		for _, acard in sgs.qlist(self.player:getCards("he")) do
			if acard:getSuit() == sgs.Card_Diamond then indul_num = indul_num + 1 end
		end
	end

	if self.player:hasSkill("heg_duanliang") then
		for _, acard in sgs.qlist(self.player:getCards("he")) do
			if acard:isBlack() then ss_num = ss_num + 1 end
		end
	end

	for _, enemy in ipairs(self.enemies) do
		if enemy:containsTrick("indulgence") then
			if not r35_standard.has_skill(self,enemy,"heg_keji") and   (not heg_zhanghe or self:playerGetRound(enemy) >= self:playerGetRound(heg_zhanghe)) then
				trick_all = trick_all + 1
				if not temp_enemy or temp_enemy:objectName() ~= enemy:objectName() then
					enemy_num = enemy_num + 1
					temp_enemy = enemy
				end
			end
		else
			possible_indul_enemy = possible_indul_enemy + 1
		end
		if self.player:distanceTo(enemy) == 1 or self.player:hasSkill("heg_duanliang") and self.player:distanceTo(enemy) <= 2 then
			if enemy:containsTrick("supply_shortage") then
				if not r35_standard.has_skill(self,enemy,"heg_shensu") and (not heg_zhanghe or self:playerGetRound(enemy) >= self:playerGetRound(heg_zhanghe)) then
					trick_all = trick_all + 1
					if not temp_enemy or temp_enemy:objectName() ~= enemy:objectName() then
						enemy_num = enemy_num + 1
						temp_enemy = enemy
					end
				end
			else
				possible_ss_enemy = possible_ss_enemy + 1
			end
		end
	end
	indul_num = math.min(possible_indul_enemy, indul_num)
	ss_num = math.min(possible_ss_enemy, ss_num)
	if not EnemyCount then
		return trick_all + indul_num + ss_num
	else
		return enemy_num + indul_num + ss_num
	end
end
end

