-- silently propagate a later write to the loader's copied heg_kurou value.
end)() end

;(function()
local function fail(key)ai_unsupported('Original R37 input/provider is not lawfully known',key)end
local known = AIValue.requireKnown
local function invoke(o,m,...)
 local f=o and o[m];if type(f)~='function'then fail(m)end
 local v=f(o,...);if AIUnsupported.is(v)then error(v,0)end;return v,f
end

local function shown(self,p,name)
 local f=self.world and AIHegemony.facts(self.world)
 local row=f and f.players and f.players[p:objectName()]
 if type(row)~='table'or type(row.shown_skills)~='table'then fail('hegemony.shown_skills')end
 return row.shown_skills[name]~=nil
end
-- General-pile contents, the engine kingdom list and the JadeSeal treasure
-- effect are supplied as viewer-scoped pure-value domains.
local function fact(self)
 local world=self.world
 local facts=world and world.hegemony_facts
 if type(facts)~='table' then fail('hegemony_facts')end
 return facts
end
local function plainList(v,key)
 if not AIValue.isList(v) or getmetatable(v)~=nil then fail(key)end
 for _,x in ipairs(v)do if type(x)~='string'then fail(key)end end
 return v
end
local function equip(player,index)
 local v=invoke(player,'getEquip',index)
 if v==nil and AIValue.isPlayer(player)then
  local row=rawget(player,'_view');if type(row)~='table'or not AIValue.isList(row.equips)then fail('getEquip')end
 end
 return v
end
function SmartAIView:originalHegemonyHasKnownSkill(expression,player)
 player=player or self.player
 if AIValue.kind(expression)~=nil then return false end
 expression=type(expression)=='table'and expression.name or expression
 if type(expression)~='string'then return false end
 for _,group in ipairs(expression:split('|'))do
  local present=true
  for _,name in ipairs(group:split('+'))do
   local found=player:objectName()==self.player:objectName()and player:hasSkill(name)or shown(self,player,name)
   if not found then present=false;break end
  end
  if present then return true end
 end
 return false
end
function SmartAIView:originalHegemonyHasKnownSkills(names,player)
 player=player or self.player
 -- Native Player userdata is represented by PlayerView, not a source Lua list.
 if type(player)=='table'and not AIValue.isPlayer(player)and not AIList.isNativeList(player)then
  for _,p in ipairs(player)do if self:hasKnownSkill(names,p)then return true end end
  return false
 end
 return self:hasKnownSkill(names,player)
end
function SmartAIView:originalHegemonyGetFriendNumBySeat(from,to)
 local players=sgs.QList2Table(self.room:getAllPlayers())
 local to_seat=(to:getSeat()-from:getSeat())%#players
 local friendnum=0
 for _,p in ipairs(players)do
  if self:isFriend(from,p)and((p:getSeat()-from:getSeat())%#players)<to_seat then friendnum=friendnum+1 end
 end
 return friendnum
end
local function pileRow(self,p)
 local rows=fact(self).general_piles;local row=type(rows)=='table'and rows[p:objectName()]
 if type(row)~='table'or row.complete~=true or type(row.open)~='table'or type(row.piles)~='table'or type(row.lookup)~='table'then fail('general_piles.catalogue')end
 plainList(row.names,'general_piles.names');return row
end
function SmartAIView:originalHegemonyGetGeneralPile(player,name)
 player=player or self.player
 local row=pileRow(self,player)
 if player:objectName()~=self.player:objectName()and row.open[name]~=true then return{}end
 local out={};local contents=row.piles[name]
 if contents==nil then
  return out
 end
 for _,value in ipairs(plainList(contents,'general_piles.contents'))do out[#out+1]=value end
 return out
end
function SmartAIView:originalHegemonyGetGeneralPileNames(player)
 player=player or self.player
 local row=pileRow(self,player);local names={}
 for _,name in ipairs(row.names)do
  if player:objectName()==self.player:objectName()or row.open[name]==true then names[#names+1]=name end
 end
 return names
end
function SmartAIView:originalHegemonyGetGeneralPileName(player,general)
 player=player or self.player
 local row=pileRow(self,player)
 local direct=type(general)=='string' and row.lookup[general] or nil
 if direct~=nil then
  if type(direct)~='string'then fail('general_piles.lookup')end
  return direct
 end
 local blocked=false
 local own=player:objectName()==self.player:objectName()
 for _,name in ipairs(row.names)do
  if own or row.open[name]==true then
   local contents=row.piles[name]
   if contents~=nil and table.contains(plainList(contents,'general_piles.contents'),general)then
    -- Source searches the whole native QMap before applying visibility. A
    -- hidden earlier duplicate could mask this public hit; never scan it.
    if blocked then fail('general_piles.hidden_earlier_membership')end
    return name
   end
  else blocked=true end
 end
 -- Any unseen hit is in a closed pile, which source itself masks to ''.
 return ''
end
local aliases = {
    nosganglie = {"heg_ganglie"}, nostuxi = {"tenyeartuxi"}, nosluoyi = {"heg_luoyi"},
    nosyiji = {"heg_yiji"}, shensu = {"heg_shensu"},
    duanliang = {"heg_duanliang"}, nosjushou = {"heg_jushou"}, qiangxi = {"heg_qiangxi"},
    jieming = {"heg_jieming"}, fangzhu = {"mobilefangzhu"}, luoshen = {"heg_luoshen"},
    guicai = {"heg_guicai"},
    paoxiao = {"heg_paoxiao"}, kongcheng = {"heg_kongcheng"}, longdan = {"heg_longdan"},
    tieqi = {"heg_tieqi"}, jizhi = {"heg_jizhi"}, liegong = {"heg_liegong"},
    wusheng = {"tenyearwusheng"}, kuanggu = {"tenyearkuanggu"}, huoshou = {"heg_huoshou"}, juxiang = {"heg_juxiang"},
    keji = {"heg_keji"},
    kurou = {"heg_kurou"}, yingzi = {"heg_yingzi_sunce", "heg_yingzi_zhouyu"},
    qicai = {"nosqicai"},
    fanjian = {"heg_fanjian"}, guose = {"heg_guose"}, qianxun = {"heg_qianxun"},
    xiaoji = {"heg_xiaoji"}, yinghun = {"heg_yinghun_sunjian", "heg_yinghun_sunce"},
    tianxiang = {"heg_tianxiang"}, buqu = {"heg_buqu"}, guzheng = {"heg_guzheng"},
    duanbing = {"heg_duanbing"}, fenxun = {"heg_fenxun"}, luanji = {"heg_luanji"},
     weimu = {"heg_weimu"},
	leiji = {"nosleiji"}, duanchang = {"heg_duanchang"},
    wushuang = {"heg_wushuang"}, jiang = {"heg_jiang"},
}
local function shownSkills(self,p,expression)
 for _,group in ipairs(expression:split('|'))do
  local yes=true
  for _,name in ipairs(group:split('+'))do
   local found=false
   for _,actual in ipairs(aliases[name]or{name})do if shown(self,p,actual)then found=true;break end end
   if not found then yes=false;break end
  end
  if yes then return true end
 end
 return false
end
function SmartAIView:originalHegemonyGetGuixinValue(player)
	if player:isAllNude() then return 0 end
	local card_id = self:askForCardChosen(player,"hej","dummy")
	if self:isEnemy(player) then
		for _, card in sgs.qlist(player:getJudgingArea()) do
			if card:getKnownEffectiveId() == card_id then
				if card:isKindOf("Lightning") then
					if self:hasWizard(self.enemies,true) then return 0.8
					elseif self:hasWizard(self.friends,true) then return 0.4
					else return 0.5 * (#self.friends) / (#self.friends + #self.enemies) end
				else
					return -0.2
				end
			end
		end
		for i = 0, 3 do
			local card = equip(player,i)
			if card and card:getKnownEffectiveId() == card_id then
				if card:isKindOf("Armor") and self:needToThrowArmor(player) then return 0 end
				local value = 0
				if self:getDangerousCard(player) == card_id then value = 1.5
				elseif self:getValuableCard(player) == card_id then value = 1.1
				elseif i == 1 then value = 1
				elseif i == 2 then value = 0.8
				elseif i == 0 then value = 0.7
				elseif i == 3 then value = 0.5
				end
				if shownSkills(self,player, sgs.lose_equip_skill) or self:doNotDiscard(player,"e",true) then value = value - 0.2 end
				return value
			end
		end
		if self:needKongcheng(player) and player:getHandcardNum() == 1 then return 0 end
		if not self:hasLoseHandcardEffective() then return 0.1
		else
			local index = shownSkills(self,player, "jijiu|qingnang|nosleiji|jieyin|beige|heg_kanpo|liuli|qiaobian|heg_zhiheng|guidao|heg_tianxiang|lijian") and 0.7 or 0.6
			local value = 0.2 + index / (player:getHandcardNum() + 1)
			if self:doNotDiscard(player,"h",true) then value = value - 0.1 end
			return value
		end
	elseif self:isFriend(player) then
		for _, card in sgs.qlist(player:getJudgingArea()) do
			if card:getKnownEffectiveId() == card_id then
				if card:isKindOf("Lightning") then
					if self:hasWizard(self.enemies,true) then return 1
					elseif self:hasWizard(self.friends,true) then return 0.8
					else return 0.4 * (#self.enemies) / (#self.friends + #self.enemies) end
				else
					return 1.5
				end
			end
		end
		for i = 0, 3 do
			local card = equip(player,i)
			if card and card:getKnownEffectiveId() == card_id then
				if card:isKindOf("Armor") and self:needToThrowArmor(player) then return 0.9 end
				local value = 0
				if i == 1 then value = 0.1
				elseif i == 2 then value = 0.2
				elseif i == 0 then value = 0.25
				elseif i == 3 then value = 0.25
				end
				if shownSkills(self,player, sgs.lose_equip_skill) then value = value + 0.1 end
				if player:hasShownSkill("heg_tuntian") then value = value + 0.1 end
				return value
			end
		end
		if self:needKongcheng(player,true) and player:getHandcardNum() == 1 then return 0.5
		elseif self:needKongcheng(player) and player:getHandcardNum() == 1 then return 0.3 end
		if not self:hasLoseHandcardEffective() then return 0.2
		else
